"],"progressions":["Archer push-up","Decline push-up"],"safety":"Keep the width moderate; very wide hands stress the shoulder joint.","video":null,"diagram":"","notes":""},{"id":"doorrow","name":"Doorway row","aliases":["Door frame row"],"training_type":"Strength","tags":["Home-friendly","Rehab","Strength"],"muscle_group":"Back","primary_muscles":["Upper back","Lats"],"secondary_muscles":["Biceps","Rear delts"],"movement_pattern":"Horizontal pull","equipment":["Door frame"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"10–15","form_cues":["Grip both sides of a door frame, feet close to the threshold.","Lean back with straight arms and a straight body.","Pull your chest toward the frame by squeezing shoulder blades."],"common_mistakes":["Bending at the hips instead of staying straight","Shrugging up"],"regressions":[],"progressions":["Table row","Inverted row"],"safety":"Hold firmly; a slipping grip means a fall backward.","video":null,"diagram":"","notes":"Walk feet closer to the frame to make it harder. One-arm version works too."},{"id":"tablerow","name":"Table row","aliases":["Under-table inverted row"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Upper back"],"secondary_muscles":["Biceps","Rear delts","Core"],"movement_pattern":"Horizontal pull","equipment":["Sturdy table"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"6–12","form_cues":["Lie under a sturdy table and grip the edge, hands shoulder-width.","Keep your body straight from heels to head.","Pull your chest to the table edge, then lower slowly."],"common_mistakes":["Hips sagging","Shrugging shoulders toward the ears"],"regressions":["Doorway row"],"progressions":["Inverted row"],"safety":"Test the table first: it must not tip or slide when you pull.","video":null,"diagram":"","notes":"Bend knees to make it easier."},{"id":"ytw","name":"Prone Y-T-W raise","aliases":["YTWs","Floor Y-T-W"],"training_type":"Strength","tags":["Home-friendly","Isolation","Rehab","Strength","Warm-up"],"muscle_group":"Shoulders","primary_muscles":["Rear delts","Lower traps","Rhomboids"],"secondary_muscles":["Rotator cuff"],"movement_pattern":"Isolation","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"8 / letter","form_cues":["Lie face down, forehead resting, arms out in a Y shape.","Lift arms a few centimetres, thumbs up, then lower.","Repeat with arms in a T, then elbows bent in a W."],"common_mistakes":["Lifting the head and arching the back","Shrugging instead of squeezing shoulder blades"],"regressions":[],"progressions":["Dumbbell Y-T-W raise"],"safety":"Keep the lift small and pain-free.","video":null,"diagram":"","notes":"Great for posture and shoulder health."},{"id":"scappush","name":"Scapular push-up","aliases":["Push-up plus","Scap push-up"],"training_type":"Strength","tags":["Home-friendly","Isolation","Rehab","Strength","Warm-up"],"muscle_group":"Shoulders","primary_muscles":["Serratus anterior"],"secondary_muscles":["Rhomboids","Core"],"movement_pattern":"Isolation","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"10–15","form_cues":["Start in a high plank with straight arms.","Let your chest sink between shoulder blades, then push the floor away.","Keep elbows locked the whole time."],"common_mistakes":["Bending the elbows","Moving the hips instead of the shoulder blades"],"regressions":["Wall push-up"],"progressions":["Push-ups"],"safety":"Keep the range pain-free if you have shoulder impingement.","video":null,"diagram":"","notes":"Great warm-up for push-ups and handstands."},{"id":"benchdip","name":"Bench dips","aliases":["Chair dip","Triceps bench dip"],"training_type":"Strength","tags":["Home-friendly","Isolation","Strength"],"muscl