ilateral":true,"sets":3,"reps":"8–12 / side","form_cues":["Rest your back foot laces-down on a bench behind you.","Lower straight down until the front thigh is near parallel.","Drive through the front heel to stand tall."],"common_mistakes":["Front foot too close to the bench","Pushing off the back leg"],"regressions":["Split squat"],"progressions":["Shrimp squat","Dumbbell Bulgarian split squat"],"safety":"Use a stable bench that won't slide.","video":null,"diagram":"splitsquat","notes":"Hold dumbbells to add load; listed here as the bodyweight version."},{"id":"cossack","name":"Cossack squat","aliases":["Side-to-side squat"],"training_type":"Strength","tags":["Home-friendly","Mobility","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Adductors","Glutes"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Lunge","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":true,"sets":3,"reps":"6–8 / side","form_cues":["Start in a very wide stance.","Shift into one hip and squat deep while the other leg goes straight.","Keep the bent-side heel down and chest tall."],"common_mistakes":["Lifting the heel of the working leg","Rounding the back to get lower"],"regressions":["Lateral lunge"],"progressions":["Goblet Cossack squat"],"safety":"Hold onto a door frame for balance if needed.","video":null,"diagram":"","notes":""},{"id":"fwdlunge","name":"Forward lunge","aliases":["Front lunge"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Calves","Core"],"movement_pattern":"Lunge","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":true,"sets":3,"reps":"8–12 / side","form_cues":["Step forward and lower both knees to about 90°.","Keep your torso upright and front knee over the foot.","Push hard off the front foot to 