":null,"diagram":"","notes":"Proven to reduce hamstring strain risk in sport. Can also be done with a GHD or a band for help."},{"id":"revlunge","name":"Reverse lunge","aliases":["Backward lunge"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Glutes","Quadriceps"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Lunge","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":true,"sets":3,"reps":"8–12 / side","form_cues":["Step back and lower the back knee toward the floor.","Keep most of your weight in the front heel.","Drive through the front foot to bring the leg back."],"common_mistakes":["Leaning far forward","Stepping back too narrow and losing balance"],"regressions":["Split squat"],"progressions":["Deficit reverse lunge","Shrimp squat"],"safety":"Often the most knee-friendly lunge.","video":null,"diagram":"","notes":""},{"id":"revnordic","name":"Reverse Nordic","aliases":["Reverse Nordic curl"],"training_type":"Strength","tags":["Home-friendly","Isolation","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps"],"secondary_muscles":["Hip flexors","Core"],"movement_pattern":"Isolation","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"6–10","form_cues":["Kneel tall with knees hip-width and toes flat.","Lean your straight body back by bending only at the knees.","Squeeze your quads to pull yourself upright."],"common_mistakes":["Bending at the hips","Going deeper than you can control"],"regressions":["Wall sit"],"progressions":["Sissy squat"],"safety":"Use a thick pad under the knees and start with a small range.","video":null,"diagram":"","notes":""},{"id":"slcalf","name":"Single-leg calf raise","aliases":[],"training_type":"Strength","tags":["Home-friendly","Isolation","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Calv