or.","Push through the front foot to rise, feet staying planted."],"common_mistakes":["Front knee caving in","Stance too narrow, like walking a tightrope"],"regressions":["Bodyweight squat"],"progressions":["Bulgarian split squat"],"safety":"Hold a wall for balance if needed.","video":null,"diagram":"","notes":""},{"id":"sumobwsquat","name":"Sumo squat","aliases":["Wide-stance bodyweight squat","Plié squat"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Adductors","Glutes"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Squat","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"15–20","form_cues":["Take a wide stance with toes turned out about 45°.","Sit straight down, pushing knees out over toes.","Keep chest tall and squeeze glutes to stand."],"common_mistakes":["Knees collapsing inward","Leaning far forward"],"regressions":["Bodyweight squat"],"progressions":["Cossack squat"],"safety":"Only go as wide as your hips comfortably allow.","video":null,"diagram":"","notes":"Hold a dumbbell or kettlebell between the legs to load it."},{"id":"tibraise","name":"Tibialis raise","aliases":["Wall tib raise","Toe raise"],"training_type":"Strength","tags":["Home-friendly","Isolation","Rehab","Strength"],"muscle_group":"Legs","primary_muscles":["Tibialis anterior"],"secondary_muscles":[],"movement_pattern":"Isolation","equipment":["Wall"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"15–25","form_cues":["Lean your back on a wall with feet a step out in front.","Pull your toes up toward your shins as high as you can.","Lower slowly without touching down fully."],"common_mistakes":["Feet too close to the wall","Rushing the reps"],"regressions":[],"progressions":["Tib bar raise"],"safety":"Step feet further out to make it harder.","video":null,"diagram":"","note