driceps","Core"],"movement_pattern":"Hinge","equipment":["Bench or sofa"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"15–20","form_cues":["Rest your upper back on a bench, feet flat and knees bent.","Drive hips up until shins are vertical and body is flat.","Tuck chin and squeeze glutes at the top."],"common_mistakes":["Over-arching the back at the top","Feet too far away"],"regressions":["Glute bridge"],"progressions":["Single-leg hip thrust","Barbell hip thrust"],"safety":"Make sure the bench is against a wall so it can't slide.","video":null,"diagram":"","notes":""},{"id":"clamshell","name":"Clamshell","aliases":["Clams"],"training_type":"Strength","tags":["Home-friendly","Isolation","Rehab","Strength"],"muscle_group":"Glutes","primary_muscles":["Glute medius"],"secondary_muscles":["Hip rotators"],"movement_pattern":"Isolation","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":true,"sets":3,"reps":"15–20 / side","form_cues":["Lie on your side, hips and knees bent, feet together.","Keep feet touching and lift the top knee.","Pause at the top and lower slowly."],"common_mistakes":["Rolling the hips backward","Lifting the feet apart"],"regressions":[],"progressions":["Banded clamshell","Fire hydrant"],"safety":"A common rehab move for knee and hip pain.","video":null,"diagram":"","notes":"Add a mini band above the knees to progress."},{"id":"curtsy","name":"Curtsy lunge","aliases":["Curtsy squat"],"training_type":"Strength","tags":["Home-friendly","Strength","Unilateral"],"muscle_group":"Glutes","primary_muscles":["Glutes","Quadriceps"],"secondary_muscles":["Adductors","Hip abductors"],"movement_pattern":"Lunge","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":true,"sets":3,"reps":"8–12 / side","form_cues":["Step one leg diagonally behind the other.","Lower until the front thigh is near parallel.","Push through the front heel to return."],"common_mistakes":["Front knee collapsing inward","Twisting the hips too much"],"regressions":["Reverse lunge"],"progressions":["Dumbbell curtsy lunge"],"safety":"Shorten the step if you feel strain in the knee.","video":null,"diagram":"","notes":""},{"id":"donkeykick","name":"Donkey kick","aliases":["Quadruped hip extension","Kickback (bodyweight)"],"training_type":"Strength","tags":["Home-friendly","Isolation","Rehab","Strength"],"muscle_group":"Glutes","primary_muscles":["Glutes"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Extension","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":true,"sets":3,"reps":"12–15 / side","form_cues":["Start on hands and knees with a flat back.","Keep the knee bent and push one heel toward the ceiling.","Stop when the thigh is level, then lower slowly."],"common_mistakes":["Arching the lower back to lift higher","Rotating the hips open"],"regressions":[],"progressions":["Banded donkey kick"],"safety":"Keep the movement in the hip, not the lower back.","video":null,"diagram":"","notes":""},{"id":"firehydrant","name":"Fire hydrant","aliases":["Quadruped hip abduction"],"training_type":"Strength","tags":["Home-friendly","Isolation","Rehab","Strength"],"muscle_group":"Glutes","primary_muscles":["Glute medius"],"secondary_muscles":["Glute maximus","Core"],"movement_pattern":"Isolation","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":true,"sets":3,"reps":"12–15 / side","form_cues":["Start on hands and knees, back flat.","Lift one bent knee out to the side to hip height.","Lower with control, keeping weight even on both hands."],"common_mistakes":["Shifting the whole body sideways","Rounding the back"],"regressions":["Clamshell"],"progressions":["Banded fire hydrant"],"safety":"Go only as high as you can without twisting the torso.","video":null,"diagram":"","notes":""},{"id":"frogpump","nam