:["Mat (optional)"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":true,"sets":3,"reps":"10–12 / side","form_cues":["Lie on your back with one foot planted and the other leg raised.","Push through the planted heel to lift your hips.","Keep the pelvis level, pause, and lower."],"common_mistakes":["Hips tilting to one side","Arching the lower back"],"regressions":["Glute bridge"],"progressions":["Single-leg hip thrust"],"safety":"Lower the range if you feel hamstring cramping.","video":null,"diagram":"","notes":""},{"id":"slhipthrust","name":"Single-leg hip thrust","aliases":[],"training_type":"Strength","tags":["Home-friendly","Strength","Unilateral"],"muscle_group":"Glutes","primary_muscles":["Glutes"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Hinge","equipment":["Bench or sofa"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":true,"sets":3,"reps":"8–12 / side","form_cues":["Upper back on a bench, one foot planted, other knee pulled up.","Drive through the planted heel to lift hips level.","Lower with control without touching down."],"common_mistakes":["Pelvis dropping on the free side","Pushing through the toes"],"regressions":["Bodyweight hip thrust","Single-leg glute bridge"],"progressions":["Barbell hip thrust"],"safety":"Keep the bench stable and the movement slow.","video":null,"diagram":"","notes":""},{"id":"bandfly","name":"Band chest fly","aliases":[],"training_type":"Strength","tags":["Chest","Home-friendly","Isolation","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts"],"movement_pattern":"Isolation","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Anchor the band behind you at chest height.","Keep a slight bend in the elbows.","Hug your arms together in front of your chest."],"common_mistakes":["Bending elbows into a press","Letting arms travel too far back"],"regressions":[],"progressions":["Dumbbell fly"],"safety":"Avoid overstretching the front of the shoulder.","video":null,"diagram":"","notes":""},{"id":"bandpress","name":"Band chest press","aliases":["Standing band chest press"],"training_type":"Strength","tags":["Chest","Compound","Home-friendly","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Triceps","Front delts"],"movement_pattern":"Horizontal push","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Anchor the band at chest height behind you.","Stagger your stance and brace your core.","Press straight forward until arms are long, then return slowly."],"common_mistakes":["Shrugging shoulders toward ears","Letting the band snap back"],"regressions":["Incline push-up"],"progressions":["Push-ups","Band chest fly"],"safety":"Secure the anchor point firmly so the band can't slip free.","video":null,"diagram":"cablepress","notes":""},{"id":"bandpushup","name":"Banded push-up","aliases":[],"training_type":"Strength","tags":["Compound","Home-friendly","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Horizontal push","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Loop a band across your upper back, ends under your hands.","Do a normal push-up against the band's pull.","Lock out hard at the top where tension is highest."],"common_mistakes":["Band slipping off the shoulders","Losing body line"],"regressions":["Push-ups"],"progressions":["Decline push-up"],"safety":"Check the band for damage before each use.","video":null,"diagram":"","notes":""},{"id":"dbfloorfly","name":"Dumbbell floor fly","aliases":["Floor fly"],"training_type":"Strength","tags":["Home-friendly","Hypertrophy","Isolation","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts"],"movement_pattern":"Isolation","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Lie on the floor with a soft bend in your elbows.","Open your arms wide until elbows lightly touch the floor.","Hug the weights back up over your chest."],"common_mistakes":["Bending the elbows into a press","Going too heavy"],"regressions":[],"progressions":["Dumbbell fly"],"safety":"Use light weights and keep the elbow bend fixed.","video":null,"diagram":"","notes":"The floor stops the stretch, so it is safer than a bench fly for beginners."},{"id":"dbfloorpress","name":"Dumbbell floor press","aliases":["DB floor press"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts"],"movement_pattern":"Horizontal push","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Lie on your back, knees bent, dumbbells over your chest.","Lower until your upper arms touch the floor, then pause.","Press straight up and squeeze your chest at the top."],"common_mistakes":["Bouncing the elbows off the floor","Flaring elbows out to 90°"],"regressions":[],"progressions":["Flat dumbbell press"],"safety":"Lay the dumbbells down at your sides, don't drop them over your face.","video":null,"diagram":"","notes":"Great no-bench option; the shorter range is kind to cranky shoulders."},{"id":"kbfloorpress","name":"Kettlebell floor press","aliases":[],"training_type":"Strength","tags":["Chest","Compound","Home-friendly","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts"],"movement_pattern":"Horizontal push","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Lie on the floor, upper arm resting on the ground.","Press the bell up over your shoulder.","Lower until the elbow lightly touches the floor."],"common_mistakes":["Bouncing the elbow off the floor","Wrist bent backward"],"regressions":["Push-ups"],"progressions":["Flat dumbbell press"],"safety":"Roll the bell into position from your side rather than lifting it overhead.","video":null,"diagram":"","notes":"Can also be done with two bells."},{"id":"mbpushup","name":"Medicine ball push-up","aliases":["Staggered med ball push-up"],"training_type":"Strength","tags":["Chest","Home-friendly","Strength","Unilateral"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Horizontal push","equipment":["Medicine ball"],"req":"medball","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"6–8 / side","form_cues":["Place one hand on the ball, the other on the floor.","Lower with control, keeping hips square.","Press up and switch the ball to the other hand."],"common_mistakes":["Ball rolling away","Twisting the hips"],"regressions":["Push-ups"],"progressions":["Ring push-ups"],"safety":"Use a non-bouncing ball and keep the wrist stacked over it.","video":null,"diagram":"","notes":""},{"id":"vestpushup","name":"Weighted vest push-up","aliases":[],"training_type":"Strength","tags":["Chest","Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Horizontal push","equipment":["Weighted vest"],"req":"weightvest","equipment_tier":1,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Tighten the vest so the load sits high on the chest.","Keep a straight line from head to heels.","Lower until the chest nearly touches, then press up."],"common_mistakes":["Hips sagging under the extra load","Elbows flaring wide"],"regressions":["Push-ups"],"progressions":["Banded push-up"],"safety":"Add load gradually; reduce it if your lower back sags.","video":null,"diagram":"","notes":"Log vest weight as added kg."},{"id":"bandlatpull","name":"Band lat pulldown","aliases":["Kneeling band pulldown"],"training_type":"Strength","tags":["Back","Compound","Home-friendly","Strength"],"muscle_group":"Back","primary_muscles":["Lats"],"secondary_muscles":["Biceps","Rear delts"],"movement_pattern":"Vertical pull","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Anchor the band high and kneel facing it.","Pull elbows down toward your back pockets.","Keep chest tall and return slowly."],"common_mistakes":["Pulling with the arms only","Rounding forward"],"regressions":[],"progressions":["Assisted pull-up","Wide-grip lat pulldown"],"safety":"Double-check the high anchor is secure before loading it.","video":null,"diagram":"","notes":""},{"id":"bandrow","name":"Band seated row","aliases":["Resistance band row"],"training_type":"Strength","tags":["Back","Compound","Home-friendly","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Rhomboids"],"secondary_muscles":["Biceps","Rear delts"],"movement_pattern":"Horizontal pull","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Sit tall with legs long and the band looped around your feet.","Pull handles to your lower ribs.","Squeeze shoulder blades together before releasing slowly."],"common_mistakes":["Rounding the back","Leaning back to cheat the pull"],"regressions":[],"progressions":["Suspension row","One-arm dumbbell row"],"safety":"Wrap the band securely around the feet so it can't slip off.","video":null,"diagram":"","notes":""},{"id":"bandstraight","name":"Band straight-arm pulldown","aliases":[],"training_type":"Strength","tags":["Back","Home-friendly","Isolation","Strength"],"muscle_group":"Back","primary_muscles":["Lats"],"secondary_muscles":["Triceps (long head)","Core"],"movement_pattern":"Isolation","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Anchor the band high and hinge slightly.","Keep arms straight and sweep hands to your thighs.","Feel the lats squeeze, then return slowly."],"common_mistakes":["Bending the elbows","Shrugging"],"regressions":[],"progressions":["Straight-arm pulldown"],"safety":"Secure the high anchor before loading it.","video":null,"diagram":"","notes":""},{"id":"dbbentrow","name":"Bent-over dumbbell row","aliases":["Two-arm dumbbell row","DB bent-over row"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Rhomboids","Middle traps"],"secondary_muscles":["Rear delts","Biceps","Lower back"],"movement_pattern":"Horizontal pull","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Hinge forward with a flat back, weights hanging under your shoulders.","Row elbows back toward your hips.","Squeeze at the top, then lower all the way."],"common_mistakes":["Standing up as you row","Rounding the lower back"],"regressions":["One-arm dumbbell row"],"progressions":["Dumbbell gorilla row"],"safety":"Brace your abs; if your lower back fatigues, switch to a supported row.","video":null,"diagram":"","notes":""},{"id":"dbtrap3","name":"Bent-over dumbbell trap-3 raise","aliases":["Trap 3 raise"],"training_type":"Strength","tags":["Isolation","Rehab","Strength"],"muscle_gr