:["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Stand wide, hinge forward, dumbbells on the floor between your feet.","Row one weight up while the other arm pushes into its dumbbell.","Lower and alternate sides."],"common_mistakes":["Twisting the torso","Rounding the back"],"regressions":["Bent-over dumbbell row"],"progressions":["Renegade row"],"safety":"Keep your hips level and back flat throughout.","video":null,"diagram":"","notes":"Popular with kettlebells; dumbbells work just as well."},{"id":"shrug","name":"Dumbbell shrug","aliases":["DB shrug"],"training_type":"Strength","tags":["Home-friendly","Hypertrophy","Isolation","Strength"],"muscle_group":"Back","primary_muscles":["Upper traps"],"secondary_muscles":["Levator scapulae","Forearms"],"movement_pattern":"Isolation","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Stand tall with heavy dumbbells at your sides.","Shrug your shoulders straight up toward your ears.","Hold one second, then lower fully."],"common_mistakes":["Rolling the shoulders","Bending the elbows"],"regressions":[],"progressions":["Incline dumbbell shrug"],"safety":"Keep your neck neutral; don't jut your chin forward.","video":null,"diagram":"","notes":"Use straps if grip gives out before your traps."},{"id":"dbsuitcasedl","name":"Dumbbell suitcase deadlift","aliases":["Suitcase deadlift"],"training_type":"Strength","tags":["Compound","Strength","Unilateral"],"muscle_group":"Back","primary_muscles":["Glutes","Hamstrings","Quadriceps"],"secondary_muscles":["Obliques","Quadratus lumborum","Forearms"],"movement_pattern":"Hinge","equipment":["Dumbbell"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"8 / side","form_cues":["Stand with one dumbbell at your side.","