"Keep the bell close to avoid hitting your face.","video":null,"diagram":"","notes":"A teaching step toward the snatch."},{"id":"kbsdhp","name":"Kettlebell sumo deadlift high pull","aliases":["KB SDHP"],"training_type":"Strength","tags":["Compound","Endurance","Power","Strength"],"muscle_group":"Back","primary_muscles":["Upper traps","Glutes"],"secondary_muscles":["Quadriceps","Shoulders"],"movement_pattern":"Vertical pull","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Take a wide stance, bell between your feet.","Drive up through the legs and hips.","Pull the bell to chin height, elbows high."],"common_mistakes":["Pulling with arms before hips extend","Rounding the back"],"regressions":["Kettlebell deadlift"],"progressions":[],"safety":"Avoid it if upright rows bother your shoulders.","video":null,"diagram":"","notes":""},{"id":"renegade","name":"Renegade row","aliases":["Plank row","Dumbbell renegade row"],"training_type":"Strength","tags":["Compound","Core","Home-friendly","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Rhomboids"],"secondary_muscles":["Core","Chest","Triceps","Rear delts"],"movement_pattern":"Horizontal pull","equipment":["Hex dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"6–8 / side","form_cues":["Get into a push-up position holding hex dumbbells, feet wide.","Row one dumbbell to your hip without twisting.","Set it down softly and alternate."],"common_mistakes":["Hips rotating","Feet too close together"],"regressions":["Bent-over dumbbell row","Plank"],"progressions":["Man maker"],"safety":"Use hex dumbbells so they can't roll and catch your wrists.","video":null,"diagram":"","notes":"Add a push-up between rows for a harder version."},{"id":"sbrow","name":"Sandbag bent-over row","aliases":[],"training_type":"Strength","tags":["Back","Compound","Home-friendly","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Rhomboids"],"secondary_muscles":["Biceps","Rear delts","Forearms"],"movement_pattern":"Horizontal pull","equipment":["Sandbag"],"req":"sandbag","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Hinge forward with a flat back, holding the bag's handles.","Row the bag to your belly button.","Lower it slowly without losing your hinge."],"common_mistakes":["Standing up during the row","Rounding the back"],"regressions":["Band seated row"],"progressions":["Barbell bent-over row"],"safety":"Keep the spine neutral and brace before each rep.","video":null,"diagram":"","notes":""},{"id":"sbclean","name":"Sandbag clean","aliases":["Sandbag lap clean"],"training_type":"Strength","tags":["Compound","Power","Strength","Strongman"],"muscle_group":"Back","primary_muscles":["Glutes","Hamstrings","Upper back"],"secondary_muscles":["Biceps","Forearms","Quadriceps"],"movement_pattern":"Hinge","equipment":["Sandbag"],"req":"sandbag","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"5–8","form_cues":["Straddle the bag and grip the sides or handles.","Drive hips through to pop the bag up.","Drop under it and catch it on your forearms at the chest."],"common_mistakes":["Pulling with a rounded back","Curling the bag up with the arms"],"regressions":["Kettlebell clean"],"progressions":["Sandbag shouldering"],"safety":"Start light; awkward loads need a tight, neutral spine.","video":null,"diagram":"","notes":""},{"id":"arnold","name":"Arnold press","aliases":["Arnold dumbbell press"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Side delts"],"secondary_muscles":["Triceps","Upper traps"],"movement_pattern":"Vertical push","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Start with dumbbells at chin height, palms facing you.","Rotate palms forward as you press overhead.","Reverse the turn on the way down."],"common_mistakes":["Rushing the rotation","Arching the lower back"],"regressions":["Seated dumbbell shoulder press"],"progressions":[],"safety":"Go lighter than your normal press; the rotation loads the shoulder more.","video":null,"diagram":"dbpress","notes":"Usually done seated on an upright bench; standing works too."},{"id":"bandextrot","name":"Band external rotation","aliases":["Band shoulder external rotation"],"training_type":"Strength","tags":["Isolation","Rehab","Shoulders","Strength","Warm-up"],"muscle_group":"Shoulders","primary_muscles":["Rotator cuff (infraspinatus)"],"secondary_muscles":["Rear delts"],"movement_pattern":"Isolation","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":3,"reps":"15 / side","form_cues":["Anchor the band at elbow height.","Tuck the elbow at your side, a towel helps.","Rotate the forearm outward, keeping the elbow still."],"common_mistakes":["Elbow drifting away from the body","Using too strong a band"],"regressions":[],"progressions":["Band face pull"],"safety":"Use a light band and stop if you feel pinching.","video":null,"diagram":"","notes":""},{"id":"bandfacepull","name":"Band face pull","aliases":[],"training_type":"Strength","tags":["Home-friendly","Rehab","Shoulders","Strength","Warm-up"],"muscle_group":"Shoulders","primary_muscles":["Rear delts"],"secondary_muscles":["Rotator cuff","Middle traps"],"movement_pattern":"Horizontal pull","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"15–20","form_cues":["Anchor the band at face height.","Pull the band toward your forehead, elbows high.","Finish with hands beside your ears, thumbs back."],"common_mistakes":["Elbows dropping below shoulders","Leaning back"],"regressions":["Band pull-apart"],"progressions":["Rope face pull"],"safety":"Keep it light and pain-free in the shoulder.","video":null,"diagram":"","notes":""},{"id":"bandintrot","name":"Band internal rotation","aliases":[],"training_type":"Strength","tags":["Isolation","Rehab","Shoulders","Strength"],"muscle_group":"Shoulders","primary_muscles":["Rotator cuff (subscapularis)"],"secondary_muscles":["Chest"],"movement_pattern":"Isolation","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":3,"reps":"15 / side","form_cues":["Anchor the band at elbow height on your working side.","Keep the elbow tucked at 90 degrees.","Rotate the forearm in across your stomach."],"common_mistakes":["Twisting the torso","Letting the elbow lift"],"regressions":[],"progressions":[],"safety":"Light resistance only; this is a control drill.","video":null,"diagram":"","notes":""},{"id":"bandlateral","name":"Band lateral raise","aliases":[],"training_type":"Strength","tags":["Home-friendly","Isolation","Shoulders","Strength"],"muscle_group":"Shoulders","primary_muscles":["Side delts"],"secondary_muscles":["Upper traps"],"movement_pattern":"Isolation","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Stand on the band with handles at your sides.","Raise arms out to shoulder height with soft elbows.","Lower slowly and keep shoulders away from ears."],"common_mistakes":["Shrugging the weight up","Raising above shoulder height"],"regressions":[],"progressions":["Dumbbell lateral raise"],"safety":"Use a light band; the tension is highest at the top.","video":null,"diagram":"","notes":""},{"id":"bandohp","name":"Band overhead press","aliases":["Resistance band shoulder press"],"training_type":"Strength","tags":["Compound","Home-friendly","Shoulders","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Side delts"],"secondary_muscles":["Triceps","Upper traps"],"movement_pattern":"Vertical push","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Stand on the band and hold handles at shoulder height.","Press straight up until arms are locked out.","Keep ribs down and glutes tight."],"common_mistakes":["Arching the lower back","Pressing forward instead of up"],"regressions":[],"progressions":["Seated dumbbell shoulder press"],"safety":"Stand squarely on the band so it can't slip out from underfoot.","video":null,"diagram":"","notes":""},{"id":"bandpullapart","name":"Band pull-apart","aliases":[],"training_type":"Strength","tags":["Home-friendly","Isolation","Rehab","Shoulders","Strength","Warm-up"],"muscle_group":"Shoulders","primary_muscles":["Rear delts"],"secondary_muscles":["Rhomboids","Middle traps"],"movement_pattern":"Horizontal pull","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"15–20","form_cues":["Hold the band at shoulder height with straight arms.","Pull the band apart until it touches your chest.","Squeeze shoulder blades together, then return slowly."],"common_mistakes":["Bending the elbows too much","Arching the lower back"],"regressions":[],"progressions":["Band face pull"],"safety":"Use a light band; this should never pinch the front of the shoulder.","video":null,"diagram":"revfly","notes":"Great as a warm-up before pressing."},{"id":"banduprow","name":"Band upright row","aliases":[],"training_type":"Strength","tags":["Home-friendly","Shoulders","Strength"],"muscle_group":"Shoulders","primary_muscles":["Side delts","Upper traps"],"secondary_muscles":["Biceps"],"movement_pattern":"Vertical pull","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Stand on the band, hands shoulder-width.","Lead with the elbows up to chest height.","Lower slowly and keep the bar path close."],"common_mistakes":["Pulling hands above chest","Narrow grip that pinches shoulders"],"regressions":[],"progressions":["Cable upright row"],"safety":"Stop below shoulder height if you feel a pinch.","video":null,"diagram":"","notes":""},{"id":"dbrearfly","name":"Bent-over dumbbell reverse fly","aliases":["Bent-over rear delt raise","Rear delt fly"],"training_type":"Strength","tags":["Home-friendly","Hypertrophy","Isolation","Strength"],"muscle_group":"Shoulders","primary_muscles":["Rear delts"],"secondary_muscles":["Rhomboids","Middle traps"],"movement_pattern":"Isolation","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Hinge forward until your chest is nearly parallel to the floor.","With soft elbows, raise the weights out wide.","Pause, then lower without letting your torso bob."],"common_mistakes":["Using the back to swing the weights","Squeezing the shoulder blades instead of moving the arms"],"regressions":["Band pull-apart"],"progressions":["Chest-supported dumbbell reverse fly"],"safety":"Keep a flat back and brace; sit down on a bench if your lower back tires.","video":null,"diagram":"","notes":""},{"id":"kbbottomup","name":"Bottoms-up kettlebell press","aliases":["Bottom-up KB press"],"training_type":"Strength","tags":["Rehab","Shoulders","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Rotator cuff"],"secondary_muscles":["Forearms","Triceps"],"movement_pattern":"Vertical push","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":true,"sets":3,"reps":"5 / side","form_cues":["Hold the bell upside down, crushing the handle.","Keep the wrist straight and bell balanced.","Press slowly straight up and lower with control."],"common_mistakes":["Loose grip causing the bell to tip","Pressing too fast"],"regressions":["Kettlebell overhead press"],"progressions":[],"safety":"Use a light bell; it can tip suddenly, so keep your head out of its path.","video":null,"diagram":"","notes":""},{"id":"dbcuban","name":"Dumbbell Cuban press","aliases":["Cuban rotation press"],"training_type":"Strength","tags":["Rehab","Strength","Warm-up"],"muscle_group":"Shoulders","primary_muscles":["Rotator cuff","Rear delts"],"secondary_muscles":["Side delts","Middle traps"],"movement_pattern":"Vertical push","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Upright-row light dumbbells until elbows reach shoulder height.","Rotate forearms up so your hands are over your elbows.","Press overhead, then reverse each step."],"common_mistakes":["Going too heavy","Dropping elbows during the rotation"],"regressions":["Side-lying dumbbell external rotation"],"progressions":[],"safety":"Use very light weights; this is a shoulder-health drill, not a strength test.","video":null,"diagram":"","notes":""},{"id":"frontraise","name":"Dumbbell front raise","aliases":["DB front raise"],"training_type":"Strength","tags":["Home-friendly","Isolation","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts"],"secondary_muscles":["Upper chest","Serratus"],"movement_pattern":"Isolation","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Hold dumbbells in front of your thighs, palms down.","Raise to eye level with straight but soft arms.","Lower slowly without swinging back."],"common_mistakes":["Leaning back to lift the weight","Raising far above head height"],"regressions":["Band front raise"],"progressions":["Plate front raise"],"safety":"Keep it light; front delts already get lots of work from pressing.","video":null,"diagram":"lateral","notes":"Alternate arms or use a neutral grip if your shoulders feel pinchy."},{"id":"lateral","name":"Dumbbell lateral raise","aliases":["Side raise","Side lateral raise"],"training_type":"Strength","tags":["Home-friendly","Hypertrophy","Isolation","Strength"],"muscle_group":"Shoulders","primary_muscles":["Side delts"],"secondary_muscles":["Upper traps","Front delts"],"movement_pattern":"Isolation","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Stand tall with a slight bend in your elbows.","Raise the weights out to the sides to shoulder height.","Lower slowly over two to three seconds."],"common_mistakes":["Swinging the body for momentum","Shrugging the shoulders up"],"regressions":["Band lateral raise"],"progressions":["Leaning single-arm lateral raise","Cable lateral raise"],"safety":"Stop at shoulder height if you get any pinching.","video":null,"diagram":"lateral","notes":""},{"id":"dbluraise","name":"Dumbbell Lu raise","aliases":["Lu Xiaojun raise"],"training_type":"Strength","tags":["Hypertrophy","Isolation","Strength"],"muscle_group":"Shoulders","primary_muscles":["Side delts","Upper traps"],"secondary_muscles":["Front delts","Serratus"],"movement_pattern":"Isolation","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Hold light dumbbells at your sides, thumbs up.","Raise straight-armed out to the side and keep going overhead.","Lower slowly along the same path."],"common_mistakes":["Going too heavy","Bending the elbows"],"regressions":["Dumbbell lateral raise"],"progressions":[],"safety":"Only take it overhead if you can do so without pain.","video":null,"diagram":"","notes":"Named after Olympic lifter Lu Xiaojun; works the top range of the shoulder."},{"id":"dbreardeltrow","name":"Dumbbell rear delt row","aliases":["Wide-elbow dumbbell row"],"training_type":"Strength","tags":["Hypertrophy","Strength"],"muscle_group":"Shoulders","primary_muscles":["Rear delts","Middle traps"],"secondary_muscles":["Rhomboids","Biceps"],"movement_pattern":"Horizontal pull","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Hinge forward with palms facing your legs or behind you.","Row with elbows flared out wide, about 70–90°.","Pull until upper arms line up with your torso."],"common_mistakes":["Pulling elbows to the hips like a lat row","Going too heavy"],"regressions":["Bent-over dumbbell reverse fly"],"progressions":["Chest-supported dumbbell row"],"safety":"Keep a neutral spine and brace your core.","video":null,"diagram":"","notes":""},{"id":"dbscaption","name":"Dumbbell scaption raise","aliases":["Scaption","Y raise standing"],"training_type":"Strength","tags":["Isolation","Rehab","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Side delts"],"secondary_muscles":["Serratus","Lower traps"],"movement_pattern":"Isolation","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Stand with thumbs pointing up.","Raise arms in a Y shape, about 30° in front of your sides.","Stop at shoulder height and lower slowly."],"common_mistakes":["Shrugging","Lifting straight out to the side"],"regressions":[],"progressions":["Dumbbell lateral raise"],"safety":"Keep it light and pain-free.","video":null,"diagram":"","notes":"Often used in shoulder rehab; the angle matches how the shoulder blade sits."},{"id":"dbuprightrow","name":"Dumbbell upright row","aliases":["DB upright row"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength"],"muscle_group":"Shoulders","primary_muscles":["Side delts","Upper traps"],"secondary_muscles":["Biceps","Front delts"],"movement_pattern":"Vertical pull","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Hold dumbbells in front of your thighs.","Lead with your elbows and lift to lower-chest height.","Lower under control."],"common_mistakes":["Pulling higher than shoulder height","Shrugging instead of lifting with the elbows"],"regressions":["Dumbbell lateral raise"],"progressions":["Dumbbell high pull"],"safety":"Stop below shoulder height if you feel a pinch in the front of the shoulder.","video":null,"diagram":"","notes":"Dumbbells let your hands move freely, which is easier on the wrists than a bar."},{"id":"dbzpress","name":"Dumbbell Z press","aliases":["Seated floor press"],"training_type":"Strength","tags":["Compound","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Side delts"],"secondary_muscles":["Triceps","Core","Upper traps"],"movement_pattern":"Vertical push","equipment":["Dumbbells","Mat"],"req":"dumbbells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":3,"reps":"6–10","form_cues":["Sit on the floor with legs straight out in front.","Sit tall without leaning back, dumbbells at shoulders.","Press overhead and lower with control."],"common_mistakes":["Rounding or leaning back","Going too heavy"],"regressions":["Seated dumbbell shoulder press"],"progressions":[],"safety":"If tight hamstrings round your back, bend your knees slightly or sit on a plate.","video":null,"diagram":"","notes":"Named after strongman Zydrunas Savickas; exposes weak core and mobility."},{"id":"dbhkpress","name":"Half-kneeling single-arm dumbbell press","aliases":["Half-kneeling DB press"],"training_type":"Strength","tags":["Rehab","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Side delts"],"secondary_muscles":["Triceps","Glutes","Obliques"],"movement_pattern":"Vertical push","equipment":["Dumbbell","Mat"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Kneel with the same-side knee down as the pressing arm.","Squeeze the down-side glute and stay tall.","Press up slightly in front of your head, then lower."],"common_mistakes":["Arching the lower back","Shifting the hips sideways"],"regressions":["Seated dumbbell shoulder press"],"progressions":["Single-arm dumbbell overhead press"],"safety":"Pad the down knee with a mat or folded towel.","video":null,"diagram":"","notes":"The kneeling stance stops you cheating with the lower back."},{"id":"kbbentpress","name":"Kettlebell bent press","aliases":["Bent press"],"training_type":"Strength","tags":["Mobility","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Obliques","Lats"],"secondary_muscles":["Hamstrings","Glutes"],"movement_pattern":"Vertical push","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":true,"sets":3,"reps":"3 / side","form_cues":["Rack the bell and push the hip out to the side.","Lean under the bell while the arm stays vertical.","Stand up beneath the locked arm."],"common_mistakes":["Pressing the bell up instead of getting under it","Losing sight of the bell"],"regressions":["Kettlebell windmill"],"progressions":[],"safety":"An advanced lift: learn it light and with coaching.","video":null,"diagram":"","notes":"Old-time strongman lift."},{"id":"kbcleanpress","name":"Kettlebell clean and press","aliases":[],"training_type":"Strength","tags":["Compound","Power","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Glutes","Hamstrings"],"secondary_muscles":["Triceps","Core"],"movement_pattern":"Vertical push","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"6 / side","form_cues":["Clean the bell to the rack.","Pause, brace, and press overhead.","Lower to rack, then let it swing back for the next clean."],"common_mistakes":["Leaning back on the press","Banging the forearm on the clean"],"regressions":["Kettlebell clean"],"progressions":["Kettlebell jerk"],"safety":"Keep the core braced throughout.","video":null,"diagram":"","notes":""},{"id":"kbhalo","name":"Kettlebell halo","aliases":[],"training_type":"Strength","tags":["Home-friendly","Mobility","Shoulders","Strength","Warm-up"],"muscle_group":"Shoulders","primary_muscles":["Shoulders"],"secondary_muscles":["Upper back","Core","Triceps"],"movement_pattern":"Mobility","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"6 / direction","form_cues":["Hold the bell upside down by the horns.","Circle it closely around your head.","Keep ribs down and hips still."],"common_mistakes":["Arching the back","Circling too far from the head"],"regressions":[],"progressions":["Kettlebell overhead press"],"safety":"Use a light bell and move slowly to avoid knocking your head.","video":null,"diagram":"","notes":"Great shoulder warm-up before pressing."},{"id":"kbjerk","name":"Kettlebell jerk","aliases":["Single-arm kettlebell jerk"],"training_type":"Strength","tags":["Endurance","Power","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Quadriceps"],"secondary_muscles":["Triceps","Core"],"movement_pattern":"Vertical push","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":true,"sets":3,"reps":"5 / side","form_cues":["Dip and drive to launch the bell.","Drop under it with a second dip to lock out.","Stand tall with the arm locked before lowering."],"common_mistakes":["Pressing out the lockout","Rushing the second dip"],"regressions":["Kettlebell push press"],"progressions":[],"safety":"Requires solid overhead mobility and wrist position.","video":null,"diagram":"","notes":"A staple of kettlebell sport."},{"id":"kbwaiter","name":"Kettlebell overhead carry","aliases":["Waiter's walk"],"training_type":"Strength","tags":["Core","Shoulders","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Core"],"secondary_muscles":["Upper traps","Obliques"],"movement_pattern":"Carry","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"cardio","unilateral":true,"sets":3,"reps":"20 m / side","form_cues":["Press the bell overhead and lock the arm.","Keep the biceps by your ear while you walk.","Stay tall; don't lean away from the bell."],"common_mistakes":["Bent elbow","Arching the lower back"],"regressions":["Kettlebell front rack carry"],"progressions":["Turkish get-up"],"safety":"Only carry overhead with full, pain-free shoulder mobility.","video":null,"diagram":"","notes":""},{"id":"kbpress","name":"Kettlebell overhead press","aliases":["Single-arm kettlebell press","KB military press"],"training_type":"Strength","tags":["Compound","Shoulders","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Triceps"],"secondary_muscles":["Upper traps","Core"],"movement_pattern":"Vertical push","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"6–8 / side","form_cues":["Start with the bell in the rack, forearm vertical.","Squeeze glutes and grip, then press straight up.","Finish with biceps by your ear, then lower to rack."],"common_mistakes":["Leaning back to finish","Flaring the elbow early"],"regressions":["Seated dumbbell shoulder press"],"progressions":["Kettlebell push press","Bottoms-up kettlebell press"],"safety":"Brace hard and don't press through shoulder pain.","video":null,"diagram":"","notes":""},{"id":"kbpushpress","name":"Kettlebell push press","aliases":[],"training_type":"Strength","tags":["Compound","Power","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Triceps"],"secondary_muscles":["Quadriceps","Glutes"],"movement_pattern":"Vertical push","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"5–8 / side","form_cues":["Dip a few centimetres by bending the knees.","Drive up with the legs to launch the bell.","Finish the lockout with the arm."],"common_mistakes":["Dipping too deep","Pressing before the legs finish"],"regressions":["Kettlebell overhead press"],"progressions":["Kettlebell jerk"],"safety":"Keep heels down in the dip and control the bell back to the rack.","video":null,"diagram":"","notes":""},{"id":"kbsnatch","name":"Kettlebell snatch","aliases":[],"training_type":"Strength","tags":["Compound","Endurance","Power","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Glutes","Hamstrings","Shoulders"],"secondary_muscles":["Upper back","Core","Forearms"],"movement_pattern":"Hinge","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":true,"sets":3,"reps":"5–8 / side","form_cues":["Swing back and drive hips explosively.","Keep the bell close and punch through at the top.","Lock out overhead with biceps by your ear."],"common_mistakes":["Letting the bell flop onto the wrist","Pressing it up instead of hip drive"],"regressions":["One-arm kettlebell swing","Kettlebell high pull"],"progressions":[],"safety":"Needs good overhead mobility; drop the bell safely if control is lost.","video":null,"diagram":"","notes":""},{"id":"kbwindmill","name":"Kettlebell windmill","aliases":[],"training_type":"Strength","tags":["Core","Mobility","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Obliques","Shoulders"],"secondary_muscles":["Hamstrings","Glutes"],"movement_pattern":"Hinge","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"5 / side","form_cues":["Lock the bell overhead, feet angled away from it.","Push the hip out and slide your free hand down the leg.","Keep eyes on the bell and the arm vertical."],"common_mistakes":["Bending the overhead arm","Twisting the chest down to the floor"],"regressions":["Bodyweight windmill"],"progressions":["Turkish get-up"],"safety":"Start light; stop if the shoulder feels unstable.","video":null,"diagram":"","notes":""},{"id":"dbleanlateral","name":"Leaning single-arm lateral raise","aliases":["Lean-away lateral raise"],"training_type":"Strength","tags":["Hypertrophy","Isolation","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Side delts"],"secondary_muscles":["Upper traps"],"movement_pattern":"Isolation","equipment":["Dumbbell","Sturdy post or rack"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"12–15 / side","form_cues":["Hold a post and lean away with your arm straight.","Raise the dumbbell out to the side to shoulder height.","Lower slowly and keep the lean steady."],"common_mistakes":["Turning it into an upright row","Swinging"],"regressions":["Dumbbell lateral raise"],"progressions":["Lying side lateral raise"],"safety":"Hold something solid that will not move when you lean on it.","video":null,"diagram":"","notes":"The lean keeps tension on the side delt at the bottom of the rep."},{"id":"sbpress","name":"Sandbag overhead press","aliases":["Sandbag clean and press"],"training_type":"Strength","tags":["Compound","Shoulders","Strength"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Triceps"],"secondary_muscles":["Core","Upper back"],"movement_pattern":"Vertical push","equipment":["Sandbag"],"req":"sandbag","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"6–8","form_cues":["Clean the bag to your chest.","Brace and press it straight overhead.","Lower it back to the chest under control."],"common_mistakes":["Leaning back","Bag rolling forward overhead"],"regressions":["Kettlebell overhead press"],"progressions":["Log press"],"safety":"Use handles if available; loose sand shifts mid-rep.","video":null,"diagram":"","notes":""},{"id":"dbextrot","name":"Side-lying dumbbell external rotation","aliases":["Side-lying external rotation"],"training_type":"Strength","tags":["Isolation","Rehab","Strength","Warm-up"],"muscle_group":"Shoulders","primary_muscles":["Rotator cuff (infraspinatus, teres minor)"],"secondary_muscles":["Rear delts"],"movement_pattern":"Isolation","equipment":["Light dumbbell","Mat"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":2,"reps":"12–15 / side","form_cues":["Lie on your side, top elbow bent 90° and pinned to your ribs.","Rotate the forearm up toward the ceiling.","Lower slowly without the elbow lifting off your side."],"common_mistakes":["Letting the elbow leave the body","Using too heavy a weight"],"regressions":["Band external rotation"],"progressions":["Dumbbell Cuban press"],"safety":"Start with 1–3 kg; stop if you feel sharp pain.","video":null,"diagram":"","notes":"A rolled towel under the elbow helps keep good position."},{"id":"dbsapress","name":"Single-arm dumbbell overhead press","aliases":["One-arm DB shoulder press"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Side delts"],"secondary_muscles":["Triceps","Obliques"],"movement_pattern":"Vertical push","equipment":["Dumbbell"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Stand tall with one dumbbell at your shoulder.","Brace your abs and press straight up without leaning.","Lower slowly back to the shoulder."],"common_mistakes":["Leaning away from the weight","Flaring the ribs"],"regressions":["Half-kneeling single-arm dumbbell press"],"progressions":["Dumbbell push press"],"safety":"Keep the free hand on your belly to feel your abs stay tight.","video":null,"diagram":"","notes":""},{"id":"dbstandpress","name":"Standing dumbbell shoulder press","aliases":["Standing DB overhead press","Dumbbell military press"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Side delts"],"secondary_muscles":["Triceps","Upper traps","Core"],"movement_pattern":"Vertical push","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Stand tall, dumbbells at shoulder height, palms forward.","Squeeze glutes and abs, then press straight overhead.","Lower with control back to your shoulders."],"common_mistakes":["Leaning back to finish the rep","Pressing the weights forward instead of up"],"regressions":["Seated dumbbell shoulder press"],"progressions":["Dumbbell push press"],"safety":"Keep your ribs down so your lower back doesn't arch.","video":null,"diagram":"","notes":""},{"id":"kbtgu","name":"Turkish get-up","aliases":["Kettlebell get-up","TGU"],"training_type":"Strength","tags":["Compound","Core","Mobility","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Core"],"secondary_muscles":["Glutes","Triceps","Hip flexors"],"movement_pattern":"Hold","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":true,"sets":3,"reps":"2–3 / side","form_cues":["Keep eyes on the bell and arm locked the whole time.","Move step by step: roll, elbow, hand, bridge, sweep, stand.","Reverse each step slowly to return to the floor."],"common_mistakes":["Bending the bell arm","Rushing transitions"],"regressions":["Half Turkish get-up"],"progressions":[],"safety":"Practise with a shoe or no weight first; never lose sight of the bell.","video":null,"diagram":"","notes":"Builds shoulder stability through the whole body."},{"id":"bandcurl","name":"Band curl","aliases":["Resistance band bicep curl"],"training_type":"Strength","tags":["Arms","Home-friendly","Hypertrophy","Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Biceps"],"secondary_muscles":["Brachialis","Forearms"],"movement_pattern":"Isolation","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Stand on the band with feet hip-width apart.","Keep elbows pinned to your sides as you curl.","Lower slowly against the band's pull."],"common_mistakes":["Swinging the torso to finish reps","Letting elbows drift forward"],"regressions":[],"progressions":["Dumbbell curl","Band hammer curl"],"safety":"Check the band for nicks or tears before every session.","video":null,"diagram":"curl","notes":"Widen your stance to make it harder."},{"id":"bandohext","name":"Band overhead triceps extension","aliases":[],"training_type":"Strength","tags":["Arms","Home-friendly","Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Triceps"],"secondary_muscles":[],"movement_pattern":"Isolation","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Anchor the band low behind you, hands overhead.","Keep elbows pointing up and close to your head.","Straighten arms fully, then lower with control."],"common_mistakes":["Elbows flaring wide","Arching the back"],"regressions":["Band pushdown"],"progressions":["Overhead dumbbell extension"],"safety":"Make sure the band is secure behind you before loading it.","video":null,"diagram":"","notes":""},{"id":"bandpush","name":"Band pushdown","aliases":["Band triceps pushdown"],"training_type":"Strength","tags":["Arms","Home-friendly","Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Triceps"],"secondary_muscles":[],"movement_pattern":"Isolation","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Anchor the band high, over a door or bar.","Keep elbows tucked at your sides.","Push down until arms are straight, then control the return."],"common_mistakes":["Elbows flaring out","Leaning over to push with body weight"],"regressions":[],"progressions":["Band overhead triceps extension"],"safety":"Make sure the door is closed and locked if using a door anchor.","video":null,"diagram":"pushdown","notes":""},{"id":"dbconc","name":"Concentration curl","aliases":["Dumbbell concentration curl"],"training_type":"Strength","tags":["Hypertrophy","Isolation","Strength","Unilateral"],"muscle_group":"Arms","primary_muscles":["Biceps"],"secondary_muscles":["Brachialis"],"movement_pattern":"Isolation","equipment":["Dumbbell","Bench or chair"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":3,"reps":"10–12 / side","form_cues":["Sit with your elbow braced on your inner thigh.","Curl the weight toward your shoulder.","Squeeze, then lower to full extension."],"common_mistakes":["Lifting the elbow off the thigh","Leaning back"],"regressions":["Dumbbell curl"],"progressions":["Dumbbell spider curl"],"safety":"Use a stable seat; any bench or chair works.","video":null,"diagram":"","notes":""}]$ex$::jsonb)
  as r(id text, name text, aliases text[], training_type text, tags text[], muscle_group text, primary_muscles text[], secondary_muscles text[], movement_pattern text, equipment text[], req text, equipment_tier smallint, difficulty text, tracking text, unilateral boolean, sets smallint, reps text, form_cues text[], common_mistakes text[], regressions text[], progressions text[], safety text, video text, diagram text, notes text)
on conflict (id) do update set name = excluded.name, aliases = excluded.aliases, training_type = excluded.training_type, tags = excluded.tags, muscle_group = excluded.muscle_group, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, movement_pattern = excluded.movement_pattern, equipment = excluded.equipment, req = excluded.req, equipment_tier = excluded.equipment_tier, difficulty = excluded.difficulty, tracking = excluded.tracking, unilateral = excluded.unilateral, sets = excluded.sets, reps = excluded.reps, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes, regressions = excluded.regressions, progressions = excluded.progressions, safety = excluded.safety, video = excluded.video, diagram = excluded.diagram, notes = excluded.notes;

insert into public.exercises (id, name, aliases, training_type, tags, muscle_group, primary_muscles, secondary_muscles, movement_pattern, equipment, req, equipment_tier, difficulty, tracking, unilateral, sets, reps, form_cues, common_mistakes, regressions, progressions, safety, video, diagram, notes)
select id, name, aliases, training_type, tags, muscle_group, primary_muscles, secondary_muscles, movement_pattern, equipment, req, equipment_tier, difficulty, tracking, unilateral, sets, reps, form_cues, common_mistakes, regressions, progressions, safety, video, diagram, notes from jsonb_to_recordset($ex$[{"id":"dbcrosshammer","name":"Cross-body hammer curl","aliases":["Pinwheel curl"],"training_type":"Strength","tags":["Hypertrophy","Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Brachialis","Brachioradialis"],"secondary_muscles":["Biceps"],"movement_pattern":"Isolation","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12 / side","form_cues":["Hold dumbbells with thumbs up.","Curl one weight across your body toward the opposite shoulder.","Lower slowly and alternate."],"common_mistakes":["Twisting the torso","Lifting the elbow forward"],"regressions":["Hammer curl"],"progressions":[],"safety":"Keep the shoulder still; only the forearm moves.","video":null,"diagram":"","notes":""},{"id":"dbcurl","name":"Dumbbell curl","aliases":["Standing DB curl","Alternating dumbbell curl"],"training_type":"Strength","tags":["Home-friendly","Hypertrophy","Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Biceps"],"secondary_muscles":["Brachialis","Forearms"],"movement_pattern":"Isolation","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Stand tall, elbows tucked at your sides, palms forward.","Curl up and squeeze at the top.","Lower slowly until your arms are fully straight."],"common_mistakes":["Swinging the torso","Letting elbows drift forward"],"regressions":["Band curl"],"progressions":["Incline dumbbell curl","Dumbbell spider curl"],"safety":"Keep wrists neutral; drop the weight if you have to swing it.","video":null,"diagram":"hammer","notes":"Curl both arms together or alternate them."},{"id":"dbpinchhold","name":"Dumbbell pinch hold","aliases":["Dumbbell head pinch","Hex dumbbell pinch grip"],"training_type":"Strength","tags":["Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Grip (thumb and fingers)"],"secondary_muscles":["Forearms"],"movement_pattern":"Hold","equipment":["Hex dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"20–30 sec","form_cues":["Grab a hex dumbbell by one end with fingers and thumb only.","Stand and hold it at your side.","Squeeze hard until time is up."],"common_mistakes":["Letting the palm touch","Holding over your feet"],"regressions":["Farmer's carry"],"progressions":[],"safety":"Hold it beside your foot, not over it, in case it slips.","video":null,"diagram":"","notes":"Pinching two plates together is a common alternative."},{"id":"dbpronsup","name":"Dumbbell pronation and supination","aliases":["Forearm rotations","Dumbbell wrist rotations"],"training_type":"Strength","tags":["Isolation","Rehab","Strength"],"muscle_group":"Arms","primary_muscles":["Pronators","Supinators"],"secondary_muscles":["Brachioradialis"],"movement_pattern":"Rotation","equipment":["Dumbbell"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":2,"reps":"12–15 / side","form_cues":["Rest your forearm on your thigh, hold one end of a dumbbell.","Slowly rotate palm up, then palm down.","Keep the forearm still the whole time."],"common_mistakes":["Moving the elbow","Using a weight that's too heavy"],"regressions":[],"progressions":[],"safety":"Holding further from the end makes it harder; start close.","video":null,"diagram":"","notes":"A hammer works if you don't have a light dumbbell."},{"id":"dbrevcurl","name":"Dumbbell reverse curl","aliases":["Overhand dumbbell curl"],"training_type":"Strength","tags":["Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Brachioradialis","Brachialis"],"secondary_muscles":["Biceps","Wrist extensors"],"movement_pattern":"Isolation","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–15","form_cues":["Hold dumbbells with palms facing down.","Curl up keeping wrists straight.","Lower slowly."],"common_mistakes":["Letting wrists drop","Swinging"],"regressions":["Hammer curl"],"progressions":["Zottman curl"],"safety":"Go light; the overhand grip limits the load.","video":null,"diagram":"","notes":""},{"id":"dbkickback","name":"Dumbbell triceps kickback","aliases":["Triceps kickback"],"training_type":"Strength","tags":["Home-friendly","Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Triceps"],"secondary_muscles":["Rear delts"],"movement_pattern":"Isolation","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Hinge forward and pin upper arms by your sides.","Straighten your elbows to push the weights back.","Pause at full lockout, then lower slowly."],"common_mistakes":["Swinging the upper arm","Not reaching full lockout"],"regressions":["Band pushdown"],"progressions":["Rope pushdown"],"safety":"Keep your back flat; support one hand on a bench if needed.","video":null,"diagram":"","notes":"Can be done one arm at a time with a hand on a bench."},{"id":"dbwaitercurl","name":"Dumbbell waiter curl","aliases":["Waiter's curl"],"training_type":"Strength","tags":["Hypertrophy","Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Biceps"],"secondary_muscles":["Brachialis","Forearms"],"movement_pattern":"Isolation","equipment":["Dumbbell"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Cup one end of a dumbbell in both palms, like a tray.","Curl it up keeping elbows by your sides.","Lower slowly without the dumbbell tipping."],"common_mistakes":["Swinging","Letting elbows flare"],"regressions":["Dumbbell curl"],"progressions":[],"safety":"Hold the dumbbell securely so it can't slip out.","video":null,"diagram":"","notes":"Keeps the biceps under tension at the top."},{"id":"fingerext","name":"Finger extension with band","aliases":["Rubber band finger extension"],"training_type":"Strength","tags":["Arms","Home-friendly","Isolation","Rehab","Strength"],"muscle_group":"Arms","primary_muscles":["Forearm extensors"],"secondary_muscles":["Hand intrinsics"],"movement_pattern":"Isolation","equipment":["Small rubber band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"20–25 / hand","form_cues":["Loop a band around all fingers and the thumb.","Spread fingers wide against the band.","Return slowly and repeat."],"common_mistakes":["Using too thick a band","Moving through a tiny range"],"regressions":[],"progressions":["Hand gripper squeeze"],"safety":"Ease off if you feel joint pain.","video":null,"diagram":"","notes":"Balances out gripper and climbing work; helps keep elbows healthy."},{"id":"hammer","name":"Hammer curl","aliases":["Dumbbell hammer curl","Neutral-grip curl"],"training_type":"Strength","tags":["Home-friendly","Hypertrophy","Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Brachialis","Brachioradialis"],"secondary_muscles":["Biceps"],"movement_pattern":"Isolation","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Hold dumbbells with palms facing each other.","Curl up keeping thumbs on top.","Lower under control to full extension."],"common_mistakes":["Swinging","Letting the wrists bend"],"regressions":["Band curl"],"progressions":["Cross-body hammer curl"],"safety":"Keep elbows pinned to your sides.","video":null,"diagram":"hammer","notes":""},{"id":"