ary_muscles":["Wrist extensors"],"secondary_muscles":["Brachioradialis"],"movement_pattern":"Isolation","equipment":["Dumbbells","Bench or knee support"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"15–20","form_cues":["Rest forearms on your thighs, palms down, wrists off the edge.","Lift the backs of your hands toward the ceiling.","Lower slowly."],"common_mistakes":["Going too heavy","Moving the forearm"],"regressions":[],"progressions":["Dumbbell reverse curl"],"safety":"Very light weights are enough; this can help with tennis elbow rehab.","video":null,"diagram":"","notes":""},{"id":"dbsaohext","name":"Single-arm overhead dumbbell extension","aliases":["One-arm overhead triceps extension"],"training_type":"Strength","tags":["Isolation","Strength","Unilateral"],"muscle_group":"Arms","primary_muscles":["Triceps (long head)"],"secondary_muscles":[],"movement_pattern":"Isolation","equipment":["Dumbbell"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"10–12 / side","form_cues":["Hold a dumbbell overhead, arm straight.","Lower it behind your head, elbow pointing up.","Extend back up; support the elbow with your free hand if needed."],"common_mistakes":["Elbow drifting out","Going too heavy"],"regressions":["Overhead dumbbell extension"],"progressions":[],"safety":"Lower slowly to protect the elbow.","video":null,"diagram":"","notes":""},{"id":"fatgripcurl","name":"Thick-grip dumbbell curl","aliases":["Fat grip curl"],"training_type":"Strength","tags":["Arms","Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Biceps","Forearm flexors"],"secondary_muscles":["Brachioradialis"],"movement_pattern":"Isolation","equipment":["Thick bar grips","Dumbbells"],"req":"fatgrips,dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Fit the thick grips and hold the dumbbells hard.","Curl up with elbows pinned to your sides.","Lower slowly without losing your crush grip."],"common_mistakes":["Swinging","Wrists curling back"],"regressions":["Dumbbell curl"],"progressions":[],"safety":"Use about 20–30% less weight than your normal curl.","video":null,"diagram":"","notes":""},{"id":"fatgriphold","name":"Thick-grip dumbbell hold","aliases":["Fat grip hold"],"training_type":"Strength","tags":["Arms","Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Forearm flexors"],"secondary_muscles":["Traps","Hand intrinsics"],"movement_pattern":"Hold","equipment":["Thick bar grips","Dumbbells"],"req":"fatgrips,dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"20–40 sec","form_cues":["Fit thick grips over the handles.","Deadlift the dumbbells and stand tall.","Crush the handles and hold for time."],"common_mistakes":["Shrugging the shoulders","Letting the thumb slip"],"regressions":["Farmer's carry"],"progressions":["Axle deadlift"],"safety":"Set the dumbbells down before your grip fully fails.","video":null,"diagram":"","notes":""},{"id":"wristcurl","name":"Wrist curl","aliases":["Dumbbell wrist curl","Seated wrist curl"],"training_type":"Strength","tags":["Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Wrist flexors"],"secondary_muscles":["Grip"],"movement_pattern":"Isolation","equipment":["Dumbbells","Bench or knee support"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"15–20","form_cues":["Rest forearms on your thighs or a bench, palms up, wrists off the edge.","Let the dumbbells roll down toward your fingers.","Curl your wrists up as high as you can."],"common_mistakes":["Lifting the forearms","Bouncing"],"regressions":[],"progressions":["Wrist roller"],"safety":"Use light weights and smooth reps.","video":null,"diagram":"","notes":""},{"id":"wristroller","name":"Wrist roller","aliase