 lifting off the floor","Letting the band snap back"],"regressions":[],"progressions":["Lying leg curl"],"safety":"Anchor the band firmly to something heavy and low.","video":null,"diagram":"","notes":""},{"id":"bandsquat","name":"Band squat","aliases":["Resistance band squat"],"training_type":"Strength","tags":["Compound","Home-friendly","Legs","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Adductors","Core"],"movement_pattern":"Squat","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Stand on the band, handles at shoulders.","Sit hips back and down, knees tracking toes.","Drive through the whole foot to stand tall."],"common_mistakes":["Knees caving in","Heels lifting"],"regressions":["Bodyweight squat"],"progressions":["Goblet squat"],"safety":"Keep the band under the mid-foot so it can't fly out.","video":null,"diagram":"","notes":""},{"id":"stepup","name":"Box step-up","aliases":["Step-up","Dumbbell step-up"],"training_type":"Strength","tags":["Home-friendly","Legs","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Calves","Core"],"movement_pattern":"Lunge","equipment":["Plyo box or sturdy bench","Dumbbells (optional)"],"req":"plyobox|flatbench|adjbench","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":3,"reps":"10 / leg","form_cues":["Put your whole foot on the box.","Drive up through the front heel, not the back toe.","Step down slowly under control."],"common_mistakes":["Pushing off the back foot","Knee caving inward","Box too high for your hip mobility"],"regressions":["Low step-up","Bodyweight step-up"],"progressions":["Dumbbell step-up","Barbell step-up","Lateral step-up"],"safety":"Use a stable box that can't slide; start with knee height or lower.","video":null,"diagram":"splitsquat","notes":"Hold dumbbells at your sides to add load."},{"id":"kbfrontsq","name":"Double kettlebell front squat","aliases":["Double KB front squat"],"training_type":"Strength","tags":["Compound","Hypertrophy","Legs","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Core","Upper back"],"movement_pattern":"Squat","equipment":["2 kettlebells"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"6–10","form_cues":["Clean both bells to the rack, elbows tucked.","Squat to depth keeping the chest up.","Drive up without letting the bells pull you forward."],"common_mistakes":["Elbows flaring and chest dropping","Knees caving"],"regressions":["Goblet squat"],"progressions":["Front squat"],"safety":"Clean the bells into position carefully; set them down rather than drop them.","video":null,"diagram":"","notes":""},{"id":"kbrdl","name":"Double kettlebell Romanian deadlift","aliases":["Double KB RDL"],"training_type":"Strength","tags":["Compound","Hypertrophy","Legs","Strength"],"muscle_group":"Legs","primary_muscles":["Hamstrings","Glutes"],"secondary_muscles":["Lower back","Forearms"],"movement_pattern":"Hinge","equipment":["2 kettlebells"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Hold a bell in each hand at your thighs.","Push hips back with soft knees until hamstrings stretch.","Squeeze glutes to stand up."],"common_mistakes":["Rounding the back","Bending knees too much"],"regressions":["Kettlebell deadlift"],"progressions":["Barbell Romanian deadlift"],"safety":"Keep bells close to the legs throughout.","video":null,"diagram":"","notes":""},{"id":"dbcalf","name":"Dumbbell calf raise","aliases":["Standing dumbbell calf raise"],"training_type":"Strength","tags":["Home-friendly","Isolation","Strength"],"muscle_group":"Legs","primary_muscles":["Calves (gastrocnemius)"],"se