ilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Stand on a low step holding dumbbells.","Step back off it and sink deep.","Drive through the front foot to step back up."],"common_mistakes":["Using too high a step","Wobbly front knee"],"regressions":["Dumbbell reverse lunge"],"progressions":["Bulgarian split squat"],"safety":"Use a stable step no higher than about 10 cm.","video":null,"diagram":"","notes":"The extra depth stretches the glutes more than a normal lunge."},{"id":"dblunge","name":"Dumbbell forward lunge","aliases":["DB lunge"],"training_type":"Strength","tags":["Home-friendly","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Adductors"],"movement_pattern":"Lunge","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Stand tall, dumbbells at your sides.","Step forward and lower until both knees bend about 90°.","Push off the front foot back to standing."],"common_mistakes":["Front knee caving inward","Stepping too short"],"regressions":["Dumbbell reverse lunge"],"progressions":["Dumbbell walking lunge"],"safety":"Step far enough that your front heel stays down.","video":null,"diagram":"","notes":""},{"id":"dbfrontsquat","name":"Dumbbell front squat","aliases":["Front-rack dumbbell squat"],"training_type":"Strength","tags":["Compound","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Core","Upper back","Adductors"],"movement_pattern":"Squat","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Rest one end of each dumbbell on your shoulders, elbows high.","Squat down keeping your torso upright.","Drive up without letting the elbows drop."],"common_mistakes":["Elbows dropping","Rounding the upper back"],"regressions":["Goblet squat"],"progressions":["Dumbbell thruster","Front squat"],"safety":"Brace hard; the weight sits on your shoulders, so keep a tight upper back.","video":null,"diagram":"","notes":""},{"id":"dblatlunge","name":"Dumbbell lateral lunge","aliases":["Side lunge"],"training_type":"Strength","tags":["Home-friendly","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Adductors","Quadriceps","Glutes"],"secondary_muscles":["Hamstrings"],"movement_pattern":"Lunge","equipment":["Dumbbell"],"req":"dumbbells|kettlebells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Hold a dumbbell at your chest.","Step wide to the side and sit back into that hip.","Keep the other leg straight, then push back to centre."],"common_mistakes":["Knee caving inward","Heel lifting"],"regressions":["Bodyweight lateral lunge"],"progressions":["Dumbbell cossack squat"],"safety":"Keep toes pointing forward or slightly out.","video":null,"diagram":"","notes":""},{"id":"dbohlunge","name":"Dumbbell overhead walking lunge","aliases":["Overhead lunge"],"training_type":"Strength","tags":["Balance","Compound","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Shoulders","Core","Upper back"],"movement_pattern":"Lunge","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":true,"sets":3,"reps":"8 / side","form_cues":["Press dumbbells overhead and lock your arms.","Walk forward in lunges keeping your arms vertical.","Keep ribs down and steps controlled."],"common_mistakes":["Arms drifting forward","Arching the back"],"regressions":["Dumbbell walking lunge"],"progressions":[],"safety":"Use light weights; lower them with control if you lose position.","video":null,"diagram":"","notes":"Single-arm overhead version is a common CrossFit option."},{"id":"dbrevlunge","name":"Dumbbell reverse lunge","aliases":["Backward lunge"],"training_type":"Strength","tags":["Home-friendly","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Adductors"],"movement_pattern":"Lunge","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Stand tall, dumbbells at your sides.","Step back and lower your back knee toward the floor.","Drive through the front heel to return."],"common_mistakes":["Leaning forward too much","Landing on the back knee"],"regressions":["Dumbbell split squat"],"progressions":["Dumbbell deficit reverse lunge"],"safety":"Easier on the knees than forward lunges.","video":null,"diagram":"","notes":""},{"id":"dbrdl","name":"Dumbbell Romanian deadlift","aliases":["DB RDL","Dumbbell stiff-leg deadlift"],"training_type":"Strength","tags":["Compound","Home-friendly","Hypertrophy","Strength"],"muscle_group":"Legs","primary_muscles":["Hamstrings","Glutes"],"secondary_muscles":["Lower back","Forearms"],"movement_pattern":"Hinge","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Stand tall, soft knees, dumbbells in front of your thighs.","Push your hips back and slide the weights down your legs.","Stop at a deep hamstring stretch, then drive hips forward."],"common_mistakes":["Squatting the weight down","Rounding the back to go lower"],"regressions":["Dumbbell deadlift"],"progressions":["Dumbbell B-stance Romanian deadlift","Barbell Romanian deadlift"],"safety":"Only go as low as you can with a flat back.","video":null,"diagram":"","notes":"Strict stiff-leg version: knees nearly straight and weights to the floor."},{"id":"dbsplitsquat","name":"Dumbbell split squat","aliases":["Static lunge"],"training_type":"Strength","tags":["Home-friendly","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Adductors","Hamstrings"],"movement_pattern":"Lunge","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Stand in a long split stance with dumbbells at your sides.","Lower your back knee straight down toward the floor.","Drive through the front foot to come up; finish all reps then switch."],"common_mistakes":["Front heel lifting","Stance too short"],"regressions":["Bodyweight split squat"],"progressions":["Bulgarian split squat"],"safety":"Pad the floor under your back knee if it touches.","video":null,"diagram":"","notes":""},{"id":"dbsquat","name":"Dumbbell squat","aliases":["Dumbbell squat at sides","DB suitcase squat"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Adductors","Hamstrings","Forearms"],"movement_pattern":"Squat","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Hold dumbbells at your sides, feet shoulder-width.","Squat down keeping your chest up and knees over toes.","Stand by pushing the floor away."],"common_mistakes":["Rounding forward","Knees caving in"],"regressions":["Goblet squat"],"progressions":["Dumbbell front squat"],"safety":"Keep the weights hanging straight; don't let them hit your knees.","video":null,"diagram":"","notes":""},{"id":"dbsumo","name":"Dumbbell sumo squat","aliases":["Plié squat","Sumo goblet squat"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength"],"muscle_group":"Legs","primary_muscles":["Adductors","Glutes","Quadriceps"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Squat","equipment":["Dumbbell"],"req":"dumbbells|kettlebells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Stand wide, toes turned out, one dumbbell hanging between your legs.","Push knees out and sit straight down.","Squeeze your glutes to stand up."],"common_mistakes":["Knees caving in","Leaning forward"],"regressions":["Bodyweight squat"],"progressions":["Dumbbell sumo deadlift high pull"],"safety":"Stand on two plates or steps if you want the dumbbell to go deeper.","video":null,"diagram":"","notes":""},{"id":"dbtiptoewalk","name":"Dumbbell tiptoe farmer's walk","aliases":["Farmer's walk on toes","Calf walk"],"training_type":"Strength","tags":["Endurance","Strength"],"muscle_group":"Legs","primary_muscles":["Calves"],"secondary_muscles":["Grip","Upper traps","Core"],"movement_pattern":"Carry","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"20–30 m","form_cues":["Pick up dumbbells and rise onto the balls of your feet.","Walk with short steps without letting heels touch.","Stay tall and set the weights down with control."],"common_mistakes":["Heels dropping","Leaning forward"],"regressions":["Dumbbell calf raise"],"progressions":[],"safety":"Use moderate weights; rolling an ankle is the main risk.","video":null,"diagram":"","notes":""},{"id":"dbwalklunge","name":"Dumbbell walking lunge","aliases":["Walking lunges with dumbbells"],"training_type":"Strength","tags":["Endurance","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Adductors","Grip"],"movement_pattern":"Lunge","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"10 / side","form_cues":["Hold dumbbells at your sides and step forward into a lunge.","Lower the back knee close to the floor.","Drive forward into the next step without pausing upright."],"common_mistakes":["Knees caving in","Steps too short"],"regressions":["Dumbbell forward lunge"],"progressions":["Dumbbell overhead walking lunge"],"safety":"Make sure you have a clear path.","video":null,"diagram":"","notes":""},{"id":"kbcossack","name":"Goblet Cossack squat","aliases":["Kettlebell Cossack squat"],"training_type":"Strength","tags":["Legs","Mobility","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Adductors","Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Squat","equipment":["Kettlebell or dumbbell"],"req":"kettlebells|dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"6 / side","form_cues":["Take a very wide stance holding the bell at your chest.","Shift and sit deep into one hip, other leg straight.","Lift the straight-leg toes up and keep the heel down."],"common_mistakes":["Lifting the bent-leg heel","Rounding the back"],"regressions":["Lateral lunge"],"progressions":[],"safety":"Work within your hip range; go only as deep as you can control.","video":null,"diagram":"","notes":""},{"id":"kbgobrevlunge","name":"Goblet reverse lunge","aliases":["Kettlebell goblet reverse lunge"],"training_type":"Strength","tags":["Home-friendly","Legs","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Lunge","equipment":["Kettlebell or dumbbell"],"req":"kettlebells|dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":3,"reps":"8 / side","form_cues":["Hold the bell at your chest.","Step back and lower the back knee softly.","Push through the front foot to return."],"common_mistakes":["Front knee caving","Stepping too short"],"regressions":["Bodyweight reverse lunge"],"progressions":["Walking lunge"],"safety":"Use a support nearby if balance is an issue.","video":null,"diagram":"","notes":""},{"id":"goblet","name":"Goblet squat","aliases":["Dumbbell goblet squat","Kettlebell goblet squat"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Adductors","Core","Upper back"],"movement_pattern":"Squat","equipment":["Dumbbell"],"req":"dumbbells|kettlebells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Hold one dumbbell vertically against your chest.","Sit down between your knees, chest tall.","Drive up through your whole foot."],"common_mistakes":["Heels lifting","Knees caving in"],"regressions":["Bodyweight squat","Box squat"],"progressions":["Dumbbell front squat","Front squat"],"safety":"Keep your heels down; stop if your knees hurt.","video":null,"diagram":"goblet","notes":""},{"id":"dbheelsquat","name":"Heels-elevated dumbbell squat","aliases":["Cyclist squat","Heel-raised goblet squat"],"training_type":"Strength","tags":["Hypertrophy","Isolation","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps"],"secondary_muscles":["Glutes","Adductors"],"movement_pattern":"Squat","equipment":["Dumbbells","Wedge, plate or step"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"10–15","form_cues":["Put your heels on a wedge or small plate, feet close.","Hold dumbbells at your sides or one at your chest.","Sink straight down letting knees travel forward."],"common_mistakes":["Leaning forward","Bouncing out of the bottom"],"regressions":["Goblet squat"],"progressions":["Dumbbell front squat"],"safety":"Make sure the heel support can't slide out.","video":null,"diagram":"","notes":"Raised heels shift work to the quads; a weight plate is a handy wedge."},{"id":"kbdl","name":"Kettlebell deadlift","aliases":[],"training_type":"Strength","tags":["Compound","Home-friendly","Legs","Strength"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings"],"secondary_muscles":["Lower back","Quadriceps","Forearms"],"movement_pattern":"Hinge","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Stand with the bell between your feet.","Push hips back and grip it with a flat back.","Stand tall by driving hips forward."],"common_mistakes":["Rounding the back","Squatting the weight up"],"regressions":[],"progressions":["Kettlebell swing","Deadlift"],"safety":"Keep the bell close to you and the spine neutral.","video":null,"diagram":"","notes":"Teaches the hinge before learning swings."},{"id":"kbthruster","name":"Kettlebell thruster","aliases":["Double kettlebell thruster"],"training_type":"Strength","tags":["Compound","Endurance","Power","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Shoulders"],"secondary_muscles":["Triceps","Core"],"movement_pattern":"Squat","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Squat with the bell(s) in the rack.","Drive up out of the squat.","Use that momentum to press overhead."],"common_mistakes":["Pressing before standing","Chest dropping in the squat"],"regressions":["Goblet squat"],"progressions":[],"safety":"Keep heels down and lower the bells back to the rack under control.","video":null,"diagram":"","notes":""},{"id":"mblungetwist","name":"Medicine ball lunge with twist","aliases":["Lunge with rotation"],"training_type":"Strength","tags":["Core","Legs","Strength","Warm-up"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Obliques","Shoulders"],"movement_pattern":"Lunge","equipment":["Medicine ball"],"req":"medball","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":3,"reps":"8 / side","form_cues":["Hold the ball at chest height, arms extended.","Lunge forward, then rotate toward the front leg.","Turn back to centre before standing up."],"common_mistakes":["Front knee drifting inward when you rotate","Rushing the twist"],"regressions":["Bodyweight reverse lunge"],"progressions":[],"safety":"Rotate through the upper back, not the knee.","video":null,"diagram":"","notes":""},{"id":"mbohlunge","name":"Medicine ball overhead lunge","aliases":["Overhead med ball walking lunge"],"training_type":"Strength","tags":["Core","Legs","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Shoulders","Core"],"movement_pattern":"Lunge","equipment":["Medicine ball"],"req":"medball","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"8 / side","form_cues":["Hold the ball overhead with arms locked.","Step forward and lower the back knee.","Keep ribs down; don't let the ball drift forward."],"common_mistakes":["Arching the lower back","Elbows bending"],"regressions":["Goblet reverse lunge"],"progressions":[],"safety":"Skip the overhead hold if your shoulders lack mobility.","video":null,"diagram":"","notes":""},{"id":"mbsquatpress","name":"Medicine ball squat to press","aliases":["Med ball squat press"],"training_type":"Strength","tags":["Compound","Endurance","Home-friendly","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Shoulders"],"secondary_muscles":["Core","Triceps"],"movement_pattern":"Squat","equipment":["Medicine ball"],"req":"medball","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Hold the ball at your chest and squat.","Stand up and press the ball overhead.","Lower it to your chest as you sit back down."],"common_mistakes":["Heels lifting","Arching the back overhead"],"regressions":["Goblet squat"],"progressions":["Kettlebell thruster"],"safety":"Control the ball overhead; don't release or throw it.","video":null,"diagram":"","notes":""},{"id":"sbbearsq","name":"Sandbag bear-hug squat","aliases":[],"training_type":"Strength","tags":["Compound","Core","Legs","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Upper back","Core"],"movement_pattern":"Squat","equipment":["Sandbag"],"req":"sandbag","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Hug the bag tight to your chest.","Sit down between your knees.","Stand up without letting the bag pull you forward."],"common_mistakes":["Rounding forward","Heels lifting"],"regressions":["Bodyweight squat"],"progressions":["Sandbag Zercher squat"],"safety":"Keep the bag close to reduce strain on the lower back.","video":null,"diagram":"","notes":""},{"id":"sbzercher","name":"Sandbag Zercher squat","aliases":["Sandbag front-hold squat"],"training_type":"Strength","tags":["Compound","Core","Legs","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Upper back","Core","Biceps"],"movement_pattern":"Squat","equipment":["Sandbag"],"req":"sandbag","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Cradle the bag in the crooks of your elbows.","Squat deep while keeping the chest up.","Drive up through the whole foot."],"common_mistakes":["Upper back rounding","Bag sliding toward the wrists"],"regressions":["Goblet squat"],"progressions":["Front squat"],"safety":"Keep elbows high and the load tight to your body.","video":null,"diagram":"","notes":""},{"id":"dbohsquat","name":"Single-arm dumbbell overhead squat","aliases":["One-arm DB overhead squat"],"training_type":"Strength","tags":["Compound","Mobility","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Shoulders","Core","Upper back"],"movement_pattern":"Squat","equipment":["Dumbbell"],"req":"dumbbells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":true,"sets":3,"reps":"5–6 / side","form_cues":["Press one dumbbell overhead and lock the arm.","Squat down keeping the arm vertical and eyes forward.","Stand up without the weight drifting."],"common_mistakes":["Bent arm","Torso twisting"],"regressions":["Goblet squat"],"progressions":[],"safety":"Practise with no weight first; it needs good shoulder mobility.","video":null,"diagram":"","notes":""},{"id":"dbslcalf","name":"Single-leg dumbbell calf raise","aliases":["One-leg calf raise"],"training_type":"Strength","tags":["Isolation","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Calves (gastrocnemius)"],"secondary_muscles":["Soleus","Foot stabilisers"],"movement_pattern":"Isolation","equipment":["Dumbbell","Step"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"10–15 / side","form_cues":["Stand on one foot on a step, dumbbell in the same-side hand.","Lower the heel slowly below the step.","Push up as high as possible and pause."],"common_mistakes":["Rushing the reps","Using the free hand to pull up"],"regressions":["Dumbbell calf raise"],"progressions":[],"safety":"Lightly hold a wall for balance only.","video":null,"diagram":"","notes":""},{"id":"vestlunge","name":"Weighted vest walking lunge","aliases":["Vest lunge"],"training_type":"Strength","tags":["Endurance","Legs","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Core","Calves"],"movement_pattern":"Lunge","equipment":["Weighted vest"],"req":"weightvest","equipment_tier":1,"difficulty":"Intermediate","tracking":"bw","unilateral":true,"sets":3,"reps":"10 / side","form_cues":["Fit the vest snugly so it doesn't bounce.","Take a long step and lower the back knee softly.","Drive through the front heel into the next step."],"common_mistakes":["Front knee caving","Leaning forward under the vest"],"regressions":["Walking lunge"],"progressions":["Sandbag shouldered lunge"],"safety":"Start with a light vest (around 5–10% of body weight).","video":null,"diagram":"","notes":"Log the vest weight as added kg."},{"id":"kbamswing","name":"American kettlebell swing","aliases":["Overhead kettlebell swing"],"training_type":"Strength","tags":["Compound","Endurance","Power","Strength"],"muscle_group":"Glutes","primary_muscles":["Glutes","Hamstrings"],"secondary_muscles":["Shoulders","Core"],"movement_pattern":"Hinge","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"12–15","form_cues":["Swing as normal but carry the bell to overhead.","Finish with biceps by ears, bell bottom up.","Keep ribs down; don't arch to reach overhead."],"common_mistakes":["Hyperextending the lower back","Pulling with the arms"],"regressions":["Kettlebell swing"],"progressions":[],"safety":"Skip it if you lack full overhead shoulder mobility.","video":null,"diagram":"","notes":"Common in CrossFit; the Russian swing is safer for most people."},{"id":"bandkick","name":"Band glute kickback","aliases":["Standing band kickback"],"training_type":"Strength","tags":["Glutes","Home-friendly","Isolation","Strength","Unilateral"],"muscle_group":"Glutes","primary_muscles":["Glute max"],"secondary_muscles":["Hamstrings"],"movement_pattern":"Extension","equipment":["Resistance band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":3,"reps":"12–15 / side","form_cues":["Loop the band around one ankle and anchor it low.","Kick the leg back from the hip, knee slightly bent.","Squeeze the glute without arching your back."],"common_mistakes":["Arching the lower back","Swinging the leg"],"regressions":[],"progressions":["Cable glute kickback"],"safety":"Hold a support to stay balanced.","video":null,"diagram":"","notes":""},{"id":"bandclam","name":"Banded clamshell","aliases":["Clam shell with band"],"training_type":"Strength","tags":["Glutes","Home-friendly","Isolation","Rehab","Strength"],"muscle_group":"Glutes","primary_muscles":["Glute medius"],"secondary_muscles":["Hip external rotators"],"movement_pattern":"Isolation","equipment":["Mini band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":3,"reps":"15 / side","form_cues":["Lie on your side, knees bent, band above knees.","Keep feet together and open the top knee.","Hold briefly at the top, then lower slowly."],"common_mistakes":["Rolling the hips backward","Rushing the reps"],"regressions":[],"progressions":["Banded lateral walk"],"safety":"Move only through a pain-free range.","video":null,"diagram":"","notes":""},{"id":"bandbridge","name":"Banded glute bridge","aliases":["Mini-band glute bridge"],"training_type":"Strength","tags":["Glutes","Home-friendly","Rehab","Strength"],"muscle_group":"Glutes","primary_muscles":["Glute max"],"secondary_muscles":["Glute medius","Hamstrings"],"movement_pattern":"Hinge","equipment":["Mini band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"15–20","form_cues":["Lie on your back with the mini band above your knees.","Press knees out against the band.","Drive hips up and squeeze glutes at the top."],"common_mistakes":["Arching the lower back at the top","Letting knees cave"],"regressions":["Glute bridge"],"progressions":["Barbell hip thrust"],"safety":"Keep ribs down to protect the lower back.","video":null,"diagram":"","notes":""},{"id":"bandwalk","name":"Banded lateral walk","aliases":["Mini-band side walk","Lateral band walk"],"training_type":"Strength","tags":["Glutes","Home-friendly","Rehab","Strength","Warm-up"],"muscle_group":"Glutes","primary_muscles":["Glute medius"],"secondary_muscles":["Glute max","Tensor fasciae latae"],"movement_pattern":"Gait","equipment":["Mini band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"12 / side","form_cues":["Place the mini band above the knees or around the ankles.","Sit into a quarter squat with chest up.","Step sideways, keeping tension on the band."],"common_mistakes":["Letting knees cave inward","Standing up tall between steps"],"regressions":["Banded clamshell"],"progressions":["Monster walk"],"safety":"Keep the band flat on the skin so it doesn't roll and pinch.","video":null,"diagram":"","notes":"Band around ankles or feet is harder than above the knees."},{"id":"dbbstance","name":"Dumbbell B-stance Romanian deadlift","aliases":["Kickstand RDL","Staggered-stance RDL"],"training_type":"Strength","tags":["Hypertrophy","Strength","Unilateral"],"muscle_group":"Glutes","primary_muscles":["Hamstrings","Glutes"],"secondary_muscles":["Lower back","Adductors"],"movement_pattern":"Hinge","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Put most weight on the front leg, back toes lightly down beside its heel.","Hinge hips back with a flat back.","Drive through the front heel to stand tall."],"common_mistakes":["Pushing off the back foot","Rotating the hips open"],"regressions":["Dumbbell Romanian deadlift"],"progressions":["Single-leg Romanian deadlift"],"safety":"Keep the back foot as a kickstand for balance only.","video":null,"diagram":"","notes":"Bridge between two-leg and single-leg RDLs."},{"id":"dbcurtsy","name":"Dumbbell curtsy lunge","aliases":["Curtsy lunge"],"training_type":"Strength","tags":["Home-friendly","Strength","Unilateral"],"muscle_group":"Glutes","primary_muscles":["Glutes (incl. glute medius)","Quadriceps"],"secondary_muscles":["Adductors"],"movement_pattern":"Lunge","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Hold dumbbells at your sides or one at your chest.","Step one leg diagonally behind the other, like a curtsy.","Lower, then drive through the front heel to return."],"common_mistakes":["Twisting the hips too much","Front knee collapsing"],"regressions":["Dumbbell reverse lunge"],"progressions":[],"safety":"Stop short of any knee discomfort; it's a twisting angle.","video":null,"diagram":"","notes":""},{"id":"dbfrogpump","name":"Dumbbell frog pump","aliases":["Weighted frog pump"],"training_type":"Strength","tags":["Home-friendly","Hypertrophy","Isolation","Strength"],"muscle_group":"Glutes","primary_muscles":["Glutes"],"secondary_muscles":["Adductors"],"movement_pattern":"Hinge","equipment":["Dumbbell","Mat"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"20–30","form_cues":["Lie down, soles of the feet together, knees out wide.","Rest a dumbbell on your hips.","Drive your hips up fast and squeeze, then lower."],"common_mistakes":["Arching the back","Heels sliding away"],"regressions":["Glute bridge"],"progressions":["Dumbbell glute bridge"],"safety":"Keep reps smooth; stop if your hips feel pinchy.","video":null,"diagram":"","notes":"A high-rep glute burnout."},{"id":"dbglutebridge","name":"Dumbbell glute bridge","aliases":["Weighted glute bridge"],"training_type":"Strength","tags":["Home-friendly","Hypertrophy","Strength"],"muscle_group":"Glutes","primary_muscles":["Glutes"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Hinge","equipment":["Dumbbell","Mat"],"req":"dumbbells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Lie on your back, knees bent, dumbbell resting on your hip crease.","Drive through your heels and lift your hips.","Squeeze your glutes hard at the top, then lower."],"common_mistakes":["Arching the lower back at the top","Pushing through the toes"],"regressions":["Glute bridge"],"progressions":["Dumbbell hip thrust"],"safety":"Hold the dumbbell with both hands and pad it with a towel.","video":null,"diagram":"","notes":""},{"id":"dbsumodl","name":"Dumbbell sumo deadlift","aliases":["Wide-stance DB deadlift"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength"],"muscle_group":"Glutes","primary_muscles":["Glutes","Adductors","Hamstrings"],"secondary_muscles":["Quadriceps","Lower back","Forearms"],"movement_pattern":"Hinge","equipment":["Dumbbell"],"req":"dumbbells|kettlebells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Stand wide, toes out, one dumbbell on end between your feet.","Sit hips back and grab the handle with a flat back.","Push the floor apart to stand up, squeezing glutes."],"common_mistakes":["Rounding the back","Knees caving in"],"regressions":["Dumbbell sumo squat"],"progressions":["Sumo deadlift"],"safety":"Stand on two plates if the dumbbell is too low to reach with a flat back.","video":null,"diagram":"","notes":""},{"id":"kbclean","name":"Kettlebell clean","aliases":["Single-arm kettlebell clean"],"training_type":"Strength","tags":["Compound","Power","Strength","Unilateral"],"muscle_group":"Glutes","primary_muscles":["Glutes","Hamstrings"],"secondary_muscles":["Biceps","Forearms","Upper back","Core"],"movement_pattern":"Hinge","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"6–8 / side","form_cues":["Hike the bell back, then drive hips forward.","Keep the elbow close and zip the bell up.","Catch it softly in the rack, wrist straight."],"common_mistakes":["Bell flipping over and banging the forearm","Casting the bell wide"],"regressions":["Kettlebell swing"],"progressions":["Kettlebell clean and press"],"safety":"Learn with a light bell; a bruised forearm means the path is too wide.","video":null,"diagram":"","notes":""},{"id":"kbswing","name":"Kettlebell swing","aliases":["Russian kettlebell swing","Two-hand swing"],"training_type":"Strength","tags":["Compound","Endurance","Glutes","Home-friendly","Power","Strength"],"muscle_group":"Glutes","primary_muscles":["Glutes","Hamstrings"],"secondary_muscles":["Core","Lower back","Forearms"],"movement_pattern":"Hinge","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"15–20","form_cues":["Hike the bell back high between your thighs.","Snap hips forward and squeeze glutes hard.","Let the bell float to chest height; arms stay relaxed."],"common_mistakes":["Squatting the swing instead of hinging","Lifting with the arms","Rounding the back"],"regressions":["Kettlebell deadlift"],"progressions":["One-arm kettlebell swing","Kettlebell snatch"],"safety":"Clear the space around you and keep a neutral spine throughout.","video":null,"diagram":"rdl","notes":""},{"id":"monsterwalk","name":"Monster walk","aliases":["Banded monster walk"],"training_type":"Strength","tags":["Glutes","Home-friendly","Strength","Warm-up"],"muscle_group":"Glutes","primary_muscles":["Glute medius","Glute max"],"secondary_muscles":["Quadriceps"],"movement_pattern":"Gait","equipment":["Mini band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"10 / side","form_cues":["Band around ankles, sit into a quarter squat.","Step diagonally forward and out with each foot.","Keep constant tension; don't let feet come together."],"common_mistakes":["Knees caving in","Standing too upright"],"regressions":["Banded lateral walk"],"progressions":[],"safety":"Keep the band flat so it doesn't roll.","video":null,"diagram":"","notes":""},{"id":"kb1swing","name":"One-arm kettlebell swing","aliases":["Single-arm swing"],"training_type":"Strength","tags":["Compound","Power","Strength","Unilateral"],"muscle_group":"Glutes","primary_muscles":["Glutes","Hamstrings"],"secondary_muscles":["Obliques","Forearms","Lats"],"movement_pattern":"Hinge","equipment":["Kettlebell"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"10 / side","form_cues":["Grip the handle with one hand, free arm relaxed.","Keep shoulders square; resist the twist.","Drive with hips and let the bell float."],"common_mistakes":["Rotating the torso","Shrugging the working shoulder"],"regressions":["Kettlebell swing"],"progressions":["Kettlebell snatch"],"safety":"Start lighter than your two-hand swing weight.","video":null,"diagram":"","notes":""},{"id":"bandabduct","name":"Seated banded hip abduction","aliases":["Seated band abduction"],"training_type":"Strength","tags":["Glutes","Home-friendly","Isolation","Strength"],"muscle_group":"Glutes","primary_muscles":["Glute medius"],"secondary_muscles":["Glute max"],"movement_pattern":"Isolation","equipment":["Mini band"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"15–20","form_cues":["Sit on the edge of a bench, band above knees.","Push knees out as far as you can.","Hold a second, then return with control."],"common_mistakes":["Using momentum","Letting feet come off the floor"],"regressions":["Banded clamshell"],"progressions":["Hip abduction machine"],"safety":"Keep the band flat on the thighs.","video":null,"diagram":"","notes":""},{"id":"dbslbridge","name":"Single-leg dumbbell glute bridge","aliases":["Single-leg weighted bridge"],"training_type":"Strength","tags":["Home-friendly","Strength","Unilateral"],"muscle_group":"Glutes","primary_muscles":["Glutes"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Hinge","equipment":["Dumbbell","Mat"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"10–12 / side","form_cues":["Lie down, one foot planted, other leg lifted, dumbbell on the working hip.","Push through the planted heel to raise your hips.","Keep the hips level as you lower."],"common_mistakes":["Hips tilting","Arching the back"],"regressions":["Dumbbell glute bridge"],"progressions":["Single-leg dumbbell hip thrust"],"safety":"Hold the dumbbell steady with your hand so it can't roll.","video":null,"diagram":"","notes":""},{"id":"slrdl","name":"Single-leg Romanian deadlift","aliases":["Dumbbell single-leg RDL","SLDL"],"training_type":"Strength","tags":["Balance","Strength","Unilateral"],"muscle_group":"Glutes","primary_muscles":["Hamstrings","Glutes"],"secondary_muscles":["Lower back","Adductors","Foot and ankle stabilisers"],"movement_pattern":"Hinge","equipment":["Dumbbells"],"req":"dumbbells|kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Stand on one leg with a soft knee, weight in the opposite hand.","Hinge forward as your free leg reaches straight back.","Keep hips square and return to standing."],"common_mistakes":["Opening the hip toward the ceiling","Rounding the back"],"regressions":["Dumbbell B-stance Romanian deadlift"],"progressions":[],"safety":"Use a wall or rack with your free hand if balance is shaky.","video":null,"diagram":"rdl","notes":""},{"id":"farmer","name":"Farmer's carry","aliases":["Dumbbell farmer's walk","Farmer's walk"],"training_type":"Strength","tags":["Compound","Endurance","Strength","Strongman"],"muscle_group":"Core","primary_muscles":["Forearms","Grip","Upper traps"],"secondary_muscles":["Core","Glutes","Quadriceps"],"movement_pattern":"Carry","equipment":["Dumbbells"],"req":"dumbbells|kettlebells|trapbar","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"30–40 m","form_cues":["Pick up heavy dumbbells with a flat back.","Stand tall, shoulders down, and walk with short steps.","Set them down with control at the end."],"common_mistakes":["Leaning or swaying","Shrugging up"],"regressions":[],"progressions":["Suitcase carry"],"safety":"Clear your path and deadlift the weights down, don't drop them.","video":null,"diagram":"","notes":"Track the weight per hand; distance or time goes in the reps."},{"id":"kbrackcarry","name":"Kettlebell front rack carry","aliases":["Double KB rack walk"],"training_type":"Strength","tags":["Compound","Core","Endurance","Strength"],"muscle_group":"Core","primary_muscles":["Core","Upper back"],"secondary_muscles":["Shoulders","Glutes"],"movement_pattern":"Carry","equipment":["2 kettlebells"],"req":"kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"cardio","unilateral":false,"sets":3,"reps":"30 m","form_cues":["Clean two bells to the rack.","Walk tall with ribs down and short steps.","Breathe behind the brace."],"common_mistakes":["Leaning back","Elbows flaring"],"regressions":["Farmer's carry"],"progressions":["Yoke carry"],"safety":"Set the bells down with a controlled hinge.","video":null,"diagram":"","notes":"Track distance in metres; one-bell version trains anti-side-bend."},{"id":"bench","name":"Barbell bench press","aliases":["Bench press","Flat bench press"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts","Triceps"],"movement_pattern":"Horizontal push","equipment":["Olympic barbell","Weight plates","Flat bench"],"req":"barbell,plates,flatbench","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"5–8","form_cues":["Eyes under the bar, shoulder blades pinched, feet planted","Lower the bar to your mid-chest with elbows at about 45°","Press up and slightly back over your shoulders"],"common_mistakes":["Bouncing the bar off the chest","Flaring elbows to 90°","Lifting hips off the bench"],"regressions":["Push-ups","Flat dumbbell press","Smith machine bench press"],"progressions":["Pause bench press","Pin press"],"safety":"Use a spotter or safety arms; never use a thumbless grip.","video":null,"diagram":"bench","notes":""},{"id":"floorpress","name":"Barbell floor press","aliases":["Floor press"],"training_type":"Strength","tags":["Compound","Home-friendly","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts"],"movement_pattern":"Horizontal push","equipment":["Olympic barbell","Weight plates","Squat rack"],"req":"barbell,plates,powerrack","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"5–8","form_cues":["Lie under the bar in a rack with knees bent","Lower until your upper arms rest on the floor","Pause, then press back to lockout"],"common_mistakes":["Slamming elbows into the floor","Bouncing out of the bottom","Flared elbows"],"regressions":["Dumbbell floor press"],"progressions":["Barbell bench press","Pin press"],"safety":"Set rack pins low enough to unrack, and use safeties.","video":null,"diagram":"","notes":"Shoulder-friendly; good lockout builder."},{"id":"crossfly","name":"Cable crossover fly","aliases":["High-to-low cable fly","Standing cable fly","Cable crossover"],"training_type":"Strength","tags":["Chest","Hypertrophy","Isolation","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts","Biceps"],"movement_pattern":"Isolation","equipment":["Cable machine","Single handles"],"req":"cablecross|functional","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Set pulleys high and take a staggered stance.","Keep a soft bend in the elbows throughout.","Sweep hands down and together in a hugging arc."],"common_mistakes":["Bending the elbows and turning it into a press.","Letting the handles yank the shoulders back at the top."],"regressions":["Pec deck fly"],"progressions":["Single-arm cable fly"],"safety":"Use a weight you can control at the stretch to protect the shoulder joint.","video":null,"diagram":"cablefly","notes":"High-to-low angle biases the lower chest."},{"id":"declinebb","name":"Decline bench press","aliases":["Decline barbell bench press"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Lower chest"],"secondary_muscles":["Triceps","Front delts"],"movement_pattern":"Horizontal push","equipment":["Olympic barbell","Weight plates","Decline bench"],"req":"barbell,plates,declinebench","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Lock your legs under the pads","Lower the bar to your lower chest","Press straight up over your shoulders"],"common_mistakes":["Bouncing the bar","Bar drifting toward the face","Flaring elbows"],"regressions":["Barbell bench press"],"progressions":["Weighted dips"],"safety":"Always use a spotter; it's hard to bail out of a decline press.","video":null,"diagram":"bench","notes":""},{"id":"declinecablefly","name":"Decline cable fly","aliases":["Decline bench cable fly"],"training_type":"Strength","tags":["Chest","Hypertrophy","Isolation","Strength"],"muscle_group":"Chest","primary_muscles":["Lower chest"],"secondary_muscles":["Front delts"],"movement_pattern":"Isolation","equipment":["Cable machine","Decline bench","Single handles"],"req":"cablecross|functional,declinebench|adjbench","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Set a decline bench between low pulleys.","Lock in your feet before taking the handles.","Sweep the handles together over the lower chest."],"common_mistakes":["Bending the elbows too much.","Letting the head hang off the bench."],"regressions":["Cable crossover fly"],"progressions":["Single-arm cable fly"],"safety":"Avoid if lying head-down makes you dizzy or you have high blood pressure.","video":null,"diagram":"","notes":"High-to-low standing fly is an easier substitute."},{"id":"dbdeclinefly","name":"Decline dumbbell fly","aliases":["Decline fly"],"training_type":"Strength","tags":["Isolation","Stren