bells,flatbench|adjbench","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Soft bend in the elbows, locked in.","Open wide until you feel a chest stretch.","Hug the weights back up over your chest."],"common_mistakes":["Bending elbows into a press","Lowering too far"],"regressions":["Dumbbell floor fly"],"progressions":["Incline dumbbell fly"],"safety":"Go light; this is a stretch move.","video":null,"diagram":"dbbench","notes":""},{"id":"dbpullover","name":"Dumbbell pullover","aliases":["DB pullover"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Lats"],"secondary_muscles":["Triceps (long head)","Serratus"],"movement_pattern":"Isolation","equipment":["Dumbbell","Flat bench"],"req":"dumbbells,flatbench|adjbench","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Lie on a bench holding one dumbbell over your chest with both hands.","With slightly bent elbows, lower it back behind your head.","Pull it back over your chest using chest and lats."],"common_mistakes":["Bending the elbows like a triceps extension","Over-arching the lower back"],"regressions":["Straight-arm pulldown"],"progressions":[],"safety":"Grip the dumbbell securely and stop before your shoulders feel strained.","video":null,"diagram":"","notes":"Lying across the bench is the classic old-school version."},{"id":"dbsqueeze","name":"Dumbbell squeeze press","aliases":["Hex press","Crush press"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Chest (inner)","Triceps"],"secondary_muscles":["Front delts"],"movement_pattern":"Horizontal push","equipment":["Dumbbells","Flat bench"],"req":"dumbbells,flatbench|adjbench","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Lie on a bench and press the dumbbells together over your chest.","Keep squeezing them together as you lower to your chest.","Press back up without letting them separate."],"common_mistakes":["Letting the dumbbells drift apart","Using too much weight"],"regressions":["Dumbbell floor press"],"progressions":[],"safety":"Hex dumbbells are easiest to squeeze; keep wrists straight.","video":null,"diagram":"","notes":""},{"id":"flatcablefly","name":"Flat bench cable fly","aliases":["Lying cable fly"],"training_type":"Strength","tags":["Chest","Hypertrophy","Isolation","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts"],"movement_pattern":"Isolation","equipment":["Cable machine","Flat bench","Single handles"],"req":"cablecross|functional,flatbench|adjbench","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Lie on a bench between low pulleys.","Open the arms wide with soft elbows.","Hug the handles together over your chest."],"common_mistakes":["Dropping the hands too low below the bench.","Pressing instead of flying."],"regressions":["Dumbbell fly"],"progressions":["Incline bench cable fly"],"safety":"Keep the stretch controlled to protect the shoulder.","video":null,"diagram":"","notes":"Keeps tension at the top, unlike dumbbell flies."},{"id":"flatcablepress","name":"Flat bench cable press","aliases":["Cable bench press","Lying cable press"],"training_type":"Strength","tags":["Chest","Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Triceps","Front delts"],"movement_pattern":"Horizontal push","equipment":["Cable machine","Flat bench","Single handles"],"req":"cablecross|functional,flatbench|adjbench","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Place the bench between low pulleys.","Press up and slightly together over the chest.","Lower until hands are level with your chest."],"common_mistakes":["Bench not centred so tension is uneven.","Bouncing at the bottom."],"regressions":["Standing cable chest press"],"progressions":["Incline bench cable press"],"safety":"Have handles in place before lying down so you don't twist to grab them.","video":null,"diagram":"","notes":"Constant tension compared to dumbbells."},{"id":"flatdb","name":"Flat dumbbell press","aliases":["Dumbbell bench press","DB bench"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts"],"movement_pattern":"Horizontal push","equipment":["Dumbbells","Flat bench"],"req":"dumbbells,flatbench|adjbench","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Lie back with feet flat and shoulder blades pinched together.","Lower the dumbbells to the sides of your chest, elbows about 45°.","Press up and slightly in until arms are straight."],"common_mistakes":["Flaring elbows to 90°","Clanking the weights at the top"],"regressions":["Dumbbell floor press","Push-ups"],"progressions":["Incline dumbbell press","Barbell bench press"],"safety":"Kick the dumbbells up from your knees and lower them back to your knees when done.","video":null,"diagram":"dbbench","notes":""},{"id":"inclinebb","name":"Incline barbell press","aliases":["Incline bench press"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Upper chest"],"secondary_muscles":["Front delts","Triceps"],"movement_pattern":"Horizontal push","equipment":["Olympic barbell","Weight plates","Incline bench"],"req":"barbell,plates,inclinebench|adjbench","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"6–10","form_cues":["Set the bench to 30–45°","Lower the bar to your upper chest","Press up over your shoulders, 