houlder press.","Elbows flared to 90 degrees."],"regressions":["Low-to-high cable press"],"progressions":["Incline barbell press"],"safety":"Grab handles before reclining to avoid twisting under load.","video":null,"diagram":"","notes":""},{"id":"dbinclinefly","name":"Incline dumbbell fly","aliases":["Incline fly"],"training_type":"Strength","tags":["Hypertrophy","Isolation","Strength"],"muscle_group":"Chest","primary_muscles":["Upper chest"],"secondary_muscles":["Front delts"],"movement_pattern":"Isolation","equipment":["Dumbbells","Adjustable bench (incline)"],"req":"dumbbells,inclinebench|adjbench","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Set the bench to 30° and hold dumbbells over your upper chest.","Open your arms wide with a fixed elbow bend.","Squeeze them back together over your chest."],"common_mistakes":["Turning it into a press","Going too deep"],"regressions":["Dumbbell fly"],"progressions":["Low-to-high cable fly"],"safety":"Keep the weight light enough to control the stretch.","video":null,"diagram":"","notes":""},{"id":"incdb","name":"Incline dumbbell press","aliases":["Incline DB bench press"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Upper chest","Front delts"],"secondary_muscles":["Triceps"],"movement_pattern":"Horizontal push","equipment":["Dumbbells","Adjustable bench (incline)"],"req":"dumbbells,inclinebench|adjbench","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Set the bench to about 30°, not steeper.","Lower to the upper chest with elbows slightly tucked.","Press up and slightly in, without clanking the dumbbells."],"common_mistakes":["Bench set too steep","Bouncing at the bottom"],"regressions":["Flat dumbbell press"],"progressions":["Incline barbell press"],"safety":"Lower until you feel a chest stretch, never pain in the shoulder.","video":null,"diagram":"incline","notes":""},{"id":"kneelcablefly","name":"Kneeling cable crossover","aliases":["Kneeling cable fly"],"training_type":"Strength","tags":["Chest","Hypertrophy","Isolation","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts"],"movement_pattern":"Isolation","equipment":["Cable machine","Single handles"],"req":"cablecross|functional","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Kneel tall in the middle of the crossover.","Brace your core so the hips don't move.","Bring hands together in front of your belly button."],"common_mistakes":["Rocking the torso to cheat the weight.","Letting elbows drop too low."],"regressions":["Mid-height cable fly"],"progressions":["Cable crossover fly"],"safety":"Use a mat under the knees.","video":null,"diagram":"","notes":"Kneeling removes leg drive and keeps the work strict."},{"id":"landminesqueeze","name":"Landmine squeeze press","aliases":["Landmine chest press"],"training_type":"Strength","tags":["Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts","Triceps"],"movement_pattern":"Horizontal push","equipment":["Landmine","Olympic barbell","Weight plates"],"req":"landmine,barbell,plates","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Hold the bar end with both palms pressed together","Squeeze your hands hard into the bar","Press up and out from your chest"],"common_mistakes":["Losing the squeeze","Leaning back","Using the legs to push"],"regressions":["Push-ups"],"progressions":["Landmine press"],"safety":"Keep the landmine anchored so it can't slide.","video":null,"diagram":"","notes":""},{"id":"lowhighfly","name":"Low-to-high cable fly","aliases":["Low cable crossover","Upward cable fly","Incline cable fly (standing)"],"training_type":"Strength","tags":["Chest