nt_pattern":"Isolation","equipment":["Cable machine","Single handles"],"req":"cablecross|functional","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Set pulleys at chest height.","Lead with the elbows, not the hands.","Squeeze the chest hard as the handles meet."],"common_mistakes":["Shrugging the shoulders up.","Using too much weight and losing the arc."],"regressions":["Pec deck fly"],"progressions":["Single-arm cable fly"],"safety":"Stop the stretch where the shoulders still feel stable.","video":null,"diagram":"","notes":"Targets the middle of the chest."},{"id":"multigympress","name":"Multi-gym chest press","aliases":["Home gym chest press"],"training_type":"Strength","tags":["Compound","Home-friendly","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts","Triceps"],"movement_pattern":"Horizontal push","equipment":["Home multi-gym"],"req":"multigym","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Set the seat so handles line up with mid-chest.","Press forward smoothly until arms are nearly straight.","Control the weight back until you feel a chest stretch."],"common_mistakes":["Shrugging shoulders up to the ears.","Letting the stack slam between reps."],"regressions":["Push-ups"],"progressions":["Seated chest press machine","Flat dumbbell press"],"safety":"Adjust the seat before loading; keep the weight stack clear of hands and feet.","video":null,"diagram":"","notes":"Most home multi-gyms use a pulley-driven press arm; resistance may feel lighter than a commercial machine."},{"id":"multigymfly","name":"Multi-gym pec fly","aliases":["Home gym butterfly","Multi-gym pec deck"],"training_type":"Strength","tags":["Home-friendly","Hypertrophy","Isolation","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts"],"movement_pattern":"Isolation","equipment":["Home multi-gym"],"req":"multigym","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Keep a soft bend in the elbows throughout.","Squeeze the pads or handles together in front of your chest.","Open slowly until you feel a stretch, not a strain."],"common_mistakes":["Pushing with the hands instead of hugging with the arms.","Letting the arms travel too far back."],"regressions":["Band chest fly"],"progressions":["Pec deck fly"],"safety":"Avoid overstretching the shoulders at the open position.","video":null,"diagram":"","notes":""},{"id":"dbneutralpress","name":"Neutral-grip dumbbell press","aliases":["Hammer-grip dumbbell bench press"],"training_type":"Strength","tags":["Compound","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts"],"movement_pattern":"Horizontal push","equipment":["Dumbbells","Flat bench"],"req":"dumbbells,flatbench|adjbench","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Lie on a flat bench, palms facing each other.","Lower with elbows close to your sides.","Press straight up, keeping the dumbbells parallel."],"common_mistakes":["Letting elbows flare","Bouncing at the bottom"],"regressions":["Dumbbell floor press"],"progressions":["Dumbbell squeeze press"],"safety":"A shoulder-friendly option if regular pressing aches.","video":null,"diagram":"","notes":"More triceps than the standard grip."},{"id":"pinpress","name":"Pin press","aliases":["Dead bench","Bench press from pins"],"training_type":"Strength","tags":["Compound","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts"],"movement_pattern":"Horizontal push","equipment":["Olympic barbell","Weight plates","Squat rack","Flat bench"],"req":"barbell,plates,powerrack,flatbench","equipment_tier":2,"difficulty":"Advanced","tracking":"w","unilate