oulder-width","Lower under control to mid-chest","Press up without letting shoulders roll forward"],"common_mistakes":["Going wider than the rings allow","Bouncing the bar","Shoulders lifting off the bench"],"regressions":["Barbell bench press"],"progressions":[],"safety":"Avoid if you have shoulder pain; stay within competition grip width (index finger on the rings).","video":null,"diagram":"","notes":"Shorter range and more chest emphasis than a standard grip."},{"id":"bbrow","name":"Barbell bent-over row","aliases":["Bent-over row","Barbell row"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Upper back"],"secondary_muscles":["Rear delts","Biceps","Lower back"],"movement_pattern":"Horizontal pull","equipment":["Olympic barbell","Weight plates"],"req":"barbell,plates","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"6–10","form_cues":["Hinge until your torso is about 45° or lower","Pull the bar to your lower ribs","Lower under control without standing up"],"common_mistakes":["Standing up more each rep","Jerking with the hips","Rounding the back"],"regressions":["One-arm dumbbell row","Inverted row"],"progressions":["Pendlay row"],"safety":"Keep your back flat; stop if your lower back fatigues first.","video":null,"diagram":"bbrow","notes":""},{"id":"bbpullover","name":"Barbell pullover","aliases":["Lying barbell pullover","EZ-bar pullover"],"training_type":"Strength","tags":["Hypertrophy","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Chest"],"secondary_muscles":["Triceps","Core"],"movement_pattern":"Isolation","equipment":["Olympic barbell","Weight plates","Flat bench"],"req":"barbell|ezbar,flatbench","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Lie on a bench holding the bar over your chest, elbows soft","Lower it back over your head in an arc","Pull it back over your chest using lats and chest"],"common_mistakes":["Bending elbows too much","Arching the lower back","Going too heavy"],"regressions":["Dumbbell pullover"],"progressions":[],"safety":"Use a light load and stop if your shoulders pinch overhead.","video":null,"diagram":"","notes":""},{"id":"bbshrug","name":"Barbell shrug","aliases":["Shrug"],"training_type":"Strength","tags":["Hypertrophy","Isolation","Strength"],"muscle_group":"Back","primary_muscles":["Traps"],"secondary_muscles":["Forearms","Neck"],"movement_pattern":"Isolation","equipment":["Olympic barbell","Weight plates","Squat rack"],"req":"barbell,plates,powerrack","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–15","form_cues":["Hold the bar at your thighs, arms straight","Lift your shoulders straight up to your ears","Pause, then lower slowly"],"common_mistakes":["Rolling the shoulders","Bending the elbows","Bouncing the weight"],"regressions":["Dumbbell shrug"],"progressions":["Behind-the-back barbell shrug"],"safety":"Use straps for heavy sets to spare your grip.","video":null,"diagram":"","notes":""},{"id":"behindbackshrug","name":"Behind-the-back barbell shrug","aliases":["Behind-the-back shrug"],"training_type":"Strength","tags":["Hypertrophy","Isolation","Strength"],"muscle_group":"Back","primary_muscles":["Traps"],"secondary_muscles":["Rear delts","Forearms"],"movement_pattern":"Isolation","equipment":["Olympic barbell","Weight plates","Squat rack"],"req":"barbell,plates,powerrack","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"10–15","form_cues":["Hold the bar behind your thighs","Shrug up and slightly back","Hold the top for a second"],"common_mistakes":["Bar dragging on the legs","Using momentum","Short reps"],"regressions":["Barbell shrug"],"progressions":[],"safety":"Unrack from mid-thigh height in a rack.","video":null,"diagram":"","notes":""},{"id":"behindneckpull","name":"Behind-the