ement_pattern":"Hinge","equipment":["Suspension trainer"],"req":"trx","equipment_tier":2,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Lie on your back, heels in the cradles.","Press heels down and lift hips high.","Pause at the top, then lower slowly."],"common_mistakes":["Arching the lower back","Legs swinging"],"regressions":["Glute bridge"],"progressions":["Suspension hamstring curl"],"safety":"Keep the straps still before lifting.","video":null,"diagram":"","notes":""},{"id":"assistdip","name":"Assisted dip","aliases":["Machine-assisted dip","Gravitron dip"],"training_type":"Strength","tags":["Beginner-friendly","Compound","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts"],"movement_pattern":"Vertical push","equipment":["Assisted pull-up / dip machine"],"req":"assistpull","equipment_tier":3,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Kneel or stand on the pad and grip the dip handles.","Lower until upper arms are about parallel to the floor.","Press back up, leaning slightly forward for chest."],"common_mistakes":["Going too deep and straining the shoulders.","Shrugging at the bottom."],"regressions":["Bench dips"],"progressions":["Chest dips"],"safety":"More counterweight makes it easier; stop short of any shoulder pinch.","video":null,"diagram":"","notes":"Reduce the assistance over time as you get stronger."},{"id":"declinemach","name":"Decline chest press machine","aliases":["Machine decline press"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Lower chest"],"secondary_muscles":["Triceps","Front delts"],"movement_pattern":"Horizontal push","equipment":["Decline press machine"],"req":"chestpress","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Set the seat so handles start at lower chest.","Press down and forward until arms are nearly straight.","Return slowly and keep the chest proud."],"common_mistakes":["Letting shoulders roll forward.","Rushing the lowering phase."],"regressions":["Chest dips (assisted)"],"progressions":["Decline bench press","Iso-lateral decline press"],"safety":"Use the foot lever or a partner to get into position if the start is deep.","video":null,"diagram":"","notes":"Nearest app gear id is the seated chest press machine."},{"id":"inclinemach","name":"Incline press machine","aliases":["Incline chest press machine","Machine incline press"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Upper chest"],"secondary_muscles":["Front delts","Triceps"],"movement_pattern":"Horizontal push","equipment":["Incline press machine"],"req":"inclinepressm","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Set the seat so handles start at upper chest.","Press up and slightly in, keeping shoulders down.","Lower slowly until hands are level with the chest."],"common_mistakes":["Seat too low, turning it into a shoulder press.","Shrugging at the top."],"regressions":["Seated chest press machine"],"progressions":["Iso-lateral incline press","Incline dumbbell press"],"safety":"Keep shoulder blades back to protect the front of the shoulder.","video":null,"diagram":"machinepress","notes":""},{"id":"isochestpress","name":"Iso-lateral chest press","aliases":["Hammer Strength chest press","Plate-loaded chest press"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts","Triceps"],"movement_pattern":"Horizontal push","equipment":["Plate-loaded chest press machine","Weight plates"],"req":"chestpress,plates","equipment_tier":3,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":