ral":false,"sets":3,"reps":"8–10","form_cues":["Set the seat so handles sit at upper-chest level.","Drive both arms up evenly.","Lower under control to a deep upper-chest stretch."],"common_mistakes":["Uneven loading or pressing.","Bouncing at the bottom."],"regressions":["Incline press machine"],"progressions":["Incline barbell press"],"safety":"Rack both arms before getting up or changing plates.","video":null,"diagram":"","notes":"Arms can be pressed one at a time for unilateral work."},{"id":"lyingpress","name":"Lying chest press machine","aliases":["Lying machine bench press","Supine chest press"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts","Triceps"],"movement_pattern":"Horizontal push","equipment":["Lying chest press machine"],"req":"lyingpress","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Lie with handles in line with your mid-chest.","Keep feet flat and upper back tight on the pad.","Press up, then lower slowly to a stretch."],"common_mistakes":["Arching hard off the bench.","Locking out aggressively."],"regressions":["Seated chest press machine"],"progressions":["Barbell bench press"],"safety":"Make sure the starting position is safe before unracking.","video":null,"diagram":"lyingpress","notes":"Mimics the bench press with no need for a spotter."},{"id":"pecdeckfly","name":"Pec deck fly","aliases":["Pec deck","Butterfly machine","Machine fly"],"training_type":"Strength","tags":["Hypertrophy","Isolation","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts"],"movement_pattern":"Isolation","equipment":["Pec deck / fly machine"],"req":"pecdeck","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Set the seat so handles are at chest height.","Keep a slight bend in the elbows and hug the handles together.","Open slowly until you feel a stretch, then squeeze back."],"common_mistakes":["Letting the arms travel far behind the body.","Pressing with the hands instead of moving at the shoulder."],"regressions":["Multi-gym pec fly"],"progressions":["Single-arm pec deck fly","Cable crossover fly"],"safety":"Limit the backward stretch if you have shoulder pain.","video":null,"diagram":"cablefly","notes":"Pause one second at the squeeze for more chest work."},{"id":"machinechest","name":"Seated chest press machine","aliases":["Machine chest press","Vertical chest press"],"training_type":"Strength","tags":["Beginner-friendly","Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts","Triceps"],"movement_pattern":"Horizontal push","equipment":["Chest press machine"],"req":"chestpress","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Set the seat so handles are level with mid-chest.","Keep shoulder blades back and down against the pad.","Press out, then return slowly until you feel a stretch."],"common_mistakes":["Seat set too low or high.","Elbows flaring straight out to the sides."],"regressions":["Push-ups","Multi-gym chest press"],"progressions":["Iso-lateral chest press","Barbell bench press"],"safety":"Set the seat height before loading, and keep wrists stacked over elbows.","video":null,"diagram":"machinepress","notes":"A safe way to train chest to failure without a spotter."},{"id":"sachestpress","name":"Single-arm machine chest press","aliases":["One-arm chest press machine"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength","Unilateral"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts","Triceps","Obliques"],"movement_pattern":"Horizontal push","equipment":["Chest press machine"],"req":"chestpress","equipment_tier":3,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"10 / side","form_cues":["Brace your free hand on the seat or your hip.","Press one handle forward without twisting your torso.","Lower slowly and keep the shoulder blade pinned."],"common_mistakes":["Rotating the body to finish the rep.","Using momentum from the hips."],"regressions":["Seated chest press machine"],"progressions":["Iso-lateral chest press"],"safety":"Keep the torso square to stop the lower back twisting.","video":null,"diagram":"","notes":"Best on machines with independent arms."},{"id":"sapecdeck","name":"Single-arm pec deck fly","aliases":["One-arm machine fly"],"training_type":"Strength","tags":["Hypertrophy","Isolation","Strength","Unilateral"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts"],"movement_pattern":"Isolation","equipment":["Pec deck / fly machine"],"req":"pecdeck","equipment_tier":3,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"12 / side","form_cues":["Sit side-on or square and hold the frame with your free hand.","Sweep one handle across your body past midline.","Return slowly to a controlled stretch."],"common_mistakes":["Twisting the torso to move the weight.","Using too much load to cross midline."],"regressions":["Pec deck fly"],"progressions":["Cable crossover fly"],"safety":"Keep the shoulder down and back throughout.","video":null,"diagram":"","notes":"Crossing past midline gives a stronger peak contraction than two-arm flies."},{"id":"widechestpress","name":"Wide chest press machine","aliases":["Hammer Strength wide chest","Plate-loaded wide chest press"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts","Triceps"],"movement_pattern":"Horizontal push","equipment":["Plate-loaded wide chest press machine","Weight plates"],"req":"chestpress,plates","equipment_tier":3,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Grip the wide handles with elbows slightly below shoulders.","Press forward and in, squeezing the chest.","Return slowly to a full stretch across the chest."],"common_mistakes":["Shoulders rolling forward at the top.","Short, choppy reps."],"regressions":["Seated chest press machine"],"progressions":["Iso-lateral chest press"],"safety":"Avoid an aggressive stretch if your shoulders are sensitive.","video":null,"diagram":"","notes":"The wider path puts more emphasis on the outer chest stretch than a standard chest press."},{"id":"assistchinup","name":"Assisted chin-up","aliases":["Machine-assisted chin-up","Assisted underhand pull-up"],"training_type":"Strength","tags":["Beginner-friendly","Compound","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Biceps"],"secondary_muscles":["Rhomboids","Forearms"],"movement_pattern":"Vertical pull","equipment":["Assisted pull-up / dip machine"],"req":"assistpull","equipment_tier":3,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Grip shoulder-width with palms facing you.","Drive elbows down and bring chin over the bar.","Lower all the way to straight arms."],"common_mistakes":["Craning the neck to reach the bar.","Dropping fast on the way down."],"regressions":["Assisted pull-up"],"progressions":["Chin-ups"],"safety":"Keep the shoulders active at the bottom rather than hanging loose.","video":null,"diagram":"","notes":"Biceps help more here, so most people find it easier than the pull-up."},{"id":"assistpullup","name":"Assisted pull-up","aliases":["Machine-assisted pull-up","Gravitron pull-up"],"training_type":"Strength","tags":["Beginner-friendly","Compound","Strength"],"muscle_group":"Back","primary_muscles":["Lats"],"secondary_muscles":["Biceps","Rear delts","Rhomboids"],"movement_pattern":"Vertical pull","equipment":["Assisted pull-up / dip machine"],"req":"assistpull","equipment_tier":3,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Grip just outside shoulder width, palms forward.","Pull your chest towards the bar, elbows down to your ribs.","Lower slowly to fully straight arms."],"common_mistakes":["Half reps that skip the bottom stretch.","Swinging or kicking."],"regressions":["Inverted row"],"progressions":["Pull-ups"],"safety":"Step on and off the pad carefully; more counterweight means more help.","video":null,"diagram":"pullup","notes":"Cut the assistance by one plate when you can do 3 x 10."},{"id":"backext","name":"Back extension","aliases":["45-degree back extension","Hyperextension","Roman chair back extension"],"training_type":"Strength","tags":["Home-friendly","Hypertrophy","Strength"],"muscle_group":"Back","primary_muscles":["Lower back","Glutes"],"secondary_muscles":["Hamstrings"],"movement_pattern":"Hinge","equipment":["Back extension / Roman chair"],"req":"romanchair","equipment_tier":3,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Set the pad just below your hip bones.","Hinge down with a flat back, then rise until body is straight.","Squeeze glutes at the top without over-arching."],"common_mistakes":["Hyperextending past straight at the top.","Jerking up fast."],"regressions":["Superman hold"],"progressions":["Weighted back extension","GHD back extension"],"safety":"Don't arch past a straight line; stop if you feel sharp back pain.","video":null,"diagram":"backext","notes":"Hold a plate to your chest to add load."},{"id":"chestrow","name":"Chest-supported row machine","aliases":["Seated machine row","Machine row"],"training_type":"Strength","tags":["Beginner-friendly","Compound","Hypertrophy","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Rhomboids","Mid traps"],"secondary_muscles":["Rear delts","Biceps"],"movement_pattern":"Horizontal pull","equipment":["Chest-supported row machine"],"req":"rowmachine","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Set the chest pad so you can just reach the handles.","Pull elbows back and squeeze shoulder blades together.","Let the arms straighten slowly and the shoulders reach forward."],"common_mistakes":["Lifting the chest off the pad.","Shrugging instead of pulling back."],"regressions":["Inverted row"],"progressions":["Iso-lateral row","Barbell bent-over row"],"safety":"Chest support takes load off the lower back.","video":null,"diagram":"cablerow","notes":"Neutral grip hits lats more; wide overhand hits upper back more."},{"id":"cstbar","name":"Chest-supported T-bar row","aliases":["Incline T-bar row","Lying T-bar row"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Mid traps","Rhomboids"],"secondary_muscles":["Rear delts","Biceps"],"movement_pattern":"Horizontal pull","equipment":["Chest-supported T-bar row machine","Weight plates"],"req":"tbar,plates","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":4,"reps":"8–12","form_cues":["Lie chest-down on the pad with feet on the platform.","Row the handles up until elbows pass your torso.","Lower all the way to straight arms."],"common_mistakes":["Lifting the chest off the pad.","Jerking the first part of the rep."],"regressions":["Chest-supported row machine"],"progressions":["T-bar row"],"safety":"Step on the platform carefully and keep your chin neutral.","video":null,"diagram":"","notes":"Easier on the lower back than the standing T-bar row."},{"id":"ghdbackext","name":"GHD back extension","aliases":["90-degree back extension","GHD hyperextension","Horizontal back extension"],"training_type":"Strength","tags":["Advanced","Strength"],"muscle_group":"Back","primary_muscles":["Lower back","Glutes"],"secondary_muscles":["Hamstrings"],"movement_pattern":"Hinge","equipment":["Glute-ham developer (GHD)"],"req":"ghd","equipment_tier":3,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Set the pad at your hips with feet locked under the rollers.","Lower your torso towards the floor with a flat back.","Rise until your body is horizontal, not higher."],"common_mistakes":["Swinging up past horizontal.","Rounding fast at the bottom."],"regressions":["Back extension"],"progressions":["Reverse hyper"],"safety":"Lift no higher than straight; this horizontal version is harder than 45 degrees.","video":null,"diagram":"","notes":""},{"id":"dyrow","name":"Iso-lateral D.Y. row","aliases":["Hammer Strength DY row","Dorian Yates row machine"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Back","primary_muscles":["Lats"],"secondary_muscles":["Rhomboids","Biceps"],"movement_pattern":"Horizontal pull","equipment":["Plate-loaded D.Y. row machine","Weight plates"],"req":"rowmachine,plates","equipment_tier":3,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Set the chest pad so you reach the handles with straight arms.","Pull with an underhand or neutral grip towards your waist.","Lower under control for a full stretch."],"common_mistakes":["Using the legs to drive the weight.","Cutting the stretch short."],"regressions":["Chest-supported row machine"],"progressions":["Barbell bent-over row"],"safety":"Keep the chest supported to protect the lower back.","video":null,"diagram":"","notes":"Mimics the underhand barbell row made popular by Dorian Yates."},{"id":"isopulldown","name":"Iso-lateral front lat pulldown","aliases":["Hammer Strength pulldown","Plate-loaded pulldown"],"training_type":"Strength","tags":["Compound","Hypertrophy","Strength"],"muscle_group":"Back","primary_muscles":["Lats"],"secondary_muscles":["Biceps","Teres major","Rear delts"],"movement_pattern":"Vertical pull","equipment":["Plate-loaded pulldown machine","Weight plates"],"req":"latpulldown,plates","equipment_tier":3,"dif