","notes":"Most pec decks double as a rear delt machine with the handles reversed."},{"id":"shouldermach","name":"Seated shoulder press machine","aliases":["Machine shoulder press","Machine overhead press"],"training_type":"Strength","tags":["Beginner-friendly","Compound","Hypertrophy","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Side delts"],"secondary_muscles":["Triceps","Upper chest"],"movement_pattern":"Vertical push","equipment":["Shoulder press machine"],"req":"shoulderpress","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Set the seat so handles start just above shoulder level.","Press up without locking out hard.","Lower slowly until hands are near the shoulders."],"common_mistakes":["Arching the lower back off the pad.","Seat too high so the range is short."],"regressions":["Pike push-up"],"progressions":["Iso-lateral shoulder press","Seated dumbbell shoulder press"],"safety":"Keep the back flat on the pad.","video":null,"diagram":"shouldermach","notes":""},{"id":"salateralmach","name":"Single-arm machine lateral raise","aliases":["One-arm lateral raise machine"],"training_type":"Strength","tags":["Hypertrophy","Isolation","Strength","Unilateral"],"muscle_group":"Shoulders","primary_muscles":["Side delts"],"secondary_muscles":[],"movement_pattern":"Isolation","equipment":["Lateral raise machine"],"req":"lateralm","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":3,"reps":"12–15 / side","form_cues":["Sit tall and work one arm at a time.","Raise the elbow out to shoulder height.","Lower slowly and keep the shoulder down."],"common_mistakes":["Leaning away to cheat.","Rushing reps."],"regressions":["Lateral raise machine"],"progressions":["Cable lateral raise"],"safety":"Keep the weight modest and the shoulder relaxed.","video":null,"diagram":"","notes":""},{"id":"sareardelt","name":"Single-arm reverse pec deck","aliases":["One-arm rea