ing forward.","Belt riding up onto the lower back."],"regressions":["Goblet squat"],"progressions":["Barbell back squat"],"safety":"Great option when the spine needs a break; unhook the belt only when the lever is racked.","video":null,"diagram":"","notes":"Loads the legs without compressing the spine."},{"id":"beltmarch","name":"Belt squat march","aliases":["Belt squat marching"],"training_type":"Strength","tags":["Conditioning","Endurance","Strength"],"muscle_group":"Legs","primary_muscles":["Glutes","Quadriceps"],"secondary_muscles":["Hip flexors","Calves"],"movement_pattern":"Gait","equipment":["Belt squat machine"],"req":"pendulum","equipment_tier":3,"difficulty":"Intermediate","tracking":"time","unilateral":false,"sets":3,"reps":"30 sec","form_cues":["Stand tall with the belt loaded and knees soft.","March in place, lifting knees to hip height.","Keep hips level and steady."],"common_mistakes":["Shuffling feet instead of driving knees.","Leaning back."],"regressions":["Belt squat"],"progressions":[],"safety":"Keep the load moderate and stop if form breaks.","video":null,"diagram":"","notes":"A conditioning and hip-stability finisher."},{"id":"donkeycalf","name":"Donkey calf raise","aliases":["Donkey calf raise machine"],"training_type":"Strength","tags":["Hypertrophy","Isolation","Strength"],"muscle_group":"Legs","primary_muscles":["Calves"],"secondary_muscles":[],"movement_pattern":"Isolation","equipment":["Donkey calf raise machine"],"req":"standcalf","equipment_tier":3,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Hinge forward with hips under the pad and back flat.","Rise high on your toes.","Lower to a deep stretch."],"common_mistakes":["Rounding the back.","Short reps."],"regressions":["Standing calf raise"],"progressions":[],"safety":"Keep the spine neutral.","video":null,"diagram":"","notes":"No exact app gear id; nearest is the standing calf machine."},{"id":"ghr","name":"Glute-ham raise","aliases"