egressions":["Leg press"],"progressions":["Sumo deadlift"],"safety":"Only go as deep as your hips allow without rounding.","video":null,"diagram":"","notes":""},{"id":"archerpush","name":"Archer push-up","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength","Unilateral"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Horizontal push","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"bw","unilateral":true,"sets":3,"reps":"5–8 / side","form_cues":["Set hands very wide with fingers turned slightly out.","Shift down toward one hand while the other arm stays straight.","Press back up through the bent arm, then switch sides."],"common_mistakes":["Bending the 'straight' arm to help","Twisting the hips toward the floor"],"regressions":["Wide push-up"],"progressions":["One-arm push-up"],"safety":"Warm up wrists and shoulders well before loading one side.","video":null,"diagram":"","notes":"A key step toward the one-arm push-up."},{"id":"hindupush","name":"Hindu push-up","aliases":["Dand"],"training_type":"Calisthenics","tags":["Calisthenics","Endurance","Home-friendly","Mobility","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Shoulders","Triceps"],"secondary_muscles":["Lower back","Hip flexors","Core"],"movement_pattern":"Horizontal push","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Start in a downward-dog shape with hips high.","Swoop your chest low and forward between your hands.","Finish in an upward arch, then push hips back up to start."],"common_mistakes":["Collapsing into the lower back at the top","Bending the arms only, without the swoop"],"regressions":["Push-ups"],"progressions":["Dive bomber push-up"],"safety":"Skip the arched finish if you have lower back pain.","video":null,"diagram":"","notes":"Traditional Indian wrestling exercise; pairs well with Hindu squats."},{"id":"onearmpush","name":"One-arm push-up","aliases":["Single-arm push-up"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength","Unilateral"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core","Obliques"],"movement_pattern":"Horizontal push","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"bw","unilateral":true,"sets":3,"reps":"3–6 / side","form_cues":["Spread feet wide and place one hand under your chest.","Put the free hand behind your back and brace hard.","Lower with control, keeping hips square, then press up."],"common_mistakes":["Rotating the torso to cheat the rep","Feet too close together"],"regressions":["Archer push-up","Incline push-up"],"progressions":[],"safety":"Build up slowly with incline versions to protect the shoulder.","video":null,"diagram":"","notes":"Elevate the hand on a bench to regress."},{"id":"spiderpush","name":"Spiderman push-up","aliases":["Spider push-up"],"training_type":"Calisthenics","tags":["Calisthenics","Compound","Home-friendly","Mobility","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Obliques","Hip flexors","Front delts"],"movement_pattern":"Horizontal push","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"6–10 / side","form_cues":["Start in a strong push-up position.","As you lower, bring one knee toward the same-side elbow.","Return the leg as you press up; alternate sides."],"common_mistakes":["Letting the hips rotate or sag","Rushing so the chest doesn't reach the bottom"],"regressions":["Push-ups"],"progressions":["Archer push-up"],"safety":"Keep the movement slow if your hips are tight.","video":null,"diagram":"","notes":""},{"id":"typewriterpush","name":"Typewriter push-up","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Horizontal push","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"4–6 / side","form_cues":["Set hands very wide and lower to the bottom of a push-up.","Slide your chest across to one hand, then the other, staying low.","Return to centre and press up."],"common_mistakes":["Rising up while shifting sideways","Hips sagging during the slide"],"regressions":["Archer push-up"],"progressions":["One-arm push-up"],"safety":"Stop if you feel pinching in the shoulder at the bottom.","video":null,"diagram":"","notes":""},{"id":"advtuckplanche","name":"Advanced tuck planche","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts"],"secondary_muscles":["Chest","Core","Serratus anterior","Glutes"],"movement_pattern":"Hold","equipment":["Floor or parallettes"],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":4,"reps":"5–12 sec","form_cues":["Start from a tuck planche.","Open the hips so the back is flat and level.","Keep arms locked and hips at shoulder height."],"common_mistakes":["Back rounding up like a regular tuck","Hips dropping"],"regressions":["Tuck planche"],"progressions":["Straddle planche"],"safety":"Build up over months; stop with any elbow pain.","video":null,"diagram":"","notes":""},{"id":"divebomber","name":"Dive bomber push-up","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Mobility","Strength"],"muscle_group":"Shoulders","primary_muscles":["Chest","Front delts","Triceps"],"secondary_muscles":["Core","Lower back"],"movement_pattern":"Horizontal push","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"6–10","form_cues":["Start with hips high and arms straight, like a downward dog.","Dive your chest close to the floor, sweeping forward.","Reverse the path back to the start instead of pushing straight up."],"common_mistakes":["Dropping straight down without the sweep","Letting elbows flare wide"],"regressions":["Hindu push-up","Pike push-up"],"progressions":["Elevated pike push-up"],"safety":"Move slowly at first; it is tough on stiff shoulders.","video":null,"diagram":"","notes":"Unlike the Hindu push-up, the bomber returns along the same path."},{"id":"elevpikepush","name":"Elevated pike push-up","aliases":["Feet-elevated pike push-up","Box pike push-up"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Triceps"],"secondary_muscles":["Upper chest","Traps","Core"],"movement_pattern":"Vertical push","equipment":["Box, bench or chair"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"5–8","form_cues":["Put feet on a box and walk hands back until hips are over shoulders.","Lower your head in front of your hands, forming a tripod.","Press up to straight arms, keeping hips stacked."],"common_mistakes":["Hips drifting back behind the hands","Head lowering directly between hands"],"regressions":["Pike push-up"],"progressions":["Handstand push-up"],"safety":"Use a box that cannot slide; keep the neck neutral.","video":null,"diagram":"","notes":""},{"id":"handstand","name":"Freestanding handstand","aliases":["Handstand hold"],"training_type":"Calisthenics","tags":["Balance","Calisthenics"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Traps"],"secondary_muscles":["Triceps","Core","Forearms"],"movement_pattern":"Hold","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":5,"reps":"10–30 sec","form_cues":["Kick up softly with straight arms.","Balance using your fingertips and heels of the hands.","Squeeze legs together and keep a straight body line."],"common_mistakes":["Over-arching the back","Bent elbows"],"regressions":["Wall handstand hold"],"progressions":["Freestanding handstand push-up","Press to handstand"],"safety":"Practise bailing out (cartwheel or roll) before kicking up away from a wall.","video":null,"diagram":"","notes":""},{"id":"freehspu","name":"Freestanding handstand push-up","aliases":[],"training_type":"Calisthenics","tags":["Balance","Calisthenics","Strength"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Triceps"],"secondary_muscles":["Traps","Core","Forearms"],"movement_pattern":"Vertical push","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"1–5","form_cues":["Hold a steady freestanding handstand first.","Lower in control, keeping balance over your hands.","Press up while staying stacked."],"common_mistakes":["Losing balance at the bottom","Arching the back to press"],"regressions":["Handstand push-up"],"progressions":[],"safety":"Elite skill: use a soft floor and know how to bail.","video":null,"diagram":"","notes":""},{"id":"frogstand","name":"Frog stand","aliases":["Crow stand"],"training_type":"Calisthenics","tags":["Balance","Calisthenics","Home-friendly"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Wrist flexors"],"secondary_muscles":["Core","Triceps"],"movement_pattern":"Hold","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"10–30 sec","form_cues":["Squat down and place hands flat, shoulder-width.","Rest knees on the backs of your bent elbows.","Lean forward until feet float, eyes slightly ahead."],"common_mistakes":["Looking straight down and tipping over","Not leaning enough"],"regressions":[],"progressions":["Tuck planche","Freestanding handstand"],"safety":"Put a pillow in front of your face while learning.","video":null,"diagram":"","notes":"Gateway to arm balances; yoga calls a similar pose crow."},{"id":"planche","name":"Full planche","aliases":["Planche"],"training_type":"Calisthenics","tags":["Calisthenics","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts"],"secondary_muscles":["Chest","Core","Glutes","Biceps"],"movement_pattern":"Hold","equipment":["Floor or parallettes"],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":4,"reps":"2–8 sec","form_cues":["Lean far forward with locked arms.","Hold legs together and straight behind you.","Keep the whole body level just above the floor."],"common_mistakes":["Arched lower back","Bent arms"],"regressions":["Straddle planche"],"progressions":["Planche push-up"],"safety":"One of the hardest bodyweight skills; train years, not weeks.","video":null,"diagram":"","notes":""},{"id":"hspu","name":"Handstand push-up","aliases":["HSPU","Wall handstand push-up"],"training_type":"Calisthenics","tags":["Calisthenics","Strength"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Triceps"],"secondary_muscles":["Traps","Upper chest","Core"],"movement_pattern":"Vertical push","equipment":["Wall"],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"3–8","form_cues":["Kick up into a handstand with your back to the wall.","Lower your head to the floor with elbows angled forward.","Press back up to straight arms."],"common_mistakes":["Crashing the head into the floor","Elbows flaring out wide"],"regressions":["Elevated pike push-up","Wall handstand hold"],"progressions":["Deficit handstand push-up","Freestanding handstand push-up"],"safety":"Place a folded mat under your head; build up with negatives first.","video":null,"diagram":"","notes":""},{"id":"pikepush","name":"Pike push-up","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Compound","Home-friendly","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Triceps"],"secondary_muscles":["Upper chest","Traps","Core"],"movement_pattern":"Vertical push","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"6–10","form_cues":["Walk feet in so hips are high and you form an upside-down V.","Lower the top of your head toward a spot ahead of your hands.","Press back up, keeping hips high."],"common_mistakes":["Letting hips drop into a push-up shape","Elbows flaring straight out"],"regressions":["Push-ups"],"progressions":["Elevated pike push-up","Handstand push-up"],"safety":"Lower slowly so you don't bump your head.","video":null,"diagram":"pushup","notes":""}]$ex$::jsonb)
