select id, name, aliases, training_type, tags, muscle_group, primary_muscles, secondary_muscles, movement_pattern, equipment, req, equipment_tier, difficulty, tracking, unilateral, sets, reps, form_cues, common_mistakes, regressions, progressions, safety, video, diagram, notes from jsonb_to_recordset($ex$[{"id":"planchelean","name":"Planche lean","aliases":["Pseudo planche lean"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts"],"secondary_muscles":["Chest","Biceps","Core","Wrist flexors"],"movement_pattern":"Hold","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"15–30 sec","form_cues":["From a push-up, turn fingers out and lean shoulders past your hands.","Keep arms locked and shoulder blades pushed apart.","Hold the lean without letting hips sag."],"common_mistakes":["Bending the elbows","Leaning only a little"],"regressions":["Push-ups"],"progressions":["Pseudo planche push-up","Tuck planche"],"safety":"Warm wrists well and build lean distance slowly.","video":null,"diagram":"","notes":""},{"id":"planchepush","name":"Planche push-up","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Chest","Triceps"],"secondary_muscles":["Core","Serratus anterior","Biceps"],"movement_pattern":"Horizontal push","equipment":["Floor or parallettes"],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"2–5","form_cues":["Hold a tuck or straddle planche with arms straight.","Bend elbows to lower your chest while staying parallel.","Press back up without losing the lean."],"common_mistakes":["Feet touching down during the rep","Shoulders not leaning past the hands"],"regressions":["Pseudo planche push-up","Tuck planche"],"progressions":[],"safety":"Elite skill: build up over months and stop at any wrist or elbow pain.","video":null,"diagram":"","notes":"Parallettes ease the wrists; the tuck version is the usual first step."},{"id":"presshs","name":"Press to handstand","aliases":["Straddle press","Press handstand"],"training_type":"Calisthenics","tags":["Calisthenics","Mobility","Strength"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Hip flexors"],"secondary_muscles":["Core","Traps","Hamstrings"],"movement_pattern":"Hold","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"count","unilateral":false,"sets":3,"reps":"1–3","form_cues":["Start with hands down, hips high, legs straight or straddled.","Lean shoulders forward until your feet lift without jumping.","Raise legs slowly into a straight handstand."],"common_mistakes":["Jumping into it","Bending the arms"],"regressions":["Freestanding handstand","L-sit"],"progressions":[],"safety":"Requires good hamstring flexibility; warm up wrists and hips.","video":null,"diagram":"","notes":""},{"id":"pseudoplanchepush","name":"Pseudo planche push-up","aliases":["PPPU"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Chest"],"secondary_muscles":["Triceps","Biceps","Core","Serratus anterior"],"movement_pattern":"Horizontal push","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"5–8","form_cues":["Turn fingers out and place hands beside your waist.","Lean shoulders forward past your hands and keep that lean.","Lower and press while keeping arms locked in line at the top."],"common_mistakes":["Losing the forward lean as you push","Bending at the hips"],"regressions":["Push-ups","Planche lean"],"progressions":["Planche push-up"],"safety":"Warm up wrists thoroughly; the lean puts big stress on them.","video":null,"diagram":"","notes":"Main pushing drill for planche training."},{"id":"straddleplanche","name":"Straddle planche","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts"],"secondary_muscles":["Chest","Core","Glutes","Lower back"],"movement_pattern":"Hold","equipment":["Floor or parallettes"],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":4,"reps":"3–10 sec","form_cues":["Lean forward and lift legs straight and wide.","Keep the body parallel to the floor.","Lock arms and push the floor away."],"common_mistakes":["Hips piking up","Bent knees"],"regressions":["Advanced tuck planche"],"progressions":["Full planche"],"safety":"Elite skill; protect elbows and wrists with gradual volume.","video":null,"diagram":"","notes":""},{"id":"tuckplanche","name":"Tuck planche","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts"],"secondary_muscles":["Chest","Core","Serratus anterior","Triceps"],"movement_pattern":"Hold","equipment":["Floor or parallettes"],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":4,"reps":"8–15 sec","form_cues":["Hands under shoulders, knees tucked tight to the chest.","Lean forward until feet lift, arms locked.","Round the upper back and push the floor away."],"common_mistakes":["Bending the elbows","Resting knees on the arms (that is a frog stand)"],"regressions":["Frog stand","Planche lean"],"progressions":["Advanced tuck planche"],"safety":"Parallettes are kinder on the wrists.","video":null,"diagram":"","notes":""},{"id":"wallhs","name":"Wall handstand hold","aliases":["Chest-to-wall handstand","Wall handstand"],"training_type":"Calisthenics","tags":["Balance","Calisthenics","Home-friendly","Strength"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Traps"],"secondary_muscles":["Triceps","Core","Forearms"],"movement_pattern":"Hold","equipment":["Wall"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"20–45 sec","form_cues":["Walk up into a handstand facing the wall.","Push the floor away, ears covered by your arms.","Squeeze legs and glutes into a straight line."],"common_mistakes":["Banana-shaped back","Bent arms or sunken shoulders"],"regressions":["Wall walk","Pike hold on box"],"progressions":["Freestanding handstand","Handstand push-up"],"safety":"Practise on a soft floor; learn to roll or cartwheel out.","video":null,"diagram":"","notes":"Chest-to-wall teaches better alignment than back-to-wall."},{"id":"wallwalk","name":"Wall walk","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Triceps"],"secondary_muscles":["Upper chest","Core","Traps"],"movement_pattern":"Vertical push","equipment":["Wall"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"3–5","form_cues":["Start in a push-up with feet at the wall.","Walk feet up the wall and hands back toward it.","Stop with chest near the wall, then walk back down slowly."],"common_mistakes":["Arching the lower back","Rushing the descent"],"regressions":["Pike push-up"],"progressions":["Wall handstand hold"],"safety":"Clear the area and keep a soft surface around you.","video":null,"diagram":"","notes":""},{"id":"sphinxpush","name":"Sphinx push-up","aliases":["Forearm-to-hands push-up","Triceps extension push-up"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Triceps"],"secondary_muscles":["Core","Front delts"],"movement_pattern":"Isolation","equipment":["Mat (optional)"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"6–12","form_cues":["Start on forearms in a plank, hands slightly ahead of elbows.","Press through palms to straighten your arms.","Lower back onto the forearms slowly."],"common_mistakes":["Pushing with the hips instead of the arms","Hands placed too far forward"],"regressions":["Diamond push-ups"],"progressions":["Tiger bend push-up"],"safety":"Start from the knees if your elbows feel strained.","video":null,"diagram":"","notes":""},{"id":"tigerbend","name":"Tiger bend push-up","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Strength"],"muscle_group":"Arms","primary_muscles":["Triceps"],"secondary_muscles":["Front delts","Chest","Core"],"movement_pattern":"Vertical push","equipment":["Wall or partner spot"],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"2–5","form_cues":["Start in a handstand against a wall.","Lower onto your forearms with control.","Press back up to straight arms."],"common_mistakes":["Collapsing onto the head","Lowering too fast"],"regressions":["Sphinx push-up","Handstand push-up"],"progressions":[],"safety":"Only attempt with a solid wall handstand and a soft surface.","video":null,"diagram":"","notes":"Classic old-school strength feat."},{"id":"pistolbox","name":"Box pistol squat","aliases":["Single-leg box squat","Pistol to box"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Core","Calves"],"movement_pattern":"Squat","equipment":["Box, bench or chair"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":true,"sets":3,"reps":"5–8 / side","form_cues":["Stand on one leg in front of a box, other leg reaching forward.","Sit back slowly until you lightly touch the box.","Stand up without rocking or using momentum."],"common_mistakes":["Dropping onto the box","Knee caving inward"],"regressions":["Bodyweight squat"],"progressions":["Pistol squat"],"safety":"Lower the box height gradually as you get stronger.","video":null,"diagram":"","notes":""},{"id":"hindusquat","name":"Hindu squat","aliases":["Baithak"],"training_type":"Calisthenics","tags":["Calisthenics","Endurance","Home-friendly","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps"],"secondary_muscles":["Glutes","Calves","Hamstrings"],"movement_pattern":"Squat","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"20–30","form_cues":["Swing arms back as you squat and let heels rise.","Touch fingers near your heels at the bottom.","Drive up, swinging arms forward, in a smooth rhythm."],"common_mistakes":["Bouncing hard at the bottom","Holding your breath"],"regressions":["Bodyweight squat"],"progressions":["Shrimp squat"],"safety":"Stay on the balls of the feet only if your knees are pain-free.","video":null,"diagram":"","notes":"Traditional high-rep conditioning squat from Indian wrestling."},{"id":"pistol","name":"Pistol squat","aliases":["Single-leg squat"],"training_type":"Calisthenics","tags":["Balance","Calisthenics","Home-friendly","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Adductors","Core","Calves"],"movement_pattern":"Squat","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"bw","unilateral":true,"sets":3,"reps":"3–6 / side","form_cues":["Stand on one leg with the other straight out in front.","Reach arms forward and sink all the way down.","Drive up through the whole foot, keeping the free leg off the floor."],"common_mistakes":["Heel lifting at the bottom","Knee collapsing inward"],"regressions":["Box pistol squat","Skater squat"],"progressions":["Weighted pistol squat"],"safety":"Raise the heel on a small plate if ankle mobility limits depth.","video":null,"diagram":"","notes":"Holding a light weight in front can actually help balance."},{"id":"shrimp","name":"Shrimp squat","aliases":["Airborne lunge"],"training_type":"Calisthenics","tags":["Balance","Calisthenics","Home-friendly","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Squat","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"bw","unilateral":true,"sets":3,"reps":"3–6 / side","form_cues":["Stand on one leg and hold the other foot behind you.","Lower until the back knee touches the floor softly.","Drive up through the front foot, staying tall."],"common_mistakes":["Crashing the knee into the floor","Leaning far forward"],"regressions":["Skater squat","Reverse lunge"],"progressions":["Pistol squat"],"safety":"Put a cushion under the back knee while learning.","video":null,"diagram":"","notes":""},{"id":"elbowlever","name":"Elbow lever","aliases":["Peacock pose"],"training_type":"Calisthenics","tags":["Balance","Calisthenics"],"muscle_group":"Core","primary_muscles":["Abs","Wrist flexors"],"secondary_muscles":["Shoulders","Lower back","Glutes"],"movement_pattern":"Hold","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"10–20 sec","form_cues":["Tuck elbows into your belly near the hips.","Lean forward until the legs lift.","Hold the body straight and level."],"common_mistakes":["Elbows sliding apart","Looking down and tipping"],"regressions":["Frog stand"],"progressions":["Tuck planche"],"safety":"Put a cushion in front of your face while learning.","video":null,"diagram":"","notes":""},{"id":"lsit","name":"L-sit","aliases":["Floor L-sit"],"training_type":"Calisthenics","tags":["Calisthenics","Core","Strength"],"muscle_group":"Core","primary_muscles":["Hip flexors","Abs"],"secondary_muscles":["Triceps","Quads","Lats"],"movement_pattern":"Hold","equipment":["Floor, parallettes or dip bars"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":4,"reps":"10–20 sec","form_cues":["Press hands down beside hips and lift your body.","Hold legs straight and level with the floor.","Keep shoulders pushed down away from the ears."],"common_mistakes":["Shrugging shoulders","Bent knees"],"regressions":["Tuck sit","One-leg L-sit"],"progressions":["V-sit","L-sit pull-up"],"safety":"Parallettes or dip bars make it easier than the floor.","video":null,"diagram":"","notes":""},{"id":"vsit","name":"V-sit","aliases":["V-sit hold"],"training_type":"Calisthenics","tags":["Calisthenics","Core","Mobility","Strength"],"muscle_group":"Core","primary_muscles":["Hip flexors","Abs"],"secondary_muscles":["Triceps","Shoulders"],"movement_pattern":"Hold","equipment":["Floor or parallettes"],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":4,"reps":"3–10 sec","form_cues":["From an L-sit, lean shoulders back.","Raise straight legs higher toward your face.","Push hard through the hands to keep hips high."],"common_mistakes":["Bending the knees","Collapsing the shoulders"],"regressions":["L-sit"],"progressions":["Manna"],"safety":"Needs strong hamstring flexibility; progress slowly.","video":null,"diagram":"","notes":""},{"id":"chestdips","name":"Chest dips","aliases":["Parallel bar dip"],"training_type":"Calisthenics","tags":["Calisthenics","Compound","Strength"],"muscle_group":"Chest","primary_muscles":["Lower chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Vertical push","equipment":["Dip station or parallel bars"],"req":"dipstation","equipment_tier":1,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"6–12","form_cues":["Support on the bars and lean your torso forward.","Lower until shoulders are just below elbows.","Press up, squeezing the chest."],"common_mistakes":["Going too deep and straining the shoulders","Flaring elbows"],"regressions":["Bench dips","Negative dip"],"progressions":["Weighted dip","Ring dip"],"safety":"Skip or shorten the range if you have shoulder pain.","video":null,"diagram":"","notes":""},{"id":"parapush","name":"Parallette push-up","aliases":["Deep push-up"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Horizontal push","equipment":["Parallettes"],"req":"parallettes","equipment_tier":1,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Grip parallettes under your shoulders in a push-up.","Lower your chest below hand height for extra range.","Press back up to straight arms."],"common_mistakes":["Going deeper than shoulders tolerate","Sagging hips"],"regressions":["Push-ups"],"progressions":["Pseudo planche push-up"],"safety":"Make sure the parallettes are on a non-slip surface.","video":null,"diagram":"","notes":"Neutral grip is easy on the wrists."},{"id":"straightbardip","name":"Straight bar dip","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Vertical push","equipment":["Straight bar at hip height"],"req":"dipstation|pullupbar","equipment_tier":1,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"6–10","form_cues":["Support yourself on top of a straight bar with straight arms.","Lean forward and lower until the bar touches your upper belly.","Press back up to straight arms."],"common_mistakes":["Staying too upright and falling off","Shallow reps"],"regressions":["Bench dips","Chest dips"],"progressions":["Bar muscle-up"],"safety":"Needs a solid bar at around hip height.","video":null,"diagram":"","notes":"Essential for the muscle-up transition."},{"id":"advtuckfl","name":"Advanced tuck front lever","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Core","Strength"],"musc