ind.","Hold your straight body horizontal, face down.","Squeeze glutes and keep arms locked."],"common_mistakes":["Piked hips","Elbows bending"],"regressions":["Tuck back lever"],"progressions":[],"safety":"Build up through tuck and straddle versions to protect the biceps tendon.","video":null,"diagram":"","notes":""},{"id":"bandpullup","name":"Band-assisted pull-up","aliases":["Banded pull-up"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Biceps"],"secondary_muscles":["Rear delts","Forearms","Core"],"movement_pattern":"Vertical pull","equipment":["Pull-up bar","Resistance band"],"req":"pullupbar,bands","equipment_tier":1,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"5–8","form_cues":["Loop a band on the bar and put a foot or knee in it.","Pull until your chin passes the bar.","Lower slowly to a full hang."],"common_mistakes":["Bouncing off the band at the bottom","Half reps"],"regressions":["Negative pull-up"],"progressions":["Pull-ups"],"safety":"Check the band for nicks and step out carefully.","video":null,"diagram":"","notes":"Use thinner bands as you get stronger."},{"id":"muscleup","name":"Bar muscle-up","aliases":["Muscle-up"],"training_type":"Calisthenics","tags":["Calisthenics","Power","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Chest","Triceps"],"secondary_muscles":["Biceps","Core","Shoulders"],"movement_pattern":"Vertical pull","equipment":["Pull-up bar"],"req":"pullupbar","equipment_tier":1,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"2–5","form_cues":["Pull explosively, aiming the bar to your lower chest.","Lean over the bar and turn the wrists quickly.","Press out to a straight-arm support on top."],"common_mistakes":["Chicken-winging one arm over","Using a false grip on a bar (not needed)"],"regressions":["Chest-to-bar pull-up","Straight bar dip"],"progressions":["Ring muscle-up"],"safety":"Needs a high, solid bar with clearance above it.","video":null,"diagram":"","notes":""},{"id":"ctbpull","name":"Chest-to-bar pull-up","aliases":["C2B pull-up"],"training_type":"Calisthenics","tags":["Calisthenics","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Rhomboids"],"secondary_muscles":["Biceps","Rear delts","Lower traps"],"movement_pattern":"Vertical pull","equipment":["Pull-up bar"],"req":"pullupbar","equipment_tier":1,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"4–8","form_cues":["Start from a full hang.","Pull explosively until your chest touches the bar.","Lower with control."],"common_mistakes":["Stopping at chin height","Over-arching the lower back"],"regressions":["Pull-ups"],"progressions":["Muscle-up"],"safety":"Build up from strict pull-ups first.","video":null,"diagram":"","notes":"Key strength step toward the muscle-up."},{"id":"chinup","name":"Chin-ups","aliases":["Underhand pull-up"],"training_type":"Calisthenics","tags":["Calisthenics","Compound","Home-friendly","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Biceps"],"secondary_muscles":["Rear delts","Forearms","Core"],"movement_pattern":"Vertical pull","equipment":["Pull-up bar"],"req":"pullupbar","equipment_tier":1,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"6–10","form_cues":["Grip the bar palms facing you, shoulder-width.","Pull your chest toward the bar, elbows down and in.","Lower slowly to straight arms."],"common_mistakes":["Shrugging at the top","Half reps"],"regressions":["Negative pull-up","Band-assisted pull-up"],"progressions":["L-sit pull-up","One-arm chin-up"],"safety":"Ease off if your elbows or wrists get sore.","video":null,"diagram":"pullup","notes":"Usually easier than pull-ups because the biceps help more."},{"id":"commandopull","name":"Commando pull-up","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Biceps"],"secondary_muscles":["Obliques","Forearms","Core"],"movement_pattern":"Vertical pull","equipment":["Pull-up bar"],"req":"pullupbar","equipment_tier":1,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"4–6 / side","form_cues":["Stand under the bar and grip it with hands close, one in front of the other.","Pull up, moving your head to one side of the bar.","Lower and alternate sides each rep."],"common_mistakes":["Swinging the hips","Hitting the head on the bar"],"regressions":["Chin-ups"],"progressions":["Archer pull-up"],"safety":"Move your head clear of the bar on every rep.","video":null,"diagram":"","notes":""},{"id":"deadhang","name":"Dead hang","aliases":["Bar hang"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Mobility","Rehab","Strength"],"muscle_group":"Back","primary_muscles":["Forearms","Lats"],"secondary_muscles":["Shoulders","Grip"],"movement_pattern":"Hold","equipment":["Pull-up bar"],"req":"pullupbar","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"20–60 sec","form_cues":["Grip the bar shoulder-width and hang with straight arms.","Relax your shoulders while keeping a firm grip.","Breathe steadily and let your spine lengthen."],"common_mistakes":["Swinging","Holding your breath"],"regressions":[],"progressions":["Flexed-arm hang","One-arm dead hang"],"safety":"Step down instead of dropping; skip if you have a shoulder dislocation history.","video":null,"diagram":"","notes":"Builds grip and decompresses the spine."},{"id":"flexhang","name":"Flexed-arm hang","aliases":["Chin-up hold","Top hold"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Biceps"],"secondary_muscles":["Forearms","Rear delts"],"movement_pattern":"Hold","equipment":["Pull-up bar"],"req":"pullupbar","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"10–30 sec","form_cues":["Jump or step up so your chin is over the bar.","Hold, keeping shoulders down and chest up.","Lower slowly when you can't hold any longer."],"common_mistakes":["Chin resting on the bar","Shoulders creeping up"],"regressions":["Dead hang"],"progressions":["Negative pull-up","Pull-ups"],"safety":"Use a sturdy box to get into position.","video":null,"diagram":"","notes":""},{"id":"frontlever","name":"Front lever","aliases":["Full front lever"],"training_type":"Calisthenics","tags":["Calisthenics","Core","Strength"],"muscle_group":"Back","primary_muscles":["Lats"],"secondary_muscles":["Abs","Rear delts","Glutes","Rhomboids"],"movement_pattern":"Hold","equipment":["Pull-up bar or rings"],"req":"pullupbar|rings","equipment_tier":1,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":4,"reps":"2–8 sec","form_cues":["Hang and raise your straight body until horizontal, face up.","Keep legs together and glutes squeezed.","Pull the bar toward your hips with straight arms."],"common_mistakes":["Hips sagging","Bent arms"],"regressions":["Straddle front lever"],"progressions":["Front lever row"],"safety":"Very demanding on elbows and shoulders; warm up well.","video":null,"diagram":"","notes":""},{"id":"kippullup","name":"Kipping pull-up","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Endurance","Strength"],"muscle_group":"Back","primary_muscles":["Lats"],"secondary_muscles":["Core","Hip flexors","Biceps","Shoulders"],"movement_pattern":"Vertical pull","equipment":["Pull-up bar"],"req":"pullupbar","equipment_tier":1,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"8–15","form_cues":["Swing between an arch and a hollow position under the bar.","Drive hips up at the end of the hollow and pull.","Push away from the bar to re-enter the swing."],"common_mistakes":["Kipping before you can do strict pull-ups","Loose shoulders at the bottom"],"regressions":["Pull-ups"],"progressions":["Bar muscle-up"],"safety":"Only kip once you have 5+ strict pull-ups; it is hard on the shoulders.","video":null,"diagram":"","notes":"Common in CrossFit for high-rep sets."},{"id":"lsitpull","name":"L-sit pull-up","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Core","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Abs"],"secondary_muscles":["Hip flexors","Biceps"],"movement_pattern":"Vertical pull","equipment":["Pull-up bar"],"req":"pullupbar","equipment_tier":1,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"4–8","form_cues":["Hang and lift your legs straight out level with the floor.","Pull up while keeping the L shape.","Lower slowly without dropping the legs."],"common_mistakes":["Legs dropping during the pull","Bent knees"],"regressions":["Pull-ups","L-sit"],"progressions":["Muscle-up"],"safety":"Tuck the knees if the full L is too hard.","video":null,"diagram":"","notes":""},{"id":"negpullup","name":"Negative pull-up","aliases":["Eccentric pull-up"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Biceps"],"secondary_muscles":["Rear delts","Forearms","Core"],"movement_pattern":"Vertical pull","equipment":["Pull-up bar","Box or chair"],"req":"pullupbar","equipment_tier":1,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"3–6","form_cues":["Step up so your chin is above the bar.","Lower yourself as slowly as possible, 3–5 seconds.","Reach a full hang, then step back up."],"common_mistakes":["Dropping fast at the bottom","Kicking the legs"],"regressions":["Flexed-arm hang"],"progressions":["Pull-ups"],"safety":"Use a stable box to step up; expect soreness at first.","video":null,"diagram":"","notes":""},{"id":"neutralpull","name":"Neutral-grip pull-up","aliases":["Parallel-grip pull-up","Hammer-grip pull-up"],"training_type":"Calisthenics","tags":["Calisthenics","Compound","Home-friendly","