_tier":1,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"5–10","form_cues":["Hang with an overhand grip just wider than shoulders.","Pull elbows down toward your ribs until your chin clears the bar.","Lower to a full hang with control."],"common_mistakes":["Kipping or swinging","Not reaching a full hang"],"regressions":["Band-assisted pull-up","Negative pull-up"],"progressions":["Weighted pull-up","Archer pull-up","Muscle-up"],"safety":"Avoid if you have a shoulder injury flaring up.","video":null,"diagram":"pullup","notes":"Add weight with a dip belt or vest once you can do 12+."},{"id":"scappull","name":"Scapular pull-up","aliases":["Scap pull","Hanging scapular shrug"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Rehab","Strength","Warm-up"],"muscle_group":"Back","primary_muscles":["Lower traps","Lats"],"secondary_muscles":["Rhomboids","Grip"],"movement_pattern":"Vertical pull","equipment":["Pull-up bar"],"req":"pullupbar","equipment_tier":1,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Hang with straight arms.","Pull shoulder blades down and back to lift yourself slightly.","Lower back to a full hang with control."],"common_mistakes":["Bending the elbows","Swinging"],"regressions":["Dead hang"],"progressions":["Pull-ups"],"safety":"Keep arms straight the whole time.","video":null,"diagram":"","notes":"Teaches the first part of every pull-up."},{"id":"straddlefl","name":"Straddle front lever","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Core","Strength"],"muscle_group":"Back","primary_muscles":["Lats"],"secondary_muscles":["Abs","Rear delts","Glutes"],"movement_pattern":"Hold","equipment":["Pull-up bar or rings"],"req":"pullupbar|rings","equipment_tier":1,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":4,"reps":"3–10 sec","form_cues":["Hang and lift your body level with legs straight and wide.","Keep hips in line with your shoulders.","Press down hard through straight arms."],"common_mistakes":["Pike at the hips","Bent elbows"],"regressions":["Advanced tuck front lever"],"progressions":["Front lever"],"safety":"Elite skill; build up over months.","video":null,"diagram":"","notes":""},{"id":"towelpull","name":"Towel pull-up","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Forearms"],"secondary_muscles":["Biceps","Grip"],"movement_pattern":"Vertical pull","equipment":["Pull-up bar","Two towels"],"req":"pullupbar","equipment_tier":1,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"3–6","form_cues":["Drape two strong towels over the bar.","Grip a towel in each hand and hang.","Pull up as high as you can, then lower slowly."],"common_mistakes":["Loose towels sliding","Swinging"],"regressions":["Pull-ups"],"progressions":["One-arm chin-up"],"safety":"Use thick, strong towels and check they won't slip off.","video":null,"diagram":"","notes":"Brutal grip builder for climbers and grapplers."},{"id":"tuckbl","name":"Tuck back lever","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Chest","Biceps"],"secondary_muscles":["Abs","Lower back","Rear delts"],"movement_pattern":"Hold","equipment":["Rings or pull-up bar"],"req":"rings|pullupbar","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":4,"reps":"8–15 sec","form_cues":["Enter through skin the cat with knees tucked.","Stop when your back is level, face down.","Keep arms straight and squeeze the chest down."],"common_mistakes":["Bent arms","Hips too high or low"],"regressions":["German hang","Skin the cat"],"progressions":["Back lever"],"safety":"Avoid if you have biceps tendon pain; straight-arm stress is high.","video":null,"diagram":"","notes":""},{"id":"tuckfl","name":"Tuck front lever","aliases":[],"training_typ