acking":"bw","unilateral":false,"sets":3,"reps":"5–8","form_cues":["Grip the bar about one and a half shoulder-widths apart.","Pull your chest up toward the bar, elbows out and down.","Lower to straight arms."],"common_mistakes":["Going so wide that range is tiny","Kipping"],"regressions":["Pull-ups"],"progressions":["Archer pull-up"],"safety":"Don't go wider than is comfortable for your shoulders.","video":null,"diagram":"","notes":""},{"id":"germanhang","name":"German hang","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Mobility"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Chest","Biceps"],"secondary_muscles":["Lats"],"movement_pattern":"Stretch","equipment":["Rings or pull-up bar"],"req":"rings|pullupbar","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"10–30 sec","form_cues":["From a skin the cat, lower into the back position.","Let shoulders open gently with straight arms.","Keep breathing and come out slowly."],"common_mistakes":["Dropping in fast","Holding too long at first"],"regressions":[],"progressions":["Back lever"],"safety":"Start with a few seconds; it heavily stretches the shoulder capsule.","video":null,"diagram":"","notes":"Prepares the shoulders for back lever."},{"id":"humanflag","name":"Human flag","aliases":["Flag"],"training_type":"Calisthenics","tags":["Calisthenics","Core","Strength"],"muscle_group":"Shoulders","primary_muscles":["Lats","Obliques","Shoulders"],"secondary_muscles":["Core","Triceps","Grip"],"movement_pattern":"Hold","equipment":["Vertical pole or stall bars"],"req":"pullupbar","equipment_tier":1,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":4,"reps":"3–10 sec","form_cues":["Grip a vertical pole with hands wide, top arm pulling, bottom arm pushing.","Lock both arms and lift your body sideways.","Hold your legs level with the floor."],"common_mistakes":["Bending the bottom arm","Hips sagging"],"regressions":["Tuck human flag","Side plank"],"progressions":[],"safety":"Use a fixed pole that cannot rotate; warm up shoulders well.","video":null,"diagram":"","notes":"No exact gear id for a vertical pole; pullupbar used as nearest."},{"id":"koreandip","name":"Korean dip","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Mobility","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Triceps"],"secondary_muscles":["Chest","Biceps"],"movement_pattern":"Vertical push","equipment":["Straight bar at hip height"],"req":"dipstation|pullupbar","equipment_tier":1,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"3–6","form_cues":["Stand with the bar behind you, gripping it overhand.","Jump to a support and lower as your hands go behind the body.","Push back up to the top."],"common_mistakes":["Rushing into the deep stretch","Letting shoulders roll forward"],"regressions":["Straight bar dip"],"progressions":[],"safety":"Needs good shoulder mobility; progress very gradually.","video":null,"diagram":"","notes":""},{"id":"skinthecat","name":"Skin the cat","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Mobility","Strength"],"muscle_group":"Shoulders","primary_muscles":["Lats","Shoulders"],"secondary_muscles":["Abs","Biceps","Chest"],"movement_pattern":"Mobility","equipment":["Rings or pull-up bar"],"req":"rings|pullupbar","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"3–5","form_cues":["Hang and tuck your knees up through your arms.","Rotate backwards until feet point to the floor (German hang).","Return slowly the same way."],"common_mistakes":["Dropping into the bottom position","Bent arms twisted on a bar"],"regressions":["German hang"],"progressions":["Back lever"],"safety":"Go only as deep as your shoulders allow; easier on rings than a bar.","video":null,"diagram":"","notes":""},{"id":"dipsupport","name":"Dip support hold","aliases":["Parallel bar support","Top dip hold"],"training_type":"Calisthenics","tags":["Calisthenics","Home-friendly","Strength"],"muscle_group":"Arms","primary_muscles":["Triceps","Shoulders"],"secondary_muscles":["Chest","Core"],"movement_pattern":"Hold","equipment":["Dip station or parallel bars"],"req":"dipstation","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"20–30 sec","form_cues":["Jump up to support on the bars with straight arms.","Push shoulders down away from your ears.","Keep the body still and legs together."],"common_mistakes":["Shrugging","Bent elbows"],"regressions":["Bench dips"],"progressions":["Chest dips","Ring support hold"],"safety":"Start with short holds if your wrists are new to it.","video":null,"diagram":"","notes":""},{"id":"tridip","name":"Triceps dip","aliases":["Upright dip"],"training_type":"Calisthenics","tags":["Calisthenics","Compound","Strength"],"muscle_group":"Arms","primary_muscles":["Triceps"],"secondary_muscles":["Chest","Front delts"],"movement_pattern":"Vertical push","equipment":["Dip station or parallel bars"],"req":"dipstation","equipment_tier":1,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"6–12","form_cues":["Support on the bars with your body upright.","Lower with elbows pointing straight back.","Press up until arms are locked."],"common_mistakes":["Leaning forward (turns it into a chest dip)","Partial reps"],"regressions":["Bench dips"],"progressions":["Weighted dip","Korean dip"],"safety":"Stop at 90° elbow bend if your shoulders are sensitive.","video":null,"diagram":"","notes":""},{"id":"ringdip","name":"Ring dip","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Compound","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core","Biceps"],"movement_pattern":"Vertical push","equipment":["Gymnastic rings"],"req":"rings","equipment_tier":2,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"4–8","form_cues":["Start in a stable ring support.","Lower until shoulders are below elbows, rings close to the body.","Press back up and turn rings out at the top."],"common_mistakes":["Rings flaring wide","Too deep too soon"],"regressions":["Chest dips","Ring support hold"],"progressions":["Ring muscle-up"],"safety":"Master ring support holds first; instability is high.","video":null,"diagram":"","notes":""},{"id":"ringfly","name":"Ring fly","aliases":["Ring chest fly"],"training_type":"Calisthenics","tags":["Calisthenics","Isolation","Strength"],"muscle_group":"Chest","primary_muscles":["Chest"],"secondary_muscles":["Front delts","Biceps","Core"],"movement_pattern":"Horizontal push","equipment":["Gymnastic rings"],"req":"rings|trx","equipment_tier":2,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"6–10","form_cues":["Lean on the rings with arms nearly straight.","Open arms wide as you lower your chest.","Squeeze the rings back together."],"common_mistakes":["Bending the arms into a push-up","Going wider than you can control"],"regressions":["Ring push-ups"],"progressions":["Iron cross"],"safety":"Start with rings higher and a steep body angle.","video":null,"diagram":"","notes":""},{"id":"ringpush","name":"Ring push-ups","aliases":[],"training_type":"Calisthenics","tags":["Calisthenics","Compound","Strength"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core","Serratus anterior"],"movement_pattern":"Horizontal push","equipment":["Gymnastic rings"],"req":"rings","equipment_tier":2,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"6–12","form_cues":["Set rings a few centimetres off the floor and grip them.","Lower with rings close to your sides.","Press up and turn rings out slightly at the top."],"common_mistakes":["Rings drifting apart","Sagging hips"],"regressions":["Push-ups"],"progressions":["Ring dip","Ring fly"],"safety":"Start with rings higher to reduce the instability.","video":null,"diagram":"pushup","notes":""},{"id":"archerrow","name":"Archer row","aliases":["Archer inverted row"],"training_type":"Calisthenics","tags":["Calisthenics","Strength","Unilateral"],"muscle_group":"Back","primary_muscles":["Lats","Upper back"],"secondary_muscles":["Biceps","Rear delts","Core"],"movement_pattern":"Horizontal pull","equipment":["Low bar or rings"],"req":"powerrack|smith|rings","equipment_tier":2,"difficulty":"Intermediate","tracking":"bw","unilateral":true,"sets":3,"reps":"5–8 / side","form_cues":["Grip wide under a low bar.","Row toward one hand while the other arm stays straight.","Lower and switch sides."],"common_mistakes":["Rotating the hips","Bending the straight arm"],"regressions":["Inverted row"],"progressions":["One-arm inverted row","Front lever row"],"safety":"Secure the bar before loading one side.","video":null,"diagram":"","notes":""},{"id":"invrow","name":"Inverted row","aliases":["Australian pull-up","Bodyweight row"],"training_type":"Calisthenics","tags":["Calisthenics","Compound","Strength"],"muscle_group":"Back","primary_muscles":["Lats","Upper back"],"secondary_muscles":["Biceps","Rear delts","Core"],"movement_pattern":"Horizontal pull","equipment":["Low bar (rack/Smith) or rings"],"req":"powerrack|smith|rings","equipment_tier":2,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Hang under a bar at waist height, body straight.","Pull your chest to the bar, squeezing shoulder blades.","Lower to straight arms with control."],"common_mistakes":["Hips sagging","Shrugging shoulders"],"regressions":["Table row"],"progressions":["Archer row","Feet-elevated inverted row"],"safety":"Make sure the bar is locked into the rack safety pins or Smith hooks.","video":null,"diagram":"","notes":"Lower the bar or raise the feet to make it harder."},{"id":"ironcross","name":"Iron cross","aliases":["Cross"],"training_type":"Calisthenics","tags":[