the rings with straight arms.","Keep rings close to your hips.","Turn the rings out so palms face forward if you can."],"common_mistakes":["Rings swaying out","Shrugging"],"regressions":["Dip support hold"],"progressions":["Ring dip","Ring L-sit"],"safety":"Use a box to get in and out.","video":null,"diagram":"","notes":""},{"id":"ringtriext","name":"Ring triceps extension","aliases":["Bodyweight triceps extension"],"training_type":"Calisthenics","tags":["Calisthenics","Isolation","Strength"],"muscle_group":"Arms","primary_muscles":["Triceps"],"secondary_muscles":["Core","Front delts"],"movement_pattern":"Isolation","equipment":["Rings or suspension trainer"],"req":"rings|trx","equipment_tier":2,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Lean forward holding the rings at forehead height.","Bend only the elbows to bring hands beside your head.","Straighten the arms to push back up."],"common_mistakes":["Moving at the shoulders","Hips sagging"],"regressions":["Sphinx push-up"],"progressions":["Tiger bend push-up"],"safety":"Steeper body angle = harder; start nearly upright.","video":null,"diagram":"","notes":""},{"id":"superman","name":"Superman hold","aliases":["Superman","Prone back extension"],"training_type":"Core","tags":["Back","Core","Home-friendly"],"muscle_group":"Back","primary_muscles":["Erector spinae"],"secondary_muscles":["Glutes","Hamstrings","Rear delts"],"movement_pattern":"Extension","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"20–30 sec","form_cues":["Lie face down, arms stretched overhead.","Lift arms, chest and legs a few centimetres together.","Keep your neck long and look at the floor."],"common_mistakes":["Cranking the neck up","Lifting too high and pinching the lower back"],"regressions":["Bird dog","Alternating superman"],"progressions":["Superman with pulses","Back extension"],"safety":"Keep the lift small; stop if you feel lower-back pain.","video":null,"diagram":"","notes":""},{"id":"bearhold","name":"Bear plank hold","aliases":["Bear hold","Hover plank","Quadruped hover"],"training_type":"Core","tags":["Core","Home-friendly","Warm-up"],"muscle_group":"Core","primary_muscles":["Transverse abdominis","Rectus abdominis"],"secondary_muscles":["Shoulders","Quadriceps","Hip flexors"],"movement_pattern":"Anti-extension","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"20–45 sec","form_cues":["On hands and knees, hands under shoulders, knees under hips","Lift knees about 3 cm off the floor","Keep your back flat like a table"],"common_mistakes":["Hips rising high","Rounding or arching the back"],"regressions":["Bird dog"],"progressions":["Bear plank shoulder taps","Bear crawl"],"safety":"Keep breathing; go to fists if wrists hurt.","video":null,"diagram":"","notes":""},{"id":"bicycle","name":"Bicycle crunch","aliases":["Bicycle kick crunch","Bicycles","Elbow-to-knee crunch"],"training_type":"Core","tags":["Core","Home-friendly"],"muscle_group":"Core","primary_muscles":["Obliques","Rectus abdominis"],"secondary_muscles":["Hip flexors"],"movement_pattern":"Rotation","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"20 (10 / side)","form_cues":["Hands lightly behind the head, shoulders off the floor","Rotate one shoulder toward the opposite knee as the other leg extends","Slow down and pause on each twist"],"common_mistakes":["Flapping elbows instead of rotating the ribs","Racing through reps","Lower back peeling up"],"regressions":["Dead bug","Heel touches"],"progressions":["Weighted Russian twist"],"safety":"Keep the extended leg higher if your back arches.","video":null,"diagram":"","notes":""},{"id":"birddog","name":"Bird dog","aliases":["Quadruped arm and leg raise","Pointer"],"training_type":"Core","tags":["Balance","Core","Home-friendly","Rehab","Warm-up"],"muscle_group":"Core","primary_muscles":["Erector spinae","Transverse abdominis"],"secondary_muscles":["Glutes","Shoulders","Obliques"],"movement_pattern":"Anti-rotation","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"8–10 / side","form_cues":["Hands under shoulders, knees under hips, back flat","Reach the opposite arm and leg out long","Pause for 2 seconds without the hips tilting, then switch"],"common_mistakes":["Arching the back as the leg lifts","Hips rotating open"],"regressions":["Bird dog arm or leg only"],"progressions":["Bird dog elbow-to-knee crunch","Banded bird dog"],"safety":"Keep it small and controlled if you have back pain.","video":null,"diagram":"","notes":"One of McGill's 'Big 3' back-health moves."},{"id":"bodysaw","name":"Body saw","aliases":["Plank body saw","Slider body saw"],"training_type":"Core","tags":["Core","Home-friendly"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Transverse abdominis"],"secondary_muscles":["Shoulders","Lats","Serratus anterior"],"movement_pattern":"Anti-extension","equipment":["Sliders or towel"],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"count","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Forearm plank with feet on sliders or a towel","Push your body back so elbows go in front of your face","Pull back to the start without letting hips sag"],"common_mistakes":["Lower back arching as you push back","Sliding too far too soon"],"regressions":["Plank"],"progressions":["Ab wheel rollout","Stability ball rollout"],"safety":"Only go as far as you can keep the ribs down.","video":null,"diagram":"","notes":"A towel on a hard floor or socks on wood work as sliders."},{"id":"butterflysitup","name":"Butterfly sit-up","aliases":["AbMat sit-up","Frog sit-up"],"training_type":"Core","tags":["Core","Endurance","Home-friendly"],"muscle_group":"Core","primary_muscles":["Rectus abdominis"],"secondary_muscles":["Obliques","Hip flexors"],"movement_pattern":"Flexion","equipment":["Mat (optional AbMat)"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"15–25","form_cues":["Soles of feet together, knees out wide","Reach arms overhead and swing up to touch your feet","Roll back down and touch the floor behind you"],"common_mistakes":["Using only arm swing","Slamming back onto the floor"],"regressions":["Sit-up"],"progressions":["Decline sit-up","GHD sit-up"],"safety":"Use a rolled towel under the lower back if it feels uncomfortable.","video":null,"diagram":"","notes":"Common in CrossFit; the knees-out position limits hip flexor pull."},{"id":"copenhagen","name":"Copenhagen plank","aliases":["Copenhagen side plank","Copenhagen adductor plank"],"training_type":"Core","tags":["Core","Home-friendly","Rehab","Unilateral"],"muscle_group":"Core","primary_muscles":["Adductors","Obliques"],"secondary_muscles":["Quadratus lumborum","Glute medius"],"movement_pattern":"Anti-lateral flexion","equipment":["Bench or chair"],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"hold","unilateral":true,"sets":3,"reps":"15–30 sec / side","form_cues":["Top leg rests on a bench or chair, bottom leg hangs free","Lift hips into a straight side plank line","Squeeze the top leg down into the bench the whole time"],"common_mistakes":["Hips sagging","Too much leg on the bench too soon"],"regressions":["Short-lever Copenhagen (knee on bench)","Side plank"],"progressions":["Copenhagen plank with bottom-leg raise"],"safety":"Start with the knee on the bench to protect the groin; stop with sharp adductor pain.","video":null,"diagram":"","notes":"Great for groin injury prevention in field sports. A chair works if you have no bench."},{"id":"crossmtn","name":"Cross-body mountain climber","aliases":["Cross-body climbers","Twisting mountain climbers","Oblique mountain climbers"],"training_type":"Core","tags":["Cardio","Core","Home-friendly"],"muscle_group":"Core","primary_muscles":["Obliques","Rectus abdominis"],"secondary_muscles":["Hip flexors","Shoulders"],"movement_pattern":"Rotation","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"20 (10 / side)","form_cues":["Start in a strong high plank","Drive each knee toward the opposite elbow","Keep the hips low and shoulders still"],"common_mistakes":["Hips piking up","Rushing and losing the twist"],"regressions":["Mountain climbers"],"progressions":["Spiderman plank"],"safety":"Keep the pace controlled if your back sags.","video":null,"diagram":"","notes":""},{"id":"floorcrunch","name":"Crunch","aliases":["Basic crunch","Floor crunch","Abdominal crunch"],"training_type":"Core","tags":["Core","Home-friendly","Isolation"],"muscle_group":"Core","primary_muscles":["Rectus abdominis"],"secondary_muscles":["Obliques"],"movement_pattern":"Flexion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"15–20","form_cues":["Lie on your back, knees bent, feet flat","Curl your ribs toward your hips until shoulder blades lift","Lower slowly and keep a fist-sized gap under the chin"],"common_mistakes":["Yanking on the neck","Swinging up with momentum","Lifting the whole back off the floor (that's a sit-up)"],"regressions":[],"progressions":["Weighted crunch","Stability ball crunch","Decline crunch"],"safety":"Support the head lightly with fingertips; don't pull.","video":null,"diagram":"","notes":"Hold a plate on the chest to add load."},{"id":"deadbug","name":"Dead bug","aliases":["Deadbug","Contralateral dead bug"],"training_type":"Core","tags":["Core","Home-friendly","Rehab","Warm-up"],"muscle_group":"Core","primary_muscles":["Transverse abdominis","Rectus abdominis"],"secondary_muscles":["Obliques","Hip flexors"],"movement_pattern":"Anti-extension","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"8–10 / side","form_cues":["Lie on your back, arms to ceiling, knees at 90°","Lower the opposite arm and leg toward the floor","Keep the lower back flat and breathe out as you reach"],"common_mistakes":["Lower back arching","Moving too fast"],"regressions":["Heel taps (legs only)"],"progressions":["Weighted dead bug","Band dead bug","Hollow body hold"],"safety":"A good choice for sensitive backs; shorten the range if the back lifts.","video":null,"diagram":"","notes":"Hold a dumbbell or press into a band to progress."},{"id":"flutter","name":"Flutter kicks","aliases":["Flutters","Straight-leg flutter kicks"],"training_type":"Core","tags":["Core","Endurance","Home-friendly"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Hip flexors"],"secondary_muscles":["Obliques","Quadriceps"],"movement_pattern":"Anti-extension","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"30 kicks","form_cues":["Lie down, hands under hips, lower back pressed down","Lift legs a few centimetres off the floor","Kick small, quick up-and-down alternations"],"common_mistakes":["Lower back arching","Kicks too big and sloppy"],"regressions":["Dead bug"],"progressions":["Hollow body hold","Scissor kicks"],"safety":"Raise the legs higher if your back arches.","video":null,"diagram":"","notes":"Can also be tracked as time (30–45 sec)."},{"id":"heeltap","name":"Heel touches","aliases":["Alternating heel touches","Heel taps","Side-to-side oblique reach"],"training_type":"Core","tags":["Core","Home-friendly"],"muscle_group":"Core","primary_muscles":["Obliques"],"secondary_muscles":["Rectus abdominis"],"movement_pattern":"Anti-lateral flexion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"20 (10 / side)","form_cues":["Lie with knees bent, feet a bit wider than hips","Lift shoulders and reach one hand to the same-side heel","Stay curled up as you tap side to side"],"common_mistakes":["Dropping the head between reps","Pulling the chin into the chest"],"regressions":[],"progressions":["Oblique crunch","Bicycle crunch"],"safety":"Fine for most people; rest the head between sets if the neck tires.","video":null,"diagram":"","notes":""},{"id":"highplank","name":"High plank","aliases":["Straight-arm plank","Push-up plank","Full plank"],"training_type":"Core","tags":["Core","Home-friendly","Warm-up"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Transverse abdominis"],"secondary_muscles":["Shoulders","Chest","Triceps"],"movement_pattern":"Anti-extension","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30–45 sec","form_cues":["Hands under shoulders, arms straight but not locked","Spread your fingers and push the floor away","Tuck pelvis slightly and keep a straight line"],"common_mistakes":["Shoulders sinking toward the floor","Hips sagging"],"regressions":["Kneeling high plank","Incline plank on a bench"],"progressions":["Plank shoulder taps","Plank up-down"],"safety":"Go to fists or forearms if your wrists hurt.","video":null,"diagram":"","notes":""},{"id":"hollowhold","name":"Hollow body hold","aliases":["Hollow hold","Hollow position","Dish hold"],"training_type":"Core","tags":["Calisthenics","Core","Home-friendly"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Transverse abdominis"],"secondary_muscles":["Hip flexors","Obliques"],"movement_pattern":"Anti-extension","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"20–40 sec","form_cues":["Press your lower back into the floor","Lift shoulders and legs, arms reaching past your ears","Hold the banana shape and keep breathing"],"common_mistakes":["Lower back lifting off the floor","Holding the breath"],"regressions":["Tuck hollow hold","Dead bug"],"progressions":["Hollow body rock"],"safety":"Tuck the knees or bring arms forward if your back lifts.","video":null,"diagram":"","notes":"A foundation for gymnastics and calisthenics skills."},{"id":"hollowrock","name":"Hollow body rock","aliases":["Hollow rocks","Hollow rock"],"training_type":"Core","tags":["Calisthenics","Core","Home-friendly"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Transverse abdominis"],"secondary_muscles":["Hip flexors","Obliques"],"movement_pattern":"Anti-extension","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"count","unilateral":false,"sets":3,"reps":"15–20","form_cues":["Get into a tight hollow hold","Rock from shoulders to hips without changing shape","Keep arms by the ears and legs together"],"common_mistakes":["Bending at the hips to make the rock","Losing the low-back contact"],"regressions":["Hollow body hold"],"progressions":["Weighted hollow rock"],"safety":"Only rock if you can hold the hollow position for 30 sec first.","video":null,"diagram":"","notes":""},{"id":"jackknife","name":"Jackknife sit-up","aliases":["Jackknife","Single-leg V-up"],"training_type":"Core","tags":["Core","Home-friendly"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Hip flexors"],"secondary_muscles":["Obliques"],"movement_pattern":"Flexion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Lie flat, arms overhead","Raise one straight leg as you reach both hands to that foot","Lower back down and alternate legs"],"common_mistakes":["Pulling with the neck","Bending the reaching leg a lot"],"regressions":["Toe touch crunch"],"progressions":["V-up"],"safety":"Keep the non-working leg on the floor for support.","video":null,"diagram":"","notes":""},{"id":"lyinglegraise","name":"Lying leg raise","aliases":["Leg raise","Floor leg raise","Straight-leg raise"],"training_type":"Core","tags":["Core","Home-friendly"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Hip flexors"],"secondary_muscles":["Obliques"],"movement_pattern":"Flexion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"10–15","form_cues":["Lie flat, hands under hips or by your sides","Press the lower back into the floor and raise straight legs to vertical","Lower slowly until just before the back lifts"],"common_mistakes":["Lower back arching off the floor","Dropping the legs fast"],"regressions":["Bent-knee leg raise","Reverse crunch"],"progressions":["Bench leg raise","Hanging leg raise"],"safety":"Bend the knees or shorten the range if your lower back lifts.","video":null,"diagram":"","notes":""},{"id":"lyingwiper","name":"Lying windshield wipers","aliases":["Floor windshield wipers","Lying leg rotations"],"training_type":"Core","tags":["Core","Home-friendly"],"muscle_group":"Core","primary_muscles":["Obliques"],"secondary_muscles":["Rectus abdominis","Hip flexors"],"movement_pattern":"Rotation","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"8–10 / side","form_cues":["Lie on your back with arms out in a T, legs up at 90°","Lower your legs to one side while shoulders stay down","Pull them back to centre and go to the other side"],"common_mistakes":["Shoulders lifting off the floor","Dropping the legs too fast"],"regressions":["Bent-knee windshield wipers"],"progressions":["Hanging windshield wipers"],"safety":"Bend the knees to shorten the lever if your back aches.","video":null,"diagram":"","notes":""},{"id":"mtnclimber","name":"Mountain climbers","aliases":["Mountain climber","Running plank"],"training_type":"Core","tags":["Cardio","Core","Endurance","Home-friendly","Warm-up"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Hip flexors"],"secondary_muscles":["Shoulders","Quadriceps"],"movement_pattern":"A