e tuck","aliases":["Seated in-and-outs","Knee tucks","Seated crunch"],"training_type":"Core","tags":["Core","Home-friendly"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Hip flexors"],"secondary_muscles":["Obliques"],"movement_pattern":"Flexion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Sit leaning back on your hands, feet off the floor","Pull your knees toward your chest as your chest moves toward them","Extend the legs out long without touching the floor"],"common_mistakes":["Rounding the shoulders forward","Letting the feet drop"],"regressions":["Reverse crunch"],"progressions":["Tuck-up","V-sit hold"],"safety":"Lean back on forearms if you feel it in your lower back.","video":null,"diagram":"","notes":"Can also be done on a bench edge."},{"id":"sideplank","name":"Side plank","aliases":["Forearm side plank","Lateral plank"],"training_type":"Core","tags":["Core","Home-friendly","Rehab","Unilateral"],"muscle_group":"Core","primary_muscles":["Obliques","Quadratus lumborum"],"secondary_muscles":["Glute medius","Transverse abdominis","Shoulders"],"movement_pattern":"Anti-lateral flexion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":3,"reps":"20–45 sec / side","form_cues":["Elbow directly under shoulder, feet stacked or staggered","Lift hips so ankles, hips and shoulders line up","Push the floor away and don't let the top hip roll back"],"common_mistakes":["Hips sagging down","Rolling forward or back","Shoulder shrugged up to the ear"],"regressions":["Kneeling side plank"],"progressions":["Side plank hip dips","Side plank with rotation","Copenhagen plank"],"safety":"Bend the bottom knee to shorten the lever if your shoulder complains.","video":null,"diagram":"","notes":"Stagger the feet for more stability; stack them for more challenge."},{"id":"sideplankdip","name":"Side plank hip dips","alia