acking":"bw","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Load small round plates and kneel behind the bar","Roll forward with ribs down and glutes tight","Pull back with your abs"],"common_mistakes":["Arching the back","Hips staying behind"],"regressions":["Ab wheel rollout"],"progressions":["Standing ab wheel rollout"],"safety":"Use plates with round edges so the bar rolls smoothly.","video":null,"diagram":"","notes":"Wider grip than an ab wheel; good gym substitute."},{"id":"benchlegraise","name":"Bench leg raise","aliases":["Flat bench leg raise","Bench lying leg raise"],"training_type":"Core","tags":["Core"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Hip flexors"],"secondary_muscles":["Obliques"],"movement_pattern":"Flexion","equipment":["Flat bench"],"req":"flatbench|adjbench","equipment_tier":2,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"10–15","form_cues":["Lie on a bench gripping it behind your head","Raise your legs and curl the hips off the bench","Lower slowly past bench level without arching"],"common_mistakes":["Swinging the legs","Lower back lifting"],"regressions":["Lying leg raise","Reverse crunch"],"progressions":["Dragon flag"],"safety":"Bend the knees if your lower back arches.","video":null,"diagram":"","notes":""},{"id":"crunch","name":"Cable rope crunch","aliases":["Kneeling cable crunch","Cable crunch","Rope crunch"],"training_type":"Core","tags":["Core","Hypertrophy","Isolation"],"muscle_group":"Core","primary_muscles":["Rectus abdominis"],"secondary_muscles":["Obliques"],"movement_pattern":"Flexion","equipment":["Cable machine","Rope attachment"],"req":"functional|cablecross|multigym","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"10–15","form_cues":["Kneel facing the stack, rope beside your head","Curl your ribs toward your hips, rounding the spine","Keep the hips still and return slowly"],"common_mistakes":["Sitting back with the hips instead of crunching","Pulling with the arms"],"regressions":["Stability ball crunch"],"progressions":["Heavier cable crunch"],"safety":"Keep the weight moderate so you can feel the abs, not the hips.","video":null,"diagram":"crunch","notes":"One of the best ways to load the abs progressively."},{"id":"woodchop","name":"Cable woodchop","aliases":["High-to-low cable woodchop","Cable chop"],"training_type":"Core","tags":["Compound","Core"],"muscle_group":"Core","primary_muscles":["Obliques"],"secondary_muscles":["Rectus abdominis","Shoulders","Glutes"],"movement_pattern":"Rotation","equipment":["Cable machine","D-handle or rope"],"req":"functional|cablecross","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"10–12 / side","form_cues":["Set the pulley high and stand side-on","Pull diagonally down across your body to the opposite hip","Rotate through the torso and pivot the back foot"],"common_mistakes":["Arms doing all the work","Rounding the lower back"],"regressions":["Band woodchop"],"progressions":["Low-to-high cable woodchop","Landmine rotation"],"safety":"Use a load you can control on the way back up.","video":null,"diagram":"","notes":""},{"id":"declinecrunch","name":"Decline crunch","aliases":["Decline bench crunch"],"training_type":"Core","tags":["Core","Isolation"],"muscle_group":"Core","primary_muscles":["Rectus abdominis"],"secondary_muscles":["Obliques"],"movement_pattern":"Flexion","equipment":["Decline / ab bench"],"req":"abbench|declinebench","equipment_tier":2,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"12–15","form_cues":["Secure your feet and lie back on the decline bench","Curl your shoulders up without sitting all the way","Lower with control, keeping tension"],"common_mistakes":["Pulling the head forward","Using momentum"],"regressions":["Crunch"],"progressions":["Weighted decline crunch","Decline sit-up"],"safety":"Start at a shallow angle.","video":null,"diagram":"","notes":""},{"id":"situp","name":"Decline sit-up","aliases":["Decline bench sit-up","Weighted decline sit-up"],"training_type":"Core","tags":["Core"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Hip flexors"],"secondary_muscles":["Obliques"],"movement_pattern":"Flexion","equipment":["Decline / ab bench"],"req":"abbench|declinebench","equipment_tier":2,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"10–15","form_cues":["Hook feet under the pads, arms crossed on chest","Curl up until your torso is near vertical","Lower slowly to just above the bench"],"common_mistakes":["Yanking up with the neck","Dropping back fast"],"regressions":["Sit-up"],"progressions":["Weighted decline sit-up","GHD sit-up"],"safety":"Lower the bench angle to make it easier.","video":null,"diagram":"situp","notes":"Hold a plate on your chest to add load."},{"id":"dragonflag","name":"Dragon flag","aliases":["Bruce Lee dragon flag"],"training_type":"Core","tags":["Calisthenics","Core"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Transverse abdominis"],"secondary_muscles":["Obliques","Lats","Hip flexors"],"movement_pattern":"Anti-extension","equipment":["Flat bench"],"req":"flatbench|adjbench","equipment_tier":2,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"3–6","form_cues":["Lie on a bench and grip it behind your head","Lift your body to vertical, resting on the upper back","Lower as one straight line, then raise back up"],"common_mistakes":["Bending at the hips","Lower back arching on the way down"],"regressions":["Tuck dragon flag","Dragon flag negatives","Bench leg raise"],"progressions":[],"safety":"Very demanding; build up with negatives and stop if your neck takes the load.","video":null,"diagram":"","notes":""},{"id":"landminerot","name":"Landmine rotation","aliases":["Landmine 180","Landmine rainbow","Landmine twist"],"training_type":"Core","tags":["Core","Power"],"muscle_group":"Core","primary_muscles":["Obliques"],"secondary_muscles":["Shoulders","Rectus abdominis","Glutes"],"movement_pattern":"Rotation","equipment":["Barbell","Landmine attachment"],"req":"landmine,barbell","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"8–10 / side","form_cues":["Hold the bar end at arm's length above your head","Rotate it down in an arc to one hip, pivoting the feet","Bring it back over the top and go to the other side"],"common_mistakes":["Bending the arms","Twisting from the lower back with locked hips"],"regressions":["Russian twist","Cable woodchop"],"progressions":["Heavier landmine rotation"],"safety":"Start with the empty bar; use a corner if you have no landmine.","video":null,"diagram":"","notes":""},{"id":"lowhighchop","name":"Low-to-high cable woodchop","aliases":["Reverse woodchop","Cable lift","Low-to-high chop"],"training_type":"Core","tags":["Compound","Core"],"muscle_group":"Core","primary_muscles":["Obliques"],"secondary_muscles":["Shoulders","Glutes"],"movement_pattern":"Rotation","equipment":["Cable machine","D-handle or rope"],"req":"functional|cablecross","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"10–12 / side","form_cues":["Set the pulley low and stand side-on","Pull up diagonally across your body to above the opposite shoulder","Drive from the hips and keep arms long"],"common_mistakes":["Lifting with the arms only","Leaning back"],"regressions":["Band woodchop"],"progressions":["Half-kneeling cable lift"],"safety":"Keep the spine long; don't round to grab the handle.","video":null,"diagram":"","notes":""},{"id":"pallof","name":"Pallof press","aliases":["Cable Pallof press","Cable anti-rotation press"],"training_type":"Core","tags":["Core","Rehab"],"muscle_group":"Core","primary_muscles":["Obliques","Transverse abdominis"],"secondary_muscles":["Rectus abdominis","Shoulders"],"movement_pattern":"Anti-rotation","equipment":["Cable machine","D-handle"],"req":"functional|cablecross","equipment_tier":2,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":3,"reps":"10–12 / side","form_cues":["Stand side-on with the handle at chest","Press it straight out and resist the pull","Hold 2 seconds, then bring it back slowly"],"common_mistakes":["Torso twisting toward the stack","Feet too narrow"],"regressions":["Band Pallof press"],"progressions":["Half-kneeling Pallof press","Pallof press with overhead reach"],"safety":"Start light; it's harder than it looks.","video":null,"diagram":"","notes":""},{"id":"cablerot","name":"Standing cable rotation","aliases":["Horizontal cable woodchop","Cable trunk rotation","Cable twist"],"training_type":"Core","tags":["Core"],"muscle_group":"Core","primary_muscles":["Obliques"],"secondary_muscles":["Rectus abdominis","Shoulders"],"movement_pattern":"Rotation","equipment":["Cable machine","D-handle"],"req":"functional|cablecross","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"10–12 / side","form_cues":["Set the pulley at chest height, stand side-on","Rotate away from the stack with arms straight","Return slowly without letting it yank you back"],"common_mistakes":["Bending the arms","Hips locked so the lower back twists"],"regressions":["Band woodchop"],"progressions":["Landmine rotation"],"safety":"Let the hips turn a little to spare the lower back.","video":null,"diagram":"","notes":""},{"id":"trxfallout","name":"Suspension fallout","aliases":["TRX fallout","TRX rollout","Suspension body saw"],"training_type":"Core","tags":["Core"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Transverse abdominis"],"secondary_muscles":["Lats","Shoulders"],"movement_pattern":"Anti-extension","equipment":["Suspension trainer"],"req":"trx|rings","equipment_tier":2,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Hold handles facing away from the anchor, body leaning forward","Let arms rise overhead as you fall forward","Pull back up with your abs, not the arms"],"common_mistakes":["Lower back arching","Bending the elbows"],"regressions":["Plank"],"progressions":["Ab wheel rollout"],"safety":"A steeper body angle is harder; start more upright.","video":null,"diagram":"","notes":""},{"id":"trxtuck","name":"Suspension knee tuck","aliases":["TRX knee tuck","Suspension crunch","TRX crunch"],"training_type":"Core","tags":["Core"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Hip flexors"],"secondary_muscles":["Shoulders","Transverse abdominis"],"movement_pattern":"Flexion","equipment":["Suspension trainer"],"req":"trx|rings","equipment_tier":2,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Feet in the straps, high plank position","Pull knees in toward your chest","Extend back to a straight plank"],"common_mistakes":["Hips sagging","Shoulders drifting back"],"regressions":["Mountain climbers"],"progressions":["Suspension pike"],"safety":"Keep the straps at mid-calf height.","video":null,"diagram":"","notes":""},{"id":"trxpike","name":"Suspension pike","aliases":["TRX pike","Suspension trainer pike"],"training_type":"Core","tags":["Calisthenics","Core"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Hip flexors"],"secondary_muscles":["Shoulders","Serratus anterior"],"movement_pattern":"Flexion","equipment":["Suspension trainer"],"req":"trx|rings","equipment_tier":2,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Feet in the straps, start in a high plank","Lift hips high keeping legs straight","Lower slowly back to a flat plank"],"common_mistakes":["Bending the knees","Sagging hips at the bottom"],"regressions":["Suspension knee tuck"],"progressions":[],"safety":"Keep shoulders stacked over hands.","video":null,"diagram":"","notes":""},{"id":"romanside","name":"45-degree side bend","aliases":["Roman chair side bend","Hyperextension side bend","Lateral back extension"],"training_type":"Core","tags":["Core","Unilateral"],"muscle_group":"Core","primary_muscles":["Obliques","Quadratus lumborum"],"secondary_muscles":["Glute medius"],"movement_pattern":"Anti-lateral flexion","equipment":["Back extension bench"],"req":"romanchair","equipment_tier":3,"difficulty":"Intermediate","tracking":"bw","unilateral":true,"sets":3,"reps":"10–12 / side","form_cues":["Lie sideways on the bench, hip on the pad, feet locked","Lower your torso sideways toward the floor","Raise back up past level using the top-side obliques"],"common_mistakes":["Rotating forward or back","Bouncing at the bottom"],"regressions":["Dumbbell side bend","Side plank"],"progressions":["Weighted 45-degree side bend"],"safety":"Use a short range first; stop with sharp back pain.","video":null,"diagram":"","notes":""},{"id":"abmach","name":"Ab crunch machine","aliases":["Machine crunch","Seated ab crunch"],"training_type":"Core","tags":["Core","Hypertrophy","Isolation"],"muscle_group":"Core","primary_muscles":["Rectus abdominis"],"secondary_muscles":["Obliques"],"movement_pattern":"Flexion","equipment":["Ab crunch machine"],"req":"abcrunchm","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"10–15","form_cues":["Set the seat so the pads sit on your chest or shoulders","Curl down by bringing ribs to hips","Return slowly without letting the stack slam"],"common_mistakes":["Pulling with the arms","Using too much weight and hip-flexing"],"regressions":["Crunch"],"progressions":["Cable rope crunch"],"safety":"Start light and keep the motion in the abs.","video":null,"diagram":"crunch","notes":""},{"id":"kneeraise","name":"Captain's chair knee raise","aliases":["Vertical knee raise","Roman chair knee raise","Captain's chair leg raise"],"training_type":"Core","tags":["Core"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Hip flexors"],"secondary_muscles":["Obliques"],"movement_pattern":"Flexion","equipment":["Captain's chair"],"req":"captain","equipment_tier":3,"difficulty":"Beginner","tracking":"bw","unilateral":false,"sets":3,"reps":"10–15","form_cues":["Back against the pad, forearms on the rests","Lift knees to chest by curling the hips up","Lower with control without swinging"],"common_mistakes":["Swinging the legs","Only lifting to 90° without curling the pelvis"],"regressions":["Reverse crunch"],"progressions":["Hanging knee raise","Hanging leg raise"],"safety":"Keep shoulders down, not shrugged.","video":null,"diagram":"","notes":"Straighten the legs for a harder leg raise version."},{"id":"ghdsitup","name":"GHD sit-up","aliases":["Glute-ham developer sit-up"],"training_type":"Core","tags":["Core"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Hip flexors"],"secondary_muscles":["Quadriceps","Obliques"],"movement_pattern":"Flexion","equipment":["Glute-ham developer"],"req":"ghd","equipment_tier":3,"difficulty":"Advanced","tracking":"bw","unilateral":false,"sets":3,"reps":"8–15","form_cues":["Sit on the pad with feet locked, hips just past it","Lower back to parallel, then reach behind if trained","Kick the knees straight to sit up and reach for your feet"],"common_mistakes":["Going too far back too soon","Doing high volume on the first try"],"regressions":["Decline sit-up"],"progressions":[],"safety":"Start with low reps and a short range; overuse can cause rhabdo or back strain.","video":null,"diagram":"","notes":""},{"id":"torsorot","name":"Rotary torso machine","aliases":["Seated torso rotation","Torso twist machine","Oblique machine"],"training_type":"Core","tags":["Core","Isolation"],"muscle_group":"Core","primary_muscles":["Obliques"],"secondary_muscles":["Rectus abdominis"],"movement_pattern":"Rotation","equipment":["Rotary torso machine"],"req":"torso","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":3,"reps":"10–15 / side","form_cues":["Sit tall with legs locked in","Rotate through your trunk, not your arms","Return slowly to centre"],"common_mistakes":["Jerking the weight","Too much range"],"regressions":["Russian twist"],"progressions":["Cable woodchop"],"safety":"Use a moderate load; avoid with disc issues aggravated by twisting.","video":null,"diagram":"","notes":""},{"id":"heeltoewalk","name":"Heel-to-toe walk","aliases":["Tandem walk","Tightrope walk","Line walk"],"training_type":"Balance","tags":["Balance","Home-friendly","Rehab"],"muscle_group":"Legs","primary_muscles":["Ankle stabilisers"],"secondary_muscles":["Calves","Core","Hip abductors"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"20 steps","form_cues":["Walk in a straight line, heel touching the toes of the back foot","Keep your eyes forward, not on your feet","Move slowly and steadily"],"common_mistakes":["Rushing the steps","Arms flailing for balance"],"regressions":["Tandem stance hold"],"progressions":["Heel-to-toe walk backwards","Heel-to-toe walk, eyes closed"],"safety":"Walk beside a wall or counter until confident.","video":null,"diagram":"","notes":""},{"id":"slstand","name":"Single-leg stand","aliases":["Single-leg balance","Stork stand","One-leg stand"],"training_type":"Balance","tags":["Balance","Home-friendly","Rehab","Unilateral","Warm-up"],"muscle_group":"Legs","primary_muscles":["Ankle stabilisers","Glute medius"],"secondary_muscles":["Calves","Core"],"movement_pattern":"Hold","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":3,"reps":"30 sec / side","form_cues":["Stand tall and lift one foot just off the floor","Spread your toes and keep a slight bend in the standing knee","Fix your eyes on a point ahead"],"common_mistakes":["Locking the standing knee","Hip dropping on the lifted side"],"regressions":["Tandem stance hold","Fingertip support on a wall"],"progressions":["Single-leg stand, eyes closed","BOSU single-leg balance"],"safety":"Stand near a wall or counter in case you lose balance.","video":null,"diagram":"","notes":"Great for ankle sprain rehab and fall prevention."},{"id":"slstandeyes","name":"Single-leg stand, eyes closed","aliases":["Eyes-closed single-leg balance","Blind stork stand"],"training_type":"Balance","tags":["Balance","Home-friendly","Rehab","Unilateral"],"muscle_group":"Legs","primary_muscles":["Ankle stabilisers","Glute medius"],"secondary_muscles":["Calves","Core"],"movement_pattern":"Hold","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":3,"reps":"15–30 sec / side","form_cues":["Get steady on one leg with eyes open first","Close your eyes and keep the standing knee soft","Let the ankle make small corrections"],"common_mistakes":["Locking the knee","Grabbing for support too early"],"regressions":["Single-leg stand"],"progressions":["Single-leg stand on a BOSU"],"safety":"Always do this next to a wall or sturdy support.","video":null,"diagram":"","notes":"Removing vision makes the ankle and inner ear work harder."},{"id":"sltoetouch","name":"Single-leg toe touch","aliases":["Single-leg reach to floor","Single-leg balance reach","Single-leg touchdown"],"training_type":"Balance","tags":["Balance","Home-friendly","Unilateral"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings"],"secondary_muscles":["Ankle stabilisers","Core"],"movement_pattern":"Hinge","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Stand on one leg with a soft knee","Hinge forward and reach your hand toward the floor","Squeeze the glute to stand back up tall"],"common_mistakes":["Rounding the back to reach","Standing knee caving in"],"regressions":["Single-leg stand"],"progressions":["Single-leg Romanian deadlift","Single-leg airplane"],"safety":"Reach to a box or chair if the floor is too far.","video":null,"diagram":"","notes":""},{"id":"starexc","name":"Star excursion balance","aliases":["Star excursion","Single-leg clock reach","Single-leg reach"],"training_type":"Balance","tags":["Balance","Home-friendly","Rehab","Unilateral"],"muscle_group":"Legs","primary_muscles":["Glute medius","Quadriceps"],"secondary_muscles":["Ankle stabilisers","Core","Hamstrings"],"movement_pattern":"Lunge","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":3,"reps":"1 round of 8 directions / side","form_cues":["Balance on one leg in a quarter squat","Reach the free toe as far as you can along each direction like a clock","Tap lightly, return to the centre and keep the standing heel down"],"common_mistakes":["Putting weight on the reaching foot","Standing knee caving inward"],"regressions":["Single-leg stand"],"progressions":["Y-balance reach","Star excursion on a BOSU"],"safety":"Keep reaches within a range you can control.","video":null,"diagram":"","notes":"Used by physios to test and train ankle and knee stability."},{"id":"tandemstance","name":"Tandem stance hold","aliases":["Heel-to-toe stance","Tightrope stance","Romberg tandem stance"],"training_type":"Balance","tags":["Balance","Home-friendly","Rehab"],"muscle_group":"Legs","primary_muscles":["Ankle stabilisers"],"secondary_muscles":["Calves","Core","Hip abductors"],"movement_pattern":"Hold","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30 sec each foot forward","form_cues":["Place one heel directly in front of the other foot's toes","Stand tall with arms relaxed","Hold, then switch which foot is in front"],"common_mistakes":["Looking down at the feet","Leaning to one side"],"regressions":["Semi-tandem stance (feet staggered)"],"progressions":["Heel-to-toe walk","Single-leg stand"],"safety":"Stand in a corner or by a counter for safety.","video":null,"diagram":"","notes":"Common in falls-prevention programmes for older adults."},{"id":"ybalance","name":"Y-balance reach","aliases":["Y-balance","Y-balance test drill","Three-way single-leg reach"],"training_type":"Balance","tags":["Balance","Home-friendly","Rehab","Unilateral"],"muscle_group":"Legs","primary_muscles":["Glute medius","Quadriceps"],"secondary_muscles":["Ankle stabilisers","Core","Hamstrings"],"movement_pattern":"Lunge","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":3,"reps":"5 / direction / side","form_cues":["Stand on one leg at the centre of a Y","Reach the free foot forward, then back-left, then back-right","Touch lightly and return without losing balance"],"common_mistakes":["Leaning heavily on the reaching foot","Standing heel lifting"],"regressions":["Single-leg stand","Star excursion balance"],"progressions":["Y-balance reach on a BOSU"],"safety":"Mark the lines with tape; stay near support if needed.","video":null,"diagram":"","notes":"Compare reach distances side to side to spot imbalances."},{"id":"hipairplane","name":"Single-leg airplane","aliases":["Hip airplane","Airplane balance","Standing airplane"],"training_type":"Balance","tags":["Balance","Home-friendly","Mobility","Unilateral"],"muscle_group":"Glutes","primary_muscles":["Glutes","Glute medius"],"secondary_muscles":["Hamstrings","Core","Ankle stabilisers"],"movement_pattern":"Rotation","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"count","unilateral":true,"sets":3,"reps":"5–6 / side","form_cues":["Hinge forward on one leg until your torso is near horizontal","Rotate your pelvis open toward the ceiling","Rotate back down so hips face the floor, staying balanced"],"common_mistakes":["Rotating the shoulders instead of the hips","Losing the hinge and standing up"],"regressions":["Single-leg toe touch","Hand-on-wall airplane"],"progressions":[],"safety":"Hold a wall or rack with one hand until you've mastered it.","video":null,"diagram":"","notes":"Builds hip control for running and lifting."},{"id":"bosusl","name":"BOSU single-leg balance","aliases":["Single-leg stand on BOSU","BOSU stork stand"],"training_type":"Balance","tags":["Balance","Rehab","Unilateral"],"muscle_group":"Legs","primary_muscles":["Ankle stabilisers","Glute medius"],"secondary_muscles":["Calves","Core","Quadriceps"],"movement_pattern":"Hold","equipment":["BOSU ball"],"req":"bosu","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":3,"reps":"20–30 sec / side","form_cues":["Step onto the centre of the dome with one foot","Keep a soft knee and lift the other foot","Look ahead and let the ankle make small corrections"],"common_mistakes":["Locking the knee","Knee caving inward"],"regressions":["Single-leg stand"],"progressions":["BOSU single-leg balance, eyes closed","Star excursion on a BOSU"],"safety":"Start next to a wall or rack for support.","video":null,"diagram":"","notes":"A foam balance pad is a good alternative."},{"id":"bosusquat","name":"BOSU squat","aliases":["Squat on BOSU","Dome squat"],"training_type":"Balance","tags":["Balance","Home-friendly","Legs"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Ankle stabilisers","Core"],"movement_pattern":"Squat","equipment":["BOSU ball"],"req":"bosu","equipment_tier":1,"difficulty":"Intermediate","tracking":"bw","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Stand on the dome with feet hip-width","Sit back into a squat with knees tracking over toes","Stand back up without wobbling"],"common_mistakes":["Knees caving in","Going too deep and losing balance"],"regressions":["Bodyweight squat"],"progressions":["BOSU squat on the flat side (dome down)"],"safety":"Use the dome side up; standing on the flat side is advanced.","video":null,"diagram":"","notes":""},{"id":"stabkneel","name":"Stability ball kneeling balance","aliases":["Kneeling on Swiss ball","Ball kneel"],"training_type":"Balance","tags":["Balance","Core"],"muscle_group":"Core","primary_muscles":["Transverse abdominis","Obliques"],"secondary_muscles":["Glutes","Quadriceps"],"movement_pattern":"Hold","equipment":["Stability ball"],"req":"stabball","equipment_tier":1,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":3,"reps":"20–45 sec","form_cues":["Start with hands and knees on the ball beside a wall","Lift your hands off and kneel upright","Keep hips forward and eyes on a fixed point"],"common_mistakes":["Sitting back on the heels","Tensing up and over-correcting"],"regressions":["Stability ball seated balance"],"progressions":[],"safety":"Clear the area and use a wall or partner nearby; falls are possible.","video":null,"diagram":"","notes":""},{"id":"stabseated","name":"Stability ball seated balance","aliases":["Swiss ball seated march","Seated ball balance"],"training_type":"Balance","tags":["Balance","Core","Home-friendly","Rehab"],"muscle_group":"Core","primary_muscles":["Transverse abdominis","Obliques"],"secondary_muscles":["Hip flexors","Erector spinae"],"movement_pattern":"Hold","equipment":["Stability ball"],"req":"stabball","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30–45 sec","form_cues":["Sit tall on the ball, feet hip-width, knees at 90°","Lift one foot slightly off the floor and hold","Switch feet without wobbling; progress to marching"],"common_mistakes":["Slouching","Feet too close together"],"regressions":[],"progressions":["Stability ball kneeling balance"],"safety":"Use a ball sized so your hips are level with your knees.","video":null,"diagram":"","notes":""},{"id":"accelsprint","name":"Acceleration sprint","aliases":["10 m sprint","20 m sprint","Short sprint"],"training_type":"Power","tags":["Cardio","Legs","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings","Quadriceps"],"secondary_muscles":["Calves","Hip flexors","Core"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":1,"reps":"6 × 10–20 m","form_cues":["Start from a split stance, leaning forward.","Push the ground back hard with powerful, full strides.","Rise gradually to upright over the first 10–15 m."],"common_mistakes":["Popping upright immediately","Short choppy steps","Starting cold without a warm-up"],"regressions":["Wall drill","Falling start sprint"],"progressions":["Hill sprint","Sled sprint","Broad jump into sprint"],"safety":"Warm up thoroughly; rest 1–2 min between reps to stay fast.","video":null,"diagram":"","notes":"Track times if you can; stop when speed drops."},{"id":"backpedalsprint","name":"Backpedal to sprint","aliases":["Backpedal and turn","Backpedal transition"],"training_type":"Power","tags":["Agility","Legs","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Calves","Hamstrings","Hip flexors"],"movement_pattern":"Locomotion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":1,"reps":"6 × 5 m back + 10 m","form_cues":["Backpedal low with weight on the balls of your feet.","On the cue or line, open the hips and turn.","Accelerate forward hard for 10 m."],"common_mistakes":["Standing tall while backpedalling","Slow, rounded turn"],"regressions":["Backpedal"],"progressions":["T-drill"],"safety":"Use a clear, flat area; start slowly.","video":null,"diagram":"","notes":""},{"id":"broadsprint","name":"Broad jump into sprint","aliases":["Broad jump to sprint","Jump and sprint"],"training_type":"Power","tags":["Legs","Plyometric","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Glutes","Quadriceps","Hamstrings"],"secondary_muscles":["Calves","Core"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":1,"reps":"5 × jump + 10 m","form_cues":["Do one maximal broad jump.","Land in an athletic stance with a forward lean.","Immediately sprint out 10 m, pushing hard on the first steps."],"common_mistakes":["Stalling or standing up after the landing","Landing off balance"],"regressions":["Broad jump","Falling start sprint"],"progressions":["Hurdle hops"],"safety":"Land softly with knees soft and tracking over toes; skip if you have acute knee or ankle pain.","video":null,"diagram":"","notes":"Links jumping power to acceleration."},{"id":"fallingstart","name":"Falling start sprint","aliases":["Lean and go","Falling sprint start"],"training_type":"Power","tags":["Legs","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Glutes","Quadriceps","Hamstrings"],"secondary_muscles":["Calves","Core"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":1,"reps":"5 × 10 m","form_cues":["Stand tall and lean forward from the ankles as one straight line.","When you feel you will fall, explode into a sprint.","Keep the lean for the first few strong steps."],"common_mistakes":["Bending at the waist","Stepping out too far in front of the body"],"regressions":["Wall drill"],"progressions":["Acceleration sprint"],"safety":"Warm up first; use a surface with good grip.","video":null,"diagram":"","notes":""},{"id":"flyingsprint","name":"Flying sprint","aliases":["Flying 20","Flying 10","Fly-in sprint"],"training_type":"Power","tags":["Cardio","Legs","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Hamstrings","Glutes","Hip flexors"],"secondary_muscles":["Calves","Quadriceps","Core"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"count","unilateral":false,"sets":1,"reps":"4 × 20 m (after 20 m build–up)","form_cues":["Build up over 20–30 m to near top speed.","Sprint the marked zone at full speed, running tall.","Stay relaxed in face and shoulders; strike under your hips."],"common_mistakes":["Tensing up and over-striding","Too short a build-up zone"],"regressions":["Acceleration sprint"],"progressions":[],"safety":"Only do these fresh and fully warmed up; hamstring strains happen at top speed.","video":null,"diagram":"","notes":"Trains maximum velocity; rest 3+ min between reps."},{"id":"mbchest","name":"Medicine ball chest pass","aliases":["Med ball chest throw","Chest pass"],"training_type":"Power","tags":["Chest","Compound","Power","Upper body"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Throw","equipment":["Medicine ball","Wall or partner"],"req":"medball","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Stand in an athletic stance, ball at your chest.","Step and throw the ball hard and straight at the wall.","Catch on the rebound and go again with control."],"common_mistakes":["Pushing slowly instead of throwing","Throwing with only the arms and no leg drive"],"regressions":["Kneeling chest pass","Plyo push-up"],"progressions":["Medicine ball supine chest throw","Rotational medicine ball throw"],"safety":"Use a ball that bounces (not a slam ball) for wall throws; keep your face clear on the rebound.","video":null,"diagram":"","notes":"3–5 kg suits most people."},{"id":"dbdevilpress","name":"Devil press","aliases":["Dumbbell devil press"],"training_type":"Power","tags":["Cardio","Compound","Endurance","Power","Strength"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Glutes","Hamstrings"],"secondary_muscles":["Chest","Triceps","Core","Quadriceps"],"movement_pattern":"Hinge","equipment":["Hex dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Do a burpee with your hands on the dumbbells.","Jump the feet in and swing both weights back between your legs.","Snap the hips to swing them straight overhead in one motion."],"common_mistakes":["Rounding the back on the swing","Pressing with the arms"],"regressions":["Burpees","Two-arm dumbbell snatch"],"progressions":["Man maker"],"safety":"Start light; the swing should come from the hips, not the lower back.","video":null,"diagram":"","notes":""},{"id":"dbcleanpress","name":"Dumbbell clean and press","aliases":["DB clean and jerk","Dumbbell clean to press"],"training_type":"Power","tags":["Compound","Endurance","Power","Strength"],"muscle_group":"Shoulders","primary_muscles":["Glutes","Hamstrings","Shoulders"],"secondary_muscles":["Triceps","Upper traps","Core"],"movement_pattern":"Vertical push","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"6–8","form_cues":["Hang-clean the dumbbells to your shoulders.","Re-set your feet and brace.","Press or push-press overhead, then lower to the thighs."],"common_mistakes":["Rushing the press before you're stable","Arching the back overhead"],"regressions":["Dumbbell hang clean","Standing dumbbell shoulder press"],"progressions":["Man maker"],"safety":"Lower the weights in two steps to protect your back.","video":null,"diagram":"","notes":""},{"id":"dbhighpull","name":"Dumbbell high pull","aliases":["DB high pull"],"training_type":"Power","tags":["Compound","Power","Strength"],"muscle_group":"Shoulders","primary_muscles":["Upper traps","Side delts"],"secondary_muscles":["Glutes","Hamstrings","Biceps"],"movement_pattern":"Vertical pull","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"6–8","form_cues":["Hold dumbbells in front of your thighs, hinge slightly.","Drive your hips forward explosively.","Let the pop carry the weights up, elbows high and out."],"common_mistakes":["Pulling with the arms only","Rounding the back"],"regressions":["Dumbbell upright row"],"progressions":["Single-arm dumbbell snatch"],"safety":"Keep the weights close to your body and your back flat.","video":null,"diagram":"","notes":""},{"id":"dbpushpress","name":"Dumbbell push press","aliases":["DB push press"],"training_type":"Power","tags":["Compound","Power","Strength"],"muscle_group":"Shoulders","primary_muscles":["Front delts","Triceps"],"secondary_muscles":["Quadriceps","Glutes","Upper traps"],"movement_pattern":"Vertical push","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"5–8","form_cues":["Hold dumbbells at your shoulders, feet hip-width.","Dip a few inches at the knees, then drive up hard.","Use the leg drive to press overhead; lower with control."],"common_mistakes":["Dipping too deep like a squat","Pressing before the legs finish"],"regressions":["Standing dumbbell shoulder press"],"progressions":["Dumbbell thruster"],"safety":"Keep the dip short and the knees tracking over your toes.","video":null,"diagram":"","notes":"Lets you handle more weight overhead than a strict press."},{"id":"manmaker","name":"Man maker","aliases":["Dumbbell man maker"],"training_type":"Power","tags":["Cardio","Compound","Endurance","Power","Strength"],"muscle_group":"Shoulders","primary_muscles":["Chest","Back","Shoulders","Quadriceps"],"secondary_muscles":["Triceps","Core","Glutes"],"movement_pattern":"Vertical push","equipment":["Hex dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":3,"reps":"6–8","form_cues":["Push-up on the dumbbells, then row each side once.","Jump the feet in and clean the weights to your shoulders.","Squat and press overhead (thruster); that's one rep."],"common_mistakes":["Sagging hips in the plank","Rushing the clean with a round back"],"regressions":["Renegade row","Dumbbell thruster"],"progressions":[],"safety":"Use hex dumbbells and a modest weight; form fades fast as you tire.","video":null,"diagram":"","notes":""},{"id":"proagility","name":"5-10-5 pro agility drill","aliases":["5-10-5 shuttle","Pro agility shuttle","20-yard shuttle"],"training_type":"Power","tags":["Agility","Legs","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Adductors"],"secondary_muscles":["Calves","Hamstrings","Core"],"movement_pattern":"Locomotion","equipment":["Cones or lines"],"req":"","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":1,"reps":"5–6 reps","form_cues":["Start straddling the middle line in a low stance.","Sprint 5 m one way, touch, then 10 m the other way.","Touch and sprint 5 m back through the middle."],"common_mistakes":["Standing up during the turns","Crossing the feet on the first step"],"regressions":["Shuttle run"],"progressions":["L-drill"],"safety":"Use a grippy surface; rest fully between timed reps.","video":null,"diagram":"","notes":"Standard combine test (5-10-5 yards); metres work fine."},{"id":"bandsprint","name":"Band-resisted sprint","aliases":["Resisted band sprint","Partner-resisted sprint"],"training_type":"Power","tags":["Legs","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Glutes","Quadriceps","Hamstrings"],"secondary_muscles":["Calves","Core"],"movement_pattern":"Gait","equipment":["Long resistance band or harness","Partner or anchor"],"req":"bands","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":1,"reps":"6 × 10–15 m","form_cues":["Loop the band round your waist with a partner holding behind.","Lean forward and drive hard with powerful steps.","Keep strong arm drive and a straight body line."],"common_mistakes":["Bending at the waist","Partner pulling so hard your form breaks"],"regressions":["Acceleration sprint"],"progressions":["Sled sprint"],"safety":"Check the band for wear and anchor it securely.","video":null,"diagram":"","notes":"Can also be done in place against an anchored band."},{"id":"boxdrill","name":"Box drill","aliases":["Four-cone box drill","Square drill"],"training_type":"Power","tags":["Agility","Legs","Power"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Calves","Adductors","Abductors","Hamstrings"],"movement_pattern":"Locomotion","equipment":["4 cones"],"req":"","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":1,"reps":"4–6 reps","form_cues":["Set four cones in a 5 m square.","Sprint forward, shuffle sideways, backpedal, then shuffle back.","Stay low and keep your hips facing forward."],"common_mistakes":["Crossing the feet in the shuffle","Rising up at each cone"],"regressions":["Lateral shuffle"],"progressions":["T-drill"],"safety":"Use a non-slip surface.","video":null,"diagram":"","notes":"Trains changes between forward, lateral and backward movement."},{"id":"dbcluster","name":"Dumbbell cluster","aliases":["Squat clean thruster"],"training_type":"Power","tags":["Compound","Endurance","Power","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Shoulders"],"secondary_muscles":["Hamstrings","Triceps","Core"],"movement_pattern":"Squat","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":3,"reps":"6–8","form_cues":["Clean the dumbbells from the floor into a front squat.","Drive straight up out of the squat.","Use the momentum to press overhead in one motion."],"common_mistakes":["Pausing at the bottom","Pulling with a round back"],"regressions":["Dumbbell thruster","Dumbbell squat clean"],"progressions":[],"safety":"Very demanding; scale weight and reps to keep form crisp.","video":null,"diagram":"","notes":"A CrossFit staple: a squat clean flowing into a thruster."},{"id":"dbhangclean","name":"Dumbbell hang clean","aliases":["DB hang power clean"],"training_type":"Power","tags":["Compound","Power","Strength"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings","Upper traps"],"secondary_muscles":["Quadriceps","Forearms","Core"],"movement_pattern":"Hinge","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"5–6","form_cues":["Hold dumbbells at mid-thigh with a flat back.","Jump the hips forward and shrug the weights up.","Drop under and catch them on your shoulders, knees soft."],"common_mistakes":["Reverse-curling the weights","Catching with locked knees"],"regressions":["Dumbbell high pull"],"progressions":["Dumbbell squat clean","Dumbbell clean and press"],"safety":"Keep the dumbbells close to your body on the way up.","video":null,"diagram":"","notes":""},{"id":"dbjumpsquat","name":"Dumbbell jump squat","aliases":["Weighted jump squat","Kettlebell jump squat","Loaded squat jump"],"training_type":"Power","tags":["Compound","Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Calves","Hamstrings","Core"],"movement_pattern":"Jump","equipment":["Dumbbells or kettlebell"],"req":"dumbbells|kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"5–6","form_cues":["Hold light dumbbells at your sides or a kettlebell at your chest.","Dip to a quarter squat and jump as high as you can.","Land softly and reset before the next rep."],"common_mistakes":["Going too heavy so jumps barely leave the floor","Landing stiff-legged"],"regressions":["Jump squat"],"progressions":["Trap bar jump"],"safety":"Keep the load light (10–30% of body weight); land softly with knees soft and tracking over toes; skip if you have acute knee or ankle pain.","video":null,"diagram":"","notes":""},{"id":"dbsplitjump","name":"Dumbbell split jump","aliases":["Weighted jumping lunge","Loaded split jump"],"training_type":"Power","tags":["Legs","Plyometric","Power","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Calves","Core"],"movement_pattern":"Lunge","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":3,"reps":"5 / side","form_cues":["Hold light dumbbells at your sides in a lunge stance.","Jump up, switching legs in the air.","Land softly in a lunge with the front knee over the foot."],"common_mistakes":["Using weights that are too heavy","Back knee hitting the floor"],"regressions":["Split jump"],"progressions":[],"safety":"Keep loads light and stop when landings get sloppy.","video":null,"diagram":"","notes":""},{"id":"dbsquatclean","name":"Dumbbell squat clean","aliases":["DB clean from floor"],"training_type":"Power","tags":["Compound","Power","Strength"],"muscle_group":"Legs","primary_muscles":["Glutes","Quadriceps","Hamstrings"],"secondary_muscles":["Upper traps","Core","Forearms"],"movement_pattern":"Squat","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":4,"reps":"5","form_cues":["Start with dumbbells on the floor beside your feet.","Pull explosively and drop into a front squat to catch them.","Stand up tall with the weights on your shoulders."],"common_mistakes":["Rounding the back off the floor","Catching too high and stiff"],"regressions":["Dumbbell hang clean"],"progressions":["Dumbbell cluster"],"safety":"Brace before every pull and keep a flat back.","video":null,"diagram":"","notes":""},{"id":"dbsdhp","name":"Dumbbell sumo deadlift high pull","aliases":["SDHP"],"training_type":"Power","tags":["Cardio","Compound","Power","Strength"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings","Upper traps"],"secondary_muscles":["Side delts","Adductors","Quadriceps"],"movement_pattern":"Hinge","equipment":["Dumbbell"],"req":"dumbbells|kettlebells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"10–12","form_cues":["Stand wide holding one dumbbell by the head with both hands.","Drive through your legs and hips explosively.","Pull the dumbbell to chin height, elbows high, then lower."],"common_mistakes":["Pulling with the arms only","Rounding the back"],"regressions":["Dumbbell sumo squat"],"progressions":["Dumbbell high pull"],"safety":"Keep the dumbbell close and stop the pull below your chin.","video":null,"diagram":"","notes":""},{"id":"dbthruster","name":"Dumbbell thruster","aliases":["DB squat to press"],"training_type":"Power","tags":["Compound","Endurance","Power","Strength"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Front delts"],"secondary_muscles":["Triceps","Core","Upper traps"],"movement_pattern":"Squat","equipment":["Dumbbells"],"req":"dumbbells","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"8–10","form_cues":["Hold dumbbells at your shoulders and squat down.","Drive up hard and use the momentum to press overhead.","Lower to the shoulders as you sink into the next squat."],"common_mistakes":["Pressing before you stand","Elbows dropping in the squat"],"regressions":["Dumbbell front squat","Standing dumbbell shoulder press"],"progressions":["Dumbbell cluster"],"safety":"Keep your core braced and don't arch at the top.","video":null,"diagram":"","notes":""},{"id":"ldrill","name":"L-drill","aliases":["3-cone drill","Three-cone drill"],"training_type":"Power","tags":["Agility","Legs","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Adductors"],"secondary_muscles":["Calves","Hamstrings","Core"],"movement_pattern":"Locomotion","equipment":["3 cones"],"req":"","equipment_tier":1,"difficulty":"Advanced","tracking":"count","unilateral":false,"sets":1,"reps":"4–6 reps","form_cues":["Set three cones in an L, 5 m apart.","Sprint out and back, then go round the far cone in a figure eight.","Stay low and tight round the cones; sprint home."],"common_mistakes":["Running wide round the cones","Standing tall through the bends"],"regressions":["5-10-5 pro agility drill"],"progressions":[],"safety":"Use a grippy surface; rest fully between reps.","video":null,"diagram":"","notes":"NFL combine 3-cone drill."},{"id":"parachute","name":"Parachute sprint","aliases":["Speed chute sprint","Resistance parachute run"],"training_type":"Power","tags":["Cardio","Legs","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings","Quadriceps"],"secondary_muscles":["Calves","Hip flexors"],"movement_pattern":"Gait","equipment":["Speed parachute"],"req":"","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":1,"reps":"6 × 20–30 m","form_cues":["Clip the chute on and start with a strong forward lean.","Sprint hard so the chute opens behind you.","Keep your form tall and relaxed once the chute fills."],"common_mistakes":["Leaning back against the pull","Over-striding"],"regressions":["Acceleration sprint"],"progressions":["Sled sprint"],"safety":"Use only in open space with no wind gusts that could yank you.","video":null,"diagram":"","notes":"No gear id for a speed chute; req is empty."},{"id":"shuttlerun","name":"Shuttle run","aliases":["Suicides","Line drills","10 m shuttle"],"training_type":"Power","tags":["Agility","Cardio","Legs","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Calves","Hamstrings","Adductors"],"movement_pattern":"Locomotion","equipment":["Cones or lines"],"req":"","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":1,"reps":"6 × 4 × 10 m","form_cues":["Sprint to the line and touch it with your hand.","Drop your hips and plant the outside foot to turn.","Push off hard and accelerate back."],"common_mistakes":["Turning tall and slow","Rounding wide turns instead of planting"],"regressions":["Jog shuttles"],"progressions":["5-10-5 pro agility drill"],"safety":"Wear grippy shoes on a non-slip surface.","video":null,"diagram":"","notes":"No cones? Use court or field lines. No gear id for cones, so req is empty."},{"id":"dbsnatch","name":"Single-arm dumbbell snatch","aliases":["DB snatch","Dumbbell power snatch"],"training_type":"Power","tags":["Compound","Power","Strength","Unilateral"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings","Shoulders"],"secondary_muscles":["Upper traps","Quadriceps","Core"],"movement_pattern":"Hinge","equipment":["Dumbbell"],"req":"dumbbells","equipment_tier":1,"difficulty":"Advanced","tracking":"w","unilateral":true,"sets":4,"reps":"5 / side","form_cues":["Start with the dumbbell between your feet, hips back, flat back.","Explode up through the hips and pull the dumbbell high and close.","Punch it overhead and stand tall; lower in stages."],"common_mistakes":["Pressing it up instead of pulling","Rounding the back at the start"],"regressions":["Dumbbell high pull","Dumbbell hang clean"],"progressions":[],"safety":"Learn it light; lower the weight to the shoulder first, then the floor.","video":null,"diagram":"","notes":"Alternate arms each rep for conditioning work."},{"id":"tdrill","name":"T-drill","aliases":["T-test agility drill"],"training_type":"Power","tags":["Agility","Legs","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Adductors"],"secondary_muscles":["Calves","Abductors","Hamstrings"],"movement_pattern":"Locomotion","equipment":["4 cones"],"req":"","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":1,"reps":"4–6 reps","form_cues":["Sprint forward 10 m to the middle cone.","Shuffle 5 m left, 10 m right, 5 m back to the middle.","Backpedal to the start, staying low throughout."],"common_mistakes":["Crossing feet while shuffling","Standing tall in the shuffle"],"regressions":["Lateral shuffle"],"progressions":["Box drill"],"safety":"Use a flat, non-slip surface.","video":null,"diagram":"","notes":"Cones laid out in a T; no gear id for cones, so req is empty."},{"id":"wallball","name":"Wall ball","aliases":["Wall ball shot","Wall balls","Med ball thruster"],"training_type":"Power","tags":["Cardio","Compound","Endurance","Legs","Power"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Shoulders"],"secondary_muscles":["Triceps","Core","Calves"],"movement_pattern":"Squat","equipment":["Medicine ball","Wall"],"req":"medball","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"15–20","form_cues":["Hold the ball at your chest and squat to parallel.","Drive up and throw it to a target about 3 m high.","Catch it and go straight into the next squat."],"common_mistakes":["Partial squats","Throwing with the arms only","Catching with locked arms"],"regressions":["Goblet squat","Medicine ball chest pass"],"progressions":[],"safety":"Use a soft wall ball; stand about an arm's length from the wall.","video":null,"diagram":"","notes":"CrossFit standard: 9 kg / 6 kg to 3 m / 2.7 m."},{"id":"zigzag","name":"Zig-zag cone drill","aliases":["Zigzag sprint","Cone weave"],"training_type":"Power","tags":["Agility","Legs","Power","Speed"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Adductors"],"secondary_muscles":["Calves","Abductors"],"movement_pattern":"Locomotion","equipment":["5–6 cones"],"req":"","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":1,"reps":"6 reps","form_cues":["Set cones 3–5 m apart in a zig-zag.","Sprint to each cone and cut sharply off the outside foot.","Lower your hips before each cut."],"common_mistakes":["Rounding off the cuts","Leaning the body the wrong way on the cut"],"regressions":["Shuttle run"],"progressions":["L-drill"],"safety":"Use a grippy surface; build up speed gradually.","video":null,"diagram":"","notes":""},{"id":"mbbackthrow","name":"Overhead backward medicine ball throw","aliases":["Backward med ball toss","Granny toss","Reverse scoop throw"],"training_type":"Power","tags":["Compound","Glutes","Posterior chain","Power"],"muscle_group":"Glutes","primary_muscles":["Glutes","Hamstrings"],"secondary_muscles":["Lower back","Shoulders","Quadriceps"],"movement_pattern":"Throw","equipment":["Medicine ball","Open space"],"req":"medball","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"5","form_cues":["Hold the ball low between your legs, hips hinged.","Explode through the hips and throw the ball up and back over your head.","Let arms follow straight through."],"common_mistakes":["Squatting instead of hinging","Throwing with bent arms only"],"regressions":["Kettlebell swing"],"progressions":[],"safety":"Make sure the area behind you is completely clear.","video":null,"diagram":"","notes":"Excellent hip-extension power drill; measure throw distance."},{"id":"mbscoop","name":"Underhand forward medicine ball throw","aliases":["Forward scoop toss","Underhand med ball toss","Forward granny throw"],"training_type":"Power","tags":["Glutes","Posterior chain","Power"],"muscle_group":"Glutes","primary_muscles":["Glutes","Hamstrings","Quadriceps"],"secondary_muscles":["Shoulders","Lower back"],"movement_pattern":"Throw","equipment":["Medicine ball","Open space"],"req":"medball","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"5","form_cues":["Hinge with the ball held low between your legs.","Drive hips forward and throw the ball out and up.","Let the throw pull you into a step or jump forward."],"common_mistakes":["Using arms instead of hips","Rounding the back at the bottom"],"regressions":["Kettlebell swing"],"progressions":["Overhead backward medicine ball throw","Broad jump"],"safety":"Throw into open space away from people.","video":null,"diagram":"","notes":""},{"id":"mbshotput","name":"Medicine ball shot-put throw","aliases":["Med ball shot put","Single-arm rotational put"],"training_type":"Power","tags":["Core","Power","Rotation","Unilateral"],"muscle_group":"Core","primary_muscles":["Obliques","Chest","Triceps"],"secondary_muscles":["Shoulders","Glutes"],"movement_pattern":"Throw","equipment":["Medicine ball","Wall"],"req":"medball","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"5 / side","form_cues":["Hold the ball at your shoulder, side-on to the wall.","Rotate the hips and push the ball out with one arm.","Follow through fully and reset each rep."],"common_mistakes":["Pushing with the arm before the hips turn","Elbow dropping under the ball"],"regressions":["Rotational medicine ball throw"],"progressions":[],"safety":"Keep the wrist behind the ball; use a soft ball.","video":null,"diagram":"","notes":""},{"id":"medslam","name":"Medicine ball slam","aliases":["Med ball slam","Overhead slam","Slam ball"],"training_type":"Power","tags":["Cardio","Compound","Core","Power"],"muscle_group":"Core","primary_muscles":["Lats","Abs"],"secondary_muscles":["Shoulders","Glutes","Triceps"],"movement_pattern":"Throw","equipment":["Medicine ball","Slam ball"],"req":"medball","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Lift the ball overhead, rising onto your toes.","Slam it down hard in front of your feet using your abs and lats.","Squat to pick it up with a flat back."],"common_mistakes":["Using a ball that bounces back into the face","Rounding the back to pick it up"],"regressions":["Band pulldown"],"progressions":["Rotational medicine ball slam"],"safety":"Use a dead (non-bounce) slam ball and keep the face away from the bounce.","video":null,"diagram":"","notes":""},{"id":"mbsoccer","name":"Overhead medicine ball throw","aliases":["Soccer throw","Overhead forward throw","Med ball overhead pass"],"training_type":"Power","tags":["Core","Power","Shoulders"],"muscle_group":"Core","primary_muscles":["Lats","Abs","Triceps"],"secondary_muscles":["Chest","Shoulders"],"movement_pattern":"Throw","equipment":["Medicine ball","Wall or partner"],"req":"medball","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Stand or kneel with the ball overhead, arms long.","Brace the abs and pull the ball forward hard.","Release in front of the head into a wall or partner."],"common_mistakes":["Arching the lower back to wind up","Throwing with elbows only"],"regressions":["Kneeling overhead throw"],"progressions":["Medicine ball slam"],"safety":"Keep ribs down; use a soft ball for wall throws.","video":null,"diagram":"","notes":""},{"id":"mbrotslam","name":"Rotational medicine ball slam","aliases":["Side slam","Lateral med ball slam"],"training_type":"Power","tags":["Cardio","Core","Power","Rotation"],"muscle_group":"Core","primary_muscles":["Obliques","Lats"],"secondary_muscles":["Shoulders","Glutes"],"movement_pattern":"Rotation","equipment":["Medicine ball","Slam ball"],"req":"medball","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":3,"reps":"6–8 / side","form_cues":["Lift the ball overhead, then rotate towards one side.","Slam it down outside your foot, pivoting the back foot.","Pick up and alternate sides."],"common_mistakes":["Twisting through the lower back only","Not pivoting the back foot"],"regressions":["Medicine ball slam"],"progressions":["Rotational medicine ball throw"],"safety":"Use a dead slam ball; keep the spine long.","video":null,"diagram":"","notes":""},{"id":"mbrotthrow","name":"Rotational medicine ball throw","aliases":["Med ball side throw","Rotational scoop toss","Hip toss"],"training_type":"Power","tags":["Compound","Core","Power","Rotation"],"muscle_group":"Core","primary_muscles":["Obliques","Glutes"],"secondary_muscles":["Shoulders","Chest","Core"],"movement_pattern":"Rotation","equipment":["Medicine ball","Wall"],"req":"medball","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":3,"reps":"6–8 / side","form_cues":["Stand side-on to a wall, ball at the back hip.","Drive the back hip round and let the arms follow.","Release hard into the wall and catch the rebound."],"common_mistakes":["Throwing with the arms instead of the hips","Rounding the lower back"],"regressions":["Cable woodchop"],"progressions":["Medicine ball shot-put throw"],"safety":"Use a soft or rebounding ball; check the wall can take impact.","video":null,"diagram":"","notes":"Great for golf, tennis, baseball and combat sports."},{"id":"cleanpress","name":"Clean and press","aliases":["Barbell clean and press"],"training_type":"Power","tags":["Compound","Power","Strength"],"muscle_group":"Shoulders","primary_muscles":["Glutes","Hamstrings","Shoulders"],"secondary_muscles":["Traps","Triceps","Core"],"movement_pattern":"Vertical push","equipment":["Olympic barbell","Bumper plates"],"req":"barbell,plates","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":5,"reps":"3–6","form_cues":["Power clean to front rack","Stand and brace","Strictly press overhead"],"common_mistakes":["Leaning back","Reverse-curling","Rushing"],"regressions":["Hang power clean"],"progressions":["Clean and jerk"],"safety":"Moderate loads.","video":null,"diagram":"","notes":""},{"id":"musclesnatch","name":"Muscle snatch","aliases":[],"training_type":"Power","tags":["Compound","Power","Strength"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Traps","Upper back"],"secondary_muscles":["Glutes","Hamstrings","Triceps"],"movement_pattern":"Vertical pull","equipment":["Olympic barbell","Bumper plates"],"req":"barbell,plates","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":5,"reps":"3–5","form_cues":["Extend fully on your toes first","Pull elbows high and out, then turn the bar over","Punch overhead without rebending your knees"],"common_mistakes":["Dipping under the bar","Bar swinging out","Rushing the turnover"],"regressions":["Snatch high pull"],"progressions":["Power snatch"],"safety":"Light weights only; it's a technique and upper-back builder.","video":null,"diagram":"","notes":""},{"id":"powerjerk","name":"Power jerk","aliases":[],"training_type":"Power","tags":["Compound","Power","Strength"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Quadriceps","Glutes"],"secondary_muscles":["Triceps","Core","Upper back","Calves"],"movement_pattern":"Vertical push","equipment":["Olympic barbell","Bumper plates","Squat rack"],"req":"barbell,plates,powerrack","equipment_tier":2,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":5,"reps":"2–3","form_cues":["Dip and drive hard","Jump feet out to squat stance","Catch with locked arms in a quarter squat"],"common_mistakes":["Pressing out","Feet too wide","Lazy drive"],"regressions":["Push press"],"progressions":["Split jerk"],"safety":"Use a rack and bumpers.","video":null,"diagram":"","notes":""},{"id":"pushjerk","name":"Push jerk","aliases":[],"training_type":"Power","tags":["Compound","Power","Strength"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Quadriceps","Glutes"],"secondary_muscles":["Triceps","Core","Upper back","Calves"],"movement_pattern":"Vertical push","equipment":["Olympic barbell","Bumper plates","Squat rack"],"req":"barbell,plates,powerrack","equipment_tier":2,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":5,"reps":"2–3","form_cues":["Dip and drive like a push press","Drop under into a partial squat","Catch with locked arms, then stand"],"common_mistakes":["Pressing the bar out","Heels rising early","Leaning forward"],"regressions":["Push press"],"progressions":["Split jerk"],"safety":"Use a rack and bumpers.","video":null,"diagram":"","notes":""},{"id":"pushpress","name":"Push press","aliases":[],"training_type":"Power","tags":["Compound","Power","Strength"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Triceps"],"secondary_muscles":["Quadriceps","Glutes","Core"],"movement_pattern":"Vertical push","