ates","equipment_tier":2,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":5,"reps":"2–3","form_cues":["Start standing, hinge to just above the knees","Explode up and pull under","Catch in a full front squat"],"common_mistakes":["Arms bending early","Hips swinging into the bar","Slow elbows"],"regressions":["Hang power clean"],"progressions":["Squat clean"],"safety":"Use bumpers; drop forward on a miss.","video":null,"diagram":"","notes":""},{"id":"hangpowerclean","name":"Hang power clean","aliases":["HPC"],"training_type":"Power","tags":["Compound","Power","Strength"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings","Quadriceps","Traps"],"secondary_muscles":["Upper back","Core","Calves","Forearms"],"movement_pattern":"Hinge","equipment":["Olympic barbell","Bumper plates"],"req":"barbell,plates","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":5,"reps":"3–5","form_cues":["Hinge with the bar at mid-thigh","Jump and shrug","Whip elbows forward and catch above parallel"],"common_mistakes":["Using the arms to lift","Wrists catching the bar","Leaning back"],"regressions":["Clean high pull"],"progressions":["Power clean","Hang clean"],"safety":"Bumpers and a clear platform.","video":null,"diagram":"","notes":"Great entry point to Olympic lifting."},{"id":"hangpowersnatch","name":"Hang power snatch","aliases":["HPS"],"training_type":"Power","tags":["Compound","Power","Strength"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings","Quadriceps","Traps"],"secondary_muscles":["Shoulders","Upper back","Core","Calves","Triceps"],"movement_pattern":"Hinge","equipment":["Olympic barbell","Bumper plates"],"req":"barbell,plates","equipment_tier":2,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":5,"reps":"3–5","form_cues":["Lower the bar to mid-thigh with a flat back","Jump and shrug hard","Punch under and catch high with locked arms"],"common_mistakes":["Pressing out the catch","Rever