ough to clap once.","Get hands back under shoulders and land softly."],"common_mistakes":["Not getting enough height and landing on the face","Body sagging in the air"],"regressions":["Plyo push-up"],"progressions":["Depth push-up"],"safety":"Practise on a soft mat; only progress once plyo push-ups are high and controlled.","video":null,"diagram":"","notes":""},{"id":"inclineplyopush","name":"Incline plyo push-up","aliases":["Wall plyo push-up","Bench plyometric push-up"],"training_type":"Plyometric","tags":["Chest","Home-friendly","Plyometric","Power"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Horizontal push","equipment":["Bench or wall"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"6–8","form_cues":["Hands on a wall, bench or counter, body straight.","Lower quickly, then push hard so your hands leave the surface.","Catch yourself with soft elbows and go again."],"common_mistakes":["Sagging hips","Landing with locked elbows"],"regressions":["Incline push-up"],"progressions":["Kneeling plyo push-up","Plyo push-up"],"safety":"Use a stable surface that will not slide.","video":null,"diagram":"","notes":"The higher the hands, the easier it is."},{"id":"kneelplyopush","name":"Kneeling plyo push-up","aliases":["Kneeling explosive push-up"],"training_type":"Plyometric","tags":["Chest","Home-friendly","Plyometric","Power"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Horizontal push","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"6–8","form_cues":["Kneel with hands under shoulders and a straight line knees to head.","Lower, then push explosively so hands leave the floor.","Land with soft elbows and flow into the next rep."],"common_mistakes":["Hips piking up","Flaring elbows wide"],"regressions":["Incline plyo push-up"],"progressions":["Plyo push-up"],"safety":"Use a mat for the knees; stop if wrists hurt.","video":null,"diagram":"","notes":""},{"id":"plyopush","name":"Plyo push-up","aliases":["Explosive push-up","Plyometric push-up","Pop-up push-up"],"training_type":"Plyometric","tags":["Calisthenics","Chest","Compound","Home-friendly","Plyometric","Power"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Horizontal push","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"5–8","form_cues":["Start in a strong plank, hands under shoulders.","Lower under control, then push hard so hands leave the floor.","Land with soft elbows and go straight into the next rep."],"common_mistakes":["Hips sagging or piking","Landing on locked elbows","Rushing with poor depth"],"regressions":["Kneeling plyo push-up","Push-ups"],"progressions":["Clap push-up","Depth push-up","Medicine ball chest pass"],"safety":"Warm up wrists and shoulders; stop if you land with pain.","video":null,"diagram":"","notes":""},{"id":"jump180","name":"180-degree jump squat","aliases":["180 jump","Rotational jump squat","Half-turn jump"],"training_type":"Plyometric","tags":["Agility","Home-friendly","Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Obliques","Calves","Core"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"6–8 (alternate direction)","form_cues":["Squat down and swing arms to start the turn.","Jump and rotate 180 degrees in the air.","Land facing the other way in a soft squat, then reverse."],"common_mistakes":["Twisting the knees on landing instead of turning fully in the air","Landing with feet too narrow"],"regressions":["Jump squat"],"progressions":["L