ull,"diagram":"","notes":"Measure distance from toes to heels to track progress."},{"id":"carioca","name":"Carioca","aliases":["Grapevine","Karaoke drill"],"training_type":"Plyometric","tags":["Agility","Cardio","Mobility","Plyometric","Warm-up"],"muscle_group":"Legs","primary_muscles":["Hip flexors","Adductors","Abductors"],"secondary_muscles":["Obliques","Calves","Glutes"],"movement_pattern":"Locomotion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"20 m / direction","form_cues":["Move sideways, crossing the trail leg in front then behind.","Rotate the hips while the shoulders stay square.","Stay on the balls of your feet and speed up as you get it."],"common_mistakes":["Turning the shoulders with the hips","Tripping over crossing feet by going too fast too soon"],"regressions":["Lateral shuffle"],"progressions":["Agility ladder crossover"],"safety":"Start slowly; use a flat, clear surface.","video":null,"diagram":"","notes":"Great dynamic warm-up for field and court sports."},{"id":"contbroad","name":"Consecutive broad jumps","aliases":["Continuous broad jumps","Bunny hops","Repeated broad jumps"],"training_type":"Plyometric","tags":["Glutes","Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings","Quadriceps"],"secondary_muscles":["Calves","Core"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"3–5 jumps","form_cues":["Do one broad jump, then rebound straight into the next.","Spend as little time on the ground as possible.","Keep the arm swing rhythmic and powerful."],"common_mistakes":["Stopping fully between jumps","Collapsing knees on each landing"],"regressions":["Broad jump"],"progressions":["Bounds","Hurdle hops"],"safety":"Use a flat, non-slip surface; land softly with knees soft and tracking over toes; skip if you have acute knee or ankle pai