ck line hops","Line jumps"],"training_type":"Plyometric","tags":["Agility","Home-friendly","Legs","Plyometric","Warm-up"],"muscle_group":"Legs","primary_muscles":["Calves"],"secondary_muscles":["Quadriceps","Hamstrings","Core"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"20 sec","form_cues":["Stand behind a line with feet together.","Hop forward and back over it quickly.","Keep knees soft and contacts short."],"common_mistakes":["Landing heavy on the heels","Leaning too far forward"],"regressions":["Pogo jumps"],"progressions":["Single-leg line hops","Dot drill"],"safety":"Use a non-slip surface.","video":null,"diagram":"","notes":"Do single-leg for more challenge."},{"id":"frogjump","name":"Frog jump","aliases":["Frog hop"],"training_type":"Plyometric","tags":["Glutes","Home-friendly","Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Adductors"],"secondary_muscles":["Calves","Hamstrings"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"6–8","form_cues":["Start in a wide, deep squat with fingers near the floor.","Jump up and forward, swinging arms overhead.","Land back in the deep squat and go again."],"common_mistakes":["Knees caving in when landing","Rounding the back at the bottom"],"regressions":["Sumo squat","Jump squat"],"progressions":["Broad jump"],"safety":"Only squat as deep as you can with a flat back; land softly with knees soft and tracking over toes; skip if you have acute knee or ankle pain.","video":null,"diagram":"","notes":""},{"id":"jumpsquat","name":"Jump squat","aliases":["Squat jump","Bodyweight jump squat"],"training_type":"Plyometric","tags":["Cardio","Compound","Home-friendly","Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Calves","Hamstrings","Core"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Sit back to a quarter or half squat, arms swinging back.","Drive through the whole foot and jump straight up.","Land softly and sink straight into the next rep."],"common_mistakes":["Landing stiff-legged with a loud thud","Knees caving in on take-off or landing","Rushing reps and losing height"],"regressions":["Bodyweight squat","Squat to calf raise"],"progressions":["Tuck jump","Dumbbell jump squat","Box jump"],"safety":"Land softly with knees soft and tracking over toes; skip if you have acute knee or ankle pain.","video":null,"diagram":"goblet","notes":""},{"id":"lateralbound","name":"Lateral bound","aliases":["Skater bound","Heiden","Side-to-side bound"],"training_type":"Plyometric","tags":["Agility","Glutes","Home-friendly","Legs","Plyometric","Power","Unilateral"],"muscle_group":"Legs","primary_muscles":["Glutes","Quadriceps"],"secondary_muscles":["Adductors","Abductors","Calves","Core"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":3,"reps":"5 / side","form_cues":["Load on one leg and push hard sideways off it.","Jump as far as you can to the side.","Land on the opposite leg and stick it for a second."],"common_mistakes":["Landing with knee caving inward","Jumping up instead of out","Not controlling the landing"],"regressions":["Skater hop (small)","Lateral lunge"],"progressions":["Continuous lateral bounds","Single-leg lateral hop"],"safety":"Land softly with knees soft and tracking over toes; skip if you have acute knee or ankle pain.","video":null,"diagram":"","notes":"Make it continuous for conditioning; stick each landing for strength and control."},{"id":"lathop","name":"Lateral line hops","aliases":["Side-to-side hops","Two-foot lateral hops","Lateral hops"],"training_type":"Plyometric","tags":["Agility","Home-friendly","Legs","Plyometric","Warm-up"],"muscle_group":"Legs","primary_muscles":["Calves"],"secondary_muscles":["Quadriceps","Adductors","Abductors","Core"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"20 sec","form_cues":["Stand beside a line with feet together.","Hop side to side over it as fast as you can.","Stay on the balls of your feet with quick, light contacts."],"common_mistakes":["Hopping too high","Looking down and hunching over"],"regressions":["Pogo jumps"],"progressions":["Single-leg lateral hop","Lateral box jump"],"safety":"Use a non-slip surface; ease in if ankles are stiff.","video":null,"diagram":"","notes":""},{"id":"staticsquatjump","name":"Pause squat jump","aliases":["Static squat jump","Non-countermovement jump"],"training_type":"Plyometric","tags":["Home-friendly","Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Calves","Hamstrings","Core"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":4,"reps":"5","form_cues":["Lower to a half squat and hold still for 2–3 seconds.","Explode straight up without dipping first.","Stick the landing, reset, then repeat."],"common_mistakes":["Dipping before the jump, which defeats the pause","Holding too deep a squat"],"regressions":["Jump squat"],"progressions":["Dumbbell jump squat","Seated box jump"],"safety":"Land softly with knees soft and tracking over toes; skip if you have acute knee or ankle pain.","video":null,"diagram":"","notes":"Trains starting strength by removing the stretch-shortening cycle."},{"id":"pikejump","name":"Pike jump","aliases":["Pike tuck jump"],"training_type":"Plyometric","tags":["Core","Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Hip flexors"],"secondary_muscles":["Hamstrings","Core","Calves"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"count","unilateral":false,"sets":3,"reps":"5–6","form_cues":["Jump straight up with a strong arm drive.","Lift straight legs forward and reach hands toward toes.","Drop legs back under you before you land."],"common_mistakes":["Bending the knees instead of piking","Landing off balance"],"regressions":["Tuck jump"],"progressions":[],"safety":"Needs good hamstring flexibility; land softly with knees soft and tracking over toes; skip if you have acute knee or ankle pain.","video":null,"diagram":"","notes":""},{"id":"pogo","name":"Pogo jumps","aliases":["Pogo hops","Ankle hops","Ankling hops"],"training_type":"Plyometric","tags":["Home-friendly","Legs","Plyometric","Warm-up"],"muscle_group":"Legs","primary_muscles":["Calves"],"secondary_muscles":["Ankles","Quadriceps","Feet"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"20","form_cues":["Stand tall with almost-straight knees.","Bounce off the balls of your feet using only your ankles.","Keep ground contact quick and stiff, like a spring."],"common_mistakes":["Bending the knees too much","Landing on the heels","Letting the ankles collapse"],"regressions":["Jump rope","Calf raise"],"progressions":["Single-leg hop","Hurdle hops","Depth jump"],"safety":"Build up slowly if you have Achilles or calf issues.","video":null,"diagram":"","notes":"Great warm-up for running and jumping; builds ankle stiffness."},{"id":"powerskip","name":"Power skip","aliases":["Skip for height","Power skips"],"training_type":"Plyometric","tags":["Legs","Plyometric","Power","Speed","Warm-up"],"muscle_group":"Legs","primary_muscles":["Glutes","Calves","Quadriceps"],"secondary_muscles":["Hip flexors","Core","Shoulders"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"20 m","form_cues":["Skip, pushing hard off the ground for height.","Drive the knee and opposite arm up together.","Land softly and go straight into the next skip."],"common_mistakes":["Skipping low and fast instead of high","Weak arm drive"],"regressions":["A-skip"],"progressions":["Bounds"],"safety":"Use a non-slip surface and build up gradually.","video":null,"diagram":"","notes":"Do it for distance instead of height as a variation."},{"id":"slbroad","name":"Single-leg broad jump","aliases":["Single-leg standing long jump","Single-leg forward hop for distance"],"training_type":"Plyometric","tags":["Balance","Legs","Plyometric","Power","Unilateral"],"muscle_group":"Legs","primary_muscles":["Glutes","Quadriceps","Hamstrings"],"secondary_muscles":["Calves","Core","Adductors"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"count","unilateral":true,"sets":3,"reps":"3 / side","form_cues":["Stand on one leg, hinge and swing arms back.","Jump forward off one leg as far as you can.","Land on the same leg and hold it for two seconds."],"common_mistakes":["Knee caving on landing","Jumping further than you can control"],"regressions":["Broad jump","Single-leg hop"],"progressions":["Bounds"],"safety":"Master two-leg landings first; stop if knee feels unstable.","video":null,"diagram":"","notes":"Common return-to-sport hop test."},{"id":"slhop","name":"Single-leg hop","aliases":["Single-leg forward hops","One-leg hops"],"training_type":"Plyometric","tags":["Balance","Legs","Plyometric","Unilateral"],"muscle_group":"Legs","primary_muscles":["Calves","Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Core","Feet"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Balance on one leg with a soft knee.","Hop forward a short distance and land on the same foot.","Keep the knee over the toes and hips level."],"common_mistakes":["Knee caving inward","Hip dropping on the free-leg side"],"regressions":["Pogo jumps","Single-leg balance"],"progressions":["Single-leg broad jump","Single-leg lateral hop"],"safety":"Stop if the landing knee wobbles or hurts.","video":null,"diagram":"","notes":""},{"id":"sllathop","name":"Single-leg lateral hop","aliases":["Single-leg side hops","Lateral single-leg hop"],"training_type":"Plyometric","tags":["Agility","Balance","Legs","Plyometric","Unilateral"],"muscle_group":"Legs","primary_muscles":["Calves","Glutes"],"secondary_muscles":["Quadriceps","Abductors","Adductors","Core"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":3,"reps":"8–10 / side","form_cues":["Stand on one leg beside a line.","Hop sideways over it and back on the same leg.","Land quietly with the knee tracking over the toes."],"common_mistakes":["Knee wobbling inward","Losing balance between hops"],"regressions":["Lateral line hops"],"progressions":["Lateral bound"],"safety":"Stop if the ankle or knee feels unstable.","video":null,"diagram":"","notes":""},{"id":"snapdown","name":"Snap down","aliases":["Drop squat","Snap-down drill","Drop and stick"],"training_type":"Plyometric","tags":["Home-friendly","Legs","Plyometric","Rehab","Warm-up"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Calves","Core"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"5–6","form_cues":["Rise onto your toes with arms overhead.","Snap arms down and drop fast into an athletic quarter squat.","Freeze in the landing: chest up, hips back, knees over toes."],"common_mistakes":["Landing with knees caving","Too deep and slow a drop"],"regressions":["Bodyweight squat"],"progressions":["Depth drop","Depth jump"],"safety":"Teaches safe landing mechanics; keep the drop quick but controlled.","video":null,"diagram":"","notes":"Use as a warm-up before any jumping session."},{"id":"splitjump","name":"Split jump","aliases":["Jumping lunge","Plyo lunge","Lunge jump","Scissor jump"],"training_type":"Plyometric","tags":["Cardio","Home-friendly","Legs","Plyometric","Power","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Calves","Core"],"movement_pattern":"Lunge","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"6–8 / side","form_cues":["Start in a lunge, chest up, front knee over mid-foot.","Jump up and switch legs in the air.","Land softly back into a lunge and go straight away."],"common_mistakes":["Back knee slamming the floor","Front knee caving inward","Short, choppy stance on landing"],"regressions":["Reverse lunge","Split squat"],"progressions":["Dumbbell split jump","Bulgarian split jump"],"safety":"Land softly with knees soft and tracking over toes; skip if you have acute knee or ankle pain.","video":null,"diagram":"","notes":""},{"id":"straightlegbound","name":"Straight-leg bound","aliases":["Straight-leg run","Scissor bound"],"training_type":"Plyometric","tags":["Legs","Plyometric","Speed","Warm-up"],"muscle_group":"Legs","primary_muscles":["Hamstrings","Glutes"],"secondary_muscles":["Calves","Hip flexors"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"20 m","form_cues":["Keep knees nearly straight and stay tall.","Sweep each leg down and back, striking under your hips.","Pull the ground behind you with quick, active feet."],"common_mistakes":["Leaning back","Reaching the foot out in front"],"regressions":["A-skip"],"progressions":["Bounds"],"safety":"Warm up well first; stop if you feel any hamstring tightness.","video":null,"diagram":"","notes":"Sprint drill that teaches a fast, backward-pulling foot strike."},{"id":"tuckjump","name":"Tuck jump","aliases":["Knee tuck jump"],"training_type":"Plyometric","tags":["Cardio","Home-friendly","Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Hip flexors"],"secondary_muscles":["Calves","Core"],"movement_pattern":"Jump","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"6–8","form_cues":["Jump straight up from a quick dip.","Pull your knees up toward your chest at the top.","Untuck before landing and land softly on the balls of your feet."],"common_mistakes":["Landing while still tucked","Leaning forward instead of jumping vertically","Pausing too long between reps"],"regressions":["Jump squat"],"progressions":["Pike jump","Depth jump"],"safety":"Land softly with knees soft and tracking over toes; skip if you have acute knee or ankle pain.","video":null,"diagram":"","notes":""},{"id":"wallsprintdrill","name":"Wall drill","aliases":["Acceleration wall drill","Wall march","Wall run"],"training_type":"Plyometric","tags":["Legs","Plyometric","Speed","Warm-up"],"muscle_group":"Legs","primary_muscles":["Hip flexors","Glutes"],"secondary_muscles":["Calves","Core","Quadriceps"],"movement_pattern":"Gait","equipment":["Wall"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"3–5 switches","form_cues":["Lean into a wall at about 45 degrees, hands on it.","Hold one knee up, toe pulled up, body in a straight line.","Switch legs explosively, striking down under your hips."],"common_mistakes":["Bending at the hips instead of leaning as a straight line","Feet drifting forward under the wall"],"regressions":["Wall march (slow)"],"progressions":["Falling start sprint"],"safety":"Wear shoes with grip so your feet do not slip.","video":null,"diagram":"","notes":"Teaches the body angle and leg action of acceleration."},{"id":"laddersinglehop","name":"Agility ladder: single-leg hops","aliases":["Single-leg ladder hops","One-foot ladder hops"],"training_type":"Plyometric","tags":["Agility","Balance","Legs","Plyometric","Unilateral"],"muscle_group":"Legs","primary_muscles":["Calves","Quadriceps"],"secondary_muscles":["Glutes","Core"],"movement_pattern":"Jump","equipment":["Agility ladder"],"req":"","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":3,"reps":"2 lengths / leg","form_cues":["Hop on one foot into each square.","Land softly on the ball of the foot, knee slightly bent.","Keep the hip level and the knee over the toes."],"common_mistakes":["Knee caving on landing","Hopping too far and losing control"],"regressions":["Agility ladder: hopscotch"],"progressions":["Single-leg lateral hop"],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"hurdlehop","name":"Hurdle hops","aliases":["Mini hurdle hops","Hurdle jumps"],"training_type":"Plyometric","tags":["Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Calves","Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Jump","equipment":["Mini hurdles or cones"],"req":"","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"5–6 hurdles","form_cues":["Line up 4–6 low hurdles about a stride apart.","Jump over each with both feet, tucking knees slightly.","Rebound quickly off each landing, staying tall."],"common_mistakes":["Long, sinking ground contacts","Clipping hurdles by not lifting the knees"],"regressions":["Pogo jumps","Consecutive broad jumps"],"progressions":["Depth jump"],"safety":"Use collapsible hurdles or cones that fall over if clipped.","video":null,"diagram":"","notes":"No gear id for hurdles; req is empty."},{"id":"laddercross","name":"Agility ladder crossover","aliases":["Ladder carioca","Crossover ladder step"],"training_type":"Plyometric","tags":["Agility","Cardio","Legs","Plyometric","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Hip flexors","Adductors"],"secondary_muscles":["Obliques","Abductors"],"movement_pattern":"Locomotion","equipment":["Agility ladder"],"req":"","equipment_tier":1,"difficulty":"Advanced","tracking":"count","unilateral":false,"sets":3,"reps":"4 lengths","form_cues":["Move sideways along the ladder.","Cross the trail foot over into each square, then step out.","Turn the hips, keep the shoulders square."],"common_mistakes":["Turning the whole body","Stepping on rungs"],"regressions":["Carioca"],"progressions":[],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"ladderhopscotch","name":"Agility ladder: hopscotch","aliases":["Hopscotch ladder","Ladder in-out hops"],"training_type":"Plyometric","tags":["Agility","Cardio","Legs","Plyometric","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Quadriceps"],"secondary_muscles":["Glutes","Core"],"movement_pattern":"Jump","equipment":["Agility ladder"],"req":"","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"4 lengths","form_cues":["Hop with both feet into a square, then land one foot either side of the next.","Alternate in and out all the way down.","Keep contacts quick and quiet."],"common_mistakes":["Landing heavy on the heels","Losing rhythm halfway"],"regressions":["Agility ladder: two feet in each"],"progressions":["Agility ladder: single-leg hops"],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"ladderlateral","name":"Agility ladder: lateral in-in-out-out","aliases":["Lateral in and out","Lateral two-in ladder"],"training_type":"Plyometric","tags":["Agility","Cardio","Legs","Plyometric","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Abductors","Adductors"],"secondary_muscles":["Quadriceps","Glutes"],"movement_pattern":"Locomotion","equipment":["Agility ladder"],"req":"","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"4 lengths","form_cues":["Face the side of the ladder.","Step in, in, then out, out, moving down one square each time.","Keep your hips low and facing forward."],"common_mistakes":["Crossing the feet","Standing too tall"],"regressions":["Agility ladder: two feet in each"],"progressions":["Icky shuffle"],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"ladderone","name":"Agility ladder: one foot in each","aliases":["Quick feet ladder","Ladder run-through","One-in ladder"],"training_type":"Plyometric","tags":["Agility","Cardio","Legs","Plyometric","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Hip flexors"],"secondary_muscles":["Quadriceps","Core"],"movement_pattern":"Locomotion","equipment":["Agility ladder"],"req":"","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"4 lengths","form_cues":["Run through, placing one foot in each square.","Stay on the balls of your feet, arms pumping.","Speed up only as long as you stay clean."],"common_mistakes":["Stepping on the rungs","Looking straight down the whole time"],"regressions":["Walk-through"],"progressions":["Agility ladder: two feet in each"],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"laddertwo","name":"Agility ladder: two feet in each","aliases":["Two-in ladder","Two feet in each square"],"training_type":"Plyometric","tags":["Agility","Cardio","Legs","Plyometric","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Hip flexors"],"secondary_muscles":["Quadriceps","Core"],"movement_pattern":"Locomotion","equipment":["Agility ladder"],"req":"","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"4 lengths","form_cues":["Step both feet into each square, one after the other.","Keep steps short, light and fast.","Drive arms in rhythm with your feet."],"common_mistakes":["Heavy, flat-footed steps","Rushing and kicking the ladder"],"regressions":["Agility ladder: one foot in each"],"progressions":["Agility ladder: lateral in-in-out-out"],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"ickyshuffle","name":"Icky shuffle","aliases":["Ickey shuffle","In-in-out ladder"],"training_type":"Plyometric","tags":["Agility","Cardio","Legs","Plyometric","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Abductors","Adductors"],"secondary_muscles":["Quadriceps","Hip flexors"],"movement_pattern":"Locomotion","equipment":["Agility ladder"],"req":"","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"4 lengths","form_cues":["Step in-in, then out to the side, moving forward each square.","Alternate the outside step from side to side.","Stay light and rhythmic, eyes up."],"common_mistakes":["Losing the in-in-out rhythm","Big slow steps"],"regressions":["Agility ladder: lateral in-in-out-out"],"progressions":["Agility ladder crossover"],"safety":"Lay the ladder flat on a non-slip surface so it cannot slide.","video":null,"diagram":"","notes":"Agility ladder has no gear id, so req is empty; tape on the floor works too."},{"id":"depthpush","name":"Depth push-up","aliases":["Drop push-up","Box drop push-up"],"training_type":"Plyometric","tags":["Calisthenics","Chest","Plyometric","Power"],"muscle_group":"Chest","primary_muscles":["Chest","Triceps"],"secondary_muscles":["Front delts","Core"],"movement_pattern":"Horizontal push","equipment":["Two low boxes or plates"],"req":"plyobox|plates","equipment_tier":2,"difficulty":"Advanced","tracking":"count","unilateral":false,"sets":3,"reps":"4–6","form_cues":["Hold a plank with hands on two low boxes.","Drop hands to the floor between them, landing with soft elbows.","Push explosively back up onto the boxes."],"common_mistakes":["Landing on locked elbows","Hips sagging on the drop"],"regressions":["Clap push-up"],"progressions":[],"safety":"Only attempt once clap push-ups are solid; keep the boxes low.","video":null,"diagram":"","notes":""},{"id":"boxjump","name":"Box jump","aliases":["Plyo box jump"],"training_type":"Plyometric","tags":["Compound","Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Calves","Hamstrings","Core"],"movement_pattern":"Jump","equipment":["Plyo box"],"req":"plyobox","equipment_tier":2,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":4,"reps":"4–6","form_cues":["Stand a foot from the box, swing arms back and dip.","Jump and land softly on the box in a quarter squat.","Stand tall, then step down rather than jumping off."],"common_mistakes":["Choosing a box so high you land in a deep squat","Jumping down repeatedly","Knees caving on landing"],"regressions":["Jump squat","Step-up"],"progressions":["Seated box jump","Depth jump","Single-leg box jump"],"safety":"Use a stable box; step down to protect Achilles and knees.","video":null,"diagram":"","notes":"Height of jump, not box, is the goal."},{"id":"depthdrop","name":"Depth drop","aliases":["Drop landing","Box drop"],"training_type":"Plyometric","tags":["Legs","Plyometric","Rehab"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Calves","Core"],"movement_pattern":"Jump","equipment":["Plyo box"],"req":"plyobox","equipment_tier":2,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"5","form_cues":["Step off a low box, do not jump off.","Land on both feet at once in an athletic quarter squat.","Freeze the landing for two seconds."],"common_mistakes":["Landing loudly on the heels","Knees caving in","Stepping off a box too high"],"regressions":["Snap down"],"progressions":["Depth jump"],"safety":"Start at 30–45 cm; stop if knees ache.","video":null,"diagram":"","notes":"Teaches landing before you add depth jumps."},{"id":"depthjump","name":"Depth jump","aliases":["Drop jump","Reactive jump"],"training_type":"Plyometric","tags":["Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Calves"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Jump","equipment":["Plyo box"],"req":"plyobox","equipment_tier":2,"difficulty":"Advanced","tracking":"count","unilateral":false,"sets":3,"reps":"4–5","form_cues":["Step off a low box and land on both feet.","Spend as little time on the ground as possible.","Rebound straight up as high as you can."],"common_mistakes":["Sinking too deep on landing","Box too high so you cannot rebound quickly","Jumping off the box instead of stepping"],"regressions":["Depth drop","Pogo jumps"],"progressions":["Depth jump to broad jump"],"safety":"Advanced shock drill: do it fresh, low volume, with a 30–60 cm box and good landing mechanics first.","video":null,"diagram":"","notes":"Rest 1–2 min between reps."},{"id":"latboxjump","name":"Lateral box jump","aliases":["Side box jump","Lateral jump onto box"],"training_type":"Plyometric","tags":["Agility","Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Abductors"],"secondary_muscles":["Adductors","Calves","Core"],"movement_pattern":"Jump","equipment":["Plyo box"],"req":"plyobox","equipment_tier":2,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"4 / side","form_cues":["Stand side-on to a low box.","Dip and jump sideways onto it, landing with both feet.","Step down and repeat, switching sides each set."],"common_mistakes":["Clipping the box edge","Landing with feet too narrow"],"regressions":["Lateral line hops"],"progressions":["Lateral bound"],"safety":"Start with a low box; step down each rep.","video":null,"diagram":"","notes":""},{"id":"powerstepup","name":"Power step-up","aliases":["Explosive step-up","Plyo step-up","Box step-up jump"],"training_type":"Plyometric","tags":["Glutes","Legs","Plyometric","Power","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Calves","Hip flexors"],"movement_pattern":"Lunge","equipment":["Plyo box or bench"],"req":"plyobox|flatbench","equipment_tier":2,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":3,"reps":"5–6 / side","form_cues":["Place one foot fully on a knee-height box.","Drive through that foot to jump up, swinging the other knee high.","Land softly with the same foot on the box and repeat."],"common_mistakes":["Pushing off the back foot","Box too high so the hip sinks below the knee"],"regressions":["Box step-up"],"progressions":["Single-leg box jump"],"safety":"Use a stable box that won't tip; keep the working knee over the foot.","video":null,"diagram":"","notes":"Alternating version switches feet in the air."},{"id":"seatedboxjump","name":"Seated box jump","aliases":["Seated jump to box"],"training_type":"Plyometric","tags":["Legs","Plyometric","Power"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Hamstrings"],"secondary_muscles":["Calves","Core"],"movement_pattern":"Jump","equipment":["Plyo box","Bench"],"req":"plyobox","equipment_tier":2,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":4,"reps":"3–5","form_cues":["Sit on a bench facing the box, feet flat.","Swing arms and explode up off the seat onto the box.","Land softly and step down."],"common_mistakes":["Rocking back for momentum","Choosing too high a box"],"regressions":["Box jump"],"progressions":["Depth jump"],"safety":"Start with a low box; step down after each rep.","video":null,"diagram":"","notes":"Removes the countermovement to build starting strength."},{"id":"slboxjump","name":"Single-leg box jump","aliases":["One-leg box jump"],"training_type":"Plyometric","tags":["Balance","Legs","Plyometric","Power","Unilateral"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Calves","Core"],"movement_pattern":"Jump","equipment":["Plyo box"],"req":"plyobox","equipment_tier":2,"difficulty":"Advanced","tracking":"count","unilateral":true,"sets":3,"reps":"3–4 / side","form_cues":["Stand on one leg facing a low box.","Swing arms and jump onto the box off one leg.","Land on the same leg, stabilise, step down."],"common_mistakes":["Using too high a box","Knee caving on landing"],"regressions":["Box jump","Single-leg hop"],"progressions":[],"safety":"Use a low box; step down every rep.","video":null,"diagram":"","notes":""},{"id":"sbload","name":"Sandbag load to platform","aliases":["Sandbag over bar","Sandbag to platform"],"training_type":"Strongman","tags":["Compound","Power","Strongman"],"muscle_group":"Back","primary_muscles":["Glutes","Hamstrings","Lower back"],"secondary_muscles":["Upper back","Biceps"],"movement_pattern":"Hinge","equipment":["Sandbag","Platform or box"],"req":"sandbag","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"3–5","form_cues":["Lap the bag onto your thighs.","Hug it tight and extend the hips hard.","Drive the bag onto the platform without pressing it."],"common_mistakes":["Using the arms to throw the bag","Standing too far from the platform"],"regressions":["Sandbag clean"],"progressions":["Atlas stone load"],"safety":"Use a stable platform at waist to chest height and keep fingers clear.","video":null,"diagram":"","notes":"Popular in strongman events and medleys."},{"id":"sbshoulder","name":"Sandbag shouldering","aliases":["Sandbag to shoulder"],"training_type":"Strongman","tags":["Compound","Power","Strength","Strongman"],"muscle_group":"Back","primary_muscles":["Glutes","Hamstrings","Upper back"],"secondary_muscles":["Biceps","Core","Traps"],"movement_pattern":"Hinge","equipment":["Sandbag"],"req":"sandbag","equipment_tier":1,"difficulty":"Intermediate","tracking":"w","unilateral":true,"sets":4,"reps":"3–5 / side","form_cues":["Lap the bag first by squatting and pulling it to your thighs.","Explode hips and pop the bag onto one shoulder.","Stand tall, then lower it under control."],"common_mistakes":["Lifting with the lower back alone","Not alternating shoulders"],"regressions":["Sandbag clean"],"progressions":["Atlas stone load"],"safety":"A rounded back is normal on stone-style lifts but keep it braced; start light.","video":null,"diagram":"","notes":""},{"id":"sandcarry","name":"Sandbag bear-hug carry","aliases":["Sandbag carry"],"training_type":"Strongman","tags":["Compound","Core","Endurance","Strength","Strongman"],"muscle_group":"Core","primary_muscles":["Core","Upper back"],"secondary_muscles":["Biceps","Glutes","Quadriceps"],"movement_pattern":"Carry","equipment":["Sandbag"],"req":"sandbag","equipment_tier":1,"difficulty":"Intermediate","tracking":"cardio","unilateral":false,"sets":3,"reps":"40 m","form_cues":["Hug the bag tight to your chest, hands clasped.","Stand tall and keep your chin over the bag.","Walk with short, quick steps and steady breathing."],"common_mistakes":["Leaning back excessively","Letting the bag slide down"],"regressions":["Kettlebell front rack carry"],"progressions":["Yoke carry"],"safety":"Lift the bag from the floor with a hinge, not a rounded back.","video":null,"diagram":"","notes":""},{"id":"suitcase","name":"Suitcase carry","aliases":["One-arm farmer's carry"],"training_type":"Strongman","tags":["Core","Strength","Strongman","Unilateral"],"muscle_group":"Core","primary_muscles":["Obliques","Forearms"],"secondary_muscles":["Quadratus lumborum","Traps","Glutes"],"movement_pattern":"Anti-lateral flexion","equipment":["Dumbbell or kettlebell"],"req":"dumbbells|kettlebells","equipment_tier":1,"difficulty":"Beginner","tracking":"w","unilateral":true,"sets":3,"reps":"30 m / side","form_cues":["Hold one weight at your side like a suitcase.","Stay perfectly upright; don't lean either way.","Walk slowly, then switch hands."],"common_mistakes":["Leaning away from or toward the weight","Hiking the hip"],"regressions":["Farmer's carry"],"progressions":[],"safety":"Brace hard and pick the weight up with a hinge.","video":null,"diagram":"","notes":""},{"id":"atlas","name":"Atlas stone load","aliases":["Stone to platform","Stone load"],"training_type":"Strongman","tags":["Compound","Power","Strongman"],"muscle_group":"Back","primary_muscles":["Glutes","Hamstrings","Spinal erectors"],"secondary_muscles":["Biceps","Upper back","Quadriceps"],"movement_pattern":"Hinge","equipment":["Atlas stone","Platform"],"req":"sandbag","equipment_tier":3,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":4,"reps":"2–4","form_cues":["Straddle the stone and wrap your arms deep around it.","Lap it onto your thighs, then re-grip high.","Extend hips explosively to roll it onto the platform."],"common_mistakes":["Pulling with straight legs","Stone too far from the body"],"regressions":["Sandbag load to platform"],"progressions":[],"safety":"Use tacky and forearm sleeves, start light, and keep your feet clear of the drop.","video":null,"diagram":"","notes":"No gear id for stones; req uses sandbag, the closest home substitute."},{"id":"axledl","name":"Axle deadlift","aliases":["Fat bar deadlift"],"training_type":"Strongman","tags":["Back","Compound","Strength","Strongman"],"muscle_group":"Back","primary_muscles":["Glutes","Hamstrings","Forearms"],"secondary_muscles":["Spinal erectors","Traps","Quadriceps"],"movement_pattern":"Hinge","equipment":["Axle bar or barbell with thick grips","Weight plates"],"req":"barbell,plates,fatgrips","equipment_tier":3,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":3,"reps":"3–5","form_cues":["Set up like a normal deadlift, double overhand grip.","Squeeze the thick bar hard before you pull.","Drive through the floor and lock out tall."],"common_mistakes":["Mixed grip to avoid grip work","Bar drifting away from the shins"],"regressions":["Thick-grip dumbbell hold","Deadlift"],"progressions":[],"safety":"Use a hook or double overhand grip and lower with control; the axle doesn't spin.","video":null,"diagram":"","notes":"Thick grips on a regular barbell mimic an axle."},{"id":"sledpull","name":"Sled rope pull","aliases":["Hand-over-hand sled pull"],"training_type":"Strongman","tags":["Back","Endurance","Strength","Strongman"],"muscle_group":"Back","primary_muscles":["Lats","Biceps"],"secondary_muscles":["Forearms","Core","Rear delts"],"movement_pattern":"Horizontal pull","equipment":["Sled","Rope"],"req":"sled","equipment_tier":3,"difficulty":"Intermediate","tracking":"w","unilateral":false,"sets":4,"reps":"20 m","form_cues":["Sit or stand in an athletic stance holding the rope.","Pull hand over hand, keeping the sled moving.","Brace your core and don't round your back."],"common_mistakes":["Pulling with a rounded back","Pausing between pulls"],"regressions":["Band seated row"],"progressions":[],"safety":"Clear the rope path and keep fingers out of the sled hardware.","video":null,"diagram":"","notes":""},{"id":"logpress","name":"Log press","aliases":["Log clean and press"],"training_type":"Strongman","tags":["Compound","Power","Shoulders","Strongman"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Triceps"],"secondary_muscles":["Upper chest","Core","Quadriceps"],"movement_pattern":"Vertical push","equipment":["Strongman log"],"req":"barbell","equipment_tier":3,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":4,"reps":"3–5","form_cues":["Clean the log onto your chest, elbows high.","Dip and drive with the legs.","Press through to lockout with the head forward."],"common_mistakes":["Pressing with elbows low","Leaning back on the press"],"regressions":["Sandbag overhead press","Standing barbell overhead press"],"progressions":[],"safety":"Learn the clean light and drop the log in front, never behind you.","video":null,"diagram":"","notes":"No log gear id; req uses barbell as nearest. Neutral grip suits sore shoulders."},{"id":"sledback","name":"Backward sled drag","aliases":["Reverse sled drag"],"training_type":"Strongman","tags":["Endurance","Legs","Rehab","Strength","Strongman"],"muscle_group":"Legs","primary_muscles":["Quadriceps"],"secondary_muscles":["Calves","Glutes","Forearms"],"movement_pattern":"Locomotion","equipment":["Sled","Straps"],"req":"sled","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":4,"reps":"20 m","form_cues":["Hold the straps facing the sled, arms long.","Sit slightly and walk backward on the balls of your feet.","Keep tension in the straps and take steady steps."],"common_mistakes":["Standing too upright","Pulling with the arms"],"regressions":[],"progressions":["Sled push"],"safety":"Check the path behind you is clear before you start.","video":null,"diagram":"","notes":"Knee-friendly quad builder; often used for rehab."},{"id":"sledfwd","name":"Forward sled drag","aliases":["Harness sled drag"],"training_type":"Strongman","tags":["Endurance","Legs","Strength","Strongman"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings"],"secondary_muscles":["Calves","Quadriceps","Core"],"movement_pattern":"Locomotion","equipment":["Sled","Harness or straps"],"req":"sled","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":4,"reps":"20 m","form_cues":["Clip the harness or hold the straps behind you.","Lean forward and drive each leg back powerfully.","Keep a tall spine and steady pace."],"common_mistakes":["Leaning too far and losing balance","Shuffling short steps"],"regressions":[],"progressions":["Sled push"],"safety":"Use a harness that sits at the waist or chest, not the neck.","video":null,"diagram":"","notes":""},{"id":"sledpush","name":"Sled push","aliases":["Prowler push"],"training_type":"Strongman","tags":["Compound","Endurance","Legs","Power","Strength","Strongman"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Calves","Hamstrings","Shoulders","Core"],"movement_pattern":"Locomotion","equipment":["Push sled"],"req":"sled","equipment_tier":3,"difficulty":"Beginner","tracking":"w","unilateral":false,"sets":4,"reps":"20 m","form_cues":["Grip the poles with arms long and lean in at 45 degrees.","Drive knees forward and push through the balls of the feet.","Keep your back flat and steps powerful."],"common_mistakes":["Hips too high","Short, choppy steps"],"regressions":[],"progressions":["Sled forward drag","Yoke carry"],"safety":"Use a clear lane and a surface the sled slides evenly on.","video":null,"diagram":"","notes":"No eccentric load, so it is easy to recover from."},{"id":"tyreflip","name":"Tyre flip","aliases":["Tire flip"],"training_type":"Strongman","tags":["Compound","Power","Strongman"],"muscle_group":"Legs","primary_muscles":["Glutes","Hamstrings","Quadriceps"],"secondary_muscles":["Spinal erectors","Chest","Triceps"],"movement_pattern":"Hinge","equipment":["Large tyre"],"req":"sled","equipment_tier":3,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":4,"reps":"4–6","form_cues":["Squat down, chest against the tyre, fingers under the tread.","Drive forward and up with the legs, not the arms.","Pop a knee in, flip hands, and push it over."],"common_mistakes":["Deadlifting with a rounded back","Curling the tyre with the arms (biceps tear risk)"],"regressions":["Sandbag load to platform"],"progressions":[],"safety":"Keep arms long (never curl the tyre) and stay clear of where it lands.","video":null,"diagram":"","notes":"No gear id for a tyre; req uses sled as the nearest strongman-area id."},{"id":"yoke","name":"Yoke carry","aliases":["Yoke walk"],"training_type":"Strongman","tags":["Compound","Core","Legs","Strongman"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Core"],"secondary_muscles":["Upper back","Calves","Spinal erectors"],"movement_pattern":"Carry","equipment":["Yoke"],"req":"barbell,plates,powerrack","equipment_tier":3,"difficulty":"Advanced","tracking":"w","unilateral":false,"sets":4,"reps":"20 m","form_cues":["Set under the yoke bar like a back squat.","Brace hard and stand it up.","Take short, fast steps, keeping the yoke level."],"common_mistakes":["Taking long strides that swing the yoke","Losing the brace and folding forward"],"regressions":["Farmer's carry"],"progressions":[],"safety":"Learn with light loads on a flat surface and drop the yoke forward or back if you lose control.","video":null,"diagram":"","notes":"No yoke? A barbell in a rack can be walked out for short distances (bar walk). req uses barbell as nearest gear id."},{"id":"swimback","name":"Backstroke","aliases":["Back crawl"],"training_type":"Cardio","tags":["Cardio","Endurance","Recovery"],"muscle_group":"Cardio","primary_muscles":["Latissimus dorsi","Shoulders"],"secondary_muscles":["Core","Glutes","Hip flexors","Heart and lungs"],"movement_pattern":"Locomotion","equipment":["Swimming pool","Goggles"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"cardio","unilateral":false,"sets":1,"reps":"500 m","form_cues":["Lie flat with your ears in the water, eyes up.","Enter little-finger first, arms straight overhead.","Kick steadily from the hips with loose ankles."],"common_mistakes":["Sitting in the water with hips low","Bending the knees too much on the kick"],"regressions":["Freestyle swimming"],"progressions":["Butterfly"],"safety":"Count strokes from the flags so you don't hit the wall.","video":null,"diagram":"","notes":"Good for posture: opens the chest. Needs pool access."},{"id":"bearcrawl","name":"Bear crawl","aliases":["Bear walk"],"training_type":"Cardio","tags":["Calisthenics","Cardio","Core","Home-friendly"],"muscle_group":"Cardio","primary_muscles":["Shoulders","Core","Quadriceps"],"secondary_muscles":["Chest","Triceps","Hip flexors","Heart and lungs"],"movement_pattern":"Locomotion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"time","unilateral":false,"sets":3,"reps":"30 sec","form_cues":["Hands under shoulders, knees under hips, knees hovering just off the floor.","Move opposite hand and foot together.","Keep your back flat like a tabletop."],"common_mistakes":["Hips shooting up high","Big, sloppy steps"],"regressions":["Bear plank hold"],"progressions":["Lateral bear crawl"],"safety":"Use a clear, non-slip floor and stop if wrists hurt.","video":null,"diagram":"","notes":"Crawl forward and backward, or log distance (e.g. 4 × 10 m) in notes."},{"id":"swimbreast","name":"Breaststroke","aliases":["Breaststroke swimming"],"training_type":"Cardio","tags":["Cardio","Endurance","Recovery"],"muscle_group":"Cardio","primary_muscles":["Pectorals","Adductors","Quadriceps"],"secondary_muscles":["Shoulders","Glutes","Latissimus dorsi","Heart and lungs"],"movement_pattern":"Locomotion","equipment":["Swimming pool or open water","Goggles"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"cardio","unilateral":false,"sets":1,"reps":"500 m","form_cues":["Pull, breathe, kick, glide—in that order.","Snap your heels round in a whip kick.","Glide with arms extended before the next stroke."],"common_mistakes":["Skipping the glide","Keeping the head up the whole time"],"regressions":[],"progressions":["Freestyle swimming"],"safety":"Breaststroke kick can strain the inner knee; ease in if you have knee issues.","video":null,"diagram":"","notes":"Needs pool access; no app gear id for a pool."},{"id":"walk","name":"Brisk walking","aliases":["Power walking","Walk"],"training_type":"Cardio","tags":["Cardio","Endurance","Home-friendly","Recovery","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Glutes","Quadriceps"],"secondary_muscles":["Hamstrings","Core","Heart and lungs"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"cardio","unilateral":false,"sets":1,"reps":"30 min","form_cues":["Walk tall with your eyes ahead, not at your feet.","Swing your arms naturally from the shoulders.","Pick a pace where you can talk but not sing."],"common_mistakes":["Strolling too slowly to raise your heart rate","Overstriding and landing hard on the heel"],"regressions":[],"progressions":["Hiking","Rucking","Jogging"],"safety":"Wear supportive shoes and start with shorter walks if you're new to exercise.","video":null,"diagram":"","notes":"Great daily base for fat loss and recovery days. Count your walk to the gym here."},{"id":"burpeebroad","name":"Burpee broad jump","aliases":["Burpee long jump"],"training_type":"Cardio","tags":["Cardio","Compound","Endurance","Plyometric"],"muscle_group":"Cardio","primary_muscles":["Quadriceps","Glutes","Core"],"secondary_muscles":["Chest","Hamstrings","Calves","Heart and lungs"],"movement_pattern":"Locomotion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"count","unilateral":false,"sets":3,"reps":"8–10","form_cues":["Do a burpee, then jump forward as far as you can.","Swing your arms and land softly on both feet.","Go straight into the next burpee where you land."],"common_mistakes":["Landing with knees caving in","Rushing so the burpee gets sloppy"],"regressions":["Burpees"],"progressions":[],"safety":"Needs clear space ahead and a non-slip surface.","video":null,"diagram":"","notes":"Popular in CrossFit and HYROX training; can also be logged by distance."},{"id":"burpee","name":"Burpees","aliases":["Burpee","Jumping burpee"],"training_type":"Cardio","tags":["Cardio","Compound","Endurance","Home-friendly","Plyometric"],"muscle_group":"Cardio","primary_muscles":["Quadriceps","Chest","Core"],"secondary_muscles":["Glutes","Shoulders","Triceps","Calves","Heart and lungs"],"movement_pattern":"Locomotion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"10–15","form_cues":["Squat, hands down, jump feet back to a plank.","Jump feet back in, then jump up with arms overhead.","Land softly and flow into the next rep."],"common_mistakes":["Belly flopping with a saggy back","Landing stiff-legged from the jump"],"regressions":["Squat thrusts","Step-back burpee"],"progressions":["Push-up burpee","Burpee broad jump"],"safety":"Scale to stepping if you have wrist, shoulder or low-back pain.","video":null,"diagram":"","notes":""},{"id":"buttkick","name":"Butt kicks","aliases":["Heel flicks","Butt kickers"],"training_type":"Cardio","tags":["Cardio","Home-friendly","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Hamstrings","Calves"],"secondary_muscles":["Quadriceps","Hip flexors","Heart and lungs"],"movement_pattern":"Locomotion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"time","unilateral":false,"sets":3,"reps":"30 sec","form_cues":["Flick your heels up toward your glutes.","Keep your knees pointing down at the floor.","Stay quick and light on your toes."],"common_mistakes":["Knees swinging forward","Leaning the torso forward"],"regressions":["March in place"],"progressions":["High knees"],"safety":"Stop if you feel a cramp or pull in the hamstring.","video":null,"diagram":"","notes":""},{"id":"swimfly","name":"Butterfly","aliases":["Butterfly stroke","Fly"],"training_type":"Cardio","tags":["Cardio","Endurance","Power"],"muscle_group":"Cardio","primary_muscles":["Latissimus dorsi","Shoulders","Core"],"secondary_muscles":["Chest","Triceps","Glutes","Lower back","Heart and lungs"],"movement_pattern":"Locomotion","equipment":["Swimming pool","Goggles"],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"cardio","unilateral":false,"sets":4,"reps":"50 m","form_cues":["Move in a wave from chest to hips to feet.","Sweep both arms together, out of the water and forward.","Use two dolphin kicks per arm stroke."],"common_mistakes":["Lifting the head too high to breathe","Bending the knees for a big kick instead of a body wave"],"regressions":["Freestyle swimming"],"progressions":[],"safety":"Very demanding on the shoulders and lower back—build up slowly.","video":null,"diagram":"","notes":"Needs pool access."},{"id":"fartlek","name":"Fartlek run","aliases":["Speed play"],"training_type":"Cardio","tags":["Cardio","Endurance"],"muscle_group":"Cardio","primary_muscles":["Quadriceps","Hamstrings","Glutes","Calves"],"secondary_muscles":["Core","Heart and lungs"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"cardio","unilateral":false,"sets":1,"reps":"25–30 min","form_cues":["Mix fast bursts with easy running, no fixed plan needed.","Pick landmarks: surge to the next lamppost, then recover.","Keep the easy bits genuinely easy."],"common_mistakes":["Making every surge an all-out sprint","Stopping to walk instead of jogging the recovery"],"regressions":["Run-walk intervals"],"progressions":["Interval repeats (400 m)"],"safety":"Warm up well before surges to protect your hamstrings and calves.","video":null,"diagram":"","notes":"Swedish for 'speed play'. A fun way to add speed without a track."},{"id":"swimfree","name":"Freestyle swimming","aliases":["Front crawl","Freestyle"],"training_type":"Cardio","tags":["Cardio","Endurance","Recovery"],"muscle_group":"Cardio","primary_muscles":["Latissimus dorsi","Shoulders"],"secondary_muscles":["Triceps","Core","Glutes","Hip flexors","Heart and lungs"],"movement_pattern":"Locomotion","equipment":["Swimming pool or open water","Goggles"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"cardio","unilateral":false,"sets":1,"reps":"1 km","form_cues":["Keep your head down and body long and flat.","Rotate your body and reach long with each stroke.","Breathe to the side every 2–3 strokes."],"common_mistakes":["Lifting the head to breathe so the legs sink","Kicking from the knees instead of the hips","Crossing hands over the midline"],"regressions":["Kickboard kicks","Breaststroke"],"progressions":["Butterfly"],"safety":"Swim in supervised areas; avoid open water alone.","video":null,"diagram":"","notes":"No app gear id exists for a pool, so 'req' is left empty—needs pool access."},{"id":"highknees","name":"High knees","aliases":["Running in place with high knees"],"training_type":"Cardio","tags":["Cardio","Endurance","Home-friendly","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Hip flexors","Quadriceps","Calves"],"secondary_muscles":["Core","Glutes","Heart and lungs"],"movement_pattern":"Locomotion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"time","unilateral":false,"sets":3,"reps":"30 sec","form_cues":["Drive each knee up to hip height.","Stay light on the balls of your feet.","Pump your arms in time with your legs."],"common_mistakes":["Leaning back to lift the knees","Landing heavy on the heels"],"regressions":["March in place"],"progressions":["Sprint intervals"],"safety":"Use a softer surface or march instead if you have knee or ankle pain.","video":null,"diagram":"","notes":""},{"id":"hike","name":"Hiking","aliases":["Hillwalking","Trekking"],"training_type":"Cardio","tags":["Balance","Cardio","Endurance"],"muscle_group":"Cardio","primary_muscles":["Quadriceps","Glutes","Calves"],"secondary_muscles":["Hamstrings","Core","Heart and lungs"],"movement_pattern":"Gait","equipment":["Hiking boots or trail shoes"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"cardio","unilateral":false,"sets":1,"reps":"5–15 km","form_cues":["Take shorter steps going uphill.","Lean slightly forward on climbs and use your glutes.","Go slow and controlled on descents."],"common_mistakes":["Locking the knees on descents","Starting too fast up the first climb"],"regressions":["Brisk walking"],"progressions":["Rucking","Trail running"],"safety":"Check weather, carry water, and use poles if your knees struggle downhill.","video":null,"diagram":"","notes":"Log elevation gain in notes if your watch tracks it."},{"id":"hillsprint","name":"Hill sprints","aliases":["Hill repeats","Incline sprints"],"training_type":"Cardio","tags":["Cardio","Endurance","Power"],"muscle_group":"Cardio","primary_muscles":["Glutes","Quadriceps","Calves"],"secondary_muscles":["Hamstrings","Hip flexors","Core","Heart and lungs"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"count","unilateral":false,"sets":8,"reps":"1","form_cues":["Lean slightly into the hill from your ankles.","Take short, powerful steps and pump your arms.","Walk back down slowly as your recovery."],"common_mistakes":["Running back down fast and pounding the knees","Looking at your feet instead of up the hill"],"regressions":["Sprint intervals","Hiking"],"progressions":[],"safety":"Choose a moderate grade (5–10%) and a non-slippery surface.","video":null,"diagram":"","notes":"Sprint 10–20 sec up; count each climb as one rep. Easier on the hamstrings than flat sprints."},{"id":"run400","name":"Interval repeats (400 m)","aliases":["Track repeats","400s","Quarter-mile repeats"],"training_type":"Cardio","tags":["Cardio","Endurance","Power"],"muscle_group":"Cardio","primary_muscles":["Quadriceps","Hamstrings","Glutes","Calves"],"secondary_muscles":["Hip flexors","Core","Heart and lungs"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"cardio","uni