,"form_cues":["Jump feet wide as your arms sweep overhead.","Land softly with knees slightly bent.","Keep a steady rhythm and breathe."],"common_mistakes":["Landing stiff-legged","Half-reaching with the arms"],"regressions":["Step jacks"],"progressions":["Plank jacks"],"safety":"Step side to side instead of jumping if you have knee, ankle or pelvic floor issues.","video":null,"diagram":"","notes":""},{"id":"latshuffle","name":"Lateral shuffle","aliases":["Side shuffle","Defensive slide"],"training_type":"Cardio","tags":["Balance","Cardio","Home-friendly","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Abductors","Glutes","Quadriceps"],"secondary_muscles":["Adductors","Calves","Heart and lungs"],"movement_pattern":"Locomotion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"time","unilateral":false,"sets":3,"reps":"30 sec","form_cues":["Sink into a half squat with your chest up.","Push off the trailing foot and slide sideways.","Don't let your feet click together."],"common_mistakes":["Standing up tall between steps","Crossing the feet"],"regressions":["Step jacks"],"progressions":[],"safety":"Wear shoes with lateral support; avoid slippery floors.","video":null,"diagram":"","notes":""},{"id":"marchplace","name":"March in place","aliases":["Marching on the spot","Standing march"],"training_type":"Cardio","tags":["Cardio","Home-friendly","Rehab","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Hip flexors","Quadriceps"],"secondary_muscles":["Calves","Core","Heart and lungs"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"time","unilateral":false,"sets":3,"reps":"1 min","form_cues":["Lift each knee to a comfortable height.","Swing your opposite arm with each step.","Stand tall and breathe steadily."],"common_mistakes":["Slouching forward","Shuffling with tiny lifts"],"regressions":[],"progressions":["High knees"],"safety":"Hold a counter or wall for balance if you're unsteady.","video":null,"diagram":"","notes":"Zero-impact option for beginners, older adults or small spaces."},{"id":"plankjack","name":"Plank jacks","aliases":["Plank jumping jacks"],"training_type":"Cardio","tags":["Cardio","Core","Home-friendly"],"muscle_group":"Cardio","primary_muscles":["Core","Shoulders"],"secondary_muscles":["Adductors","Abductors","Calves","Heart and lungs"],"movement_pattern":"Locomotion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"20–30","form_cues":["Hold a straight plank on your hands.","Hop your feet wide, then back together.","Keep hips level and don't bounce them."],"common_mistakes":["Hips piking up","Sagging lower back"],"regressions":["Plank"],"progressions":["Burpees"],"safety":"Step feet out one at a time if your wrists or shoulders complain.","video":null,"diagram":"","notes":""},{"id":"burpeepu","name":"Push-up burpee","aliases":["Chest-to-floor burpee","Full burpee","Military burpee"],"training_type":"Cardio","tags":["Cardio","Compound","Endurance","Home-friendly"],"muscle_group":"Cardio","primary_muscles":["Chest","Quadriceps","Core"],"secondary_muscles":["Triceps","Shoulders","Glutes","Heart and lungs"],"movement_pattern":"Locomotion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Advanced","tracking":"count","unilateral":false,"sets":3,"reps":"8–12","form_cues":["Jump back to a plank and do a full push-up.","Keep your body in a straight line on the push-up.","Jump feet in, stand, and jump with a clap overhead."],"common_mistakes":["Worming up from the floor hips-first","Skipping the push-up range"],"regressions":["Burpees"],"progressions":["Burpee broad jump"],"safety":"Drop the push-up when form slips; protect your shoulders and lower back.","video":null,"diagram":"","notes":""},{"id":"runwalk","name":"Run-walk intervals","aliases":["Jeffing","Walk-run","Couch to 5K intervals"],"training_type":"Cardio","tags":["Cardio","Endurance","Home-friendly"],"muscle_group":"Cardio","primary_muscles":["Quadriceps","Hamstrings","Glutes","Calves"],"secondary_muscles":["Core","Heart and lungs"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"cardio","unilateral":false,"sets":1,"reps":"20–30 min","form_cues":["Jog for a set time, then walk briskly to recover.","Keep the jog easy enough to repeat every round.","Walk with purpose; don't stop completely."],"common_mistakes":["Running the jog bits too hard","Cutting walk breaks short before you've recovered"],"regressions":["Brisk walking"],"progressions":["Jogging"],"safety":"Ease off if you feel sharp pain in shins, knees or feet.","video":null,"diagram":"","notes":"Classic start: 1 min jog / 1–2 min walk, repeated 8–10 times. Lengthen the jog each week."},{"id":"run","name":"Running","aliases":["Outdoor run","Road run"],"training_type":"Cardio","tags":["Cardio","Endurance","Home-friendly"],"muscle_group":"Cardio","primary_muscles":["Quadriceps","Hamstrings","Glutes","Calves"],"secondary_muscles":["Hip flexors","Core","Heart and lungs"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"cardio","unilateral":false,"sets":1,"reps":"5 km","form_cues":["Stand tall with a slight forward lean from the ankles.","Take quick, light steps landing under your hips.","Drive your elbows back and keep your hands relaxed."],"common_mistakes":["Overstriding and braking with each step","Tensing the shoulders and clenching fists","Running every run hard"],"regressions":["Jogging","Run-walk intervals"],"progressions":["Tempo run","Trail running","Sprint intervals"],"safety":"Increase distance slowly and replace worn-out shoes to protect knees and shins.","video":null,"diagram":"","notes":"Log distance and time; the app can work out your pace."},{"id":"sprint","name":"Sprint intervals","aliases":["Sprints","Flat sprints","100 m sprints"],"training_type":"Cardio","tags"