","Glutes","Calves"],"secondary_muscles":["Hamstrings","Core","Heart and lungs"],"movement_pattern":"Gait","equipment":["Flight of stairs"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":6,"reps":"1 flight","form_cues":["Run up every step, landing on the balls of your feet.","Pump your arms and keep your chest up.","Walk down carefully, holding the rail if needed."],"common_mistakes":["Rushing the way down","Hunching over and looking at your feet"],"regressions":["Stair climber"],"progressions":["Hill sprints"],"safety":"Use dry, well-lit stairs and always walk—never run—back down.","video":null,"diagram":"","notes":"Take every second step for a glute-focused version."},{"id":"stepjack","name":"Step jacks","aliases":["Low-impact jumping jacks","Side step jacks"],"training_type":"Cardio","tags":["Cardio","Home-friendly","Rehab","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Shoulders","Abductors"],"secondary_muscles":["Calves","Glutes","Heart and lungs"],"movement_pattern":"Locomotion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"30–40","form_cues":["Step one foot out to the side as arms rise overhead.","Bring the foot back in and lower the arms.","Alternate sides at a brisk tempo."],"common_mistakes":["Moving too slowly to raise the heart rate","Shrugging the shoulders"],"regressions":["March in place"],"progressions":["Jumping jacks"],"safety":"Fine for most joint issues since there's no jumping.","video":null,"diagram":"","notes":""},{"id":"stepburpee","name":"Step-back burpee","aliases":["Low-impact burpee","Walk-out burpee"],"training_type":"Cardio","tags":["Cardio","Home-friendly","Rehab"],"muscle_group":"Cardio","primary_muscles":["Quadriceps","Core","Shoulders"],"secondary_muscles":["Glutes","Chest","Heart and lungs"],"movement_pattern":"Locomotion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracki