],"safety":"Use a rope sized to your height and jump on a forgiving surface, not concrete.","video":null,"diagram":"","notes":"Can also be logged as reps (skips)."},{"id":"ruck","name":"Rucking","aliases":["Ruck march","Weighted walking","Backpack walk"],"training_type":"Cardio","tags":["Cardio","Endurance","Strength"],"muscle_group":"Cardio","primary_muscles":["Glutes","Quadriceps","Upper back"],"secondary_muscles":["Calves","Hamstrings","Core","Trapezius","Heart and lungs"],"movement_pattern":"Carry","equipment":["Backpack or rucksack with weight","Weighted vest (optional)"],"req":"weightvest","equipment_tier":1,"difficulty":"Intermediate","tracking":"cardio","unilateral":false,"sets":1,"reps":"5 km","form_cues":["Wear the pack high and tight on your back.","Walk tall; don't lean far forward.","Keep a brisk, steady pace."],"common_mistakes":["Starting with a pack that's too heavy","Loose straps letting the load bounce"],"regressions":["Brisk walking"],"progressions":["Hiking"],"safety":"Start around 10% of body weight and add load slowly to protect your back and feet.","video":null,"diagram":"","notes":"A loaded backpack works fine; 'weightvest' is the nearest app gear id."},{"id":"ropeside","name":"Side-to-side jump rope","aliases":["Skier jump rope","Lateral jump rope"],"training_type":"Cardio","tags":["Cardio","Home-friendly"],"muscle_group":"Cardio","primary_muscles":["Calves","Abductors"],"secondary_muscles":["Adductors","Core","Heart and lungs"],"movement_pattern":"Locomotion","equipment":["Jump rope"],"req":"jumprope","equipment_tier":1,"difficulty":"Intermediate","tracking":"time","unilateral":false,"sets":3,"reps":"30 sec","form_cues":["Jump a few centimetres side to side with feet together.","Keep your shoulders square to the front.","Stay light and quick."],"common_mistakes":["Jumping too wide","Rolling the ankles on landing"],"regressions":["Jump rope"],"progressions":["Criss-cross jump rope"],"safety":"Avoid if you have unstable ankles.","video":null,