si"],"secondary_muscles":["Glutes","Hamstrings","Biceps","Core","Heart and lungs"],"movement_pattern":"Horizontal pull","equipment":["Rowing machine"],"req":"rower","equipment_tier":2,"difficulty":"Beginner","tracking":"cardio","unilateral":false,"sets":1,"reps":"5 km","form_cues":["Legs, hips, then arms on the drive.","Arms, hips, then legs on the return.","Keep the handle level and wrists flat."],"common_mistakes":["Pulling with the arms first","Rounding the back at the catch","Damper set to 10"],"regressions":[],"progressions":["Rowing intervals","2,000 m row test"],"safety":"Keep a neutral spine; set the damper around 3–5.","video":null,"diagram":"","notes":"Roughly 60% legs, 20% hips/back, 20% arms."},{"id":"spinint","name":"Spin bike intervals","aliases":["Spin class","Indoor cycling","Spinning"],"training_type":"Cardio","tags":["Cardio","Endurance","Power"],"muscle_group":"Cardio","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Calves","Core","Heart and lungs"],"movement_pattern":"Locomotion","equipment":["Spin bike"],"req":"spinbike|bike","equipment_tier":2,"difficulty":"Intermediate","tracking":"time","unilateral":false,"sets":1,"reps":"30–45 min","form_cues":["Alternate seated sprints with standing climbs.","Add resistance rather than spinning out of control.","Keep hips steady and core engaged out of the saddle."],"common_mistakes":["Too little resistance so you bounce","Bobbing the upper body when standing"],"regressions":["Stationary bike"],"progressions":["Tabata bike"],"safety":"Set up the bike properly and use clipped or caged pedals.","video":null,"diagram":"","notes":""},{"id":"bikeride","name":"Stationary bike","aliases":["Exercise bike","Upright bike"],"training_type":"Cardio","tags":["Cardio","Endurance","Recovery"],"muscle_group":"Cardio","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hamstrings","Calves","Heart and lungs"],"movement_pattern":"Locomotion","equipment":["Stationary bike"],"req":"bike|