termediate","tracking":"time","unilateral":false,"sets":1,"reps":"20 min","form_cues":["Alternate fast running with easy jogging or walking.","Change speed with the buttons, not by jumping off.","Keep form tall and relaxed at speed."],"common_mistakes":["Straddling the belt on/off at high speed","Setting the sprint speed beyond control"],"regressions":["Treadmill run"],"progressions":["Curved treadmill sprints"],"safety":"Use the safety key; build sprint speed gradually.","video":null,"diagram":"","notes":"Example: 1 min fast / 1–2 min easy × 8."},{"id":"treadrun","name":"Treadmill run","aliases":["Treadmill jog","Treadmill running"],"training_type":"Cardio","tags":["Cardio","Endurance"],"muscle_group":"Cardio","primary_muscles":["Quadriceps","Hamstrings","Glutes","Calves"],"secondary_muscles":["Hip flexors","Core","Heart and lungs"],"movement_pattern":"Gait","equipment":["Treadmill"],"req":"treadmill","equipment_tier":2,"difficulty":"Beginner","tracking":"cardio","unilateral":false,"sets":1,"reps":"5 km","form_cues":["Set a 1% incline to mimic outdoor running.","Run in the middle of the belt with quick, light steps.","Look ahead, not down at the console."],"common_mistakes":["Holding the rails","Overstriding and landing far in front"],"regressions":["Treadmill walk"],"progressions":["Treadmill intervals"],"safety":"Use the safety key and step onto the side rails to stop.","video":null,"diagram":"","notes":""},{"id":"treadwalk","name":"Treadmill walk","aliases":["Treadmill walking"],"training_type":"Cardio","tags":["Cardio","Endurance","Recovery","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Calves","Glutes","Quadriceps"],"secondary_muscles":["Hamstrings","Heart and lungs"],"movement_pattern":"Gait","equipment":["Treadmill"],"req":"treadmill","equipment_tier":2,"difficulty":"Beginner","tracking":"cardio","unilateral":false,"sets":1,"reps":"20–30 min","form_cues":["Walk tall in the middle of the belt.","Swing your arms; let go of the handrails.","Use a brisk pace, around 5–6 km/h."],"common_mistakes":["Holding the handrails the whole time","Walking too close to the front"],"regressions":[],"progressions":["Incline treadmill walk","Treadmill run"],"safety":"Clip on the safety key and straddle the belt before starting.","video":null,"diagram":"","notes":""},{"id":"ube","name":"Arm bike","aliases":["Upper body ergometer","UBE","Arm ergometer"],"training_type":"Cardio","tags":["Cardio","Endurance","Rehab"],"muscle_group":"Cardio","primary_muscles":["Shoulders","Upper back"],"secondary_muscles":["Biceps","Triceps","Chest","Heart and lungs"],"movement_pattern":"Locomotion","equipment":["Upper body ergometer"],"req":"bike","equipment_tier":3,"difficulty":"Beginner","tracking":"time","unilateral":false,"sets":1,"reps":"10 min","form_cues":["Sit tall with the crank at shoulder height.","Pedal smoothly with your hands.","Switch direction halfway through."],"common_mistakes":["Hunching forward","Too much resistance so you jerk the cranks"],"regressions":[],"progressions":["Air bike"],"safety":"Useful when legs are injured; keep resistance low if shoulders are sore.","video":null,"diagram":"","notes":"No arm-ergometer gear id; 'bike' used as nearest."},{"id":"curvedrun","name":"Curved treadmill run","aliases":["Assault Runner","Manual treadmill run","Woodway Curve"],"training_type":"Cardio","tags":["Cardio","Endurance"],"muscle_group":"Cardio","primary_muscles":["Quadriceps","Hamstrings","Glutes","Calves"],"secondary_muscles":["Hip flexors","Core","Heart and lungs"],"movement_pattern":"Gait","equipment":["Curved / manual treadmill"],"req":"curvedtread","equipment_tier":3,"difficulty":"Intermediate","tracking":"cardio","unilateral":false,"sets":1,"reps":"3 km","form_cues":["Move forward on the curve to speed up, back to slow down.","Run tall with quick, light steps.","Stay near the middle to hold a steady pace."],"common_mistakes":["Drifting too far forward and accelerating","Heavy heel-striking"],"regressions":["Treadmill run"],"progressions":["Curved treadmill sprints"],"safety":"Use the handrails to get on and off safely; the belt keeps moving.","video":null,"diagram":"","notes":""},{"id":"curvedsprint","name":"Curved treadmill sprints","aliases":["Assault Runner sprints","Curve sprints"],"training_type":"Cardio","tags":["Cardio","Endurance","Power"],"muscle_group":"Cardio","primary_muscles":["Glutes","Hamstrings","Quadriceps"],"secondary_muscles":["Calves","Hip flexors","Core","Heart and lungs"],"movement_pattern":"Gait","equipment":["Curved / manual treadmill"],"req":"curvedtread","equipment_tier":3,"difficulty":"Advanced","tracking":"time","unilateral":false,"sets":8,"reps":"20 sec","form_cues":["Lean into the curve and drive hard with your arms.","Stay on the balls of your feet.","Step back onto the rails to stop and rest."],"common_mistakes":["Sprinting cold without warm-up","Looking down at the belt"],"regressions":["Curved treadmill run"],"progressions":[],"safety":"Hold the rails when stepping off; the belt freewheels for a few seconds.","video":null,"diagram":"","notes":"Example: 8 × 20 sec all-out / 40 sec rest."},{"id":"ski","name":"Ski erg","aliases":["SkiErg","Ski ergometer"],"training_type":"Cardio","tags":["Cardio","Compound","Endurance"],"muscle_group":"Cardio","primary_muscles":["Latissimus dorsi","Triceps","Core"],"secondary_muscles":["Shoulders","Glutes","Hamstrings","Heart and lungs"],"movement_pattern":"Vertical pull","equipment":["Ski erg"],"req":"skierg","equipment_tier":3,"difficulty":"Intermediate","tracking":"cardio","unilateral":false,"sets":1,"reps":"2 km","form_cues":["Reach tall, then drive the handles down by hinging hips.","Finish with hands past your hips.","Let the arms float back up as you stand tall."],"common_mistakes":["Squatting deep instead of hinging","Pulling with arms only"],"regressions":[],"progressions":[],"safety":"Hinge with a neutral back; don't crunch your spine forward.","video":null,"diagram":"","notes":""},{"id":"stair","name":"Stair cli