and strike with the shin.","Bring the leg back to stance with your hands up."],"common_mistakes":["Not pivoting the standing foot","Kicking with just the leg, no hip turn"],"regressions":["Front kick"],"progressions":["Heavy bag roundhouse kicks"],"safety":"Warm up hips and hamstrings first; kick low until mobility allows higher.","video":null,"diagram":"","notes":""},{"id":"shadowkick","name":"Shadow kickboxing","aliases":["Cardio kickboxing","Shadow Muay Thai"],"training_type":"Combat","tags":["Cardio","Combat","Home-friendly"],"muscle_group":"Cardio","primary_muscles":["Shoulders","Core","Glutes"],"secondary_muscles":["Hip flexors","Quadriceps","Obliques","Heart and lungs"],"movement_pattern":"Rotation","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"time","unilateral":false,"sets":3,"reps":"3 min","form_cues":["Mix punches with kicks and knees, hands always up.","Turn your hips over on every kick.","Return to stance after each combination."],"common_mistakes":["Leaning way back on kicks","Dropping the guard while kicking"],"regressions":["Shadowboxing"],"progressions":["Kickboxing bag rounds"],"safety":"Kick only as high as your hips allow; warm up the hips first.","video":null,"diagram":"","notes":""},{"id":"shadowbox","name":"Shadowboxing","aliases":["Shadow boxing"],"training_type":"Combat","tags":["Cardio","Combat","Home-friendly","Warm-up"],"muscle_group":"Cardio","primary_muscles":["Shoulders","Core"],"secondary_muscles":["Chest","Triceps","Calves","Heart and lungs"],"movement_pattern":"Rotation","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"time","unilateral":false,"sets":3,"reps":"3 min","form_cues":["Stay in stance with hands up guarding your chin.","Throw crisp punches and snap them back.","Keep moving your feet between combinations."],"common_mistakes":["Dropping the hands after punching","Fully locking the elbows on every punch","Standing flat-footed"],"regressions":[],"progressions":["Shadow kickboxing","Punching bag rounds"],"safety":"Don't snap your elbows straight; keep a tiny bend at full extension.","video":null,"diagram":"","notes":"Rounds are usually 3 min work / 1 min rest. Light hand weights are optional but go easy."},{"id":"speedpunch","name":"Speed punches","aliases":["Punch-outs","Speed bag punches (shadow)"],"training_type":"Combat","tags":["Cardio","Combat","Endurance","Home-friendly"],"muscle_group":"Cardio","primary_muscles":["Shoulders"],"secondary_muscles":["Chest","Triceps","Core","Heart and lungs"],"movement_pattern":"Horizontal push","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"time","unilateral":false,"sets":4,"reps":"30 sec","form_cues":["Square up with a slight bend in the knees.","Punch straight ahead, alternating as fast as you can.","Keep your core tight and shoulders down."],"common_mistakes":["Shrugging the shoulders up","Locking the elbows hard"],"regressions":[],"progressions":["Shadowboxing"],"safety":"Keep a soft bend in the elbows to protect the joints.","video":null,"diagram":"","notes":"Common finisher in cardio kickboxing classes; works well as 20–30 sec intervals."},{"id":"sprawl","name":"Sprawls","aliases":["Sprawl drill","Wrestler sprawl"],"training_type":"Combat","tags":["Cardio","Combat","Home-friendly"],"muscle_group":"Cardio","primary_muscles":["Core","Hip flexors","Quadriceps"],"secondary_muscles":["Chest","Shoulders","Glutes","Heart and lungs"],"movement_pattern":"Locomotion","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"10–15","form_cues":["From a fighting stance, drop hands to the floor.","Shoot your legs back and drive hips down to the mat.","Snap your feet back under you and return to stance."],"common_mistakes":["Landing on straight arms and jarring the elbows","Hips staying high instead of pressing down"],"regressions":["Squat thrusts"],"progressions":["Push-up burpee"],"safety":"Use a mat; build speed only once the movement is smooth.","video":null,"diagram":"","notes":"Takedown defence from wrestling/MMA and a brutal conditioning drill."},{"id":"bagfront","name":"Heavy bag front kick","aliases":["Bag teep","Push kick on bag"],"training_type":"Combat","tags":["Balance","Combat","Power"],"muscle_group":"Cardio","primary_muscles":["Hip flexors","Quadriceps","Glutes"],"secondary_muscles":["Core","Calves"],"movement_pattern":"Extension","equipment":["Punching bag (long/standing)"],"req":"bag","equipment_tier":2,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":3,"reps":"10 / side","form_cues":["Chamber the knee high before extending.","Push through the ball of the foot into the bag.","Keep your hands up and recover to stance."],"common_mistakes":["Kicking with toes and jamming them","Locking out the knee hard"],"regressions":["Front kick"],"progressions":["Heavy bag roundhouse kicks"],"safety":"Strike with the ball of the foot, toes pulled back.","video":null,"diagram":"","notes":""},{"id":"baghook","name":"Heavy bag hooks","aliases":["Lead and rear hooks"],"training_type":"Combat","tags":["Cardio","Combat","Core","Power"],"muscle_group":"Cardio","primary_muscles":["Obliques","Shoulders"],"secondary_muscles":["Chest","Biceps","Core"],"movement_pattern":"Rotation","equipment":["Punching bag","Gloves or hand wraps"],"req":"bag","equipment_tier":2,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"10 / side","form_cues":["Bend the arm about 90° and keep the elbow up.","Turn the hips and pivot the lead foot into the punch.","Bring the hand straight back to guard."],"common_mistakes":["Swinging wide with an open arm","Punching with arm only, no hip turn"],"regressions":["Heavy bag jab-cross"],"progressions":["Heavy bag jab-cross-hook"],"safety":"Keep the wrist straight to avoid sprains.","video":null,"diagram":"","notes":""},{"id":"bagjabcross","name":"Heavy bag jab-cross","aliases":["1-2 combo","One-two"],"training_type":"Combat","tags":["Cardio","Combat","Power"],"muscle_group":"Cardio","primary_muscles":["Shoulders","Chest","Triceps"],"secondary_muscles":["Obliques","Calves","Core"],"movement_pattern":"Horizontal push","equipment":["Punching bag","Gloves or hand wraps"],"req":"bag","equipment_tier":2,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"20","form_cues":["Snap the lead hand straight out, then back to the chin.","Pivot the back foot and turn the hip for the cross.","Keep the non-punching hand guarding your face."],"common_mistakes":["Winding up before punching","Not rotating the back foot on the cross"],"regressions":["Shadowboxing"],"progressions":["Heavy bag jab-cross-hook"],"safety":"Punch with the first two knuckles and a straight wrist.","video":null,"diagram":"","notes":""},{"id":"bag123","name":"Heavy bag jab-cross-hook","aliases":["1-2-3 combo","Jab-cross-hook combo"],"training_type":"Combat","tags":["Cardio","Combat","Endurance","Power"],"muscle_group":"Cardio","primary_muscles":["Shoulders","Obliques","Chest"],"secondary_muscles":["Triceps","Core","Calves","Heart and lungs"],"movement_pattern":"Rotation","equipment":["Punching bag","Gloves or hand wraps"],"req":"bag","equipment_tier":2,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"15","form_cues":["Jab, cross, then lead hook in one smooth flow.","Let the cross's hip turn load the hook.","Reset to stance with hands up after each combo."],"common_mistakes":["Pausing between punches","Dropping the rear hand during the hook"],"regressions":["Heavy bag jab-cross"],"progressions":["Punching bag rounds"],"safety":"Stay in range so you don't overreach and strain the shoulder.","video":null,"diagram":"","notes":"Count each full combination as one rep."},{"id":"bagknee","name":"Heavy bag knees","aliases":["Clinch knees","Bag knee strikes"],"training_type":"Combat","tags":["Cardio","Combat","Core","Endurance"],"muscle_group":"Cardio","primary_muscles":["Hip flexors","Core"],"secondary_muscles":["Glutes","Quadriceps","Shoulders","Heart and lungs"],"movement_pattern":"Flexion","equipment":["Punching bag"],"req":"bag","equipment_tier":2,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"20","form_cues":["Grip the top of the bag as if clinching.","Pull the bag in as you drive the knee up and through.","Rise onto the toes of your standing foot."],"common_mistakes":["Kneeing with hips pushed back","Not alternating sides"],"regressions":["Knee strikes"],"progressions":["Kickboxing bag rounds"],"safety":"Keep a firm grip; a swinging bag can catch you off balance.","video":null,"diagram":"","notes":""},{"id":"bagpunchout","name":"Heavy bag punch-outs","aliases":["Bag sprints","Bag blitz"],"training_type":"Combat","tags":["Cardio","Combat","Endurance","Power"],"muscle_group":"Cardio","primary_muscles":["Shoulders"],"secondary_muscles":["Chest","Triceps","Core","Heart and lungs"],"movement_pattern":"Horizontal push","equipment":["Punching bag","Gloves or hand wraps"],"req":"bag","equipment_tier":2,"difficulty":"Intermediate","tracking":"time","unilateral":false,"sets":5,"reps":"20 sec","form_cues":["Square up close to the bag.","Throw fast, straight punches non-stop.","Keep punches short and snappy, not wild."],"common_mistakes":["Wild, looping punches that hurt wrists","Leaning on the bag"],"regressions":["Speed punches"],"progressions":["Punching bag rounds"],"safety":"Use proper gloves and wraps; stop if a wrist or knuckle hurts.","video":null,"diagram":"","notes":"Great finisher: 20 sec all-out / 40 sec rest."},{"id":"bagkick","name":"Heavy bag roundhouse kicks","aliases":["Bag round kicks","Thai kicks on the bag"],"training_type":"Combat","tags":["Cardio","Combat","Power"],"muscle_group":"Cardio","primary_muscles":["Obliques","Glutes","Hip flexors"],"secondary_muscles":["Quadriceps","Adductors","Core"],"movement_pattern":"Rotation","equipment":["Punching bag (long/standing)","Shin guards (optional)"],"req":"bag","equipment_tier":2,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":3,"reps":"10 / side","form_cues":["Step out, pivot on the standing foot, and turn the hip over.","Strike with the shin, not the foot.","Return quickly to a guarded stance."],"common_mistakes":["Kicking with the foot and hurting the instep","Leaning too far back"],"regressions":["Roundhouse kick"],"progressions":["Kickboxing bag rounds"],"safety":"Start light; shins need time to condition.","video":null,"diagram":"","notes":""},{"id":"baguppercut","name":"Heavy bag uppercuts","aliases":["Uppercuts"],"training_type":"Combat","tags":["Cardio","Combat","Power"],"muscle_group":"Cardio","primary_muscles":["Shoulders","Biceps"],"secondary_muscles":["Obliques","Quadriceps","Core"],"movement_pattern":"Vertical push","equipment":["Punching bag","Gloves or hand wraps"],"req":"bag","equipment_tier":2,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":3,"reps":"10 / side","form_cues":["Dip slightly with the knees, then drive up.","Punch upward with the palm facing you.","Keep the other hand guarding your chin."],"common_mistakes":["Dropping the hand low before punching","Leaning back as you punch"],"regressions":["Heavy bag jab-cross"],"progressions":["Heavy bag jab-cross-hook"],"safety":"An uppercut bag or teardrop bag is best; go lighter on a straight hanging bag.","video":null,"diagram":"","notes":""},{"id":"kickbagrounds","name":"Kickboxing bag rounds","aliases":["Muay Thai bag rounds"],"training_type":"Combat","tags":["Cardio","Combat","Endurance","Power"],"muscle_group":"Cardio","primary_muscles":["Shoulders","Obliques","Glutes"],"secondary_muscles":["Hip flexors","Quadriceps","Core","Heart and lungs"],"movement_pattern":"Rotation","equipment":["Punching bag (long/standing)","Gloves or hand wraps"],"req":"bag","equipment_tier":2,"difficulty":"Advanced","tracking":"time","unilateral":false,"sets":3,"reps":"3 min","form_cues":["Mix punches, kicks and knees in combinations.","Finish each combo with a step or angle change.","Pace yourself to last the full round."],"common_mistakes":["Throwing single strikes with no flow","Dropping the guard on kicks"],"regressions":["Punching bag rounds","Shadow kickboxing"],"progressions":[],"safety":"Wrap hands, warm up the hips, and start with light kicks.","video":null,"diagram":"","notes":""},{"id":"bagrounds","name":"Punching bag rounds","aliases":["Heavy bag rounds","Bag work"],"training_type":"Combat","tags":["Cardio","Combat","Endurance"],"muscle_group":"Cardio","primary_muscles":["Shoulders","Core"],"secondary_muscles":["Chest","Triceps","Obliques","Calves","Heart and lungs"],"movement_pattern":"Rotation","equipment":["Punching bag","Gloves or hand wraps"],"req":"bag","equipment_tier":2,"difficulty":"Beginner","tracking":"time","unilateral":false,"sets":3,"reps":"3 min","form_cues":["Wrap your hands and stand at arm's length from the bag.","Throw combinations, then move around the bag.","Return your hands to your face after every punch."],"common_mistakes":["Pushing the bag instead of snapping punches","Hands dropping as you tire","Holding your breath"],"regressions":["Shadowboxing"],"progressions":["Kickboxing bag rounds","Heavy bag punch-outs"],"safety":"Always wear wraps and gloves; build intensity gradually to protect wrists.","video":null,"diagram":"","notes":"Typical: 3 × 3 min rounds with 1 min rest."},{"id":"speedbag","name":"Speed bag","aliases":["Speedball"],"training_type":"Combat","tags":["Cardio","Combat","Endurance"],"muscle_group":"Cardio","primary_muscles":["Shoulders","Forearms"],"secondary_muscles":["Upper back","Triceps"],"movement_pattern":"Rotation","equipment":["Speed bag and platform"],"req":"bag","equipment_tier":3,"difficulty":"Intermediate","tracking":"time","unilateral":false,"sets":3,"reps":"2 min","form_cues":["Set the bag at mouth or chin height.","Hit in a steady rhythm with small circular motions.","Let the bag rebound three times before the next hit."],"common_mistakes":["Hitting too hard and losing rhythm","Arms too far from the bag"],"regressions":["Shadowboxing"],"progressions":[],"safety":"Wear light gloves or wraps to protect your knuckles.","video":null,"diagram":"","notes":"No speed-bag gear id exists; 'bag' (punching bag) is used as nearest. Mostly a timing and shoulder endurance drill."},{"id":"ninetyswitch","name":"90/90 hip switch","aliases":["Shin box switch","Windshield wiper hip switch"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Hip rotators","Glutes"],"secondary_muscles":["Adductors","Hip flexors"],"movement_pattern":"Mobility","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":2,"reps":"8 / side","form_cues":["Sit with both knees bent to 90°, one leg in front and one to the side.","Keep feet planted and rotate both knees to the other side.","Sit tall; use hands behind you only if needed."],"common_mistakes":["Slumping the lower back","Lifting the feet off the floor"],"regressions":["90/90 hip stretch"],"progressions":["Shin box get-up"],"safety":"Use hand support if knees or hips are irritated.","video":null,"diagram":"","notes":""},{"id":"activeslr","name":"Active straight leg raise","aliases":["ASLR","Lying leg raise for mobility"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Hamstrings","Hip flexors"],"secondary_muscles":["Core"],"movement_pattern":"Mobility","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"8–10 / side","form_cues":["Lie on your back with both legs straight.","Raise one straight leg as high as you can without help.","Press the other leg firmly into the floor."],"common_mistakes":["Bending the raised knee","Bottom leg lifting off the floor"],"regressions":["Strap hamstring stretch"],"progressions":[],"safety":"Keep the lower back flat; useful as a hamstring mobility check.","video":null,"diagram":"","notes":""},{"id":"adductrock","name":"Adductor rock-back","aliases":["Quadruped adductor stretch","Frog rock-back"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Adductors"],"secondary_muscles":["Hips","Hamstrings"],"movement_pattern":"Mobility","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"10 / side","form_cues":["Kneel on all fours and straighten one leg out to the side.","Rock hips back toward your heel.","Keep your back flat and return forward."],"common_mistakes":["Rounding the lower back","Rotating the foot up"],"regressions":["Side lunge adductor stretch"],"progressions":[],"safety":"Keep the range comfortable on the groin.","video":null,"diagram":"","notes":""},{"id":"anklecircle","name":"Ankle circles","aliases":["Ankle rotations","Ankle rolls"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Rehab","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Ankle joint","Calves"],"secondary_muscles":["Shins"],"movement_pattern":"Mobility","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":1,"reps":"10 each way / side","form_cues":["Lift one foot off the floor or sit with the leg extended.","Draw slow, full circles with your toes.","Change direction halfway."],"common_mistakes":["Moving the whole leg instead of the ankle","Rushing small circles"],"regressions":[],"progressions":["Knee-to-wall ankle mobilization"],"safety":"Move only in a pain-free range after ankle sprains.","video":null,"diagram":"","notes":""},{"id":"armcircle","name":"Arm circles","aliases":["Shoulder circles"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Deltoids","Rotator cuff"],"secondary_muscles":["Trapezius"],"movement_pattern":"Mobility","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"10 each way","form_cues":["Stand tall with arms straight out to the sides.","Draw small circles, then gradually make them bigger.","Reverse direction halfway through."],"common_mistakes":["Shrugging shoulders up to the ears","Arching the lower back"],"regressions":[],"progressions":["Arm swings","Shoulder CARs"],"safety":"Keep circles pain-free; shrink them if anything pinches.","video":null,"diagram":"","notes":""},{"id":"deepsquat","name":"Deep squat hold","aliases":["Bodyweight squat hold","Asian squat","Prying squat"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Hips","Ankles","Adductors"],"secondary_muscles":["Lower back","Quadriceps"],"movement_pattern":"Squat","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30–60 sec","form_cues":["Sit down into the bottom of a squat, feet flat.","Push knees out with your elbows and lift your chest.","Shift side to side gently to explore the range."],"common_mistakes":["Heels rising off the floor","Collapsing the chest forward"],"regressions":["Box squat hold","Hold a doorframe for support"],"progressions":["Goblet squat hold"],"safety":"Hold onto something if heels lift; skip if deep knee flexion hurts.","video":null,"diagram":"","notes":"Raise heels on a plate if ankle mobility limits depth."},{"id":"frankenstein","name":"Frankenstein walk","aliases":["Toy soldiers","Straight-leg kicks"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Hamstrings"],"secondary_muscles":["Hip flexors","Calves","Core"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"10 / side","form_cues":["Walk forward kicking one straight leg up.","Reach the opposite hand toward the toes.","Keep your chest up and standing leg tall."],"common_mistakes":["Rounding the back to reach the toes","Kicking higher than your hamstrings allow"],"regressions":["Front-to-back leg swing"],"progressions":[],"safety":"Kick only to a comfortable height; this is a warm-up, not a max test.","video":null,"diagram":"","notes":""},{"id":"legswing","name":"Front-to-back leg swing","aliases":["Forward leg swings","Sagittal leg swings"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Unilateral","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Hamstrings","Hip flexors"],"secondary_muscles":["Glutes","Core"],"movement_pattern":"Mobility","equipment":["Wall or support (optional)"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"10–15 / side","form_cues":["Hold a wall and stand tall on one leg.","Swing the free leg forward and back like a pendulum.","Let the range grow gradually with each swing."],"common_mistakes":["Rounding the lower back to fake range","Swinging wildly from the first rep"],"regressions":[],"progressions":["Lateral leg swing","Frankenstein walk"],"safety":"Start small and build range; keep the swing controlled.","video":null,"diagram":"","notes":"Classic pre-run and pre-leg-day drill."},{"id":"hipcars","name":"Hip CARs","aliases":["Hip controlled articular rotations","Standing hip circles (controlled)"],"training_type":"Mobility","tags":["Balance","Home-friendly","Mobility","Rehab","Unilateral","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Hip rotators","Hip flexors","Glutes"],"secondary_muscles":["Core","Adductors"],"movement_pattern":"Mobility","equipment":["Wall or support (optional)"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":2,"reps":"3–5 / side each way","form_cues":["Brace your core and lift one knee to hip height.","Rotate the knee out, open it to the side, then sweep the leg back.","Move as slowly as possible with zero movement in the torso."],"common_mistakes":["Leaning or twisting the trunk","Moving fast to get through sticky spots"],"regressions":["Standing hip circles"],"progressions":["Quadruped hip CARs"],"safety":"Stay in a pain-free range and keep the trunk locked.","video":null,"diagram":"","notes":"From Functional Range Conditioning; also done on all fours."},{"id":"inchworm","name":"Inchworm","aliases":["Walkout","Hand walkout"],"training_type":"Mobility","tags":["Calisthenics","Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Hamstrings","Core"],"secondary_muscles":["Shoulders","Chest","Calves"],"movement_pattern":"Mobility","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"6–8","form_cues":["Hinge forward and place hands on the floor, bending knees as needed.","Walk hands out to a plank, keeping hips level.","Walk hands back toward the feet and stand up."],"common_mistakes":["Letting the hips sag in the plank","Walking hands out too far for your strength"],"regressions":["Standing hamstring stretch"],"progressions":["Inchworm with push-up"],"safety":"Bend the knees as much as needed to protect your lower back.","video":null,"diagram":"","notes":"Add a push-up at the plank for a fuller warm-up."},{"id":"kneewall","name":"Knee-to-wall ankle mobilization","aliases":["Ankle dorsiflexion drill","Knee-to-wall test"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Rehab","Unilateral","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Ankle joint","Calves"],"secondary_muscles":["Soleus"],"movement_pattern":"Mobility","equipment":["Wall"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"10–15 / side","form_cues":["Stand facing a wall in a split stance, front toes a few cm away.","Drive the front knee toward the wall over the middle toes.","Keep the heel glued to the floor."],"common_mistakes":["Heel lifting","Knee caving inward"],"regressions":["Ankle circles"],"progressions":["Banded ankle distraction"],"safety":"Move the foot back as you improve; stop with sharp front-of-ankle pain.","video":null,"diagram":"","notes":"Doubles as a dorsiflexion test: aim for about 10 cm toe-to-wall."},{"id":"legswinglat","name":"Lateral leg swing","aliases":["Side-to-side leg swings","Frontal leg swings"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Unilateral","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Adductors","Hip abductors"],"secondary_muscles":["Glutes","Core"],"movement_pattern":"Mobility","equipment":["Wall or support (optional)"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"10–15 / side","form_cues":["Face a wall with both hands on it.","Swing one leg across your body and out to the side.","Keep your hips and chest facing the wall."],"common_mistakes":["Twisting the torso with each swing","Locking the standing knee"],"regressions":["Front-to-back leg swing"],"progressions":["Walking hip opener"],"safety":"Keep swings controlled; ease off if you feel groin pinching.","video":null,"diagram":"","notes":""},{"id":"kneedrop","name":"Lumbar rotations","aliases":["Lying knee drops","Windshield wipers (supine)"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Rehab","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Obliques","Lower back"],"secondary_muscles":["Hip rotators"],"movement_pattern":"Rotation","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"10 / side","form_cues":["Lie on your back with knees bent and feet flat.","Let both knees fall slowly to one side.","Keep shoulders flat and return through the middle."],"common_mistakes":["Lifting the opposite shoulder","Dropping the knees too fast"],"regressions":[],"progressions":["Scorpion stretch"],"safety":"Move within a pain-free range; great gentle option for stiff backs.","video":null,"diagram":"","notes":""},{"id":"openbook","name":"Open book","aliases":["Side-lying thoracic rotation","Open book stretch"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Thoracic spine","Pectorals"],"secondary_muscles":["Obliques"],"movement_pattern":"Rotation","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"8 / side","form_cues":["Lie on your side with knees bent to hip height and arms out front.","Open the top arm across, following it with your eyes.","Keep the knees stacked on the floor."],"common_mistakes":["Knees lifting apart","Forcing the arm to the floor"],"regressions":[],"progressions":["Quadruped thoracic rotation"],"safety":"Squeeze a pillow between knees to keep the lower back still.","video":null,"diagram":"","notes":""},{"id":"quadtrot","name":"Quadruped thoracic rotation","aliases":["Hand-behind-head T-spine rotation","Quadruped T-spine rotation"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Thoracic spine"],"secondary_muscles":["Obliques","Rear deltoids"],"movement_pattern":"Rotation","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"8 / side","form_cues":["Kneel on all fours and sit the hips slightly back.","Place one hand behind your head.","Rotate that elbow down under the body, then up toward the ceiling."],"common_mistakes":["Rotating from the lower back","Shifting hips side to side"],"regressions":["Open book"],"progressions":["World's greatest stretch"],"safety":"Sitting back toward the heels keeps the movement in the upper back.","video":null,"diagram":"","notes":""},{"id":"wristrock","name":"Quadruped wrist rocks","aliases":["Wrist prep rocks","All-fours wrist rocks"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Forearm flexors","Wrist joint"],"secondary_muscles":["Forearm extensors"],"movement_pattern":"Mobility","equipment":["Mat (optional)"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"10 each direction","form_cues":["Kneel on all fours with hands under shoulders.","Rock forward and back over the hands, keeping palms flat.","Repeat with fingers turned out, then with backs of hands down."],"common_mistakes":["Letting palms peel off the floor","Pushing into sharp pain"],"regressions":["Wrist circles"],"progressions":[],"safety":"Shift less body weight onto the hands if wrists are sensitive.","video":null,"diagram":"","notes":"Great before handstands, push-ups and front squats."},{"id":"scorpion","name":"Scorpion stretch","aliases":["Prone scorpion"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Hip flexors","Obliques"],"secondary_muscles":["Thoracic spine","Glutes"],"movement_pattern":"Rotation","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":2,"reps":"6 / side","form_cues":["Lie face down with arms out wide.","Lift one leg and reach the foot toward the opposite hand.","Keep both shoulders as close to the floor as you can."],"common_mistakes":["Shoulders lifting off the floor","Swinging the leg fast"],"regressions":["Lumbar rotations"],"progressions":[],"safety":"Move slowly; skip if you have a disc problem or lower back pain.","video":null,"diagram":"","notes":""},{"id":"shouldercars","name":"Shoulder CARs","aliases":["Shoulder controlled articular rotations"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Rehab","Unilateral","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Rotator cuff","Deltoids"],"secondary_muscles":["Scapular muscles","Core"],"movement_pattern":"Mobility","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"3–5 / side each way","form_cues":["Make a tight fist and brace your whole body.","Raise the arm forward and overhead as far as possible.","Rotate the thumb out and draw the biggest slow circle behind you."],"common_mistakes":["Arching the lower back or twisting to cheat range","Moving too fast"],"regressions":["Arm circles"],"progressions":["Wall slide"],"safety":"Keep everything but the working arm still; skip painful arcs.","video":null,"diagram":"","notes":""},{"id":"spiderlunge","name":"Spiderman lunge","aliases":["Elbow-to-instep lunge","Lunge with elbow drop"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Unilateral","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Hip flexors","Adductors"],"secondary_muscles":["Glutes","Hamstrings"],"movement_pattern":"Mobility","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"5–8 / side","form_cues":["From a push-up position, step one foot outside the same hand.","Sink the hips and reach that elbow toward the instep.","Step back and switch sides."],"common_mistakes":["Hips piking up high","Front heel lifting off the floor"],"regressions":["Kneeling hip flexor stretch"],"progressions":["World's greatest stretch"],"safety":"Keep the back leg long and core braced; stop if the groin pinches.","video":null,"diagram":"","notes":""},{"id":"spinecars","name":"Spinal CARs","aliases":["Spine segmentation","Standing cat-cow roll-down"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Spinal erectors","Abdominals"],"secondary_muscles":["Neck"],"movement_pattern":"Mobility","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":2,"reps":"3–5 each way","form_cues":["Stand tall with knees soft and squeeze your glutes lightly.","Curl down one vertebra at a time, starting at the neck.","Roll back up one segment at a time, then try side bends and rotation."],"common_mistakes":["Bending only at the hips","Rushing so the spine moves as one block"],"regressions":["Lumbar rotations"],"progressions":[],"safety":"Go slowly and avoid if you have an acute disc injury.","video":null,"diagram":"","notes":""},{"id":"hipcircle","name":"Standing hip circles","aliases":["Hip rotations","Hula hoops"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Hip flexors","Lower back"],"secondary_muscles":["Obliques","Glutes"],"movement_pattern":"Mobility","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"10 each way","form_cues":["Stand with hands on hips and feet shoulder-width.","Draw big circles with your hips.","Keep your head and shoulders still."],"common_mistakes":["Moving the whole upper body","Making tiny, rushed circles"],"regressions":[],"progressions":["Hip CARs"],"safety":"Keep the movement pain-free and controlled.","video":null,"diagram":"","notes":""},{"id":"hipgate","name":"Walking hip opener and closer","aliases":["Open the gate","Close the gate","Hip gate swings"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Hip rotators","Adductors"],"secondary_muscles":["Glutes","Hip flexors"],"movement_pattern":"Mobility","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"8 / side each way","form_cues":["Lift one knee high in front of you.","Rotate it out to the side and down (open), or side to front (close).","Stand tall and walk forward between reps."],"common_mistakes":["Leaning the torso to fake range","Rushing the circle"],"regressions":["Standing hip circles"],"progressions":["Hip CARs"],"safety":"Hold a wall for balance if needed; keep the movement smooth.","video":null,"diagram":"","notes":""},{"id":"kneehug","name":"Walking knee hug","aliases":["Knee-to-chest walk","Knee pulls"],"training_type":"Mobility","tags":["Balance","Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Glutes","Hamstrings"],"secondary_muscles":["Hip flexors","Calves"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"8 / side","form_cues":["Step forward and pull one knee to your chest.","Rise onto the toes of the standing foot.","Release and step through to the other side."],"common_mistakes":["Rounding the back to meet the knee","Losing balance from rushing"],"regressions":[],"progressions":["Walking leg cradle"],"safety":"Hold a wall if balance is shaky.","video":null,"diagram":"","notes":""},{"id":"lungetwist","name":"Walking lunge with twist","aliases":["Lunge with rotation","Twisting lunge"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Unilateral","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Quadriceps","Glutes","Obliques"],"secondary_muscles":["Hip flexors","Thoracic spine"],"movement_pattern":"Lunge","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"8 / side","form_cues":["Step forward into a lunge with the front knee over the foot.","Rotate your chest toward the front leg.","Return to centre, then step through to the next lunge."],"common_mistakes":["Front knee caving inward","Twisting from the knee instead of the torso"],"regressions":["Static lunge"],"progressions":["World's greatest stretch"],"safety":"Keep steps short if knees are sore; rotate from the ribs, not the knee.","video":null,"diagram":"","notes":"Hold a light plate or ball at the chest to add load."},{"id":"quadpull","name":"Walking quad pull","aliases":["Walking quad stretch","Heel-to-glute walk"],"training_type":"Mobility","tags":["Balance","Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Quadriceps","Hip flexors"],"secondary_muscles":["Calves"],"movement_pattern":"Gait","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"8 / side","form_cues":["Step forward and grab the opposite ankle behind you.","Pull heel to glute and squeeze that glute.","Reach the free arm overhead for balance."],"common_mistakes":["Arching the lower back","Knee drifting out to the side"],"regressions":["Standing quad stretch"],"progressions":[],"safety":"Keep knees close together and avoid yanking the ankle.","video":null,"diagram":"","notes":""},{"id":"wallangel","name":"Wall angel","aliases":["Wall snow angels"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Rehab","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Lower trapezius","Rhomboids","Thoracic spine"],"secondary_muscles":["Rotator cuff","Pectorals"],"movement_pattern":"Mobility","equipment":["Wall"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"10","form_cues":["Stand with head, upper back and glutes against a wall.","Hold arms in a W with backs of hands on the wall.","Slide arms up and down without anything lifting away."],"common_mistakes":["Lower back arching off the wall","Hands peeling away from the wall"],"regressions":["Floor angel"],"progressions":["Wall slide"],"safety":"Step feet farther out if you can't keep your back flat.","video":null,"diagram":"","notes":""},{"id":"wallslide","name":"Wall slide","aliases":["Scapular wall slide","Wall slides"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Rehab","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Serratus anterior","Lower trapezius"],"secondary_muscles":["Rotator cuff"],"movement_pattern":"Mobility","equipment":["Wall"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"10–12","form_cues":["Put forearms on a wall at shoulder height.","Slide them up, letting shoulder blades wrap around the ribs.","Lower slowly back down."],"common_mistakes":["Shrugging as the arms rise","Arching the lower back"],"regressions":["Wall angel"],"progressions":["Wall slide with band","Foam roller wall slide"],"safety":"Stay below any pinching point in the shoulder.","video":null,"diagram":"","notes":"Add a loop band around the wrists for more rotator cuff work."},{"id":"wgs","name":"World's greatest stretch","aliases":["Lunge with rotation and reach","WGS"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Unilateral","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Hip flexors","Hamstrings","Thoracic spine"],"secondary_muscles":["Adductors","Glutes","Shoulders"],"movement_pattern":"Mobility","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":2,"reps":"5 / side","form_cues":["Step into a long lunge and put both hands inside the front foot.","Drop the inside elbow toward the instep, then rotate that arm to the ceiling.","Finish by straightening the front leg to stretch the hamstring."],"common_mistakes":["Letting the back knee collapse to the floor","Rushing through each position","Rotating from the lower back instead of the upper back"],"regressions":["Spiderman lunge","Kneeling hip flexor stretch"],"progressions":[],"safety":"Move slowly; drop the back knee to the floor if balance is an issue.","video":null,"diagram":"","notes":"One of the best single warm-up drills: hips, hamstrings and upper back in one move."},{"id":"wristcircle","name":"Wrist circles","aliases":["Wrist rotations","Wrist CARs"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Forearms","Wrist joint"],"secondary_muscles":[],"movement_pattern":"Mobility","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":1,"reps":"10 each way","form_cues":["Interlock fingers or make loose fists.","Draw slow, full circles with the wrists.","Keep the forearms still."],"common_mistakes":["Moving the elbows instead of the wrists","Going too fast"],"regressions":[],"progressions":["Quadruped wrist rocks"],"safety":"Keep it pain-free; useful before push-ups, handstands and pressing.","video":null,"diagram":"","notes":""},{"id":"banddisloc","name":"Band shoulder dislocate","aliases":["Band pass-through","Shoulder pass-through"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Pectorals","Anterior deltoids","Rotator cuff"],"secondary_muscles":["Lats","Upper back"],"movement_pattern":"Mobility","equipment":["Resistance band or dowel"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"10–15","form_cues":["Hold a band wide with straight arms in front.","Lift it overhead and behind you in one smooth arc.","Bring it back the same way."],"common_mistakes":["Bending the elbows","Arching the lower back"],"regressions":["Arm circles"],"progressions":["Narrow-grip pass-through"],"safety":"Start with a wide grip and narrow it gradually.","video":null,"diagram":"","notes":"A PVC pipe or broomstick works too."},{"id":"bandankle","name":"Banded ankle distraction","aliases":["Banded ankle mobilization"],"training_type":"Mobility","tags":["Home-friendly","Mobility","Rehab"],"muscle_group":"Mobility","primary_muscles":["Ankle joint","Calves"],"secondary_muscles":["Soleus"],"movement_pattern":"Mobility","equipment":["Heavy resistance band","Low anchor"],"req":"bands","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":2,"reps":"10–15 / side","form_cues":["Loop a band around the front of the ankle, anchored behind you.","Step forward into a half-kneel.","Drive the knee forward over the toes; the band pulls the ankle back."],"common_mistakes":["Band on the foot, not the ankle crease","Heel lifting"],"regressions":["Knee-to-wall ankle mobilization"],"progressions":[],"safety":"Avoid after a recent sprain without clearance.","video":null,"diagram":"","notes":""},{"id":"bandhip","name":"Banded hip distraction","aliases":["Band hip flexor distraction","Banded hip mobilization"],"training_type":"Mobility","tags":["Home-friendly","Mobility"],"muscle_group":"Mobility","primary_muscles":["Hip capsule","Hip flexors"],"secondary_muscles":["Glutes"],"movement_pattern":"Mobility","equipment":["Heavy resistance band","Low anchor"],"req":"bands","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":2,"reps":"60 sec / side","form_cues":["Loop a heavy band around the top of your thigh from a low anchor.","Step away into a kneeling lunge or all-fours position.","Rock gently into the stretch."],"common_mistakes":["Band sliding down to the knee","Not enough tension"],"regressions":["Kneeling hip flexor stretch"],"progressions":[],"safety":"Anchor must be solid; band high in the hip crease.","video":null,"diagram":"","notes":""},{"id":"tke","name":"Terminal knee extension","aliases":["TKE","Banded knee extension"],"training_type":"Mobility","tags":["Home-friendly","Isolation","Mobility","Rehab","Unilateral"],"muscle_group":"Mobility","primary_muscles":["Quadriceps","Vastus medialis"],"secondary_muscles":[],"movement_pattern":"Isolation","equipment":["Resistance band","Low anchor"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"15–20 / side","form_cues":["Loop a band behind your knee from an anchor in front.","Start with the knee slightly bent.","Squeeze the quad to straighten the knee fully."],"common_mistakes":["Leaning the torso forward","Letting the knee snap back"],"regressions":[],"progressions":["Spanish squat"],"safety":"Keep it pain-free; common after knee surgery.","video":null,"diagram":"","notes":""},{"id":"ninetyhold","name":"90/90 hip stretch","aliases":["90-90 stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Glutes","Hip external rotators"],"secondary_muscles":["Hip flexors","Adductors"],"movement_pattern":"Stretch","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30–60 sec / side","form_cues":["Sit in the 90/90 position with both knees at right angles.","Sit tall and hinge your chest over the front shin.","Breathe slowly and relax into it."],"common_mistakes":["Rounding the back instead of hinging","Forcing the knee down"],"regressions":["Supine figure-four stretch"],"progressions":["90/90 hip switch"],"safety":"Prop the hip on a cushion if the knee feels strained.","video":null,"diagram":"","notes":""},{"id":"soleus","name":"Bent-knee soleus stretch","aliases":["Soleus stretch","Bent-knee calf stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Soleus"],"secondary_muscles":["Achilles tendon"],"movement_pattern":"Stretch","equipment":["Wall"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Stand in a short split stance facing a wall.","Bend both knees and sink the back knee toward the floor.","Keep the back heel down."],"common_mistakes":["Heel lifting","Standing too far from the wall"],"regressions":["Wall calf stretch"],"progressions":["Knee-to-wall ankle mobilization"],"safety":"Back off if the Achilles feels sharp rather than stretched.","video":null,"diagram":"","notes":""},{"id":"bretzel","name":"Bretzel stretch","aliases":["Pretzel stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Hip flexors","Quadriceps","Thoracic spine"],"secondary_muscles":["Pectorals","Glutes"],"movement_pattern":"Stretch","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":2,"reps":"45–60 sec / side","form_cues":["Lie on your side, top knee bent at hip height and pinned down.","Grab the bottom foot behind you with your top hand.","Rotate your chest and shoulders toward the floor behind you."],"common_mistakes":["Letting the top knee lift","Holding the breath"],"regressions":["Open book"],"progressions":[],"safety":"Use a strap on the back foot if you can't reach it.","video":null,"diagram":"","notes":""},{"id":"butterfly","name":"Butterfly stretch","aliases":["Seated groin stretch","Seated adductor stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Adductors"],"secondary_muscles":["Hip rotators"],"movement_pattern":"Stretch","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":2,"reps":"30–45 sec","form_cues":["Sit with the soles of your feet together.","Hold your feet and sit tall.","Let the knees drop; hinge forward a little for more."],"common_mistakes":["Bouncing the knees","Rounding the back"],"regressions":[],"progressions":["PNF adductor stretch"],"safety":"Don't push the knees down with force.","video":null,"diagram":"","notes":""},{"id":"couch","name":"Couch stretch","aliases":["Rear-foot elevated hip flexor stretch","Wall quad stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Quadriceps","Hip flexors"],"secondary_muscles":["Rectus femoris"],"movement_pattern":"Stretch","equipment":["Wall or couch","Mat or cushion"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":2,"reps":"60–90 sec / side","form_cues":["Kneel with your back shin up a wall or couch.","Step the other foot forward and squeeze the back glute.","Lift your chest slowly toward upright."],"common_mistakes":["Arching the lower back","Kneeling right on the kneecap without padding"],"regressions":["Kneeling hip flexor stretch"],"progressions":[],"safety":"Pad the knee well and back off if the knee hurts.","video":null,"diagram":"","notes":""},{"id":"crossbody","name":"Cross-body shoulder stretch","aliases":["Posterior shoulder stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Rear deltoids","Rotator cuff"],"secondary_muscles":["Rhomboids"],"movement_pattern":"Stretch","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Bring one straight arm across your chest.","Pull it in at the upper arm with the other hand.","Keep the shoulder down, away from the ear."],"common_mistakes":["Pulling at the elbow joint","Rotating the torso"],"regressions":[],"progressions":["Sleeper stretch"],"safety":"Pull above the elbow, not on the joint.","video":null,"diagram":"","notes":""},{"id":"doorlat","name":"Doorframe lat stretch","aliases":["Standing lat stretch","Door lat hang stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Lats"],"secondary_muscles":["Teres major","Obliques"],"movement_pattern":"Stretch","equipment":["Doorframe or sturdy post"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Grab a doorframe at hip height with one hand.","Sit your hips back and away, letting the side body lengthen.","Rotate slightly to find the tightest spot."],"common_mistakes":["Rounding through the shoulders only","Holding the breath"],"regressions":["Standing overhead side stretch"],"progressions":["Bench lat stretch"],"safety":"Make sure the post you hold is solid.","video":null,"diagram":"","notes":""},{"id":"doorway","name":"Doorway chest stretch","aliases":["Doorframe pec stretch","Corner stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Pectorals"],"secondary_muscles":["Anterior deltoids","Biceps"],"movement_pattern":"Stretch","equipment":["Doorframe"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Place your forearm on a doorframe with elbow at shoulder height.","Step through with the same-side leg.","Turn your chest slightly away until you feel the chest open."],"common_mistakes":["Shrugging the shoulder up","Elbow far above the shoulder"],"regressions":[],"progressions":["PNF chest stretch"],"safety":"Keep the elbow at or below shoulder height to protect the shoulder joint.","video":null,"diagram":"","notes":"Raise the elbow higher to bias the lower pec."},{"id":"hipflexor","name":"Kneeling hip flexor stretch","aliases":["Half-kneeling hip flexor stretch","Lunge stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Hip flexors","Psoas"],"secondary_muscles":["Quadriceps"],"movement_pattern":"Stretch","equipment":["Mat or cushion"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30–45 sec / side","form_cues":["Kneel on one knee with the other foot forward.","Tuck your pelvis and squeeze the back glute.","Shift your weight forward until you feel the front of the hip."],"common_mistakes":["Arching the lower back","Lunging far without tucking the pelvis"],"regressions":["Standing hip flexor stretch"],"progressions":["Couch stretch"],"safety":"Pad the knee; you should feel it in the hip, not the lower back.","video":null,"diagram":"","notes":"Reach the same-side arm overhead for a stronger stretch."},{"id":"shinstretch","name":"Kneeling shin stretch","aliases":["Tibialis stretch","Anterior shin stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Tibialis anterior"],"secondary_muscles":["Ankle"],"movement_pattern":"Stretch","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":2,"reps":"30 sec","form_cues":["Kneel with the tops of your feet flat on the floor.","Sit back toward your heels.","Lift the knees slightly for more stretch."],"common_mistakes":["Sitting back on painful knees","Toes curling under"],"regressions":["Standing shin stretch"],"progressions":[],"safety":"Use a cushion under the knees; skip if kneeling hurts.","video":null,"diagram":"","notes":"Useful for shin splints."},{"id":"levator","name":"Levator scapulae stretch","aliases":["Armpit-sniff stretch"],"training_type":"Stretching","tags":["Home-friendly","Recovery","Stretching"],"muscle_group":"Mobility","primary_muscles":["Levator scapulae"],"secondary_muscles":["Upper trapezius"],"movement_pattern":"Stretch","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Turn your nose toward your armpit.","Gently pull your head down with the same-side hand.","Hold the opposite shoulder down."],"common_mistakes":["Pulling too hard","Rounding the whole upper back"],"regressions":["Upper trap stretch"],"progressions":[],"safety":"Keep pressure gentle; neck stretches should never feel sharp.","video":null,"diagram":"","notes":""},{"id":"tristretch","name":"Overhead triceps stretch","aliases":["Triceps stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Triceps"],"secondary_muscles":["Lats"],"movement_pattern":"Stretch","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Raise one arm and bend the elbow so your hand drops behind your head.","Use the other hand to ease the elbow back.","Keep your ribs down."],"common_mistakes":["Arching the lower back","Pulling the head forward"],"regressions":[],"progressions":[],"safety":"Ease off if you feel pinching at the top of the shoulder.","video":null,"diagram":"","notes":""},{"id":"pnfadd","name":"PNF adductor stretch","aliases":["Contract-relax butterfly"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Adductors"],"secondary_muscles":["Hip rotators"],"movement_pattern":"Stretch","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":2,"reps":"3 cycles","form_cues":["Sit in a butterfly with hands on the inner knees.","Press knees up into your hands for 6 seconds.","Relax and let the knees fall a little lower."],"common_mistakes":["Forcing the knees down","Holding the breath"],"regressions":["Butterfly stretch"],"progressions":[],"safety":"Gentle hand pressure only; never push through groin pain.","video":null,"diagram":"","notes":""},{"id":"pnfchest","name":"PNF chest stretch","aliases":["Contract-relax pec stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Pectorals"],"secondary_muscles":["Anterior deltoids"],"movement_pattern":"Stretch","equipment":["Doorframe or partner"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":2,"reps":"3 cycles / side","form_cues":["Set up in the doorway chest stretch.","Press the forearm into the frame for 6 seconds.","Relax, step through a little deeper and hold."],"common_mistakes":["Shrugging during the push","Going deeper too fast"],"regressions":["Doorway chest stretch"],"progressions":[],"safety":"Keep the elbow at or below shoulder height.","video":null,"diagram":"","notes":""},{"id":"pnfham","name":"PNF hamstring stretch","aliases":["Contract-relax hamstring stretch","Partner hamstring stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Hamstrings"],"secondary_muscles":["Calves"],"movement_pattern":"Stretch","equipment":["Partner, strap or towel"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"count","unilateral":true,"sets":2,"reps":"3 cycles / side","form_cues":["Lie down with one leg raised; a partner or strap holds it at a stretch.","Push the leg down into resistance for 6 seconds.","Relax, breathe out and ease the leg higher; repeat."],"common_mistakes":["Pushing at full force","Partner forcing the leg past comfort"],"regressions":["Strap hamstring stretch"],"progressions":[],"safety":"Contract at moderate effort; communicate clearly with your partner.","video":null,"diagram":"","notes":"Proprioceptive neuromuscular facilitation: contract 6 sec, relax, then stretch 20–30 sec."},{"id":"plantar","name":"Seated plantar fascia stretch","aliases":["Toe stretch","Foot arch stretch"],"training_type":"Stretching","tags":["Home-friendly","Rehab","Stretching"],"muscle_group":"Mobility","primary_muscles":["Plantar fascia"],"secondary_muscles":["Foot intrinsics"],"movement_pattern":"Stretch","equipment":["Chair"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":3,"reps":"20–30 sec / side","form_cues":["Sit and cross one foot over the other knee.","Pull your toes back toward your shin.","Feel along the arch with the other thumb."],"common_mistakes":["Pulling the ankle instead of the toes","Rushing it"],"regressions":[],"progressions":["Massage ball foot roll"],"safety":"Great first thing in the morning for plantar fasciitis.","video":null,"diagram":"","notes":""},{"id":"seatedham","name":"Seated single-leg hamstring stretch","aliases":["Seated hamstring stretch","Hurdler stretch (modified)"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Hamstrings"],"secondary_muscles":["Lower back","Calves"],"movement_pattern":"Stretch","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Sit with one leg straight and the other foot against the inner thigh.","Hinge forward from the hips toward the straight leg's foot.","Keep your chest long rather than curling down."],"common_mistakes":["Rounding the back","Bouncing"],"regressions":["Standing hamstring stretch"],"progressions":["PNF hamstring stretch"],"safety":"Sit on a cushion if your lower back rounds a lot.","video":null,"diagram":"","notes":""}]$ex$::jsonb)
  as r(id text, name text, aliases text[], training_type text, tags text[], muscle_group text, primary_muscles text[], secondary_muscles text[], movement_pattern text, equipment text[], req text, equipment_tier smallint, difficulty text, tracking text, unilateral boolean, sets smallint, reps text, form_cues text[], common_mistakes text[], regressions text[], progressions text[], safety text, video text, diagram text, notes text)
