insert into public.exercises (id, name, aliases, training_type, tags, muscle_group, primary_muscles, secondary_muscles, movement_pattern, equipment, req, equipment_tier, difficulty, tracking, unilateral, sets, reps, form_cues, common_mistakes, regressions, progressions, safety, video, diagram, notes)
select id, name, aliases, training_type, tags, muscle_group, primary_muscles, secondary_muscles, movement_pattern, equipment, req, equipment_tier, difficulty, tracking, unilateral, sets, reps, form_cues, common_mistakes, regressions, progressions, safety, video, diagram, notes from jsonb_to_recordset($ex$[{"id":"sidelungestretch","name":"Side lunge adductor stretch","aliases":["Standing groin stretch","Lateral lunge stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Adductors"],"secondary_muscles":["Hamstrings"],"movement_pattern":"Stretch","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Stand with feet wide.","Shift into one bent knee, keeping the other leg straight.","Keep both feet flat and chest up."],"common_mistakes":["Bent knee caving inward","Straight-leg foot rolling onto its edge"],"regressions":["Butterfly stretch"],"progressions":["Adductor rock-back"],"safety":"Keep the bent knee tracking over the toes.","video":null,"diagram":"","notes":""},{"id":"sleeper","name":"Sleeper stretch","aliases":["Side-lying internal rotation stretch"],"training_type":"Stretching","tags":["Home-friendly","Rehab","Stretching"],"muscle_group":"Mobility","primary_muscles":["Posterior rotator cuff","Posterior shoulder capsule"],"secondary_muscles":["Rear deltoids"],"movement_pattern":"Stretch","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Lie on your side with the bottom arm out at 90°, elbow bent.","Use the top hand to press the forearm gently toward the floor.","Roll back slightly to ease pressure on the shoulder."],"common_mistakes":["Pushing hard into pain","Lying directly on the point of the shoulder"],"regressions":["Cross-body shoulder stretch"],"progressions":[],"safety":"Very gentle pressure only; stop with any sharp front-of-shoulder pain.","video":null,"diagram":"","notes":"Popular with throwers and racquet-sport players."},{"id":"standham","name":"Standing hamstring stretch","aliases":["Heel-on-step hamstring stretch","Elevated hamstring stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Hamstrings"],"secondary_muscles":["Calves"],"movement_pattern":"Stretch","equipment":["Low step or chair (optional)"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Put one heel on a low step with the leg straight.","Keep your back flat and hinge forward from the hips.","Point the toes up for more stretch."],"common_mistakes":["Rounding the back to reach down","Locking the knee hard"],"regressions":["Seated hamstring stretch"],"progressions":["Strap hamstring stretch"],"safety":"Use a lower step if you feel it behind the knee rather than the thigh.","video":null,"diagram":"","notes":""},{"id":"itband","name":"Standing IT band stretch","aliases":["Cross-leg side stretch","Standing TFL stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Tensor fasciae latae","Gluteus medius"],"secondary_muscles":["Obliques"],"movement_pattern":"Stretch","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Cross one leg behind the other.","Push the hip of the back leg out to the side.","Reach the same arm overhead and lean away."],"common_mistakes":["Bending forward","Bending the back knee"],"regressions":[],"progressions":["Foam roll IT band"],"safety":"Hold a wall for balance.","video":null,"diagram":"","notes":"The IT band itself barely stretches; this mainly targets the TFL and glute."},{"id":"standquad","name":"Standing quad stretch","aliases":["Standing quadriceps stretch"],"training_type":"Stretching","tags":["Balance","Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Quadriceps"],"secondary_muscles":["Hip flexors"],"movement_pattern":"Stretch","equipment":["Wall or support (optional)"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Stand tall and grab one ankle behind you.","Pull the heel toward your glute, knees together.","Tuck your pelvis gently to feel more in the hip."],"common_mistakes":["Arching the back","Knee flaring out to the side"],"regressions":["Side-lying quad stretch"],"progressions":["Couch stretch"],"safety":"Hold a wall for balance; don't yank the ankle.","video":null,"diagram":"","notes":""},{"id":"figure4","name":"Supine figure-four stretch","aliases":["Lying piriformis stretch","Figure-4 glute stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Glutes","Piriformis"],"secondary_muscles":["Hip external rotators"],"movement_pattern":"Stretch","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30–45 sec / side","form_cues":["Lie on your back and cross one ankle over the other knee.","Pull the bottom thigh toward your chest.","Gently push the crossed knee away to deepen it."],"common_mistakes":["Lifting the head and shoulders","Letting the ankle sickle"],"regressions":["Seated figure-four stretch"],"progressions":["90/90 hip stretch"],"safety":"Flex the crossed foot to protect the knee.","video":null,"diagram":"","notes":""},{"id":"towelir","name":"Towel internal rotation stretch","aliases":["Behind-back towel stretch","Towel shoulder stretch"],"training_type":"Stretching","tags":["Home-friendly","Rehab","Stretching"],"muscle_group":"Mobility","primary_muscles":["Rotator cuff","Posterior shoulder"],"secondary_muscles":["Triceps"],"movement_pattern":"Stretch","equipment":["Towel"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"20–30 sec / side","form_cues":["Hold a towel overhead with one hand and behind your back with the other.","Pull up with the top hand to raise the lower hand.","Keep shoulders relaxed."],"common_mistakes":["Yanking the towel","Arching the back"],"regressions":["Sleeper stretch"],"progressions":[],"safety":"Gentle pull only; common in shoulder rehab programmes.","video":null,"diagram":"","notes":""},{"id":"traps","name":"Upper trap stretch","aliases":["Lateral neck stretch","Side neck stretch"],"training_type":"Stretching","tags":["Home-friendly","Recovery","Stretching"],"muscle_group":"Mobility","primary_muscles":["Upper trapezius"],"secondary_muscles":["Scalenes"],"movement_pattern":"Stretch","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Sit tall and hold the chair with one hand.","Tilt your ear toward the opposite shoulder.","Rest the other hand on your head for light extra pull."],"common_mistakes":["Pulling hard on the head","Letting the shoulder rise"],"regressions":["Neck half circles"],"progressions":[],"safety":"Use only light hand pressure; stop with tingling in the arm.","video":null,"diagram":"","notes":""},{"id":"calfwall","name":"Wall calf stretch","aliases":["Gastrocnemius stretch","Standing calf stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Gastrocnemius"],"secondary_muscles":["Achilles tendon"],"movement_pattern":"Stretch","equipment":["Wall"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Put your hands on a wall with one leg back and straight.","Press the back heel down, toes pointing forward.","Lean your hips toward the wall."],"common_mistakes":["Back heel lifting","Back foot turned out"],"regressions":[],"progressions":["Bent-knee soleus stretch"],"safety":"Ease in gradually if you have Achilles pain.","video":null,"diagram":"","notes":""},{"id":"wristext","name":"Wrist extensor stretch","aliases":["Forearm extensor stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Forearm extensors"],"secondary_muscles":["Wrist"],"movement_pattern":"Stretch","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Hold one arm out straight, palm down.","Gently press the back of the hand toward you.","Keep the elbow straight."],"common_mistakes":["Bending the elbow","Pushing too hard"],"regressions":[],"progressions":["Quadruped wrist rocks"],"safety":"Helpful for tennis-elbow type tightness; keep it gentle.","video":null,"diagram":"","notes":""},{"id":"wristflex","name":"Wrist flexor stretch","aliases":["Forearm flexor stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Forearm flexors"],"secondary_muscles":["Wrist"],"movement_pattern":"Stretch","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Hold one arm out straight, palm up.","Gently pull the fingers back with the other hand.","Keep the elbow straight."],"common_mistakes":["Bending the elbow","Forcing it through tingling"],"regressions":[],"progressions":["Quadruped wrist rocks"],"safety":"Stop with numbness or tingling in the fingers.","video":null,"diagram":"","notes":""},{"id":"bandlat","name":"Banded lat stretch","aliases":["Band overhead lat distraction"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Lats"],"secondary_muscles":["Teres major","Triceps"],"movement_pattern":"Stretch","equipment":["Resistance band","High anchor"],"req":"bands","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30–60 sec / side","form_cues":["Loop a band around a high anchor and your wrist.","Step back and sit your hips back.","Let the band pull your arm overhead and to the side."],"common_mistakes":["Shrugging up","Rounding through the lower back"],"regressions":["Doorframe lat stretch"],"progressions":[],"safety":"Use a secure anchor; check the band for tears.","video":null,"diagram":"","notes":""},{"id":"stabtspine","name":"Stability ball back stretch","aliases":["Ball thoracic extension","Swiss ball back extension stretch"],"training_type":"Stretching","tags":["Home-friendly","Recovery","Stretching"],"muscle_group":"Mobility","primary_muscles":["Thoracic spine","Abdominals","Pectorals"],"secondary_muscles":["Hip flexors"],"movement_pattern":"Stretch","equipment":["Stability ball"],"req":"stabball","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":2,"reps":"30–45 sec","form_cues":["Sit on a stability ball and walk your feet forward.","Lie back so the ball supports your upper and mid back.","Reach your arms overhead and relax."],"common_mistakes":["Letting the head drop unsupported","Feet too close together"],"regressions":["Foam roll thoracic spine"],"progressions":[],"safety":"Keep feet wide for balance; avoid if you get dizzy.","video":null,"diagram":"","notes":""},{"id":"strapadd","name":"Strap adductor stretch","aliases":["Lying strap groin stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Adductors"],"secondary_muscles":["Hamstrings"],"movement_pattern":"Stretch","equipment":["Stretching strap"],"req":"stretchstrap","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Lie on your back with a strap on one foot, leg straight up.","Lower the leg out to the side.","Keep the opposite hip pinned down."],"common_mistakes":["Rolling the pelvis over","Bending the knee"],"regressions":["Butterfly stretch"],"progressions":[],"safety":"Lower only as far as your hips stay level.","video":null,"diagram":"","notes":""},{"id":"hamstretch","name":"Strap hamstring stretch","aliases":["Lying hamstring stretch","Supine hamstring stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Hamstrings"],"secondary_muscles":["Calves"],"movement_pattern":"Stretch","equipment":["Stretching strap or towel"],"req":"stretchstrap","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30–45 sec / side","form_cues":["Lie on your back with a strap around one foot.","Raise the straight leg until you feel a stretch.","Keep the other leg flat on the floor."],"common_mistakes":["Bending the raised knee a lot","Lifting the hips"],"regressions":["Standing hamstring stretch"],"progressions":["PNF hamstring stretch"],"safety":"Use a towel if you don't have a strap.","video":null,"diagram":"","notes":""},{"id":"strapquad","name":"Strap prone quad stretch","aliases":["Lying strap quad stretch"],"training_type":"Stretching","tags":["Home-friendly","Stretching"],"muscle_group":"Mobility","primary_muscles":["Quadriceps"],"secondary_muscles":["Hip flexors"],"movement_pattern":"Stretch","equipment":["Stretching strap or towel"],"req":"stretchstrap","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Lie face down with a strap looped around one ankle.","Pull the heel toward your glute.","Press the hip into the floor."],"common_mistakes":["Arching the back","Knee drifting outward"],"regressions":["Side-lying quad stretch"],"progressions":["Couch stretch"],"safety":"Ease the strap in slowly.","video":null,"diagram":"","notes":""},{"id":"benchlat","name":"Bench lat stretch","aliases":["Kneeling bench lat stretch","Elbows-on-bench T-spine stretch"],"training_type":"Stretching","tags":["Stretching"],"muscle_group":"Mobility","primary_muscles":["Lats","Thoracic spine"],"secondary_muscles":["Triceps","Pectorals"],"movement_pattern":"Stretch","equipment":["Bench","Dowel (optional)"],"req":"flatbench|adjbench","equipment_tier":2,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":2,"reps":"30–60 sec","form_cues":["Kneel facing a bench with elbows on the edge.","Bend the elbows so your hands meet behind your head (or hold a dowel).","Sit hips back and let the chest sink."],"common_mistakes":["Arching the lower back","Shrugging"],"regressions":["Doorframe lat stretch"],"progressions":[],"safety":"Keep ribs down; stop with shoulder pinching.","video":null,"diagram":"","notes":"Great prep for overhead squats and presses."},{"id":"breath9090","name":"90/90 breathing","aliases":["Crocodile breathing (90/90)","Supine diaphragmatic breathing"],"training_type":"Recovery","tags":["Home-friendly","Recovery"],"muscle_group":"Mobility","primary_muscles":["Diaphragm"],"secondary_muscles":["Core","Pelvic floor"],"movement_pattern":"Hold","equipment":["Wall or chair"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"time","unilateral":false,"sets":1,"reps":"3–5 min","form_cues":["Lie on your back with feet on a wall, hips and knees at 90°.","Breathe in through the nose into the ribs and belly.","Exhale fully through the mouth and pause."],"common_mistakes":["Breathing only into the chest","Arching the lower back"],"regressions":[],"progressions":[],"safety":"Very safe; a good post-workout cool-down to calm the nervous system.","video":null,"diagram":"","notes":""},{"id":"chintuck","name":"Chin tucks","aliases":["Neck retractions","Cervical retraction"],"training_type":"Recovery","tags":["Home-friendly","Recovery","Rehab"],"muscle_group":"Mobility","primary_muscles":["Deep neck flexors"],"secondary_muscles":["Upper back"],"movement_pattern":"Mobility","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"10","form_cues":["Sit or stand tall looking straight ahead.","Slide your chin straight back to make a double chin.","Hold 2–3 seconds and relax."],"common_mistakes":["Tipping the head down instead of sliding back","Straining the jaw"],"regressions":[],"progressions":["Supine chin tuck with head lift"],"safety":"Stop if you get dizziness or arm symptoms.","video":null,"diagram":"","notes":"Good counter to 'tech neck' posture."},{"id":"eccheel","name":"Eccentric heel drop","aliases":["Alfredson heel drop","Eccentric calf lowering"],"training_type":"Recovery","tags":["Home-friendly","Recovery","Rehab","Unilateral"],"muscle_group":"Mobility","primary_muscles":["Gastrocnemius","Soleus","Achilles tendon"],"secondary_muscles":[],"movement_pattern":"Isolation","equipment":["Step"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":3,"reps":"15 / side","form_cues":["Stand on a step and rise up on both feet.","Shift onto one foot and lower the heel slowly below the step.","Use both feet to come back up."],"common_mistakes":["Dropping fast instead of lowering slowly","Bouncing at the bottom"],"regressions":["Two-leg heel drop"],"progressions":["Weighted eccentric heel drop"],"safety":"Mild tendon discomfort is common; stop if pain is sharp or worsening.","video":null,"diagram":"","notes":"Classic Achilles tendinopathy protocol; do with straight and bent knee."},{"id":"mckenzie","name":"Prone press-up","aliases":["McKenzie press-up","Prone extension"],"training_type":"Recovery","tags":["Home-friendly","Recovery","Rehab"],"muscle_group":"Mobility","primary_muscles":["Lumbar spine"],"secondary_muscles":["Abdominals"],"movement_pattern":"Extension","equipment":["Mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"10","form_cues":["Lie face down with hands under your shoulders.","Press your chest up, letting the hips and belly stay on the floor.","Relax your lower back and lower slowly."],"common_mistakes":["Squeezing the glutes and lifting the hips","Going into painful range"],"regressions":["Prone on elbows"],"progressions":[],"safety":"Stop if leg pain spreads further down; see a professional for disc issues.","video":null,"diagram":"","notes":"Part of the McKenzie method for some back pain types."},{"id":"sciatic","name":"Sciatic nerve floss","aliases":["Seated nerve glide","Slump nerve glide"],"training_type":"Recovery","tags":["Home-friendly","Recovery","Rehab"],"muscle_group":"Mobility","primary_muscles":["Sciatic nerve"],"secondary_muscles":["Hamstrings"],"movement_pattern":"Mobility","equipment":["Chair"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"10–15 / side","form_cues":["Sit tall at the edge of a chair.","Straighten one knee while you look up.","Bend the knee as you look down; keep it smooth."],"common_mistakes":["Holding at end range like a stretch","Moving into tingling"],"regressions":[],"progressions":[],"safety":"Should feel mild; stop if symptoms increase or linger.","video":null,"diagram":"","notes":"Nerves like movement, not long holds."},{"id":"shortfoot","name":"Short foot exercise","aliases":["Foot doming","Arch lifts"],"training_type":"Recovery","tags":["Balance","Home-friendly","Recovery","Rehab"],"muscle_group":"Mobility","primary_muscles":["Foot intrinsics"],"secondary_muscles":["Tibialis posterior"],"movement_pattern":"Isolation","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"10 × 5 sec / side","form_cues":["Sit or stand with the foot flat.","Draw the ball of the foot toward the heel to lift the arch.","Keep the toes long and relaxed."],"common_mistakes":["Curling the toes","Rolling the foot outward"],"regressions":[],"progressions":["Single-leg balance with short foot"],"safety":"Gentle and safe; useful for flat feet and plantar pain.","video":null,"diagram":"","notes":""},{"id":"frcalf","name":"Foam roll calves","aliases":["Calf roll"],"training_type":"Recovery","tags":["Home-friendly","Recovery"],"muscle_group":"Mobility","primary_muscles":["Gastrocnemius","Soleus"],"secondary_muscles":[],"movement_pattern":"Mobility","equipment":["Foam roller"],"req":"foamroller","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":1,"reps":"60 sec / side","form_cues":["Sit with the roller under your calves.","Lift your hips and roll from ankle to knee.","Turn the foot in and out to hit each side."],"common_mistakes":["Rolling over the Achilles hard","Going too fast"],"regressions":[],"progressions":["Massage ball calf release"],"safety":"Stack one leg on top for more pressure.","video":null,"diagram":"","notes":""},{"id":"frpec","name":"Foam roll chest","aliases":["Pec roll"],"training_type":"Recovery","tags":["Home-friendly","Recovery"],"muscle_group":"Mobility","primary_muscles":["Pectorals"],"secondary_muscles":["Anterior deltoids"],"movement_pattern":"Mobility","equipment":["Foam roller"],"req":"foamroller","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":1,"reps":"45–60 sec / side","form_cues":["Lie face down with the roller at an angle under one side of the chest.","Extend that arm out to the side.","Roll slowly from the breastbone toward the shoulder."],"common_mistakes":["Rolling over the collarbone","Too much body weight"],"regressions":[],"progressions":["Massage ball pec release"],"safety":"Light pressure; avoid the front of the shoulder joint.","video":null,"diagram":"","notes":""},{"id":"frglute","name":"Foam roll glutes","aliases":["Glute roll","Piriformis roll"],"training_type":"Recovery","tags":["Home-friendly","Recovery"],"muscle_group":"Mobility","primary_muscles":["Glutes","Piriformis"],"secondary_muscles":[],"movement_pattern":"Mobility","equipment":["Foam roller"],"req":"foamroller","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":1,"reps":"60 sec / side","form_cues":["Sit on the roller and cross one ankle over the other knee.","Lean toward the crossed-leg side.","Roll slowly over the glute."],"common_mistakes":["Rolling onto the lower back","Rolling fast"],"regressions":[],"progressions":["Massage ball glute release"],"safety":"Stay on the meaty glute area, away from the tailbone.","video":null,"diagram":"","notes":""},{"id":"frham","name":"Foam roll hamstrings","aliases":["Hamstring roll"],"training_type":"Recovery","tags":["Home-friendly","Recovery"],"muscle_group":"Mobility","primary_muscles":["Hamstrings"],"secondary_muscles":[],"movement_pattern":"Mobility","equipment":["Foam roller"],"req":"foamroller","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":1,"reps":"60 sec / side","form_cues":["Sit with the roller under your thighs and hands behind you.","Lift your hips and roll from knee to glute.","Cross one leg over the other for more pressure."],"common_mistakes":["Rolling behind the knee","Rushing"],"regressions":[],"progressions":[],"safety":"Avoid the back of the knee.","video":null,"diagram":"","notes":""},{"id":"fritb","name":"Foam roll IT band","aliases":["Lateral thigh roll","IT band roll"],"training_type":"Recovery","tags":["Home-friendly","Recovery"],"muscle_group":"Mobility","primary_muscles":["Tensor fasciae latae","Vastus lateralis"],"secondary_muscles":["IT band"],"movement_pattern":"Mobility","equipment":["Foam roller"],"req":"foamroller","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":1,"reps":"45–60 sec / side","form_cues":["Lie on your side with the roller under the outer thigh.","Use the top leg and hands to control pressure.","Roll from hip to just above the knee."],"common_mistakes":["Putting full body weight on it","Rolling over the hip bone"],"regressions":[],"progressions":[],"safety":"This area is sensitive; reduce pressure with the top foot.","video":null,"diagram":"","notes":""},{"id":"frlat","name":"Foam roll lats","aliases":["Lat roll"],"training_type":"Recovery","tags":["Home-friendly","Recovery"],"muscle_group":"Mobility","primary_muscles":["Lats"],"secondary_muscles":["Teres major"],"movement_pattern":"Mobility","equipment":["Foam roller"],"req":"foamroller","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":1,"reps":"60 sec / side","form_cues":["Lie on your side with the roller under your armpit, arm overhead.","Roll down toward the bottom of the ribs.","Rotate slightly forward and back."],"common_mistakes":["Rolling over the shoulder joint","Rolling onto the ribs too hard"],"regressions":[],"progressions":[],"safety":"Keep the head supported on the arm.","video":null,"diagram":"","notes":""},{"id":"foamroll","name":"Foam roll legs and back","aliases":["Foam rolling","Self-myofascial release"],"training_type":"Recovery","tags":["Home-friendly","Recovery","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Quadriceps","Hamstrings","Calves","Upper back"],"secondary_muscles":["Glutes"],"movement_pattern":"Mobility","equipment":["Foam roller"],"req":"foamroller","equipment_tier":1,"difficulty":"Beginner","tracking":"time","unilateral":false,"sets":1,"reps":"5–10 min","form_cues":["Roll slowly, about 2–3 cm per second.","Pause 20–30 seconds on tender spots and breathe.","Spend 30–60 seconds on each area."],"common_mistakes":["Rolling too fast","Rolling directly on joints or the lower back"],"regressions":[],"progressions":[],"safety":"Avoid bony areas, the lower back and the neck.","video":null,"diagram":"","notes":"General routine; see individual entries for each area."},{"id":"frquad","name":"Foam roll quads","aliases":["Quad roll"],"training_type":"Recovery","tags":["Home-friendly","Recovery","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Quadriceps"],"secondary_muscles":["Hip flexors"],"movement_pattern":"Mobility","equipment":["Foam roller"],"req":"foamroller","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":1,"reps":"60 sec / side","form_cues":["Lie face down with the roller under your thighs.","Roll from just above the knee to the hip.","Turn slightly in and out to hit inner and outer quads."],"common_mistakes":["Sagging the hips","Rolling over the kneecap"],"regressions":[],"progressions":["Single-leg quad roll"],"safety":"Keep your core braced to protect the lower back.","video":null,"diagram":"","notes":""},{"id":"frtspine","name":"Foam roll thoracic spine","aliases":["Upper back roll","Foam roller thoracic extension"],"training_type":"Recovery","tags":["Home-friendly","Recovery","Warm-up"],"muscle_group":"Mobility","primary_muscles":["Thoracic spine","Rhomboids"],"secondary_muscles":["Spinal erectors"],"movement_pattern":"Extension","equipment":["Foam roller"],"req":"foamroller","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"10 reps + 60 sec roll","form_cues":["Lie with the roller under your upper back, hands behind your head.","Roll from mid-back to the shoulder blades.","Pause and gently extend over the roller at stiff spots."],"common_mistakes":["Rolling onto the lower back","Flaring ribs and arching from the lower back"],"regressions":[],"progressions":["Peanut thoracic extension"],"safety":"Never roll the lumbar spine; support your head.","video":null,"diagram":"","notes":""},{"id":"ballfoot","name":"Massage ball foot roll","aliases":["Plantar fascia ball roll","Foot ball release"],"training_type":"Recovery","tags":["Home-friendly","Recovery","Rehab"],"muscle_group":"Mobility","primary_muscles":["Plantar fascia"],"secondary_muscles":["Foot intrinsics"],"movement_pattern":"Mobility","equipment":["Massage or lacrosse ball"],"req":"massageball","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":1,"reps":"60–90 sec / side","form_cues":["Stand or sit with the ball under one foot.","Roll from heel to toes with steady pressure.","Pause on tender spots."],"common_mistakes":["Standing with full weight straight away","Rolling the heel bone hard"],"regressions":["Seated plantar fascia stretch"],"progressions":[],"safety":"A frozen water bottle works for sore arches.","video":null,"diagram":"","notes":""},{"id":"ballforearm","name":"Massage ball forearm release","aliases":["Lacrosse ball forearm roll"],"training_type":"Recovery","tags":["Home-friendly","Recovery"],"muscle_group":"Mobility","primary_muscles":["Forearm flexors","Forearm extensors"],"secondary_muscles":[],"movement_pattern":"Mobility","equipment":["Massage or lacrosse ball"],"req":"massageball","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":1,"reps":"60 sec / side","form_cues":["Place the ball on a table under your forearm.","Press down with the other hand.","Open and close your fist as you roll."],"common_mistakes":["Rolling over the elbow joint","Pressing too hard"],"regressions":["Wrist flexor stretch"],"progressions":[],"safety":"Good for climbers, lifters with grippy forearms and desk workers.","video":null,"diagram":"","notes":""},{"id":"ballrelease","name":"Massage ball glute release","aliases":["Lacrosse ball glute release","Piriformis ball release"],"training_type":"Recovery","tags":["Home-friendly","Recovery"],"muscle_group":"Mobility","primary_muscles":["Glutes","Piriformis"],"secondary_muscles":[],"movement_pattern":"Mobility","equipment":["Massage or lacrosse ball"],"req":"massageball","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":1,"reps":"60–90 sec / side","form_cues":["Sit or lie with the ball under one glute.","Find a tender spot and let your weight sink in.","Breathe and make small circles."],"common_mistakes":["Rolling on the sciatic nerve with sharp, shooting pain","Going too hard"],"regressions":["Foam roll glutes"],"progressions":[],"safety":"Move off any spot that causes numbness or shooting pain.","video":null,"diagram":"","notes":"Do it against a wall for less pressure."},{"id":"ballpec","name":"Massage ball pec release","aliases":["Lacrosse ball chest release"],"training_type":"Recovery","tags":["Home-friendly","Recovery"],"muscle_group":"Mobility","primary_muscles":["Pectorals","Pec minor"],"secondary_muscles":["Anterior deltoids"],"movement_pattern":"Mobility","equipment":["Massage or lacrosse ball"],"req":"massageball","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":1,"reps":"60 sec / side","form_cues":["Stand facing a wall with the ball under your chest, just inside the shoulder.","Lean in to apply pressure.","Slowly move the arm up and down."],"common_mistakes":["Pressing on the collarbone or armpit nerves","Too much pressure"],"regressions":["Foam roll chest"],"progressions":[],"safety":"Stay on soft tissue; stop with tingling down the arm.","video":null,"diagram":"","notes":""},{"id":"balltfl","name":"Massage ball TFL release","aliases":["Hip flexor ball release","Lacrosse ball TFL"],"training_type":"Recovery","tags":["Home-friendly","Recovery"],"muscle_group":"Mobility","primary_muscles":["Tensor fasciae latae","Hip flexors"],"secondary_muscles":[],"movement_pattern":"Mobility","equipment":["Massage or lacrosse ball"],"req":"massageball","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":1,"reps":"60 sec / side","form_cues":["Lie face down with the ball just in front of and below the hip bone.","Let your weight sink in.","Bend and straighten the knee slowly."],"common_mistakes":["Pressing on the hip bone","Lying on it with full weight from the start"],"regressions":["Foam roll IT band"],"progressions":[],"safety":"Avoid the groin area and front-of-hip nerves.","video":null,"diagram":"","notes":""},{"id":"balltrap","name":"Massage ball upper back release","aliases":["Lacrosse ball trap release","Shoulder blade ball release"],"training_type":"Recovery","tags":["Home-friendly","Recovery"],"muscle_group":"Mobility","primary_muscles":["Rhomboids","Upper trapezius"],"secondary_muscles":["Rotator cuff"],"movement_pattern":"Mobility","equipment":["Massage or lacrosse ball"],"req":"massageball","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":1,"reps":"60 sec / side","form_cues":["Stand against a wall or lie with the ball between spine and shoulder blade.","Lean into the ball at a tender spot.","Cross the arm over your chest to open the area."],"common_mistakes":["Putting the ball on the spine","Rolling onto the neck"],"regressions":["Foam roll thoracic spine"],"progressions":[],"safety":"Keep the ball off the spine and the neck.","video":null,"diagram":"","notes":""},{"id":"chairpose","name":"Chair pose","aliases":["Utkatasana","Fierce pose","Awkward pose"],"training_type":"Yoga","tags":["Endurance","Home-friendly","Strength","Yoga"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Core","Shoulders","Calves"],"movement_pattern":"Squat","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30 sec","form_cues":["Sit hips back as if onto a chair, weight in the heels.","Keep knees behind the toes.","Reach arms up and draw the belly in."],"common_mistakes":["Arching the low back","Letting knees drift far past the toes"],"regressions":["Wall sit with hands on thighs"],"progressions":["Revolved chair"],"safety":"Keep the bend shallower if knees hurt.","video":null,"diagram":"","notes":""},{"id":"eagle","name":"Eagle pose","aliases":["Garudasana"],"training_type":"Yoga","tags":["Balance","Mobility","Unilateral","Yoga"],"muscle_group":"Legs","primary_muscles":["Glutes","Quadriceps","Adductors"],"secondary_muscles":["Rhomboids","Rear deltoids","Core"],"movement_pattern":"Hold","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":2,"reps":"20–30 sec / side","form_cues":["Sit into a slight squat, wrap one thigh over the other.","Cross arms and lift elbows to shoulder height.","Squeeze everything toward the midline."],"common_mistakes":["Standing knee locked straight","Shoulders hunched up to the ears"],"regressions":["Toes of the top leg on the floor"],"progressions":["Eagle with a forward fold"],"safety":"Skip the leg wrap if you have knee pain.","video":null,"diagram":"","notes":""},{"id":"sideangle","name":"Extended side angle","aliases":["Utthita Parsvakonasana"],"training_type":"Yoga","tags":["Mobility","Strength","Unilateral","Yoga"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Obliques","Adductors"],"secondary_muscles":["Glutes","Latissimus dorsi"],"movement_pattern":"Lunge","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["From Warrior II, rest the forearm on the front thigh or hand on a block.","Reach the top arm over your ear in one long line.","Roll the top ribs open toward the ceiling."],"common_mistakes":["Dumping weight into the forearm","Collapsing the chest toward the floor"],"regressions":["Forearm on thigh"],"progressions":["Bound side angle"],"safety":"Use a block under the hand if the floor feels far away.","video":null,"diagram":"","notes":""},{"id":"goddess","name":"Goddess pose","aliases":["Utkata Konasana","Horse stance"],"training_type":"Yoga","tags":["Home-friendly","Mobility","Strength","Yoga"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Adductors","Glutes"],"secondary_muscles":["Calves","Core"],"movement_pattern":"Squat","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30 sec","form_cues":["Take a wide stance, toes turned out.","Bend knees over the toes and sink hips.","Keep the spine tall and arms in cactus."],"common_mistakes":["Knees caving inward","Tipping the pelvis forward"],"regressions":["Shallower bend"],"progressions":["Goddess with heels lifted"],"safety":"Keep knees in line with toes to protect them.","video":null,"diagram":"","notes":""},{"id":"halfmoon","name":"Half moon pose","aliases":["Ardha Chandrasana"],"training_type":"Yoga","tags":["Balance","Strength","Unilateral","Yoga"],"muscle_group":"Legs","primary_muscles":["Glutes","Hip abductors","Quadriceps"],"secondary_muscles":["Obliques","Hamstrings"],"movement_pattern":"Hold","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":2,"reps":"20–30 sec / side","form_cues":["Balance on one leg with the bottom hand on a block.","Lift the top leg to hip height, foot flexed.","Stack hips and open the chest to the side."],"common_mistakes":["Standing knee locked","Top hip rolling forward"],"regressions":["Half moon with back to a wall"],"progressions":["Revolved half moon","Sugarcane pose"],"safety":"Practise near a wall until balance is steady.","video":null,"diagram":"","notes":""},{"id":"crescent","name":"High lunge","aliases":["Crescent lunge","Ashta Chandrasana"],"training_type":"Yoga","tags":["Balance","Strength","Unilateral","Yoga"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Hip flexors"],"secondary_muscles":["Core","Calves"],"movement_pattern":"Lunge","equipment":["Yoga mat"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Stay on the ball of the back foot, back leg strong.","Bend the front knee to about 90 degrees.","Square the hips and reach arms up."],"common_mistakes":["Back knee sagging","Leaning the torso forward"],"regressions":["Low lunge"],"progressions":["Warrior III"],"safety":"Shorten the stance for knee comfort.","video":null,"diagram":"","notes":""},{"id":"revwarrior","name":"Reverse warrior","aliases":["Viparita Virabhadrasana","Peaceful warrior"],"training_type":"Yoga","tags":["Mobility","Unilateral","Yoga"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Obliques","Latissimus dorsi"],"secondary_muscles":["Glutes","Intercostals"],"movement_pattern":"Lunge","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"20–30 sec / side","form_cues":["From Warrior II, slide the back hand down the back leg.","Reach the front arm up and back over your ear.","Keep the front knee bent and steady."],"common_mistakes":["Straightening the front knee","Leaning all your weight on the back hand"],"regressions":["Warrior II"],"progressions":["Extended side angle"],"safety":"Keep the reach gentle if you have low-back pain.","video":null,"diagram":"","notes":""},{"id":"revchair","name":"Revolved chair","aliases":["Parivrtta Utkatasana","Twisted chair"],"training_type":"Yoga","tags":["Mobility","Strength","Yoga"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Obliques"],"secondary_muscles":["Glutes","Upper back"],"movement_pattern":"Rotation","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":2,"reps":"20–30 sec / side","form_cues":["From Chair pose, bring palms together at the chest.","Hook the elbow outside the opposite knee.","Keep knees level and twist from the upper back."],"common_mistakes":["One knee sliding forward past the other","Rounding the back instead of lengthening"],"regressions":["Chair pose","Twist with hands on thighs"],"progressions":[],"safety":"Skip deep twists if pregnant or with a disc injury.","video":null,"diagram":"","notes":""},{"id":"tree","name":"Tree pose","aliases":["Vrksasana","Vrikshasana"],"training_type":"Yoga","tags":["Balance","Home-friendly","Unilateral","Yoga"],"muscle_group":"Legs","primary_muscles":["Glutes","Hip abductors","Calves"],"secondary_muscles":["Core","Adductors","Feet"],"movement_pattern":"Hold","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Press the lifted foot into the inner calf or thigh, never the knee.","Keep the standing hip stacked over the foot.","Fix your gaze on one still point."],"common_mistakes":["Resting the foot on the side of the knee","Standing hip jutting out to the side"],"regressions":["Tree pose with toes on the floor (kickstand)"],"progressions":["Tree pose with eyes closed","Tree pose with arms overhead"],"safety":"Use a wall for support if balance is unsteady.","video":null,"diagram":"","notes":""},{"id":"warrior1","name":"Warrior I","aliases":["Virabhadrasana I","Warrior one"],"training_type":"Yoga","tags":["Home-friendly","Strength","Unilateral","Yoga"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes"],"secondary_muscles":["Hip flexors","Shoulders","Core"],"movement_pattern":"Lunge","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Bend the front knee over the ankle, back foot angled 45 degrees.","Square hips toward the front of the mat.","Reach arms up while dropping shoulders away from ears."],"common_mistakes":["Front knee drifting past the toes or caving in","Arching the low back to square the hips"],"regressions":["High lunge with back heel lifted"],"progressions":["Warrior III"],"safety":"Shorten the stance if hips or knees complain.","video":null,"diagram":"","notes":""},{"id":"warrior2","name":"Warrior II","aliases":["Virabhadrasana II","Warrior two"],"training_type":"Yoga","tags":["Home-friendly","Strength","Unilateral","Yoga"],"muscle_group":"Legs","primary_muscles":["Quadriceps","Glutes","Adductors"],"secondary_muscles":["Shoulders","Core"],"movement_pattern":"Lunge","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Bend the front knee to track over the middle toes.","Open hips to the long side of the mat.","Reach arms out level and look over the front hand."],"common_mistakes":["Front knee collapsing inward","Leaning the torso over the front leg"],"regressions":["Shorter stance with less knee bend"],"progressions":["Reverse warrior","Extended side angle"],"safety":"Keep the front knee no further forward than the ankle.","video":null,"diagram":"","notes":""},{"id":"dancer","name":"Dancer pose","aliases":["Natarajasana","Lord of the dance"],"training_type":"Yoga","tags":["Balance","Mobility","Unilateral","Yoga"],"muscle_group":"Mobility","primary_muscles":["Quadriceps","Hip flexors","Glutes"],"secondary_muscles":["Shoulders","Erector spinae","Calves"],"movement_pattern":"Extension","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":2,"reps":"20–30 sec / side","form_cues":["Hold the inside of one foot behind you.","Kick the foot into the hand as you tip forward.","Reach the free arm forward for balance."],"common_mistakes":["Letting the lifted knee splay out wide","Collapsing the chest down"],"regressions":["Standing quad stretch at a wall"],"progressions":["Dancer with a strap overhead"],"safety":"Use a wall or strap; ease off with low-back pain.","video":null,"diagram":"","notes":""},{"id":"handtotoe","name":"Extended hand-to-big-toe pose","aliases":["Utthita Hasta Padangusthasana"],"training_type":"Yoga","tags":["Balance","Stretching","Unilateral","Yoga"],"muscle_group":"Mobility","primary_muscles":["Hamstrings","Hip flexors"],"secondary_muscles":["Glutes","Core"],"movement_pattern":"Hold","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":2,"reps":"20–30 sec / side","form_cues":["Hook the big toe with two fingers or use a strap.","Stand tall on a firm standing leg.","Extend the lifted leg forward, then open it to the side."],"common_mistakes":["Rounding the back to straighten the leg","Hiking the hip of the lifted leg"],"regressions":["Bent lifted knee","Using a strap"],"progressions":["Free-floating leg without the hand"],"safety":"Use a strap or bend the knee to avoid straining the hamstring.","video":null,"diagram":"","notes":""},{"id":"garland","name":"Garland pose","aliases":["Malasana","Yogi squat"],"training_type":"Yoga","tags":["Home-friendly","Mobility","Stretching","Yoga"],"muscle_group":"Mobility","primary_muscles":["Adductors","Hip flexors","Calves"],"secondary_muscles":["Erector spinae","Glutes"],"movement_pattern":"Squat","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30–60 sec","form_cues":["Squat deep with feet a little wider than hips.","Press elbows into the inner knees, palms together.","Lift the chest and keep heels down if you can."],"common_mistakes":["Heels lifting and weight rolling forward","Rounding the back heavily"],"regressions":["Block under the hips or rolled mat under heels"],"progressions":["Bound garland"],"safety":"Sit on a block if knees are sensitive.","video":null,"diagram":"","notes":""},{"id":"legsupwall","name":"Legs up the wall","aliases":["Viparita Karani"],"training_type":"Yoga","tags":["Recovery","Restorative","Yoga"],"muscle_group":"Mobility","primary_muscles":["Hamstrings"],"secondary_muscles":["Calves","Lower back"],"movement_pattern":"Hold","equipment":["Wall"],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":1,"reps":"3–10 min","form_cues":["Sit sideways to a wall and swing legs up.","Rest your back and head on the floor.","Let arms fall open and breathe slowly."],"common_mistakes":["Hips too far from the wall with straining hamstrings","Forcing the legs straight"],"regressions":["Calves on a chair"],"progressions":["Blanket under the hips"],"safety":"Come down if your feet go numb; check with a doctor if you have glaucoma.","video":null,"diagram":"","notes":""},{"id":"mountain","name":"Mountain pose","aliases":["Tadasana","Samasthiti"],"training_type":"Yoga","tags":["Balance","Beginner-friendly","Home-friendly","Warm-up","Yoga"],"muscle_group":"Mobility","primary_muscles":["Core","Quadriceps"],"secondary_muscles":["Calves","Glutes","Erector spinae"],"movement_pattern":"Hold","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30–60 sec","form_cues":["Stand with feet hip-width, weight even through both feet.","Lift kneecaps gently and lengthen up through the crown.","Relax shoulders down and breathe slowly."],"common_mistakes":["Locking knees hard","Leaning weight into the heels"],"regressions":[],"progressions":["Tree pose"],"safety":"Safe for nearly everyone; widen stance if balance is poor.","video":null,"diagram":"","notes":"Foundation stance for all standing poses; good for posture awareness."},{"id":"pyramid","name":"Pyramid pose","aliases":["Parsvottanasana","Intense side stretch"],"training_type":"Yoga","tags":["Stretching","Unilateral","Yoga"],"muscle_group":"Mobility","primary_muscles":["Hamstrings","Calves"],"secondary_muscles":["Hip rotators","Erector spinae"],"movement_pattern":"Stretch","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Step one foot back about a leg's length, hips square.","Fold over the front leg with a long spine.","Keep the front knee soft, not locked."],"common_mistakes":["Hips twisting open","Rounding to get the head lower"],"regressions":["Hands on blocks"],"progressions":["Revolved triangle"],"safety":"Shorten the stance if hamstrings feel sharp, not stretched.","video":null,"diagram":"","notes":""},{"id":"revtriangle","name":"Revolved triangle","aliases":["Parivrtta Trikonasana"],"training_type":"Yoga","tags":["Balance","Mobility","Unilateral","Yoga"],"muscle_group":"Mobility","primary_muscles":["Hamstrings","Obliques"],"secondary_muscles":["Erector spinae","Glutes"],"movement_pattern":"Rotation","equipment":[],"req":"","equipment_tier":0,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Use a shorter stance with hips squared forward.","Lengthen the spine first, then twist from the ribs.","Place the bottom hand on a block if needed."],"common_mistakes":["Twisting from the neck instead of the torso","Losing balance by keeping feet on one line"],"regressions":["Revolved hand on block","Pyramid pose"],"progressions":["Revolved half moon"],"safety":"Avoid deep twists if pregnant or with disc issues.","video":null,"diagram":"","notes":""},{"id":"standfold","name":"Standing forward fold","aliases":["Uttanasana","Forward bend"],"training_type":"Yoga","tags":["Mobility","Recovery","Stretching","Yoga"],"muscle_group":"Mobility","primary_muscles":["Hamstrings","Calves"],"secondary_muscles":["Erector spinae"],"movement_pattern":"Stretch","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30–60 sec","form_cues":["Hinge from the hips with a long spine.","Bend knees as much as you need.","Let the head and neck hang heavy."],"common_mistakes":["Locking the knees and rounding hard","Holding the breath"],"regressions":["Ragdoll with bent knees","Half forward fold"],"progressions":["Big-toe hold forward fold"],"safety":"Rise slowly to avoid dizziness; bend knees if you have back pain.","video":null,"diagram":"","notes":""},{"id":"triangle","name":"Triangle pose","aliases":["Trikonasana","Utthita Trikonasana"],"training_type":"Yoga","tags":["Mobility","Stretching","Unilateral","Yoga"],"muscle_group":"Mobility","primary_muscles":["Hamstrings","Obliques","Adductors"],"secondary_muscles":["Glutes","Quadriceps"],"movement_pattern":"Stretch","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Straighten both legs, front foot pointing forward.","Hinge at the front hip and reach long before tipping down.","Stack shoulders and open the chest to the side."],"common_mistakes":["Rounding the spine to reach the floor","Hyperextending the front knee"],"regressions":["Hand on a block or shin"],"progressions":["Revolved triangle"],"safety":"Keep a micro-bend in the front knee if you hyperextend.","video":null,"diagram":"","notes":""},{"id":"widefold","name":"Wide-legged forward fold","aliases":["Prasarita Padottanasana"],"training_type":"Yoga","tags":["Mobility","Stretching","Yoga"],"muscle_group":"Mobility","primary_muscles":["Hamstrings","Adductors"],"secondary_muscles":["Erector spinae","Calves"],"movement_pattern":"Stretch","equipment":[],"req":"","equipment_tier":0,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30–60 sec","form_cues":["Step feet wide, toes slightly in.","Hinge from the hips with hands on the floor or blocks.","Lengthen the crown toward the floor."],"common_mistakes":["Weight sinking into the heels","Rounding only from the upper back"],"regressions":["Hands on blocks"],"progressions":["Hands clasped behind the back"],"safety":"Rise slowly with a flat back to avoid dizziness.","video":null,"diagram":"","notes":""},{"id":"chaturanga","name":"Four-limbed staff pose","aliases":["Chaturanga Dandasana","Chaturanga","Yoga push-up"],"training_type":"Yoga","tags":["Calisthenics","Strength","Yoga"],"muscle_group":"Chest","primary_muscles":["Triceps","Pectorals","Anterior deltoids"],"secondary_muscles":["Core","Serratus anterior"],"movement_pattern":"Horizontal push","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"5–10 sec","form_cues":["From plank, shift forward onto the toes.","Lower with elbows hugging the ribs.","Stop when upper arms are parallel to the floor."],"common_mistakes":["Dropping lower than the shoulders","Hips sagging toward the mat"],"regressions":["Knees-down chaturanga","Knees-chest-chin"],"progressions":["Chaturanga push-ups"],"safety":"Lower with control and stop above shoulder height to protect shoulders.","video":null,"diagram":"","notes":""},{"id":"bow","name":"Bow pose","aliases":["Dhanurasana"],"training_type":"Yoga","tags":["Mobility","Stretching","Yoga"],"muscle_group":"Back","primary_muscles":["Erector spinae","Quadriceps","Hip flexors"],"secondary_muscles":["Pectorals","Anterior deltoids","Glutes"],"movement_pattern":"Extension","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"15–30 sec","form_cues":["Lie face down and hold the outside of the ankles.","Kick feet into hands to lift chest and thighs.","Keep knees about hip-width."],"common_mistakes":["Knees splaying wide","Holding the breath"],"regressions":["Half bow (one leg)","Locust pose"],"progressions":["Wheel pose"],"safety":"Avoid if pregnant or with acute back pain.","video":null,"diagram":"","notes":""},{"id":"cobra","name":"Cobra pose","aliases":["Bhujangasana"],"training_type":"Yoga","tags":["Mobility","Rehab","Stretching","Yoga"],"muscle_group":"Back","primary_muscles":["Erector spinae"],"secondary_muscles":["Glutes","Hip flexors","Rhomboids"],"movement_pattern":"Extension","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"15–30 sec","form_cues":["Lie face down, hands under the shoulders.","Lift the chest using the back, little weight in the hands.","Keep elbows bent and close to the ribs."],"common_mistakes":["Pushing to straight arms and crunching the low back","Craning the neck up"],"regressions":["Sphinx pose"],"progressions":["Upward-facing dog"],"safety":"Keep the lift low if you feel low-back pinching.","video":null,"diagram":"","notes":""},{"id":"locust","name":"Locust pose","aliases":["Salabhasana"],"training_type":"Yoga","tags":["Rehab","Strength","Yoga"],"muscle_group":"Back","primary_muscles":["Erector spinae","Glutes"],"secondary_muscles":["Hamstrings","Rear deltoids","Rhomboids"],"movement_pattern":"Extension","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"15–30 sec","form_cues":["Lie face down, arms by your sides.","Lift chest, arms and legs together.","Look slightly down to keep the neck long."],"common_mistakes":["Bending the knees","Throwing the head back"],"regressions":["Half locust (one leg)"],"progressions":["Bow pose"],"safety":"Keep the lift modest with low-back issues.","video":null,"diagram":"","notes":""},{"id":"sphinx","name":"Sphinx pose","aliases":["Salamba Bhujangasana"],"training_type":"Yoga","tags":["Mobility","Recovery","Stretching","Yoga"],"muscle_group":"Back","primary_muscles":["Erector spinae"],"secondary_muscles":["Hip flexors","Rectus abdominis"],"movement_pattern":"Extension","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30–60 sec","form_cues":["Lie on your belly with elbows under the shoulders.","Press forearms down and lift the chest.","Relax glutes and let the spine lengthen."],"common_mistakes":["Sinking between the shoulders","Clenching the glutes hard"],"regressions":["Lie flat with a pillow under the chest"],"progressions":["Cobra pose"],"safety":"Lower down if you feel pinching in the lower back.","video":null,"diagram":"","notes":""},{"id":"updog","name":"Upward-facing dog","aliases":["Urdhva Mukha Svanasana","Up dog"],"training_type":"Yoga","tags":["Mobility","Stretching","Yoga"],"muscle_group":"Back","primary_muscles":["Erector spinae","Triceps"],"secondary_muscles":["Glutes","Hip flexors","Shoulders"],"movement_pattern":"Extension","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"15–30 sec","form_cues":["Press through straight arms, thighs lifted off the mat.","Roll shoulders back and open the chest.","Press the tops of the feet down."],"common_mistakes":["Shoulders shrugged up to ears","Hanging into the low back"],"regressions":["Cobra pose"],"progressions":["Wheel pose"],"safety":"Use cobra instead with low-back or wrist pain.","video":null,"diagram":"","notes":""},{"id":"wheel","name":"Wheel pose","aliases":["Urdhva Dhanurasana","Full backbend"],"training_type":"Yoga","tags":["Mobility","Strength","Yoga"],"muscle_group":"Back","primary_muscles":["Erector spinae","Shoulders","Glutes"],"secondary_muscles":["Quadriceps","Triceps","Hip flexors"],"movement_pattern":"Extension","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":3,"reps":"10–20 sec","form_cues":["Place hands by the ears, fingers toward the shoulders.","Press up onto the crown, then straighten arms.","Keep feet and knees parallel."],"common_mistakes":["Elbows and knees splaying out","Pushing up from cold muscles"],"regressions":["Bridge pose","Wheel with blocks at a wall"],"progressions":["Wheel with one leg lifted"],"safety":"Warm up well first; avoid with shoulder, wrist or back injuries.","video":null,"diagram":"","notes":""},{"id":"dolphin","name":"Dolphin pose","aliases":["Ardha Pincha Mayurasana","Dolphin dog"],"training_type":"Yoga","tags":["Mobility","Strength","Yoga"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Upper back"],"secondary_muscles":["Hamstrings","Core"],"movement_pattern":"Hold","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"30 sec","form_cues":["Start on forearms, elbows shoulder-width.","Lift hips up and back into an inverted V.","Press forearms down and push away from the floor."],"common_mistakes":["Elbows sliding outward","Upper back collapsing"],"regressions":["Puppy pose"],"progressions":["Forearm stand","Dolphin push-ups"],"safety":"Use a strap above the elbows if they splay.","video":null,"diagram":"","notes":""},{"id":"headstand","name":"Supported headstand","aliases":["Salamba Sirsasana","Headstand"],"training_type":"Yoga","tags":["Balance","Strength","Yoga"],"muscle_group":"Shoulders","primary_muscles":["Shoulders","Core"],"secondary_muscles":["Trapezius","Triceps","Neck"],"movement_pattern":"Hold","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Advanced","tracking":"hold","unilateral":false,"sets":3,"reps":"10–60 sec","form_cues":["Interlace fingers and cradle the back of the head.","Press forearms down to lift weight off the head.","Walk feet in, then lift legs slowly with control."],"common_mistakes":["Kicking up with momentum","Dumping weight into the neck"],"regressions":["Dolphin pose","Headstand at a wall"],"progressions":["Tripod headstand"],"safety":"Learn with a teacher; avoid with neck injury, high blood pressure or glaucoma.","video":null,"diagram":"","notes":""},{"id":"bridgepose","name":"Bridge pose","aliases":["Setu Bandha Sarvangasana"],"training_type":"Yoga","tags":["Mobility","Rehab","Strength","Yoga"],"muscle_group":"Glutes","primary_muscles":["Glutes","Hamstrings"],"secondary_muscles":["Erector spinae","Hip flexors","Pectorals"],"movement_pattern":"Extension","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30 sec","form_cues":["Lie on your back, feet hip-width near the hips.","Press feet down and lift hips high.","Roll shoulders under and interlace hands below you."],"common_mistakes":["Knees falling out wide","Turning the head while lifted"],"regressions":["Supported bridge on a block"],"progressions":["Wheel pose"],"safety":"Keep the neck still while the hips are up.","video":null,"diagram":"","notes":"Yoga version focuses on chest opening; see Glute bridge for strength reps."},{"id":"boat","name":"Boat pose","aliases":["Navasana","Paripurna Navasana"],"training_type":"Yoga","tags":["Core","Strength","Yoga"],"muscle_group":"Core","primary_muscles":["Rectus abdominis","Hip flexors"],"secondary_muscles":["Obliques","Quadriceps"],"movement_pattern":"Hold","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"20–30 sec","form_cues":["Balance just behind the sit bones.","Lift shins parallel to the floor, chest proud.","Reach arms forward alongside the knees."],"common_mistakes":["Rounding the back","Holding the breath"],"regressions":["Half boat with hands behind the thighs"],"progressions":["Full boat with straight legs","Low boat"],"safety":"Keep knees bent if the low back aches.","video":null,"diagram":"","notes":""},{"id":"crow","name":"Crow pose","aliases":["Bakasana","Crane pose"],"training_type":"Yoga","tags":["Balance","Calisthenics","Strength","Yoga"],"muscle_group":"Core","primary_muscles":["Core","Triceps","Wrist flexors"],"secondary_muscles":["Shoulders","Hip flexors"],"movement_pattern":"Hold","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"10–30 sec","form_cues":["Plant hands shoulder-width and bend elbows back.","Rest knees high on the backs of the upper arms.","Shift forward and lift one foot, then the other."],"common_mistakes":["Looking straight down and tipping over","Not leaning far enough forward"],"regressions":["Feet on a block","One foot lifted"],"progressions":["Side crow","Crane with straight arms"],"safety":"Put a pillow in front of your face while learning; skip with wrist pain.","video":null,"diagram":"","notes":""},{"id":"sidecrow","name":"Side crow","aliases":["Parsva Bakasana"],"training_type":"Yoga","tags":["Balance","Calisthenics","Strength","Yoga"],"muscle_group":"Core","primary_muscles":["Obliques","Triceps"],"secondary_muscles":["Shoulders","Wrist flexors"],"movement_pattern":"Hold","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Advanced","tracking":"hold","unilateral":true,"sets":2,"reps":"10–20 sec / side","form_cues":["Squat and twist so both knees face one side.","Plant hands, stack the outer thigh on one arm.","Lean forward and float the feet."],"common_mistakes":["Twisting too little","Collapsing the shoulders"],"regressions":["Crow pose"],"progressions":["Eka Pada Koundinyasana I"],"safety":"Skip with wrist injuries; use a cushion in front.","video":null,"diagram":"","notes":""},{"id":"shoulderstand","name":"Supported shoulder stand","aliases":["Salamba Sarvangasana","Candle pose"],"training_type":"Yoga","tags":["Balance","Mobility","Yoga"],"muscle_group":"Core","primary_muscles":["Core","Upper back"],"secondary_muscles":["Neck extensors","Glutes"],"movement_pattern":"Hold","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"30–60 sec","form_cues":["Swing legs over, hands supporting the back.","Walk elbows in toward each other.","Stack hips over shoulders, weight on shoulders not neck."],"common_mistakes":["Turning the head while up","Elbows splaying wide"],"regressions":["Legs up the wall","Half shoulder stand"],"progressions":["Plough pose"],"safety":"Avoid with neck injury, high blood pressure or glaucoma; fold blankets under the shoulders.","video":null,"diagram":"","notes":""},{"id":"boundangle","name":"Bound angle pose","aliases":["Baddha Konasana","Butterfly pose","Cobbler's pose"],"training_type":"Yoga","tags":["Mobility","Stretching","Yoga"],"muscle_group":"Mobility","primary_muscles":["Adductors"],"secondary_muscles":["Hip external rotators","Erector spinae"],"movement_pattern":"Stretch","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30–60 sec","form_cues":["Sit with soles of the feet together.","Hold the feet and sit tall.","Let knees relax down, no pushing."],"common_mistakes":["Pressing knees down with the hands","Slumping the lower back"],"regressions":["Sit on a blanket","Blocks under the knees"],"progressions":["Forward fold in bound angle"],"safety":"Support the knees with blocks if groin feels strained.","video":null,"diagram":"","notes":""},{"id":"camel","name":"Camel pose","aliases":["Ustrasana"],"training_type":"Yoga","tags":["Mobility","Stretching","Yoga"],"muscle_group":"Mobility","primary_muscles":["Hip flexors","Quadriceps","Rectus abdominis"],"secondary_muscles":["Pectorals","Erector spinae"],"movement_pattern":"Extension","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":false,"sets":3,"reps":"15–30 sec","form_cues":["Kneel with hips over knees, hands on the low back.","Lift the chest up before leaning back.","Reach for the heels only if the hips stay forward."],"common_mistakes":["Hips drifting back behind the knees","Dropping the head back early"],"regressions":["Hands on low back","Toes tucked for higher heels"],"progressions":["Wheel pose"],"safety":"Come up slowly; skip with neck or low-back injuries.","video":null,"diagram":"","notes":""},{"id":"catcow","name":"Cat-cow","aliases":["Marjaryasana-Bitilasana","Cat and cow"],"training_type":"Yoga","tags":["Mobility","Recovery","Warm-up","Yoga"],"muscle_group":"Mobility","primary_muscles":["Erector spinae","Rectus abdominis"],"secondary_muscles":["Shoulders","Neck"],"movement_pattern":"Mobility","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":3,"reps":"8–10 cycles","form_cues":["Start on hands and knees, wrists under shoulders.","Inhale, drop the belly and lift chest.","Exhale, round the spine and tuck the chin."],"common_mistakes":["Moving only 