","notes":""},{"id":"cowface","name":"Cow face pose","aliases":["Gomukhasana"],"training_type":"Yoga","tags":["Mobility","Stretching","Yoga"],"muscle_group":"Mobility","primary_muscles":["Glutes","Hip external rotators","Triceps"],"secondary_muscles":["Shoulders","Latissimus dorsi"],"movement_pattern":"Stretch","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":2,"reps":"30–60 sec / side","form_cues":["Stack one knee over the other, feet by the hips.","Reach one arm up and one behind, clasp fingers.","Sit evenly on both sit bones."],"common_mistakes":["One hip lifting off the floor","Arching the back to reach hands"],"regressions":["Strap between hands","Sit on a block"],"progressions":["Forward fold in cow face"],"safety":"Use a strap; avoid if knee or shoulder pain.","video":null,"diagram":"","notes":""},{"id":"downdog","name":"Downward dog","aliases":["Adho Mukha Svanasana","Downward-facing dog","Down dog"],"training_type":"Yoga","tags":["Mobility","Stretching","Warm-up","Yoga"],"muscle_group":"Mobility","primary_muscles":["Hamstrings","Calves","Shoulders"],"secondary_muscles":["Latissimus dorsi","Core","Triceps"],"movement_pattern":"Stretch","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30–60 sec","form_cues":["Press hands wide and lift hips up and back.","Bend knees to keep the spine long.","Let heels sink toward the floor."],"common_mistakes":["Rounding the upper back","Shoulders crunched up to the ears"],"regressions":["Puppy pose","Downward dog with bent knees"],"progressions":["Three-legged dog"],"safety":"Rest in child's pose if wrists or shoulders hurt.","video":null,"diagram":"","notes":""},{"id":"fish","name":"Fish pose","aliases":["Matsyasana"],"training_type":"Yoga","tags":["Mobility","Stretching","Yoga"],"muscle_group":"Mobility","primary_muscles":["Pectorals","Hip flexors","Neck flexors"],"secondary_muscles":["Erector spinae"],"movement_pattern":"Extension","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"20–30 sec","form_cues":["Lie on your back with hands under the hips.","Press forearms down to lift the chest.","Rest the crown lightly or keep the head lifted."],"common_mistakes":["Putting body weight into the head","Shrugging shoulders"],"regressions":["Supported fish on blocks"],"progressions":["Fish with legs lifted"],"safety":"Keep weight off the head if you have neck issues.","video":null,"diagram":"","notes":""},{"id":"happybaby","name":"Happy baby","aliases":["Ananda Balasana"],"training_type":"Yoga","tags":["Recovery","Stretching","Yoga"],"muscle_group":"Mobility","primary_muscles":["Adductors","Hamstrings","Glutes"],"secondary_muscles":["Erector spinae"],"movement_pattern":"Stretch","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30–60 sec","form_cues":["Lie on your back and hold the outer feet.","Stack ankles over knees.","Draw knees toward the armpits, tailbone heavy."],"common_mistakes":["Tailbone curling off the mat","Tugging with tense shoulders"],"regressions":["Hold the shins or use a strap"],"progressions":["Rock side to side"],"safety":"Avoid pressure on the belly late in pregnancy.","video":null,"diagram":"","notes":""},{"id":"janusirsa","name":"Head-to-knee pose","aliases":["Janu Sirsasana"],"training_type":"Yoga","tags":["Mobility","Stretching","Unilateral","Yoga"],"muscle_group":"Mobility","primary_muscles":["Hamstrings","Erector spinae"],"secondary_muscles":["Adductors","Obliques"],"movement_pattern":"Stretch","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Extend one leg, other foot against the inner thigh.","Turn the chest over the straight leg.","Fold from the hips with a long spine."],"common_mistakes":["Rounding from the upper back only","Forcing the head to the knee"],"regressions":["Strap around the foot"],"progressions":["Revolved head-to-knee"],"safety":"Pad under the bent knee if it lifts high.","video":null,"diagram":"","notes":""},{"id":"hero","name":"Hero pose","aliases":["Virasana"],"training_type":"Yoga","tags":["Mobility","Recovery","Stretching","Yoga"],"muscle_group":"Mobility","primary_muscles":["Quadriceps"],"secondary_muscles":["Ankles","Tibialis anterior"],"movement_pattern":"Stretch","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"1–3 min","form_cues":["Kneel with knees together and feet just wider than hips.","Sit between the feet, on a block if needed.","Lengthen the spine with hands on thighs."],"common_mistakes":["Feet splaying out and twisting the knees","Forcing hips to the floor"],"regressions":["Sit on a block"],"progressions":["Reclined hero"],"safety":"Use a block and stop with any knee pain.","video":null,"diagram":"","notes":""},{"id":"lizard","name":"Lizard pose","aliases":["Utthan Pristhasana"],"training_type":"Yoga","tags":["Mobility","Stretching","Unilateral","Yoga"],"muscle_group":"Mobility","primary_muscles":["Hip flexors","Adductors","Glutes"],"secondary_muscles":["Hamstrings"],"movement_pattern":"Stretch","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Intermediate","tracking":"hold","unilateral":true,"sets":2,"reps":"30–60 sec / side","form_cues":["From low lunge, place both hands inside the front foot.","Lower the back knee or keep it lifted.","Drop to forearms or blocks if hips allow."],"common_mistakes":["Front knee caving inward","Shoulders collapsing"],"regressions":["Hands on blocks"],"progressions":["Lizard with a back-leg quad stretch"],"safety":"Pad the back knee; ease off with groin pain.","video":null,"diagram":"","note