et together.","Let knees fall open, supported if needed.","Rest arms by your sides and breathe slowly."],"common_mistakes":["Straining to drop the knees","Arching the low back"],"regressions":["Blocks under each knee"],"progressions":["Bolster under the spine"],"safety":"Support the knees if you feel groin or knee strain.","video":null,"diagram":"","notes":""},{"id":"seatedfold","name":"Seated forward fold","aliases":["Paschimottanasana","Seated forward bend"],"training_type":"Yoga","tags":["Mobility","Stretching","Yoga"],"muscle_group":"Mobility","primary_muscles":["Hamstrings","Erector spinae"],"secondary_muscles":["Calves"],"movement_pattern":"Stretch","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":false,"sets":3,"reps":"30–60 sec","form_cues":["Sit tall with legs straight, feet flexed.","Hinge forward from the hips, leading with the chest.","Bend knees if the back starts rounding."],"common_mistakes":["Rounding hard to touch the toes","Bouncing into the stretch"],"regressions":["Sit on a folded blanket","Strap around the feet"],"progressions":["Hold the outer feet"],"safety":"Bend the knees if you feel nerve tingling.","video":null,"diagram":"","notes":""},{"id":"halflord","name":"Seated spinal twist","aliases":["Ardha Matsyendrasana","Half lord of the fishes"],"training_type":"Yoga","tags":["Mobility","Recovery","Yoga"],"muscle_group":"Mobility","primary_muscles":["Obliques","Erector spinae"],"secondary_muscles":["Glutes","Piriformis"],"movement_pattern":"Rotation","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"hold","unilateral":true,"sets":2,"reps":"30 sec / side","form_cues":["Cross one foot outside the opposite knee.","Lengthen up on the inhale.","Twist on the exhale, hugging the knee."],"common_mistakes":["Leaning back into the hand","Cranking the neck around"],"regressions":["Easy seated twist"],"progressions":["Bound half lord of the fishes"],"safety":"Twist gently; avoid deep twists if pregnant or with a disc injury.","video":null,"diagram":"","notes":""},{"id":"sunsal","name":"Sun salutation A","aliases":["Surya Namaskar A","Sun salutation flow"],"training_type":"Yoga","tags":["Endurance","Mobility","Warm-up","Yoga"],"muscle_group":"Mobility","primary_muscles":["Full body"],"secondary_muscles":["Shoulders","Hamstrings","Core"],"movement_pattern":"Mobility","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"time","unilateral":false,"sets":1,"reps":"5–10 min","form_cues":["Link one movement to each breath.","Move through mountain, fold, plank, chaturanga, cobra, down dog.","Step or jump forward and rise back to standing."],"common_mistakes":["Rushing and losing the breath","Collapsing in the chaturanga"],"regressions":["Knees-down plank and cobra"],"progressions":["Sun salutation B"],"safety":"Drop knees in plank and skip chaturanga if shoulders are weak.","video":null,"diagram":"","notes":"Classic warm-up; 3–5 rounds is typical."},{"id":"sunsalb","name":"Sun salutation B","aliases":["Surya Namaskar B"],"training_type":"Yoga","tags":["Endurance","Mobility","Warm-up","Yoga"],"muscle_group":"Mobility","primary_muscles":["Full body"],"secondary_muscles":["Shoulders","Hamstrings","Core"],"movement_pattern":"Mobility","equipment":["Yoga mat"],"req":"yogamat","equipment_tier":1,"difficulty":"Intermediate","tracking":"time","unilateral":false,"sets":1,"reps":"10–15 min","form_cues":["Begin and end each round in chair pose.","Add Warrior I on each side between vinyasas.","Keep each move on a single breath."],"common_mistakes":["Rushing through warrior stances","Sagging hips in plank"],"regressions":["Sun salutation A"],"progressions":["Add holds in each warrior"],"safety":"Modify chaturanga to knees-down if form fades.","video":null,"diagram":"","notes":"More heating than A; 3–5 rounds is typical."},{"id":"supinetwist","name":"Supine spinal twist","aliases":["Supt