tion","equipment":["Pilates ring","Mat"],"req":"pilatesring","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"12–15","form_cues":["Hold the ring at chest height, palms on the pads.","Squeeze the ring with soft elbows.","Keep shoulders down away from ears."],"common_mistakes":["Shrugging","Locking elbows"],"regressions":[],"progressions":["Overhead ring press"],"safety":"Use light pressure with shoulder pain.","video":null,"diagram":"","notes":""},{"id":"swan","name":"Pilates swan","aliases":["Swan dive prep","Swan"],"training_type":"Pilates","tags":["Mobility","Pilates","Strength"],"muscle_group":"Back","primary_muscles":["Erector spinae"],"secondary_muscles":["Glutes","Triceps","Rhomboids"],"movement_pattern":"Extension","equipment":["Pilates mat"],"req":"pilatesmat|yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"5–6","form_cues":["Lie face down, hands by the shoulders.","Lift the chest by lengthening up through the crown.","Lower with control."],"common_mistakes":["Crunching into the low back","Shrugging shoulders"],"regressions":["Sphinx pose"],"progressions":["Swan dive"],"safety":"Keep the lift small with low-back pain.","video":null,"diagram":"","notes":""},{"id":"swimming","name":"Pilates swimming","aliases":["Swimming"],"training_type":"Pilates","tags":["Endurance","Pilates","Strength"],"muscle_group":"Back","primary_muscles":["Erector spinae","Glutes"],"secondary_muscles":["Rear deltoids","Hamstrings"],"movement_pattern":"Extension","equipment":["Pilates mat"],"req":"pilatesmat|yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":false,"sets":2,"reps":"20–30 flutters","form_cues":["Lie face down, reach arms and legs long.","Lift opposite arm and leg in quick flutters.","Keep the gaze down and the neck long."],"common_mistakes":["Lifting the head too high","Bending knees"],"regressions":["Bird dog","Alternating arm-leg lift slowly"],"progressions":["Longer sets"],"safety":"Keep the lift small with low-back pain.","video":null,"diagram":"","notes":""},{"id":"singlelegkick","name":"Single-leg kick","aliases":["Pilates single leg kick"],"training_type":"Pilates","tags":["Pilates","Strength"],"muscle_group":"Legs","primary_muscles":["Hamstrings","Glutes"],"secondary_muscles":["Erector spinae","Shoulders"],"movement_pattern":"Isolation","equipment":["Pilates mat"],"req":"pilatesmat|yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"8 / side","form_cues":["Lie prone, propped on forearms, belly lifted.","Kick one heel to the glute twice.","Switch legs, keeping hips on the mat."],"common_mistakes":["Sinking into the shoulders","Hips lifting"],"regressions":["Lower chest to the mat"],"progressions":["Double-leg kick"],"safety":"Lie flatter with low-back pain.","video":null,"diagram":"","notes":""}]$ex$::jsonb)
