"],"req":"pilatesmat|yogamat","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"8–10 / side","form_cues":["Lie on your side, legs slightly forward.","Kick the top leg forward twice, then sweep back.","Keep the torso still."],"common_mistakes":["Rolling hips back","Swinging with momentum"],"regressions":["Bend the bottom knee"],"progressions":["Side kick bicycle"],"safety":"Prop the head on the hand to keep the neck easy.","video":null,"diagram":"","notes":""},{"id":"ringleg","name":"Side-lying ring leg press","aliases":["Magic circle side-lying leg press"],"training_type":"Pilates","tags":["Pilates","Strength","Unilateral"],"muscle_group":"Glutes","primary_muscles":["Hip abductors","Glutes"],"secondary_muscles":["Adductors","Obliques"],"movement_pattern":"Isolation","equipment":["Pilates ring","Mat"],"req":"pilatesring","equipment_tier":1,"difficulty":"Beginner","tracking":"count","unilateral":true,"sets":2,"reps":"10–12 / side","form_cues":["Lie on your side with the ring between the ankles.","Press the top leg down into the ring.","Lift back up against the outside pad."],"common_mistakes":["Rolling the hips back","Rushing"],"regressions":["Side kick"],"progressions":[],"safety":"Prop the head to keep the neck easy.","video":null,"diagram":"","notes":""},{"id":"corkscrew","name":"Corkscrew","aliases":["Pilates corkscrew"],"training_type":"Pilates","tags":["Core","Pilates","Rotation"],"muscle_group":"Core","primary_muscles":["Obliques","Rectus abdominis"],"secondary_muscles":["Hip flexors"],"movement_pattern":"Rotation","equipment":["Pilates mat"],"req":"pilatesmat|yogamat","equipment_tier":1,"difficulty":"Intermediate","tracking":"count","unilateral":false,"sets":2,"reps":"3 / direction","form_cues":["Lie on your back, legs together straight up.","Circle both legs to one side, down and around.","Keep shoulders heavy on the mat."],"common_mistakes":["Big uncontrolled circles","Back arching at the bottom"],"regressions":